window.TK_LOOKALIKES = [
 {"id":"das-dass","lv":"A2","words":[{"w":"das","en":"the (neuter article); that, which (pronoun)"},{"w":"dass","en":"that (conjunction)"}],"tip":"dass = conjunction that opens a subordinate clause (glauben, sagen, schade, wissen ... dass). das = article or pronoun. Test: if you can swap in dieses or welches, it is das.","items":[{"ans":"das","de":"Ich habe ___ Auto letzte Woche verkauft.","en":"I sold the car last week."},{"ans":"das","de":"Das Buch, ___ ich gerade lese, ist sehr spannend.","en":"The book I'm reading at the moment is very exciting."},{"ans":"das","de":"Wo ist ___ Kind? Es sollte längst im Bett sein.","en":"Where is the child? It should have been in bed long ago."},{"ans":"dass","de":"Ich glaube, ___ es morgen regnen wird.","en":"I think it will rain tomorrow."},{"ans":"dass","de":"Es ist schade, ___ du nicht mitkommen kannst.","en":"It's a pity you can't come along."},{"ans":"dass","de":"Sie hat mir gesagt, ___ sie nächste Woche umzieht.","en":"She told me that she is moving next week."}]},
 {"id":"seit-seid","lv":"A2","words":[{"w":"seit","en":"since, for (time)"},{"w":"seid","en":"are (ihr-form of sein)"}],"tip":"seid = ihr form of sein (ihr seid, 'you are'); seit = since/for. If you can replace it with 'bist/sind', write seid.","items":[{"ans":"seit","de":"Ich wohne ___ drei Jahren in Berlin.","en":"I have been living in Berlin for three years."},{"ans":"seit","de":"Er ist ___ Montag krank.","en":"He has been ill since Monday."},{"ans":"seit","de":"Wir lernen Deutsch, ___ wir in Wien leben.","en":"We have been learning German since we started living in Vienna."},{"ans":"seid","de":"Ihr ___ heute aber früh dran!","en":"You are early today!"},{"ans":"seid","de":"Hoffentlich ___ ihr nicht böse auf mich.","en":"I hope you are not angry with me."},{"ans":"seid","de":"Ihr ___ herzlich zu unserer Party eingeladen.","en":"You are warmly invited to our party."}]},
 {"id":"wieder-wider","lv":"B2","words":[{"w":"wieder","en":"again"},{"w":"wider","en":"against, contrary to (fixed phrases)"}],"tip":"wieder = again (repetition: wiederholen, wiedersehen). wider = against/contrary to (elevated preposition + Akk.), mostly in fixed phrases and compounds: wider Willen, wider Erwarten, Widerstand, widersprechen.","items":[{"ans":"wieder","de":"Nach dem Urlaub fängt die Arbeit morgen ___ an.","en":"After the holiday, work starts again tomorrow."},{"ans":"wieder","de":"Mein Auto ist schon ___ kaputt.","en":"My car has broken down again already."},{"ans":"wider","de":"Er hat das ___ besseres Wissen behauptet.","en":"He claimed that although he knew better."},{"ans":"wider","de":"Der Test war ___ Erwarten sehr leicht.","en":"Contrary to expectations, the test was very easy."},{"ans":"wider","de":"Sie half ihm nur ___ Willen.","en":"She only helped him against her will."}]},
 {"id":"mehl-mehr-meer","lv":"A2","words":[{"w":"Mehl","en":"flour"},{"w":"mehr","en":"more"},{"w":"Meer","en":"sea"}],"tip":"Mehl = flour (baking), mehr = more (comparative of viel), Meer = sea. Mehr and Meer sound exactly alike; Mehl differs only in the final l.","items":[{"ans":"Mehl","de":"Der Teig besteht aus ___, Wasser und Hefe.","en":"The dough is made of flour, water and yeast."},{"ans":"Mehl","de":"Für das Brot nehme ich Wasser, Salz und frisch gemahlenes ___.","en":"For the bread I use water, salt and freshly ground flour."},{"ans":"mehr","de":"Ich möchte heute nichts ___ essen.","en":"I don't want to eat anything more today."},{"ans":"mehr","de":"Mein Bruder verdient ___ Geld als ich.","en":"My brother earns more money than I do."},{"ans":"Meer","de":"Im Sommer fahren wir ans ___.","en":"In summer we go to the sea."},{"ans":"Meer","de":"Wir haben am ___ Muscheln gesammelt.","en":"We collected shells by the sea."}]},
 {"id":"wal-wahl","lv":"A2","words":[{"w":"Wal","en":"whale"},{"w":"Wahl","en":"choice; election"}],"tip":"Wal (der) = whale, no h. Wahl (die) = choice or election, with a silent lengthening h. Both sound exactly the same.","items":[{"ans":"Wal","de":"Vor der Küste haben wir einen riesigen ___ gesehen.","en":"Off the coast we saw a huge whale."},{"ans":"Wal","de":"Der ___ ist ein Säugetier, kein Fisch.","en":"The whale is a mammal, not a fish."},{"ans":"Wahl","de":"Bei der ___ im September dürfen alle Bürger abstimmen.","en":"In the election in September all citizens may vote."},{"ans":"Wahl","de":"Du hast die ___ zwischen Tee und Kaffee.","en":"You have the choice between tea and coffee."},{"ans":"Wahl","de":"Die ___ des richtigen Berufs fällt vielen schwer.","en":"Choosing the right career is hard for many people."}]},
 {"id":"lehre-leere","lv":"B2","words":[{"w":"Lehre","en":"apprenticeship; doctrine; lesson"},{"w":"Leere","en":"emptiness, void"}],"tip":"Lehre (from lehren) = apprenticeship, teaching, lesson learned. Leere (from leer) = emptiness.","items":[{"ans":"Lehre","de":"Nach der Schule macht er eine ___ als Elektriker.","en":"After school he is doing an apprenticeship as an electrician."},{"ans":"Lehre","de":"Aus diesem Fehler habe ich eine wichtige ___ gezogen.","en":"I learned an important lesson from this mistake."},{"ans":"Leere","de":"Nach dem Auszug der Kinder herrschte eine seltsame ___ im Haus.","en":"After the children moved out, a strange emptiness filled the house."},{"ans":"Leere","de":"Nach dem Verlust spürte sie eine große innere ___.","en":"After the loss she felt a great inner emptiness."}]},
 {"id":"stadt-staat-statt","lv":"B1","words":[{"w":"Stadt","en":"city, town"},{"w":"Staat","en":"state (country, government)"},{"w":"statt","en":"instead of"}],"tip":"Stadt = city (die), Staat = state/country (der, long a), statt = instead of (+ Genitiv: statt des Autos; between parallel words: Tee statt Kaffee; or statt ... zu + infinitive).","items":[{"ans":"Stadt","de":"Berlin ist die größte ___ Deutschlands.","en":"Berlin is the largest city in Germany."},{"ans":"Stadt","de":"Am Wochenende fahre ich in die ___ zum Einkaufen.","en":"At the weekend I go into town to do some shopping."},{"ans":"Staat","de":"Der ___ muss für die Sicherheit seiner Bürger sorgen.","en":"The state must ensure the safety of its citizens."},{"ans":"Staat","de":"Österreich ist ein demokratischer ___.","en":"Austria is a democratic state."},{"ans":"statt","de":"Ich trinke lieber Tee ___ Kaffee.","en":"I prefer to drink tea instead of coffee."},{"ans":"statt","de":"Wir bleiben zu Hause, ___ ins Kino zu gehen.","en":"We are staying at home instead of going to the cinema."}]},
 {"id":"ihm-ihn-in","lv":"A2","words":[{"w":"ihm","en":"him, to him (Dativ)"},{"w":"ihn","en":"him (Akkusativ)"},{"w":"in","en":"in, into"}],"tip":"ihn = Akkusativ (I see HIM: ihn), ihm = Dativ (I help HIM: ihm). in = preposition. Check the verb: sehen/treffen/kennen + ihn; helfen/gehören/geben + ihm.","items":[{"ans":"ihn","de":"Ich habe ___ gestern im Supermarkt getroffen.","en":"I met him in the supermarket yesterday."},{"ans":"ihn","de":"Kennst du seinen Bruder? Ich sehe ___ jeden Morgen im Bus.","en":"Do you know his brother? I see him on the bus every morning."},{"ans":"ihm","de":"Kannst du ___ bitte helfen? Er schafft das nicht allein.","en":"Can you please help him? He can't manage it on his own."},{"ans":"ihm","de":"Der Hund gehört ___, nicht mir.","en":"The dog belongs to him, not to me."},{"ans":"in","de":"Wir wohnen ___ einem kleinen Dorf.","en":"We live in a small village."},{"ans":"in","de":"Sie legt das Handy ___ die Tasche.","en":"She puts the phone into the bag."}]},
 {"id":"schon-schoen","lv":"A2","words":[{"w":"schon","en":"already; (modal particle)"},{"w":"schön","en":"beautiful, nice"}],"tip":"schön (with umlaut) = adjective, beautiful/nice. schon = adverb, already (or a softening particle).","items":[{"ans":"schon","de":"Ich habe ___ dreimal versucht, ihn anzurufen.","en":"I have already tried three times to call him."},{"ans":"schon","de":"Wir kennen uns ___ seit der Schulzeit.","en":"We have known each other since school."},{"ans":"schön","de":"Das Wetter ist heute wirklich ___.","en":"The weather is really nice today."},{"ans":"schön","de":"Ich finde deine neue Wohnung richtig ___.","en":"I think your new flat is really lovely."}]},
 {"id":"kennen-koennen-kommen","lv":"A2","words":[{"w":"kennen","en":"to know (a person/place), be acquainted with"},{"w":"können","en":"can, to be able to"},{"w":"kommen","en":"to come"}],"tip":"kennen = be acquainted with a person, place or thing; können = can (modal, needs another verb); kommen = come. The vowels e / ö / o make the difference.","items":[{"ans":"kennen","de":"Wir ___ uns schon seit der Schule.","en":"We have known each other since school."},{"ans":"kennen","de":"Sie ___ die Stadt sehr gut, weil sie dort aufgewachsen sind.","en":"They know the city very well because they grew up there."},{"ans":"können","de":"Sie ___ gern später kommen, wir warten.","en":"You are welcome to come later, we'll wait."},{"ans":"können","de":"Wir ___ leider nicht an der Feier teilnehmen.","en":"Unfortunately we cannot take part in the celebration."},{"ans":"kommen","de":"Die Gäste ___ gegen acht Uhr bei uns an.","en":"The guests arrive at our place around eight o'clock."},{"ans":"kommen","de":"Wir ___ aus Spanien, aber wir leben in Köln.","en":"We come from Spain, but we live in Cologne."}]},
 {"id":"rad-rat","lv":"B1","words":[{"w":"Rad","en":"wheel; bicycle"},{"w":"Rat","en":"advice; council"}],"tip":"Rad (d) = wheel/bike (Fahrrad). Rat (t) = advice (einen Rat geben) or council (Stadtrat). Both end in the same sound.","items":[{"ans":"Rad","de":"Ich fahre jeden Tag mit dem ___ zur Arbeit.","en":"I cycle to work every day."},{"ans":"Rad","de":"Das hintere ___ meines Autos hat einen Platten.","en":"The rear wheel of my car has a flat."},{"ans":"Rat","de":"Kannst du mir einen ___ geben, was ich tun soll?","en":"Can you give me some advice on what I should do?"},{"ans":"Rat","de":"Er hat auf den ___ seines Arztes gehört.","en":"He followed his doctor's advice."}]},
 {"id":"lied-lid","lv":"B2","words":[{"w":"Lied","en":"song"},{"w":"Lid","en":"eyelid"}],"tip":"Lied (ie) = song. Lid (single i) = eyelid (das Augenlid). Both are neuter and pronounced exactly alike (long i); only the spelling differs.","items":[{"ans":"Lied","de":"Sie singt ihrem Kind jeden Abend ein ___ vor.","en":"She sings her child a song every evening."},{"ans":"Lied","de":"Dieses ___ kenne ich aus dem Radio.","en":"I know this song from the radio."},{"ans":"Lid","de":"Mir ist etwas ins Auge geflogen, jetzt ist das obere ___ geschwollen.","en":"Something flew into my eye and now the upper eyelid is swollen."},{"ans":"Lid","de":"Beim Blinzeln schließt sich das ___ für einen Moment.","en":"When you blink, the eyelid closes for a moment."}]},
 {"id":"saite-seite","lv":"B2","words":[{"w":"Saite","en":"string (of an instrument)"},{"w":"Seite","en":"side; page"}],"tip":"Saite (Sa-) = string of a guitar or violin. Seite (Se-) = side or page. Same sound, different spelling.","items":[{"ans":"Saite","de":"Beim Stimmen ist an der Gitarre eine ___ gerissen.","en":"A string on the guitar snapped while it was being tuned."},{"ans":"Saite","de":"Er zog eine neue ___ auf die Geige auf.","en":"He put a new string on the violin."},{"ans":"Seite","de":"Bitte schlagen Sie das Buch auf ___ 42 auf.","en":"Please open the book at page 42."},{"ans":"Seite","de":"Auf der linken ___ der Straße ist eine Apotheke.","en":"There is a pharmacy on the left side of the street."}]},
 {"id":"fiel-viel","lv":"A2","words":[{"w":"fiel","en":"fell (Präteritum of fallen)"},{"w":"viel","en":"much, a lot"}],"tip":"fiel = past tense of fallen (it fell). viel = much/a lot. Both have ie; viel starts with v (pronounced f).","items":[{"ans":"fiel","de":"Der Teller ___ vom Tisch und zerbrach.","en":"The plate fell off the table and broke."},{"ans":"fiel","de":"Gestern ___ der erste Schnee des Jahres.","en":"Yesterday the first snow of the year fell."},{"ans":"fiel","de":"Als ich sie sah, ___ mir sofort ihr Name ein.","en":"When I saw her, her name came to me straight away."},{"ans":"viel","de":"Ich habe heute nicht ___ Zeit.","en":"I don't have much time today."},{"ans":"viel","de":"Er isst zu ___ Schokolade.","en":"He eats too much chocolate."},{"ans":"viel","de":"Das Kind hat zu ___ ferngesehen.","en":"The child has watched too much television."}]},
 {"id":"tod-tot","lv":"B1","words":[{"w":"Tod","en":"death (noun)"},{"w":"tot","en":"dead (adjective)"}],"tip":"Tod (d, capital) = death, a noun. tot (t, lower case) = dead, an adjective. Mnemonic: Tod ends in d for death.","items":[{"ans":"Tod","de":"Der ___ seines Großvaters hat ihn tief getroffen.","en":"His grandfather's death affected him deeply."},{"ans":"Tod","de":"Nach dem ___ seiner Frau zog er in eine kleinere Wohnung.","en":"After his wife's death he moved to a smaller flat."},{"ans":"Tod","de":"Die Ärzte konnten nur noch den ___ feststellen.","en":"The doctors could only confirm the death."},{"ans":"tot","de":"Der Vogel liegt ___ im Garten.","en":"The bird is lying dead in the garden."},{"ans":"tot","de":"Meine Pflanze ist leider ___.","en":"My plant is unfortunately dead."}]},
 {"id":"leeren-lehren","lv":"B2","words":[{"w":"leeren","en":"to empty"},{"w":"lehren","en":"to teach"}],"tip":"leeren (from leer) = to empty. lehren (cf. Lehre, Lehrer) = to teach. Not to be confused with lernen (to learn).","items":[{"ans":"leeren","de":"Bitte ___ Sie den Mülleimer, bevor Sie gehen.","en":"Please empty the bin before you leave."},{"ans":"leeren","de":"Wir müssen den Briefkasten regelmäßig ___.","en":"We have to empty the letterbox regularly."},{"ans":"lehren","de":"Diese Erfahrungen ___ uns Bescheidenheit.","en":"These experiences teach us humility."},{"ans":"lehren","de":"Sie möchte später an der Universität Geschichte ___.","en":"She would like to teach history at university later on."}]},
 {"id":"malen-mahlen","lv":"B1","words":[{"w":"malen","en":"to paint, to draw"},{"w":"mahlen","en":"to grind"}],"tip":"malen = paint (Maler, Gemälde). mahlen = grind (Mehl, Mühle, Kaffeemühle). The h in mahlen matches Mehl.","items":[{"ans":"malen","de":"Die Kinder ___ gern bunte Bilder.","en":"The children like painting colourful pictures."},{"ans":"malen","de":"Mein Sohn will für Oma ein Bild ___.","en":"My son wants to paint a picture for Grandma."},{"ans":"mahlen","de":"Wir ___ die Kaffeebohnen immer erst kurz vor dem Aufbrühen.","en":"We always grind the coffee beans just before brewing."},{"ans":"mahlen","de":"In der Mühle ___ sie das Korn zu feinem Mehl.","en":"In the mill they grind the grain into fine flour."}]},
 {"id":"masse-massen","lv":"B2","words":[{"w":"Maße","en":"measurements, dimensions (Pl. of Maß)"},{"w":"Massen","en":"masses, crowds (Pl. of Masse)"}],"tip":"Maße (ß, long a) = measurements, dimensions. Massen (ss, short a) = masses, crowds, large amounts.","items":[{"ans":"Maße","de":"Bevor wir Möbel kaufen, brauchen wir die genauen ___ des Zimmers.","en":"Before we buy furniture, we need the exact dimensions of the room."},{"ans":"Maße","de":"Die ___ des Tisches sind 160 mal 80 Zentimeter.","en":"The dimensions of the table are 160 by 80 centimetres."},{"ans":"Massen","de":"Zum Konzert kamen ___ von Fans.","en":"Masses of fans came to the concert."},{"ans":"Massen","de":"In den Ferien strömen ___ von Touristen an die Küste.","en":"During the holidays masses of tourists flock to the coast."}]},
 {"id":"bett-beet","lv":"A2","words":[{"w":"Bett","en":"bed"},{"w":"Beet","en":"flower bed, garden bed"}],"tip":"Bett (tt, short e) = bed to sleep in. Beet (ee, long e) = garden bed for plants. Mind the spelling: the double t and the double e are the clues.","items":[{"ans":"Bett","de":"Ich bin müde und gehe jetzt ins ___.","en":"I'm tired and going to bed now."},{"ans":"Bett","de":"Das Kind liegt schon mit Decke und Kissen im ___.","en":"The child is already lying in bed with a blanket and a pillow."},{"ans":"Beet","de":"Im Garten pflanzen wir Tomaten in einem sonnigen ___.","en":"In the garden we plant tomatoes in a sunny bed."},{"ans":"Beet","de":"Sie hat im ___ vor dem Haus Tulpen gesetzt.","en":"She planted tulips in the bed in front of the house."}]},
 {"id":"wer-wir-waere","lv":"B1","words":[{"w":"wer","en":"who"},{"w":"wir","en":"we"},{"w":"wäre","en":"would be (Konjunktiv II of sein)"}],"tip":"wer = who (question word); wir = we; wäre = would be (hypothetical). Mind the umlaut: war (was) is not wäre.","items":[{"ans":"wer","de":"Ich weiß nicht, ___ das gemacht hat.","en":"I don't know who did that."},{"ans":"wer","de":"Kannst du mir sagen, ___ morgen Dienst hat?","en":"Can you tell me who is on duty tomorrow?"},{"ans":"wir","de":"Gestern haben ___ einen Ausflug an den See gemacht.","en":"Yesterday we went on a trip to the lake."},{"ans":"wir","de":"Heute Abend gehen ___ ins Kino.","en":"Tonight we are going to the cinema."},{"ans":"wäre","de":"Wenn er nicht krank ___, könnte er mitkommen.","en":"If he weren't ill, he could come along."},{"ans":"wäre","de":"Ich würde gern reisen, wenn ich nicht so beschäftigt ___.","en":"I would like to travel if I weren't so busy."}]},
 {"id":"ofen-offen","lv":"A2","words":[{"w":"Ofen","en":"oven, stove"},{"w":"offen","en":"open"}],"tip":"Ofen (noun, capital) = oven or stove. offen (adjective) = open. The doubled f in offen is the clue.","items":[{"ans":"Ofen","de":"Die Pizza ist gleich fertig, sie ist schon im ___.","en":"The pizza will be ready soon, it's already in the oven."},{"ans":"Ofen","de":"Im Winter heizen wir mit einem ___.","en":"In winter we heat with a stove."},{"ans":"offen","de":"Das Fenster ist ___, deshalb ist es kalt im Zimmer.","en":"The window is open, that's why the room is cold."},{"ans":"offen","de":"Die Tür steht ___, weil es so heiß ist.","en":"The door is open because it's so hot."}]},
 {"id":"wissen-gewissen","lv":"B1","words":[{"w":"wissen","en":"to know (facts)"},{"w":"Wissen","en":"knowledge"},{"w":"Gewissen","en":"conscience"}],"tip":"wissen (verb, lower case) = to know a fact. das Wissen (noun) = knowledge. das Gewissen = conscience. Check the role in the sentence: verb, or noun.","items":[{"ans":"wissen","de":"Ich möchte unbedingt ___, wie das Spiel ausgegangen ist.","en":"I really want to know how the game ended."},{"ans":"wissen","de":"Wir müssen ___, ob der Zug heute fährt.","en":"We need to know whether the train is running today."},{"ans":"Wissen","de":"Sein ___ über Geschichte ist beeindruckend.","en":"His knowledge of history is impressive."},{"ans":"Wissen","de":"Das gesammelte ___ der Menschheit steht im Internet.","en":"The collected knowledge of humankind is on the internet."},{"ans":"Gewissen","de":"Er hat ein schlechtes ___, weil er gelogen hat.","en":"He has a guilty conscience because he lied."},{"ans":"Gewissen","de":"Sie konnte ruhig schlafen, denn sie hatte ein reines ___.","en":"She could sleep peacefully, because she had a clear conscience."}]},
 {"id":"kaffee-cafe","lv":"A2","words":[{"w":"Kaffee","en":"coffee (drink)"},{"w":"Café","en":"café, coffee shop"}],"tip":"der Kaffee = the drink (double f, ee). das Café = the place (accent mark on the é, stress on the last syllable).","items":[{"ans":"Kaffee","de":"Möchtest du Milch in deinen ___?","en":"Would you like milk in your coffee?"},{"ans":"Kaffee","de":"Zum Frühstück trinke ich immer eine Tasse ___.","en":"For breakfast I always drink a cup of coffee."},{"ans":"Café","de":"Das neue ___ am Marktplatz hat gestern eröffnet.","en":"The new café on the market square opened yesterday."},{"ans":"Café","de":"Dieses ___ hat den besten Kuchen der Stadt.","en":"This café has the best cake in town."}]},
 {"id":"ruhm-rum-ruhe","lv":"B2","words":[{"w":"Ruhm","en":"fame, glory"},{"w":"Rum","en":"rum"},{"w":"Ruhe","en":"peace, quiet"}],"tip":"der Ruhm = fame (h, long u). der Rum = the spirit (no h, short u). die Ruhe = quiet, calm (from ruhig).","items":[{"ans":"Ruhm","de":"Mit diesem Roman erlangte die Autorin weltweiten ___.","en":"With this novel the author gained worldwide fame."},{"ans":"Ruhm","de":"Der ___ des Sängers verblasste schnell.","en":"The singer's fame faded quickly."},{"ans":"Rum","de":"Der Kuchen enthält einen kräftigen Schuss ___.","en":"The cake contains a generous splash of rum."},{"ans":"Rum","de":"Der Pirat leerte eine ganze Flasche ___.","en":"The pirate emptied a whole bottle of rum."},{"ans":"Ruhe","de":"Im Lesesaal herrscht absolute ___.","en":"Absolute silence reigns in the reading room."},{"ans":"Ruhe","de":"Nach der Arbeit genieße ich die ___ im Garten.","en":"After work I enjoy the peace and quiet in the garden."}]},
 {"id":"bitten-bieten-beten","lv":"B1","words":[{"w":"bitten","en":"to ask, to request"},{"w":"bieten","en":"to offer"},{"w":"beten","en":"to pray"}],"tip":"bitten (um) = ask for; bieten = offer; beten = pray. Three similar-sounding verbs with different vowels: i / ie / e.","items":[{"ans":"bitten","de":"Ich möchte Sie um Hilfe ___.","en":"I would like to ask you for help."},{"ans":"bitten","de":"Dürfte ich Sie ___, etwas leiser zu sein?","en":"May I ask you to be a little quieter?"},{"ans":"bieten","de":"Das Hotel kann seinen Gästen einen Pool ___.","en":"The hotel can offer its guests a swimming pool."},{"ans":"bieten","de":"Die Firma wird ihren Mitarbeitern flexible Arbeitszeiten ___.","en":"The company will offer its employees flexible working hours."},{"ans":"beten","de":"Jeden Abend ___ die Kinder vor dem Schlafen ein Vaterunser.","en":"Every evening the children say the Lord's Prayer before going to sleep."},{"ans":"beten","de":"In der Kirche wollten alle still und andächtig zu Gott ___.","en":"In church everyone wanted to pray to God quietly and devoutly."}]},
 {"id":"vor-fuer-vier","lv":"A2","words":[{"w":"vor","en":"in front of; before; of (Angst vor)"},{"w":"für","en":"for"},{"w":"vier","en":"four"}],"tip":"vor = in front of/before (Dativ or Akkusativ place, Angst vor). für = for (+ Akkusativ). vier = the number 4. For Russian speakers: ü is not u.","items":[{"ans":"vor","de":"Wir treffen uns ___ dem Kino.","en":"We are meeting in front of the cinema."},{"ans":"vor","de":"Er hat Angst ___ Hunden.","en":"He is afraid of dogs."},{"ans":"für","de":"Ich habe ein Geschenk ___ dich.","en":"I have a present for you."},{"ans":"für","de":"Das ist ein Brief ___ meinen Chef.","en":"This is a letter for my boss."},{"ans":"vier","de":"Meine Schwester hat ___ Kinder.","en":"My sister has four children."},{"ans":"vier","de":"Unsere Familie besteht aus ___ Personen.","en":"There are four people in our family."}]},
 {"id":"stil-stiel-still","lv":"B2","words":[{"w":"Stil","en":"style"},{"w":"Stiel","en":"stalk, stem; handle"},{"w":"still","en":"quiet, still"}],"tip":"der Stil = style. der Stiel = stalk or handle (ie). Stil and Stiel sound exactly alike (long i). still = quiet (adjective, short i, double l).","items":[{"ans":"Stil","de":"Der Autor hat einen sehr eigenen ___.","en":"The author has a very distinctive style."},{"ans":"Stil","de":"Sie kleidet sich mit viel ___.","en":"She dresses with a lot of style."},{"ans":"Stiel","de":"Die Rose hat einen langen, dornigen ___.","en":"The rose has a long, thorny stem."},{"ans":"Stiel","de":"Der ___ des Hammers ist aus Holz.","en":"The handle of the hammer is made of wood."},{"ans":"still","de":"Im Raum war es plötzlich ganz ___.","en":"Suddenly it was completely quiet in the room."},{"ans":"still","de":"Bitte sei ___, das Baby schläft.","en":"Please be quiet, the baby is asleep."}]},
 {"id":"leib-laib-leid","lv":"B2","words":[{"w":"Leib","en":"body (elevated)"},{"w":"Laib","en":"loaf"},{"w":"Leid","en":"suffering, grief"}],"tip":"Leib (ei) = body (am ganzen Leib, mit Leib und Seele). Laib (ai) = loaf of bread/cheese. Leib and Laib sound exactly alike. Leid (d, pronounced t at the end) = suffering.","items":[{"ans":"Leib","de":"Er zitterte am ganzen ___ vor Kälte.","en":"He was shivering all over with cold."},{"ans":"Leib","de":"Sie ist mit ___ und Seele Lehrerin.","en":"She is a teacher body and soul."},{"ans":"Laib","de":"Auf dem Markt kaufen wir einen frischen ___ Brot.","en":"At the market we buy a fresh loaf of bread."},{"ans":"Laib","de":"Er schnitt vom ___ Käse ein großes Stück ab.","en":"He cut a big piece off the wheel of cheese."},{"ans":"Leid","de":"Die Flüchtlinge erlebten unvorstellbares ___.","en":"The refugees experienced unimaginable suffering."},{"ans":"Leid","de":"Sie wollte das ___ der Kranken lindern.","en":"She wanted to ease the suffering of the sick."}]},
 {"id":"mal-mahl","lv":"B2","words":[{"w":"Mal","en":"time, occasion"},{"w":"Mahl","en":"meal (elevated, festive)"}],"tip":"das Mal = occasion (zum ersten Mal, einmal). das Mahl = a (festive) meal; the h is the same as in Mahlzeit.","items":[{"ans":"Mal","de":"Zum ersten ___ war ich im Winter in Rom.","en":"For the first time I was in Rome in winter."},{"ans":"Mal","de":"Das war das letzte ___, dass ich dir geholfen habe.","en":"That was the last time I helped you."},{"ans":"Mahl","de":"Nach dem festlichen ___ gingen die Gäste in den Salon.","en":"After the festive meal the guests went to the drawing room."},{"ans":"Mahl","de":"Sie luden die Nachbarn zu einem gemeinsamen ___ ein.","en":"They invited the neighbours to a shared meal."}]},
 {"id":"wahr-war-ware","lv":"B1","words":[{"w":"wahr","en":"true"},{"w":"war","en":"was (Präteritum of sein)"},{"w":"Ware","en":"goods, merchandise"}],"tip":"wahr = true (Wahrheit). war = was. die Ware = goods for sale. Careful: wahr and war sound exactly the same.","items":[{"ans":"wahr","de":"Die Geschichte klingt unglaublich, aber sie ist ___.","en":"The story sounds unbelievable, but it is true."},{"ans":"wahr","de":"Ist es wirklich ___, dass du umziehst?","en":"Is it really true that you are moving?"},{"ans":"war","de":"Gestern ___ das Wetter schlecht.","en":"The weather was bad yesterday."},{"ans":"war","de":"Ich ___ letztes Jahr zum ersten Mal in Wien.","en":"Last year I was in Vienna for the first time."},{"ans":"Ware","de":"Die ___ im Laden war sehr teuer.","en":"The goods in the shop were very expensive."},{"ans":"Ware","de":"Die Firma liefert ihre ___ in ganz Europa aus.","en":"The company delivers its goods all over Europe."}]},
 {"id":"ende-ente","lv":"A2","words":[{"w":"Ende","en":"end"},{"w":"Ente","en":"duck"}],"tip":"Ende = end (from enden). Ente = duck. The d/t difference is easy to miss: Ende (d, end), Ente (t, bird).","items":[{"ans":"Ende","de":"Am ___ des Monats bekomme ich mein Gehalt.","en":"At the end of the month I get my salary."},{"ans":"Ende","de":"Der Film hatte ein trauriges ___.","en":"The film had a sad ending."},{"ans":"Ente","de":"Auf dem Teich schwimmt eine ___.","en":"A duck is swimming on the pond."},{"ans":"Ente","de":"Zu Weihnachten gibt es bei uns oft eine ___ mit Rotkohl.","en":"At Christmas we often have duck with red cabbage."}]},
 {"id":"zahn-zahl","lv":"A2","words":[{"w":"Zahn","en":"tooth"},{"w":"Zahl","en":"number, figure"}],"tip":"der Zahn = tooth (n). die Zahl = number (l; zählen = to count).","items":[{"ans":"Zahn","de":"Ich habe seit gestern Schmerzen im ___.","en":"I have had a toothache since yesterday."},{"ans":"Zahn","de":"Dem Kind ist der erste ___ ausgefallen.","en":"The child has lost its first tooth."},{"ans":"Zahl","de":"Welche ___ hast du gewürfelt?","en":"Which number did you roll?"},{"ans":"Zahl","de":"Die ___ der Teilnehmer steigt jedes Jahr.","en":"The number of participants rises every year."}]},
 {"id":"gruss-gruesse-groesse","lv":"B1","words":[{"w":"Gruß","en":"greeting (sg.)"},{"w":"Grüße","en":"greetings (pl.)"},{"w":"Größe","en":"size"}],"tip":"Gruß/Grüße (from grüßen) = greeting(s); Größe (from groß) = size, height. u/ü vs o/ö.","items":[{"ans":"Gruß","de":"Er hob die Hand zum ___.","en":"He raised his hand in greeting."},{"ans":"Gruß","de":"Bitte richten Sie Ihrem Mann einen schönen ___ von mir aus.","en":"Please give your husband my best regards."},{"ans":"Grüße","de":"Viele ___ aus dem Urlaub!","en":"Many greetings from our holiday!"},{"ans":"Grüße","de":"Bitte schick deiner Familie viele liebe ___ von mir.","en":"Please send your family lots of love from me."},{"ans":"Größe","de":"Haben Sie diese Jacke auch eine ___ kleiner?","en":"Do you also have this jacket one size smaller?"},{"ans":"Größe","de":"Die ___ des Zimmers beträgt zwanzig Quadratmeter.","en":"The size of the room is twenty square metres."}]},
 {"id":"hoehle-hoelle","lv":"B1","words":[{"w":"Höhle","en":"cave, den"},{"w":"Hölle","en":"hell"}],"tip":"Höhle (h-ö-h) = cave (long ö, lengthening h). Hölle (double l) = hell (short ö).","items":[{"ans":"Höhle","de":"Der Bär schläft im Winter in einer ___.","en":"The bear sleeps in a cave in winter."},{"ans":"Höhle","de":"Wir haben im Urlaub eine große ___ besichtigt.","en":"On holiday we visited a large cave."},{"ans":"Hölle","de":"Die Prüfung war die reinste ___.","en":"The exam was sheer hell."},{"ans":"Hölle","de":"Er hat ihr das Leben zur ___ gemacht.","en":"He made her life hell."}]},
 {"id":"ist-isst","lv":"A2","words":[{"w":"ist","en":"is (sein)"},{"w":"isst","en":"eats (essen)"}],"tip":"ist = is (sein). isst = he/she eats (essen: ich esse, du isst, er isst). isst has a double s because of the stem ess-.","items":[{"ans":"ist","de":"Das Wetter ___ heute schön.","en":"The weather is nice today."},{"ans":"ist","de":"Die Suppe ___ noch zu heiß.","en":"The soup is still too hot."},{"ans":"isst","de":"Mein Bruder ___ nie Fleisch.","en":"My brother never eats meat."},{"ans":"isst","de":"Sie ___ jeden Morgen ein Müsli.","en":"She eats muesli every morning."},{"ans":"isst","de":"Was ___ du am liebsten zum Frühstück?","en":"What do you like to eat best for breakfast?"}]},
 {"id":"laesst-lasst-lest","lv":"B1","words":[{"w":"lässt","en":"lets, leaves; has done (er/sie/es lässt)"},{"w":"lasst","en":"let, leave (ihr-form of lassen; also imperative)"},{"w":"lest","en":"read (ihr-form of lesen)"}],"tip":"lassen: er lässt (ä, ss), ihr lasst. lesen: ihr lest (e, single s). Both end in -st but mean different things.","items":[{"ans":"lässt","de":"Er ___ seinen Hund nie allein zu Hause.","en":"He never leaves his dog alone at home."},{"ans":"lässt","de":"Sie ___ sich einmal im Monat die Haare schneiden.","en":"She has her hair cut once a month."},{"ans":"lasst","de":"Ihr ___ mich nie ausreden!","en":"You never let me finish speaking!"},{"ans":"lasst","de":"Bitte ___ die Kinder noch ein bisschen spielen.","en":"Please let the children play a little longer."},{"ans":"lest","de":"Ihr ___ ja schon richtig dicke Bücher!","en":"You're already reading really thick books!"},{"ans":"lest","de":"Habt ihr Zeit? Dann ___ bitte das Buch bis Montag zu Ende.","en":"Do you have time? Then please finish reading the book by Monday."}]},
 {"id":"heiss-heisst","lv":"A2","words":[{"w":"heiß","en":"hot"},{"w":"heißt","en":"is called (heißen)"}],"tip":"heiß = hot (adjective). heißt = is called, from heißen (Wie heißt du?). heißt ends in -t.","items":[{"ans":"heiß","de":"Heute ist es draußen sehr ___.","en":"It is very hot outside today."},{"ans":"heiß","de":"Vorsicht, die Suppe ist ___!","en":"Careful, the soup is hot!"},{"ans":"heißt","de":"Wie ___ du mit Nachnamen?","en":"What is your surname?"},{"ans":"heißt","de":"Mein Hund ___ Bello.","en":"My dog is called Bello."},{"ans":"heißt","de":"Wie ___ das auf Deutsch?","en":"What is that called in German?"}]},
 {"id":"fuss-fluss","lv":"A2","words":[{"w":"Fuß","en":"foot"},{"w":"Fluss","en":"river"}],"tip":"der Fuß (ß after a long u) = foot. der Fluss (with l; ss after a short u) = river.","items":[{"ans":"Fuß","de":"Ich habe mir beim Fußball den ___ verstaucht.","en":"I sprained my foot playing football."},{"ans":"Fuß","de":"Die Kinder gehen zu ___ zur Schule.","en":"The children walk to school."},{"ans":"Fluss","de":"Der Rhein ist ein langer ___.","en":"The Rhine is a long river."},{"ans":"Fluss","de":"Wir sind mit dem Boot den ___ hinuntergefahren.","en":"We went down the river by boat."}]},
 {"id":"bis-bist-biss","lv":"A2","words":[{"w":"bis","en":"until, to"},{"w":"bist","en":"are (du)"},{"w":"biss","en":"bit (Präteritum of beißen)"}],"tip":"bis = until/to. bist = du bist (you are). biss = he/she bit (beißen; the ß turns into ss after a short vowel).","items":[{"ans":"bis","de":"Warte hier, ___ ich zurückkomme.","en":"Wait here until I come back."},{"ans":"bis","de":"Das Büro ist von Montag ___ Freitag geöffnet.","en":"The office is open Monday to Friday."},{"ans":"bist","de":"Du ___ heute sehr früh aufgestanden.","en":"You got up very early today."},{"ans":"bist","de":"Wo ___ du gestern Abend gewesen?","en":"Where were you last night?"},{"ans":"biss","de":"Der Hund ___ den Postboten ins Bein.","en":"The dog bit the postman in the leg."},{"ans":"biss","de":"Sie ___ in den Apfel und lächelte.","en":"She bit into the apple and smiled."}]},
 {"id":"schluss-schloss-schluessel","lv":"B1","words":[{"w":"Schluss","en":"end; conclusion"},{"w":"Schloss","en":"castle; lock"},{"w":"Schlüssel","en":"key"}],"tip":"Schluss = end (Schluss machen). Schloss = castle or lock. Schlüssel = key (opens the Schloss!). Look at the vowel: u / o / ü.","items":[{"ans":"Schluss","de":"Am ___ des Films weinten alle im Kino.","en":"At the end of the film everybody in the cinema cried."},{"ans":"Schluss","de":"Aus den Zahlen ziehe ich den ___, dass wir sparen müssen.","en":"From the figures I conclude that we have to save money."},{"ans":"Schloss","de":"Das alte ___ liegt auf einem Hügel über der Stadt.","en":"The old castle stands on a hill above the town."},{"ans":"Schloss","de":"Die Tür hat ein neues ___ bekommen.","en":"The door has been fitted with a new lock."},{"ans":"Schlüssel","de":"Ich kann die Tür nicht öffnen, weil ich meinen ___ verloren habe.","en":"I can't open the door because I've lost my key."},{"ans":"Schlüssel","de":"Wo hast du den ___ für die Wohnung hingelegt?","en":"Where did you put the key to the flat?"}]},
 {"id":"kirche-kirsche","lv":"A2","words":[{"w":"Kirche","en":"church"},{"w":"Kirsche","en":"cherry"}],"tip":"Kirche = church (ch as in ich). Kirsche = cherry (sch). Only one letter different.","items":[{"ans":"Kirche","de":"Am Sonntag gehen viele Leute in die ___.","en":"On Sunday many people go to church."},{"ans":"Kirche","de":"Die alte ___ im Dorf hat einen hohen Glockenturm.","en":"The old church in the village has a tall bell tower."},{"ans":"Kirsche","de":"Auf der Torte liegt eine rote ___.","en":"There is a red cherry on top of the gateau."},{"ans":"Kirsche","de":"Ich esse am liebsten eine reife ___ direkt vom Baum.","en":"I like best to eat a ripe cherry straight from the tree."}]},
 {"id":"schaf-schiff-schief","lv":"A2","words":[{"w":"Schaf","en":"sheep"},{"w":"Schiff","en":"ship"},{"w":"schief","en":"crooked, slanted"}],"tip":"das Schaf = sheep (long a). das Schiff = ship (double f, short i). schief = crooked (ie).","items":[{"ans":"Schaf","de":"Auf der Wiese weidet ein ___.","en":"A sheep is grazing in the meadow."},{"ans":"Schaf","de":"Das ___ liefert Wolle für Pullover.","en":"The sheep supplies wool for jumpers."},{"ans":"Schiff","de":"Das ___ legt um zehn Uhr im Hafen ab.","en":"The ship leaves the harbour at ten o'clock."},{"ans":"Schiff","de":"Wir fahren mit dem ___ nach Schweden.","en":"We are going to Sweden by ship."},{"ans":"schief","de":"Das Bild hängt ___ an der Wand.","en":"The picture is hanging crooked on the wall."},{"ans":"schief","de":"Der Turm von Pisa steht ___.","en":"The Tower of Pisa is leaning."}]},
 {"id":"baer-beere-bier","lv":"A2","words":[{"w":"Bär","en":"bear"},{"w":"Beere","en":"berry"},{"w":"Bier","en":"beer"}],"tip":"Bär and Beere sound similar (Beere has a second syllable). der Bär = bear (ä); die Beere = berry (ee); das Bier = beer (ie).","items":[{"ans":"Bär","de":"Im Zoo lebt ein großer brauner ___.","en":"A big brown bear lives in the zoo."},{"ans":"Bär","de":"Im Winter schläft der ___ in seiner Höhle.","en":"In winter the bear sleeps in its den."},{"ans":"Beere","de":"Auf dem Strauch hing eine reife, rote ___.","en":"A ripe red berry was hanging on the bush."},{"ans":"Beere","de":"Diese ___ schmeckt süß, aber ich weiß nicht, ob sie giftig ist.","en":"This berry tastes sweet, but I don't know whether it's poisonous."},{"ans":"Bier","de":"Zum Essen trinke ich gern ein kühles ___.","en":"With my meal I like to drink a cold beer."},{"ans":"Bier","de":"Er bestellte ein großes ___ und eine Wurst.","en":"He ordered a large beer and a sausage."}]},
 {"id":"mauer-maurer","lv":"B1","words":[{"w":"Mauer","en":"wall (masonry, e.g. garden or city wall)"},{"w":"Maurer","en":"bricklayer"}],"tip":"die Mauer = wall (garden wall, city wall). der Maurer = the person who builds walls (bricklayer): -er for the profession.","items":[{"ans":"Mauer","de":"Um den Garten steht eine hohe ___.","en":"A high wall surrounds the garden."},{"ans":"Mauer","de":"Die Berliner ___ fiel im Jahr 1989.","en":"The Berlin Wall fell in 1989."},{"ans":"Maurer","de":"Der ___ baut die Wand aus Ziegelsteinen.","en":"The bricklayer builds the wall out of bricks."},{"ans":"Maurer","de":"Mein Onkel arbeitet als ___.","en":"My uncle works as a bricklayer."}]},
 {"id":"seife-seide-seil","lv":"B1","words":[{"w":"Seife","en":"soap"},{"w":"Seide","en":"silk"},{"w":"Seil","en":"rope"}],"tip":"Seife = soap (waschen). Seide = silk (the fabric). Seil = rope. All start with Sei-.","items":[{"ans":"Seife","de":"Zum Händewaschen braucht man Wasser und ___.","en":"For washing your hands you need water and soap."},{"ans":"Seife","de":"Diese ___ schäumt kaum, obwohl sie nach Lavendel duftet.","en":"This soap hardly lathers, although it smells of lavender."},{"ans":"Seide","de":"Das Kleid ist aus reiner ___.","en":"The dress is made of pure silk."},{"ans":"Seide","de":"Die edle Bluse besteht aus feiner, glänzender ___.","en":"The elegant blouse is made of fine, shiny silk."},{"ans":"Seil","de":"Die Bergsteiger sichern sich mit einem ___.","en":"The mountaineers secure themselves with a rope."},{"ans":"Seil","de":"Der Akrobat balanciert auf einem dünnen ___.","en":"The acrobat balances on a thin rope."}]},
 {"id":"wolke-wolle","lv":"A2","words":[{"w":"Wolke","en":"cloud"},{"w":"Wolle","en":"wool"}],"tip":"die Wolke = cloud (Wolken am Himmel). die Wolle = wool (Schaf, stricken). One letter apart.","items":[{"ans":"Wolke","de":"Am Himmel hängt eine dunkle ___.","en":"A dark cloud is hanging in the sky."},{"ans":"Wolke","de":"Eine einzige ___ stand über dem Berg.","en":"A single cloud hung over the mountain."},{"ans":"Wolle","de":"Der Pullover ist aus reiner ___.","en":"The jumper is made of pure wool."},{"ans":"Wolle","de":"Meine Oma strickt Socken aus bunter ___.","en":"My grandma knits socks from colourful wool."}]},
 {"id":"kaese-kasse","lv":"A2","words":[{"w":"Käse","en":"cheese"},{"w":"Kasse","en":"till, checkout; cashier's desk"}],"tip":"der Käse = cheese (ä, long vowel). die Kasse = checkout (a, double s). The word Kasse is also the till or box office.","items":[{"ans":"Käse","de":"Ich möchte ein Stück ___ auf mein Brot.","en":"I would like a piece of cheese on my bread."},{"ans":"Käse","de":"Auf der Pizza ist viel ___.","en":"There is a lot of cheese on the pizza."},{"ans":"Kasse","de":"Bitte bezahlen Sie an der ___ dort vorn.","en":"Please pay at the checkout over there."},{"ans":"Kasse","de":"Im Supermarkt steht eine lange Schlange an der ___.","en":"In the supermarket there is a long queue at the checkout."}]},
 {"id":"tuer-tier","lv":"A2","words":[{"w":"Tür","en":"door"},{"w":"Tier","en":"animal"}],"tip":"die Tür = door (ü). das Tier = animal (ie). Do not mix up the sounds ü and ie.","items":[{"ans":"Tür","de":"Bitte mach die ___ zu, es zieht.","en":"Please shut the door, there's a draught."},{"ans":"Tür","de":"Jemand klopft an die ___.","en":"Somebody is knocking at the door."},{"ans":"Tier","de":"Welches ___ gefällt dir im Zoo am besten?","en":"Which animal do you like best at the zoo?"},{"ans":"Tier","de":"Ein Hund ist ein ___, das man gut trainieren kann.","en":"A dog is an animal that you can train well."}]},
 {"id":"reis-reise-reiz","lv":"B1","words":[{"w":"Reis","en":"rice"},{"w":"Reise","en":"journey, trip"},{"w":"Reiz","en":"charm, appeal; stimulus"}],"tip":"Reis = rice (the grain). Reise = journey. Reiz = appeal, charm or stimulus (reizen). Reis [s] and Reiz [ts] sound very similar.","items":[{"ans":"Reis","de":"Zum Mittagessen gibt es Hähnchen mit ___.","en":"For lunch there is chicken with rice."},{"ans":"Reis","de":"Ich koche den ___ immer mit etwas Salz.","en":"I always cook the rice with a little salt."},{"ans":"Reise","de":"Wir planen eine ___ nach Italien.","en":"We are planning a trip to Italy."},{"ans":"Reise","de":"Die ___ nach Japan dauerte fast zwölf Stunden.","en":"The journey to Japan took almost twelve hours."},{"ans":"Reiz","de":"Der besondere ___ dieser Stadt liegt in ihrer Lage am Meer.","en":"The special charm of this city lies in its location by the sea."},{"ans":"Reiz","de":"Die Idee verlor für ihn schnell ihren ___.","en":"The idea quickly lost its appeal for him."}]},
 {"id":"fahrt-faehrt-fahrt-verb","lv":"A2","words":[{"w":"Fahrt","en":"journey, ride"},{"w":"fährt","en":"drives, goes (er/sie fährt)"},{"w":"fahrt","en":"drive, go (ihr fahrt)"}],"tip":"die Fahrt = journey (noun). er fährt (ä!) vs ihr fahrt (a): fahren has a stem change only for du/er/sie/es.","items":[{"ans":"Fahrt","de":"Die ___ nach München dauert vier Stunden.","en":"The journey to Munich takes four hours."},{"ans":"Fahrt","de":"Wir haben auf der ___ viel gesungen.","en":"We sang a lot during the journey."},{"ans":"fährt","de":"Mein Vater ___ jeden Tag mit dem Zug zur Arbeit.","en":"My father takes the train to work every day."},{"ans":"fährt","de":"Der Bus ___ alle zehn Minuten.","en":"The bus runs every ten minutes."},{"ans":"fahrt","de":"Ihr ___ morgen nach Hamburg, oder?","en":"You are going to Hamburg tomorrow, aren't you?"},{"ans":"fahrt","de":"Wann ___ ihr in den Urlaub?","en":"When are you going on holiday?"}]},
 {"id":"feier-feuer-fehler","lv":"A2","words":[{"w":"Feier","en":"celebration, party"},{"w":"Feuer","en":"fire"},{"w":"Fehler","en":"mistake"}],"tip":"die Feier = party (feiern). das Feuer = fire. der Fehler = mistake. Watch the spelling: ei / eu / eh.","items":[{"ans":"Feier","de":"Zu meiner ___ kommen alle Freunde.","en":"All my friends are coming to my party."},{"ans":"Feier","de":"Die ___ dauerte bis spät in die Nacht.","en":"The celebration lasted until late at night."},{"ans":"Feuer","de":"Die Feuerwehr hat das ___ schnell gelöscht.","en":"The fire brigade put out the fire quickly."},{"ans":"Feuer","de":"Im Kamin brennt ein warmes ___.","en":"A warm fire is burning in the fireplace."},{"ans":"Fehler","de":"In deinem Text sind noch drei ___.","en":"There are still three mistakes in your text."},{"ans":"Fehler","de":"Das war mein größter ___.","en":"That was my biggest mistake."}]},
 {"id":"fest-fast","lv":"A2","words":[{"w":"Fest","en":"celebration, festival"},{"w":"fest","en":"firm, tight, fixed"},{"w":"fast","en":"almost"}],"tip":"das Fest = celebration (noun). fest = firm/tight (adjective/adverb). fast = almost (adverb). One letter apart: e vs a.","items":[{"ans":"Fest","de":"Am Wochenende feiern wir ein ___ im Garten.","en":"At the weekend we are having a party in the garden."},{"ans":"Fest","de":"Das ___ war ein großer Erfolg.","en":"The festival was a great success."},{"ans":"fest","de":"Halte das Seil bitte ___!","en":"Please hold the rope tight!"},{"ans":"fest","de":"Er schläft immer ganz ___.","en":"He always sleeps very soundly."},{"ans":"fast","de":"Es ist ___ zehn Uhr, wir müssen los.","en":"It's almost ten o'clock, we have to go."},{"ans":"fast","de":"Ich habe ___ alles verstanden.","en":"I understood almost everything."}]},
 {"id":"beitrag-betrag","lv":"B2","words":[{"w":"Beitrag","en":"contribution; article; membership fee"},{"w":"Betrag","en":"amount, sum"}],"tip":"Beitrag = contribution (beitragen), also an article/post or a fee. Betrag = a sum of money (Rechnungsbetrag). Look for the 'i'.","items":[{"ans":"Beitrag","de":"Sie hat einen wichtigen ___ zum Erfolg des Projekts geleistet.","en":"She made an important contribution to the project's success."},{"ans":"Beitrag","de":"Ich habe einen interessanten ___ über Klimaschutz in der Zeitung gelesen.","en":"I read an interesting article on climate protection in the newspaper."},{"ans":"Betrag","de":"Der ___ auf dem Kassenbon stimmt nicht.","en":"The amount on the receipt is wrong."},{"ans":"Betrag","de":"Der Kellner nannte uns den ___ der Rechnung: achtundvierzig Euro.","en":"The waiter told us the total of the bill: forty-eight euros."}]},
 {"id":"ergebnis-erlebnis-ereignis","lv":"B2","words":[{"w":"Ergebnis","en":"result, outcome"},{"w":"Erlebnis","en":"(personal) experience"},{"w":"Ereignis","en":"event, occurrence"}],"tip":"Ergebnis = result (of a test, a match). Erlebnis = an experience you personally live through (erleben). Ereignis = an event that happens (in the news).","items":[{"ans":"Ergebnis","de":"Das ___ der Prüfung bekommen wir nächste Woche.","en":"We will get the result of the exam next week."},{"ans":"Ergebnis","de":"Das vorläufige ___ der Wahl wurde am Abend bekannt gegeben.","en":"The provisional result of the election was announced in the evening."},{"ans":"Erlebnis","de":"Auf unserer Safari hatten wir ein ___, das wir nie vergessen werden: Ein Löwe stand direkt neben dem Jeep.","en":"On our safari we had an experience we will never forget: a lion stood right next to the jeep."},{"ans":"Erlebnis","de":"Sie erzählte begeistert von ihrem ___ mit den Delfinen.","en":"She told us enthusiastically about her experience with the dolphins."},{"ans":"Ereignis","de":"Die Mondlandung war ein historisches ___, das weltweit im Fernsehen übertragen wurde.","en":"The Moon landing was a historic event that was broadcast on television worldwide."},{"ans":"Ereignis","de":"In den Nachrichten war der Unfall das wichtigste ___ des Tages.","en":"In the news, the accident was the main event of the day."}]},
 {"id":"verbrauch-gebrauch-brauch","lv":"B2","words":[{"w":"Verbrauch","en":"consumption"},{"w":"Gebrauch","en":"use, usage"},{"w":"Brauch","en":"custom, tradition"}],"tip":"Verbrauch = consumption (Strom, Benzin). Gebrauch = use of a thing (Gebrauchsanweisung). Brauch = custom (Bräuche, Osterbrauch).","items":[{"ans":"Verbrauch","de":"Der ___ an Strom ist im Winter besonders hoch.","en":"Electricity consumption is particularly high in winter."},{"ans":"Verbrauch","de":"Das Auto hat einen niedrigen ___ von fünf Litern auf hundert Kilometer.","en":"The car has a low consumption of five litres per hundred kilometres."},{"ans":"Gebrauch","de":"Vor dem ersten ___ bitte die Anleitung lesen.","en":"Please read the instructions before first use."},{"ans":"Gebrauch","de":"Diese Salbe ist nur zum äußerlichen ___ bestimmt.","en":"This ointment is for external use only."},{"ans":"Brauch","de":"In unserem Dorf ist es ___, am 1. Mai einen Maibaum aufzustellen.","en":"In our village it is the custom to put up a maypole on 1 May."}]},
 {"id":"dann-denn-den","lv":"A2","words":[{"w":"dann","en":"then"},{"w":"denn","en":"because, for"},{"w":"den","en":"the (masc. Akk.)"}],"tip":"dann = then (adverb: the verb comes right after it: dann gehen wir). denn = because (conjunction: normal order, subject then verb: denn ich bin krank). den = article (masc. Akk.).","items":[{"ans":"dann","de":"Erst machen wir die Hausaufgaben, ___ spielen wir draußen.","en":"First we do our homework, then we play outside."},{"ans":"dann","de":"Zuerst essen wir, ___ gehen wir spazieren.","en":"First we eat, then we go for a walk."},{"ans":"denn","de":"Ich bleibe heute zu Hause, ___ ich bin krank.","en":"I'm staying at home today because I'm ill."},{"ans":"denn","de":"Sie ist müde, ___ sie hat die ganze Nacht gearbeitet.","en":"She is tired because she worked all night."},{"ans":"den","de":"Siehst du ___ Mann dort drüben?","en":"Do you see the man over there?"},{"ans":"den","de":"Kennst du ___ neuen Kollegen?","en":"Do you know the new colleague?"}]},
 {"id":"wen-wenn-wem","lv":"B1","words":[{"w":"wen","en":"whom (Akkusativ)"},{"w":"wenn","en":"if, when"},{"w":"wem","en":"to whom (Dativ)"}],"tip":"wen = whom (Akk.), wem = to/with whom (Dat.), wenn = if/when (conjunction). Check the verb: treffen + wen, gehören/helfen + wem.","items":[{"ans":"wen","de":"Weißt du, ___ sie gestern im Park getroffen hat?","en":"Do you know whom she met in the park yesterday?"},{"ans":"wen","de":"Ich möchte wissen, ___ du zur Party eingeladen hast.","en":"I'd like to know whom you've invited to the party."},{"ans":"wenn","de":"Ruf mich an, ___ du Zeit hast.","en":"Call me when you have time."},{"ans":"wenn","de":"Wir kommen später an, ___ der Zug Verspätung hat.","en":"We'll arrive later if the train is delayed."},{"ans":"wem","de":"Er fragt, ___ das Fahrrad gehört.","en":"He asks whom the bicycle belongs to."},{"ans":"wem","de":"Mit ___ hast du gestern gesprochen?","en":"Who did you speak to yesterday?"}]},
 {"id":"man-mann","lv":"A2","words":[{"w":"man","en":"one, you (impersonal)"},{"w":"Mann","en":"man; husband"}],"tip":"man (one n, lower case) = impersonal 'one/you'. der Mann (two n) = man/husband.","items":[{"ans":"man","de":"Wie schreibt ___ dieses Wort?","en":"How do you spell this word?"},{"ans":"man","de":"In Deutschland trinkt ___ oft Kaffee zum Frühstück.","en":"In Germany people often drink coffee with breakfast."},{"ans":"man","de":"Hier darf ___ nicht rauchen.","en":"You are not allowed to smoke here."},{"ans":"Mann","de":"Der ___ dort ist mein Lehrer.","en":"The man over there is my teacher."},{"ans":"Mann","de":"Ihr ___ arbeitet im Krankenhaus.","en":"Her husband works at the hospital."}]},
 {"id":"wohnen-wollen","lv":"A2","words":[{"w":"wohnen","en":"to live, to reside"},{"w":"wollen","en":"to want to"}],"tip":"wohnen = live somewhere (Wohnung). wollen = want to (modal verb + infinitive). wohnen has a long o, wollen a short o.","items":[{"ans":"wohnen","de":"Wir möchten gern in einer kleinen Wohnung am Stadtrand ___.","en":"We would like to live in a small flat on the outskirts of town."},{"ans":"wohnen","de":"Meine Eltern ___ schon seit zwanzig Jahren in diesem Haus.","en":"My parents have lived in this house for twenty years."},{"ans":"wollen","de":"Sie ___ nächstes Jahr heiraten.","en":"They want to get married next year."},{"ans":"wollen","de":"Wir ___ heute Abend ins Kino gehen.","en":"We want to go to the cinema this evening."}]},
 {"id":"leben-lieben-loben","lv":"A2","words":[{"w":"leben","en":"to live"},{"w":"lieben","en":"to love"},{"w":"loben","en":"to praise"}],"tip":"leben = be alive/live; lieben = love; loben = praise. Different vowels: e / ie / o.","items":[{"ans":"leben","de":"Meine Großeltern ___ auf dem Land.","en":"My grandparents live in the countryside."},{"ans":"leben","de":"Wir ___ seit zehn Jahren in der Schweiz.","en":"We have lived in Switzerland for ten years."},{"ans":"lieben","de":"Die beiden ___ sich so sehr, dass sie nie wieder getrennt sein wollen.","en":"The two love each other so much that they never want to be apart again."},{"ans":"lieben","de":"Wir ___ euch mehr als unser eigenes Leben.","en":"We love you more than our own life."},{"ans":"loben","de":"Der Chef wollte die Mitarbeiterin vor dem ganzen Team für ihre gute Arbeit ___.","en":"The boss wanted to praise the employee in front of the whole team for her good work."},{"ans":"loben","de":"Der Schüler hat die Aufgabe sehr gut gelöst, deshalb möchte die Lehrerin ihn ausdrücklich ___.","en":"The pupil solved the task very well, so the teacher would like to praise him explicitly."}]},
 {"id":"regel-regal-regen","lv":"A2","words":[{"w":"Regel","en":"rule"},{"w":"Regal","en":"shelf, bookcase"},{"w":"Regen","en":"rain"}],"tip":"die Regel = rule (Regeln). das Regal = shelf. der Regen = rain. Only the last letters differ.","items":[{"ans":"Regel","de":"Die wichtigste ___ lautet: Sei pünktlich.","en":"The most important rule is: be on time."},{"ans":"Regel","de":"Das ist gegen die ___, du darfst hier nicht parken.","en":"That is against the rules, you may not park here."},{"ans":"Regal","de":"Die Bücher stehen alle ordentlich im ___ im Wohnzimmer.","en":"All the books are neatly arranged on the shelf in the living room."},{"ans":"Regal","de":"Wir brauchen ein neues ___ für das Arbeitszimmer.","en":"We need a new shelf for the study."},{"ans":"Regen","de":"Heute Nachmittag gibt es ___.","en":"There will be rain this afternoon."},{"ans":"Regen","de":"Bei starkem ___ bleiben wir zu Hause.","en":"When it rains heavily we stay at home."}]},
 {"id":"tasse-tasche","lv":"A2","words":[{"w":"Tasse","en":"cup"},{"w":"Tasche","en":"bag, pocket"}],"tip":"die Tasse = cup (for coffee). die Tasche = bag or pocket. Only the ending differs: -sse vs -sche.","items":[{"ans":"Tasse","de":"Möchtest du noch eine ___ heißen Tee?","en":"Would you like another cup of hot tea?"},{"ans":"Tasse","de":"Ich trinke jeden Morgen eine große ___ Kaffee.","en":"Every morning I drink a big cup of coffee."},{"ans":"Tasche","de":"Ich habe mein Handy in der ___ vergessen.","en":"I left my phone in the bag."},{"ans":"Tasche","de":"Sie packte die Bücher in ihre ___.","en":"She packed the books into her bag."}]},
 {"id":"ohr-uhr","lv":"A2","words":[{"w":"Ohr","en":"ear"},{"w":"Uhr","en":"clock, watch; o'clock"}],"tip":"das Ohr = ear (O). die Uhr = clock/watch, and o'clock (drei Uhr; but: eine Stunde = an hour). The first letter is the only difference.","items":[{"ans":"Ohr","de":"Ich habe Schmerzen im linken ___.","en":"I have a pain in my left ear."},{"ans":"Ohr","de":"Sie flüsterte ihm etwas ins ___.","en":"She whispered something in his ear."},{"ans":"Uhr","de":"Es ist schon drei ___.","en":"It's already three o'clock."},{"ans":"Uhr","de":"Er trägt eine teure ___ am Handgelenk.","en":"He wears an expensive watch on his wrist."}]},
 {"id":"ei-eis-eisen","lv":"B1","words":[{"w":"Ei","en":"egg"},{"w":"Eis","en":"ice; ice cream"},{"w":"Eisen","en":"iron (metal)"}],"tip":"das Ei = egg. das Eis = ice or ice cream. das Eisen = iron (the metal). Watch the ending: Ei / Eis / Eisen.","items":[{"ans":"Ei","de":"Zum Frühstück esse ich ein gekochtes ___.","en":"For breakfast I eat a boiled egg."},{"ans":"Ei","de":"Der Koch schlägt ein ___ in die Pfanne.","en":"The cook cracks an egg into the pan."},{"ans":"Eis","de":"Im Sommer kaufen die Kinder am Kiosk ein ___ am Stiel.","en":"In summer the children buy an ice lolly at the kiosk."},{"ans":"Eis","de":"Im Winter ist der See mit ___ bedeckt.","en":"In winter the lake is covered with ice."},{"ans":"Eisen","de":"Die Brücke ist aus ___ gebaut und fängt langsam an zu rosten.","en":"The bridge is made of iron and is starting to rust."},{"ans":"Eisen","de":"Der Schmied schmiedet das glühende ___.","en":"The blacksmith forges the glowing iron."}]},
 {"id":"gast-gas","lv":"A2","words":[{"w":"Gast","en":"guest"},{"w":"Gas","en":"gas"}],"tip":"der Gast = guest (st). das Gas = gas. Plural: Gäste / Gase.","items":[{"ans":"Gast","de":"Wir haben heute Abend einen ___ zum Essen.","en":"We have a guest for dinner tonight."},{"ans":"Gast","de":"Der ___ im Hotel hat sich über den Lärm beschwert.","en":"The hotel guest complained about the noise."},{"ans":"Gas","de":"Die Heizung läuft mit ___.","en":"The heating runs on gas."},{"ans":"Gas","de":"Ich rieche ___ in der Küche, mach bitte das Fenster auf!","en":"I can smell gas in the kitchen, please open the window!"}]},
 {"id":"lust-last-list","lv":"B2","words":[{"w":"Lust","en":"desire, feeling like"},{"w":"Last","en":"load, burden"},{"w":"List","en":"cunning, ruse"}],"tip":"die Lust = desire (Lust haben auf). die Last = heavy load/burden. die List = cunning. One vowel decides: u / a / i.","items":[{"ans":"Lust","de":"Ich habe heute keine ___ zu kochen.","en":"I don't feel like cooking today."},{"ans":"Lust","de":"Hast du ___, mit mir ins Kino zu gehen?","en":"Do you feel like going to the cinema with me?"},{"ans":"Last","de":"Er trug die schwere ___ auf dem Rücken die Treppe hinauf.","en":"He carried the heavy load on his back up the stairs."},{"ans":"Last","de":"Die ___ der Verantwortung drückte ihn nieder.","en":"The burden of responsibility weighed him down."},{"ans":"List","de":"Mit einer ___ lockte der Fuchs den Hahn aus dem Stall.","en":"With a ruse the fox lured the rooster out of the coop."},{"ans":"List","de":"Sie erreichte ihr Ziel nicht durch Kraft, sondern durch ___.","en":"She reached her goal not through strength but through cunning."}]},
 {"id":"kind-kinn","lv":"A2","words":[{"w":"Kind","en":"child"},{"w":"Kinn","en":"chin"}],"tip":"das Kind = child (d). das Kinn = chin (nn). One letter different.","items":[{"ans":"Kind","de":"Das ___ spielt im Garten.","en":"The child is playing in the garden."},{"ans":"Kind","de":"Meine Schwester bekommt im Mai ein ___.","en":"My sister is having a baby in May."},{"ans":"Kinn","de":"Er hat sich beim Rasieren am ___ geschnitten.","en":"He cut his chin while shaving."},{"ans":"Kinn","de":"Er rieb sich nachdenklich das ___.","en":"He rubbed his chin thoughtfully."}]},
 {"id":"mund-mond","lv":"A2","words":[{"w":"Mund","en":"mouth"},{"w":"Mond","en":"moon"}],"tip":"der Mund = mouth (u). der Mond = moon (o). Both masculine, one vowel apart.","items":[{"ans":"Mund","de":"Mach bitte den ___ auf und sag „Ah“.","en":"Please open your mouth and say \"Ah\"."},{"ans":"Mund","de":"Sie hielt sich vor Schreck die Hand vor den ___.","en":"She put her hand over her mouth in fright."},{"ans":"Mond","de":"Heute Nacht scheint der ___ besonders hell.","en":"Tonight the moon is shining especially brightly."},{"ans":"Mond","de":"Der erste Mensch landete 1969 auf dem ___.","en":"The first person landed on the moon in 1969."}]},
 {"id":"schule-schuld-schulden","lv":"B1","words":[{"w":"Schule","en":"school"},{"w":"Schuld","en":"guilt, blame, fault"},{"w":"Schulden","en":"debts"}],"tip":"die Schule = school. die Schuld = guilt or blame (Es ist meine Schuld). Schulden (pl.) = debts (Schulden haben).","items":[{"ans":"Schule","de":"Mein Sohn ist sechs Jahre alt und kommt im Herbst in die ___.","en":"My son is six years old and starts school in autumn."},{"ans":"Schule","de":"Nach der ___ gehe ich zum Fußballtraining.","en":"After school I go to football practice."},{"ans":"Schuld","de":"Es war nicht deine ___, dass der Zug ausfiel.","en":"It wasn't your fault that the train was cancelled."},{"ans":"Schuld","de":"Er gab die ___ am Unfall dem anderen Fahrer.","en":"He blamed the other driver for the accident."},{"ans":"Schulden","de":"Seine ___ bei der Bank sind inzwischen auf 5000 Euro gestiegen.","en":"His debts to the bank have now risen to 5,000 euros."},{"ans":"Schulden","de":"Viele junge Leute machen ___, um sich ein Auto zu kaufen.","en":"Many young people go into debt to buy a car."}]},
 {"id":"haus-haut","lv":"A2","words":[{"w":"Haus","en":"house"},{"w":"Haut","en":"skin"}],"tip":"das Haus = house (s). die Haut = skin (t). Only the last letter differs: s vs t.","items":[{"ans":"Haus","de":"Wir wohnen in einem kleinen ___ am Stadtrand.","en":"We live in a small house on the outskirts of town."},{"ans":"Haus","de":"Das ___ hat einen großen Garten.","en":"The house has a big garden."},{"ans":"Haut","de":"Im Sommer muss man seine ___ vor der Sonne schützen.","en":"In summer you have to protect your skin from the sun."},{"ans":"Haut","de":"Meine ___ ist im Winter sehr trocken.","en":"My skin is very dry in winter."}]},
 {"id":"stein-stern","lv":"A2","words":[{"w":"Stein","en":"stone"},{"w":"Stern","en":"star"}],"tip":"der Stein = stone. der Stern = star. Both masculine; one letter differs: i vs r.","items":[{"ans":"Stein","de":"Das Kind stolperte über einen ___ auf dem Weg.","en":"The child tripped over a stone on the path."},{"ans":"Stein","de":"Die Burg ist ganz aus ___ gebaut.","en":"The castle is built entirely of stone."},{"ans":"Stern","de":"Am Himmel leuchtet ein heller ___.","en":"A bright star is shining in the sky."},{"ans":"Stern","de":"Der Polarstern ist ein ___, der immer im Norden steht.","en":"The Pole Star is a star that always stands in the north."}]},
 {"id":"herr-heer-her","lv":"C1","words":[{"w":"Herr","en":"gentleman, Mr; lord"},{"w":"Heer","en":"army; host"},{"w":"her","en":"here, hither (towards the speaker)"}],"tip":"der Herr = Mr/gentleman (short e). das Heer = army (or a great host). her = towards the speaker (komm her!). Heer and her sound the same (long e); Herr has a short e.","items":[{"ans":"Herr","de":"Der ___ dort drüben hat nach Ihnen gefragt.","en":"The gentleman over there asked for you."},{"ans":"Herr","de":"Sehr geehrter ___ Meier, vielen Dank für Ihre Nachricht.","en":"Dear Mr Meier, thank you for your message."},{"ans":"Heer","de":"Das ___ marschierte über die Grenze.","en":"The army marched across the border."},{"ans":"Heer","de":"Ein ganzes ___ von Touristen fiel in die Altstadt ein.","en":"A whole army of tourists descended on the old town."},{"ans":"her","de":"Komm bitte sofort ___!","en":"Come here at once, please!"},{"ans":"her","de":"Wo kommst du eigentlich ___?","en":"Where do you actually come from?"}]},
 {"id":"gelaende-gelaender","lv":"B2","words":[{"w":"Gelände","en":"terrain, grounds, site"},{"w":"Geländer","en":"railing, banister"}],"tip":"das Gelände = terrain/grounds (Fabrikgelände). das Geländer = railing on stairs or a balcony (one extra letter: -r).","items":[{"ans":"Gelände","de":"Das ___ rund um die Burg ist sehr hügelig.","en":"The terrain around the castle is very hilly."},{"ans":"Gelände","de":"Wir wanderten durch unwegsames ___.","en":"We hiked through rough terrain."},{"ans":"Geländer","de":"Halten Sie sich auf der Treppe bitte am ___ fest.","en":"Please hold on to the banister on the stairs."},{"ans":"Geländer","de":"Das ___ auf dem Balkon ist schon ziemlich rostig.","en":"The railing on the balcony is already quite rusty."}]},
 {"id":"gewaehr-gewehr","lv":"C1","words":[{"w":"Gewähr","en":"guarantee, warranty"},{"w":"Gewehr","en":"rifle"}],"tip":"die Gewähr = guarantee (ohne Gewähr, Gewähr leisten/übernehmen). das Gewehr = rifle, gun. Almost the same sound, different spelling (ä + h vs e + h).","items":[{"ans":"Gewähr","de":"Alle Angaben erfolgen ohne ___.","en":"All information is provided without guarantee."},{"ans":"Gewähr","de":"Für die Richtigkeit dieser Angaben übernehmen wir keine ___.","en":"We accept no guarantee for the correctness of this information."},{"ans":"Gewehr","de":"Der Jäger lud sein ___ und ging in den Wald.","en":"The hunter loaded his rifle and went into the forest."},{"ans":"Gewehr","de":"Der Soldat hängte sich das ___ über die Schulter.","en":"The soldier slung his rifle over his shoulder."}]},
 {"id":"kohl-kohle","lv":"B1","words":[{"w":"Kohl","en":"cabbage"},{"w":"Kohle","en":"coal"}],"tip":"der Kohl = cabbage (vegetable). die Kohle = coal (fuel; also slang for money). Only the final -e differs, and the gender changes.","items":[{"ans":"Kohl","de":"Im Garten wachsen Salat, Möhren und ___.","en":"In the garden, lettuce, carrots and cabbage are growing."},{"ans":"Kohl","de":"Der Bauer erntet im Herbst den ___ und den Lauch.","en":"In autumn the farmer harvests the cabbage and the leeks."},{"ans":"Kohle","de":"Früher heizte man die Wohnungen oft mit ___.","en":"In the past, flats were often heated with coal."},{"ans":"Kohle","de":"Im Ruhrgebiet wurde jahrzehntelang ___ abgebaut.","en":"In the Ruhr region coal was mined for decades."}]},
 {"id":"scheinbar-anscheinend","lv":"C1","words":[{"w":"scheinbar","en":"seemingly, only on the surface (but not really so)"},{"w":"anscheinend","en":"apparently, it seems that (probably true)"}],"tip":"scheinbar = it only looks that way, but it is an illusion; anscheinend = judging by the evidence it is probably really so. Only \"scheinbar\" can be used as a predicate: \"nur scheinbar\". (In casual speech scheinbar is often used for anscheinend, but standard usage keeps them apart.)","items":[{"ans":"scheinbar","de":"Der Widerspruch ist nur ___; bei genauerem Hinsehen löst er sich auf.","en":"The contradiction is only apparent; on closer inspection it dissolves."},{"ans":"scheinbar","de":"Der Zauberer zersägte seine Assistentin ___ in zwei Hälften, in Wirklichkeit war alles nur ein Trick.","en":"The magician seemingly sawed his assistant in two; in reality it was all just a trick."},{"ans":"anscheinend","de":"Das Konzert fällt ___ aus; auf der Homepage steht eine Absage.","en":"The concert is apparently cancelled; there is a cancellation notice on the website."},{"ans":"anscheinend","de":"Es hat ___ die ganze Nacht geregnet, die Straßen sind noch ganz nass.","en":"It seems to have rained all night; the streets are still completely wet."}]},
 {"id":"kennen-wissen-koennen","lv":"A2","words":[{"w":"kennen","en":"to know (a person, place, thing)"},{"w":"wissen","en":"to know (a fact)"},{"w":"können","en":"to know how to, to be able to"}],"tip":"kennen = be acquainted with people/places/things; wissen = know a fact (often followed by dass / ob / a question word); können = know a skill or language (can do it).","items":[{"ans":"kennen","de":"Ich möchte meinen Nachbarn gern besser ___.","en":"I would like to know my neighbour better."},{"ans":"kennen","de":"Du musst diese Stadt nicht ___, ich zeige dir alles.","en":"You don't need to know this city; I'll show you everything."},{"ans":"wissen","de":"Wir müssen unbedingt ___, ob der Laden heute geöffnet ist.","en":"We absolutely have to know whether the shop is open today."},{"ans":"wissen","de":"Ich möchte gern ___, wo du gestern Abend warst.","en":"I would like to know where you were last night."},{"ans":"können","de":"Mein Sohn will bald schwimmen ___.","en":"My son wants to be able to swim soon."},{"ans":"können","de":"Sie möchte unbedingt Klavier spielen ___.","en":"She really wants to be able to play the piano."}]},
 {"id":"lernen-lehren-studieren-unterrichten","lv":"B1","words":[{"w":"lernen","en":"to learn"},{"w":"lehren","en":"to teach (a skill/idea to someone)"},{"w":"studieren","en":"to study (at university)"},{"w":"unterrichten","en":"to teach (a class/subject)"}],"tip":"lernen = learn; lehren = teach someone something (jdn. etwas lehren, rather formal); unterrichten = teach a class/subject at school; studieren = study at a university.","items":[{"ans":"lernen","de":"Meine Tochter geht in die erste Klasse und muss noch ___, flüssig zu lesen.","en":"My daughter is in first grade and still has to learn to read fluently."},{"ans":"lehren","de":"Die Erfahrung wird ihn noch ___, vorsichtiger zu sein.","en":"Experience will yet teach him to be more careful."},{"ans":"studieren","de":"Nach dem Abitur will sie sich an der Universität einschreiben und Medizin ___, um Ärztin zu werden.","en":"After her Abitur she wants to enrol at university and study medicine in order to become a doctor."},{"ans":"unterrichten","de":"Sie muss morgens um acht die Klasse 7b in Mathe ___.","en":"She has to teach class 7b maths at eight in the morning."}]},
 {"id":"als-wenn-wann-ob","lv":"B1","words":[{"w":"als","en":"when (single event in the past)"},{"w":"wenn","en":"when, whenever, if"},{"w":"wann","en":"when (question about time)"},{"w":"ob","en":"whether, if"}],"tip":"als = one event or period in the past; wenn = present/future or repeated events (\"whenever\"); wann = question word about time; ob = indirect yes/no question.","items":[{"ans":"als","de":"Damals, ___ ich ein Kind war, wohnten wir in Köln.","en":"Back then, when I was a child, we lived in Cologne."},{"ans":"als","de":"Ich stand gerade unter der Dusche, ___ das Telefon klingelte.","en":"I was just in the shower when the phone rang."},{"ans":"wenn","de":"Immer ___ es regnet, bleibt er zu Hause.","en":"Whenever it rains, he stays at home."},{"ans":"wenn","de":"Ich rufe dich an, ___ ich in Berlin angekommen bin.","en":"I'll call you when I have arrived in Berlin."},{"ans":"wann","de":"Seit ___ lernst du schon Deutsch?","en":"Since when have you been learning German?"},{"ans":"ob","de":"Ich weiß nicht, ___ ich die Stelle annehmen soll oder nicht.","en":"I don't know whether I should accept the job or not."},{"ans":"ob","de":"Sie fragte mich, ___ ich Hunger hätte oder nicht.","en":"She asked me whether I was hungry or not."}]},
 {"id":"sondern-aber","lv":"A2","words":[{"w":"sondern","en":"but (rather) – after a negation"},{"w":"aber","en":"but"}],"tip":"sondern corrects a negation (\"not X, but Y\") and is fixed in \"nicht nur ..., sondern auch\" (not only ... but also); aber just adds a contrast without correcting anything.","items":[{"ans":"sondern","de":"Nicht Anna hat angerufen, ___ ihr Bruder.","en":"It wasn't Anna who called but her brother."},{"ans":"sondern","de":"Er ist nicht nur klug, ___ auch sehr fleißig.","en":"He is not only clever but also very hard-working."},{"ans":"aber","de":"Die Wohnung ist klein, ___ sehr gemütlich.","en":"The flat is small, but very cosy."},{"ans":"aber","de":"Ich würde gern kommen, ___ ich habe leider keine Zeit.","en":"I would love to come, but unfortunately I have no time."}]},
 {"id":"bekommen-werden","lv":"A2","words":[{"w":"bekommen","en":"to get, to receive (NOT: to become)"},{"w":"werden","en":"to become, to get (+ adjective/noun)"}],"tip":"English \"become\" = werden. German bekommen means \"to get/receive\". Only werden links to an adjective or job: kalt werden, Pilot werden.","items":[{"ans":"bekommen","de":"Zum Geburtstag möchte ich ein neues Fahrrad ___.","en":"For my birthday I would like to get a new bicycle."},{"ans":"bekommen","de":"Hast du meine Nachricht ___?","en":"Did you get my message?"},{"ans":"werden","de":"Ich möchte später einmal Pilot ___.","en":"I would like to become a pilot one day."},{"ans":"werden","de":"Im Winter kann es in den Bergen sehr kalt ___.","en":"In winter it can get very cold in the mountains."}]},
 {"id":"stellen-legen-setzen-stecken","lv":"B1","words":[{"w":"stellen","en":"to put (upright), to stand"},{"w":"legen","en":"to lay, to put (flat)"},{"w":"setzen","en":"to seat, to set (a person)"},{"w":"stecken","en":"to stick, to plug in"}],"tip":"Think of the position: stellen = upright; legen = flat; setzen = sitting (a person); stecken = push something into a hole or opening.","items":[{"ans":"stellen","de":"Du kannst dein Auto über Nacht in unsere Garage ___.","en":"You can put your car in our garage overnight."},{"ans":"legen","de":"Kannst du das Handy bitte flach auf den Tisch ___?","en":"Can you lay the phone flat on the table, please?"},{"ans":"legen","de":"Die Hühner sollen im Frühling wieder Eier ___.","en":"The hens are supposed to lay eggs again in spring."},{"ans":"setzen","de":"Bitte ___ Sie sich, der Film beginnt gleich.","en":"Please take your seats, the film is about to start."},{"ans":"stecken","de":"Du musst den Stecker richtig in die Steckdose ___.","en":"You have to push the plug properly into the socket."}]},
 {"id":"liegen-stehen-sitzen-haengen","lv":"A2","words":[{"w":"liegen","en":"to lie, to be located (flat)"},{"w":"stehen","en":"to stand"},{"w":"sitzen","en":"to sit"},{"w":"hängen","en":"to hang (be hanging)"}],"tip":"Position verbs for \"where is it?\": liegen = flat, stehen = upright, sitzen = seated, hängen = suspended. (With a movement use legen / stellen / setzen / hängen.)","items":[{"ans":"liegen","de":"Mein Handy muss irgendwo zwischen den Sofakissen ___.","en":"My phone must be lying somewhere between the sofa cushions."},{"ans":"stehen","de":"Die Flaschen sollen aufrecht im Kühlschrank ___.","en":"The bottles should stand upright in the fridge."},{"ans":"stehen","de":"Das Auto darf hier nicht ___, es ist Parkverbot.","en":"The car can't stay here; it's a no-parking zone."},{"ans":"sitzen","de":"Die Kinder sollen beim Essen ruhig am Tisch ___ und nicht dauernd aufstehen.","en":"The children are supposed to sit quietly at the table during the meal and not keep getting up."},{"ans":"hängen","de":"Wir haben den Nagel schon eingeschlagen: Das Bild soll über dem Sofa ___.","en":"We've already hammered in the nail: the picture is supposed to hang above the sofa."},{"ans":"hängen","de":"Im Flur soll mein Mantel an der Garderobe ___.","en":"My coat is supposed to hang on the coat rack in the hallway."}]},
 {"id":"ansehen-zusehen-aussehen-nachsehen","lv":"B2","words":[{"w":"ansehen","en":"to look at, to watch (sich etwas ansehen)"},{"w":"zusehen","en":"to watch (someone doing something)"},{"w":"aussehen","en":"to look (like), to appear"},{"w":"nachsehen","en":"to look up, to check"}],"tip":"ansehen = look at an object (+ Akk.); zusehen = watch an activity (+ Dat., often beim ...); aussehen = appearance; nachsehen = check/look something up.","items":[{"ans":"ansehen","de":"Wir wollen uns heute Abend den neuen Film ___.","en":"We want to watch the new film this evening."},{"ans":"zusehen","de":"Die Kinder durften dem Bäcker beim Brotbacken ___.","en":"The children were allowed to watch the baker baking bread."},{"ans":"aussehen","de":"Auf dem Foto wirst du bestimmt ganz anders ___ als in Wirklichkeit.","en":"In the photo you will certainly look quite different from real life."},{"ans":"nachsehen","de":"Ich muss kurz im Wörterbuch ___, wie man das Wort schreibt.","en":"I have to check in the dictionary how to spell the word."}]},
 {"id":"hoeren-zuhoeren-gehoeren-aufhoeren","lv":"A2","words":[{"w":"hören","en":"to hear"},{"w":"zuhören","en":"to listen (to someone)"},{"w":"gehören","en":"to belong to"},{"w":"aufhören","en":"to stop, to cease"}],"tip":"hören = perceive a sound; zuhören = listen attentively (+ Dat.); gehören = belong (+ Dat.); aufhören = stop.","items":[{"ans":"hören","de":"Ich konnte gestern Abend die Nachbarn laut streiten ___.","en":"Last night I could hear the neighbours arguing loudly."},{"ans":"zuhören","de":"Die Kinder sollen dem Lehrer aufmerksam ___.","en":"The children are supposed to listen attentively to the teacher."},{"ans":"gehören","de":"Wem kann dieser Schirm wohl ___?","en":"Whom might this umbrella belong to?"},{"ans":"aufhören","de":"Es wird bestimmt bald ___ zu regnen.","en":"It will surely stop raining soon."}]},
 {"id":"fahren-gehen-laufen","lv":"A2","words":[{"w":"fahren","en":"to go by vehicle, to drive, to ride"},{"w":"gehen","en":"to go, to walk"},{"w":"laufen","en":"to run, to jog"}],"tip":"fahren = with any vehicle (bus, car, bike), also: drive a vehicle (das Auto fahren); gehen = on foot (or \"go\" in general: ins Bett gehen); laufen = run (colloquially, very common, also: walk, go on foot).","items":[{"ans":"fahren","de":"Kannst du heute Abend das Auto ___? Ich habe Wein getrunken.","en":"Can you drive the car tonight? I've had some wine."},{"ans":"fahren","de":"Ich möchte endlich Fahrrad ___ lernen.","en":"I finally want to learn to ride a bike."},{"ans":"gehen","de":"Ich möchte heute Abend früh ins Bett ___.","en":"I would like to go to bed early tonight."},{"ans":"laufen","de":"Mein Bruder hat sich neue Laufschuhe gekauft, weil er nächstes Jahr einen Marathon ___ will.","en":"My brother has bought new running shoes because he wants to run a marathon next year."}]},
 {"id":"bringen-holen","lv":"B1","words":[{"w":"bringen","en":"to take/bring (to a place or person)"},{"w":"holen","en":"to fetch, to go and get"}],"tip":"bringen = take/carry something to a place or person; holen = go and get something from where it is.","items":[{"ans":"bringen","de":"Dein Bruder kann uns morgen früh zum Bahnhof ___, er hat ja ein Auto.","en":"Your brother can take us to the station tomorrow morning; he has a car, after all."},{"ans":"bringen","de":"Der Postbote soll das Paket zu meiner Nachbarin ___.","en":"The postman is supposed to take the parcel to my neighbour."},{"ans":"holen","de":"Ich gehe nur schnell beim Bäcker ein paar Brötchen ___.","en":"I'll just quickly go and get a few rolls at the baker's."},{"ans":"holen","de":"Die Frau geht zum Brunnen, um Wasser zu ___.","en":"The woman goes to the well to fetch water."}]},
 {"id":"mieten-vermieten-ausleihen-verleihen","lv":"B2","words":[{"w":"mieten","en":"to rent (as a tenant)"},{"w":"vermieten","en":"to rent out (as a landlord)"},{"w":"ausleihen","en":"to borrow (also: to lend out)"},{"w":"verleihen","en":"to lend out; to award"}],"tip":"mieten = pay to use; vermieten = let it out for money; ausleihen = borrow (sich etwas ausleihen; libraries also \"leihen Bücher aus\" = lend them out); verleihen = lend out (free or for a fee: Fahrradverleih), or award (einen Preis verleihen).","items":[{"ans":"mieten","de":"Ich suche eine Wohnung, die ich für höchstens 800 Euro im Monat ___ kann.","en":"I'm looking for a flat that I can rent for 800 euros a month at most."},{"ans":"vermieten","de":"Er will seine Wohnung für ein Jahr an Studenten ___ und dafür monatlich Miete kassieren.","en":"He wants to rent out his flat to students for a year and collect rent every month."},{"ans":"ausleihen","de":"Ich möchte mir in der Bibliothek zwei Bücher ___.","en":"I would like to borrow two books from the library."},{"ans":"verleihen","de":"Die Universität will der Forscherin einen Preis ___.","en":"The university wants to award the researcher a prize."},{"ans":"verleihen","de":"Die Stadt will dem Schriftsteller die Ehrenbürgerwürde ___.","en":"The city wants to confer honorary citizenship on the writer."}]},
 {"id":"selten-seltsam","lv":"B1","words":[{"w":"selten","en":"rarely, seldom"},{"w":"seltsam","en":"strange, odd"}],"tip":"selten = not often (frequency); seltsam = strange (like komisch). English \"seldom\" = selten, not seltsam.","items":[{"ans":"selten","de":"Er besucht uns nur noch ___, früher kam er jede Woche.","en":"He now only visits us rarely; he used to come every week."},{"ans":"selten","de":"Schnee fällt in dieser Region nur ___, höchstens einmal pro Jahr.","en":"Snow falls only rarely in this region, at most once a year."},{"ans":"seltsam","de":"Ich finde es ___, dass er nie anruft.","en":"I find it strange that he never calls."},{"ans":"seltsam","de":"Das Essen schmeckt ___, ich glaube, es ist verdorben.","en":"The food tastes odd; I think it has gone off."}]},
 {"id":"sensibel-sentimental","lv":"C1","words":[{"w":"sensibel","en":"sensitive (emotionally; delicate)"},{"w":"sentimental","en":"sentimental, nostalgic"}],"tip":"sensibel = sensitive (feelings, delicate topics); sentimental = nostalgic or mushy. English \"sensitive\" is not \"sentimental\".","items":[{"ans":"sensibel","de":"Unsere Tochter ist sehr ___ und zuckt schon bei einem lauten Wort zusammen.","en":"Our daughter is very sensitive and flinches at a single loud word."},{"ans":"sensibel","de":"Das Thema ist politisch sehr ___, deshalb sollten wir vorsichtig formulieren.","en":"The topic is politically very sensitive, so we should word it carefully."},{"ans":"sentimental","de":"Beim Anblick der alten Fotos wurde er ganz ___ und schwelgte in Erinnerungen.","en":"At the sight of the old photos he became quite sentimental and lost himself in memories."},{"ans":"sentimental","de":"Ich bin nicht ___, aber diese alte Uhr behalte ich, weil sie meinem Vater gehörte.","en":"I'm not sentimental, but I'm keeping this old watch because it belonged to my father."}]},
 {"id":"brauchen-benutzen-verwenden","lv":"B1","words":[{"w":"brauchen","en":"to need; to take (time)"},{"w":"benutzen","en":"to use (a thing); to use, exploit (a person)"},{"w":"verwenden","en":"to use (for a purpose); to spend (time, effort) on"}],"tip":"brauchen = need (also: take time); benutzen = use a thing or facility, also: use/exploit a person; verwenden = use for a purpose, also: spend time/effort on something (Zeit auf etwas verwenden). For things, benutzen and verwenden often overlap.","items":[{"ans":"brauchen","de":"Für die Strecke wird der Zug bestimmt zwei Stunden ___.","en":"The train will certainly take two hours for the route."},{"ans":"brauchen","de":"Ich werde bestimmt nicht lange ___.","en":"I certainly won't take long."},{"ans":"benutzen","de":"Merkst du nicht, dass er dich nur ___ will?","en":"Don't you notice that he only wants to use you?"},{"ans":"verwenden","de":"Du solltest mehr Zeit auf die Vorbereitung ___.","en":"You should spend more time on the preparation."}]},
 {"id":"verlieren-verpassen-vermissen","lv":"B1","words":[{"w":"verlieren","en":"to lose"},{"w":"verpassen","en":"to miss (a train, chance)"},{"w":"vermissen","en":"to miss (a person or thing); vermisst = missing"}],"tip":"English \"miss\" has two German equivalents: verpassen = fail to catch (train, chance); vermissen = feel the absence of someone; verlieren = lose.","items":[{"ans":"verlieren","de":"Du darfst deinen Schlüssel auf keinen Fall ___!","en":"You must not lose your key under any circumstances!"},{"ans":"verlieren","de":"Er hat Angst, seinen Job zu ___.","en":"He is afraid of losing his job."},{"ans":"verpassen","de":"Wenn wir nicht bald losgehen, werden wir den Zug ___.","en":"If we don't leave soon, we will miss the train."},{"ans":"vermissen","de":"Ich werde dich sehr ___, wenn du nach Kanada ziehst.","en":"I will miss you a lot when you move to Canada."}]},
 {"id":"nehmen-mitnehmen-annehmen-abnehmen","lv":"B2","words":[{"w":"nehmen","en":"to take"},{"w":"mitnehmen","en":"to take along; to give a lift"},{"w":"annehmen","en":"to accept; to assume"},{"w":"abnehmen","en":"to lose weight; to take off/from"}],"tip":"The prefix changes the verb: mit- = along, an- = accept/assume, ab- = off (abnehmen = lose weight).","items":[{"ans":"nehmen","de":"Wir sollten lieber die U-Bahn ___, das geht schneller.","en":"We should rather take the underground; it's faster."},{"ans":"mitnehmen","de":"Kannst du mich morgen im Auto nach Köln ___?","en":"Can you give me a lift to Cologne in your car tomorrow?"},{"ans":"annehmen","de":"Wir dürfen wohl ___, dass er nicht mehr kommt.","en":"We may well assume that he isn't coming any more."},{"ans":"abnehmen","de":"Mit dieser Diät möchte ich bis zum Sommer drei Kilo ___.","en":"With this diet I would like to lose three kilos by summer."}]},
 {"id":"fast-kaum","lv":"B1","words":[{"w":"fast","en":"almost, nearly"},{"w":"kaum","en":"hardly, barely"}],"tip":"fast = almost (nearly all, nearly always); kaum = hardly (almost none). \"fast kein\" ≈ \"kaum\".","items":[{"ans":"fast","de":"Ich bin ___ jeden Tag mit dem Rad zur Arbeit gefahren, nur dienstags nicht.","en":"I rode my bike to work almost every day, just not on Tuesdays."},{"ans":"fast","de":"Wir haben ___ alle Tickets verkauft; nur noch drei sind übrig.","en":"We have sold almost all the tickets; only three are left."},{"ans":"kaum","de":"Es ist so laut hier, dass man sein eigenes Wort ___ versteht.","en":"It's so loud here that you can hardly understand your own words."},{"ans":"kaum","de":"Wir kennen uns erst seit Montag, ich weiß ___ etwas über ihn.","en":"We've only known each other since Monday; I hardly know anything about him."}]},
 {"id":"schon-erst-noch-nur","lv":"A2","words":[{"w":"schon","en":"already"},{"w":"erst","en":"only (not until now), just"},{"w":"noch","en":"still, yet; another"},{"w":"nur","en":"only, just (limiting amount)"}],"tip":"schon = already (earlier than expected); erst = only/not until now (later or less than expected); noch = still / not yet; nur = only (just a small amount).","items":[{"ans":"schon","de":"Du bist ___ fertig? Das ging aber schnell!","en":"You're finished already? That was quick!"},{"ans":"erst","de":"Leider kommt das Paket ___ morgen an, ich brauche es aber heute.","en":"Unfortunately the parcel won't arrive until tomorrow, but I need it today."},{"ans":"noch","de":"Wir haben bis heute ___ keine Antwort bekommen.","en":"We still haven't received an answer to this day."},{"ans":"nur","de":"Sie spricht nicht ___ Deutsch, sondern auch Französisch.","en":"She speaks not only German but also French."}]},
 {"id":"aktuell-tatsaechlich","lv":"B2","words":[{"w":"aktuell","en":"current, up to date (NOT: actual)"},{"w":"tatsächlich","en":"actually, really, in fact"}],"tip":"English \"actual(ly)\" = tatsächlich (in fact, really). German aktuell means \"current, up to date\", never \"actual\".","items":[{"ans":"aktuell","de":"Die Nachrichten auf dieser Seite sind immer ___ und gut recherchiert.","en":"The news on this site is always up to date and well researched."},{"ans":"aktuell","de":"Dieser Reiseführer ist leider nicht mehr ___; viele Preise stimmen nicht mehr.","en":"Unfortunately this guidebook is no longer up to date; many prices are wrong now."},{"ans":"tatsächlich","de":"Ich habe vermutet, dass der Zug Verspätung hat, und ___: Er kam eine halbe Stunde später.","en":"I suspected the train was delayed, and sure enough, it arrived half an hour late."},{"ans":"tatsächlich","de":"Er hat gekündigt. – Ach, ___?","en":"He has quit. – Oh, really?"}]},
 {"id":"damit-dafuer-deshalb","lv":"B1","words":[{"w":"damit","en":"so that; with it"},{"w":"dafür","en":"for it; in return, on the other hand"},{"w":"deshalb","en":"therefore, that's why"}],"tip":"damit (conjunction, \"so that\") sends the verb to the end: \"..., damit ich ... kann\"; damit can also mean \"with it\" (zufrieden damit). deshalb = that's why; at the start of a clause the verb follows directly (deshalb bin ich ...), also \"nur deshalb ..., weil\"; dafür = \"for that / on the other hand\".","items":[{"ans":"damit","de":"Ich nehme einen Stift mit, ___ ich mir alles notieren kann.","en":"I'll take a pen with me so that I can note everything down."},{"ans":"damit","de":"Er hat ein neues Handy gekauft und ist sehr zufrieden ___.","en":"He has bought a new phone and is very happy with it."},{"ans":"dafür","de":"Das Auto ist alt, ___ aber sehr zuverlässig.","en":"The car is old, but on the other hand very reliable."},{"ans":"dafür","de":"Ich bin leider nicht ___ zuständig.","en":"Unfortunately I'm not responsible for that."},{"ans":"deshalb","de":"Er hat nur ___ angerufen, weil er Geld von mir will.","en":"He only called because he wants money from me."},{"ans":"deshalb","de":"Ich habe verschlafen, ___ bin ich zu spät gekommen.","en":"I overslept, that's why I was late."}]},
 {"id":"waehrend-wegen-trotz-statt","lv":"B1","words":[{"w":"während","en":"during (+ Gen.)"},{"w":"wegen","en":"because of (+ Gen.)"},{"w":"trotz","en":"despite (+ Gen.)"},{"w":"statt","en":"instead of (+ Gen.)"}],"tip":"All four take the genitive: während = time, wegen = reason, trotz = contrast, statt = replacement.","items":[{"ans":"während","de":"Bitte telefoniert nicht ___ des Unterrichts, sondern erst in der Pause.","en":"Please don't make phone calls during the lesson, only in the break."},{"ans":"während","de":"Er hat ___ des ganzen Films ununterbrochen Popcorn gegessen.","en":"He ate popcorn non-stop during the whole film."},{"ans":"wegen","de":"Der Verein nimmt ___ Platzmangels keine neuen Mitglieder mehr auf.","en":"The club is no longer accepting new members because of a lack of space."},{"ans":"trotz","de":"Sie ist ___ ihres hohen Alters noch topfit.","en":"She is still in top shape despite her great age."},{"ans":"statt","de":"Sie hat sich ___ eines Autos ein Fahrrad gekauft; ein Auto hat sie nicht.","en":"She bought herself a bicycle instead of a car; she doesn't have a car."}]},
 {"id":"denn-weil-obwohl-deshalb","lv":"B1","words":[{"w":"denn","en":"because, for (verb in position 2)"},{"w":"weil","en":"because (verb at the end)"},{"w":"obwohl","en":"although"},{"w":"deshalb","en":"therefore (verb right after it)"}],"tip":"denn = because with normal word order; weil = because, verb at the end; obwohl = although (contrast); deshalb = therefore, verb directly after it. (\"weil\" with the verb in position 2 is heard in casual speech but is not standard German.)","items":[{"ans":"denn","de":"Ich bleibe heute zu Hause, ___ ich bin krank.","en":"I'm staying at home today because I'm ill."},{"ans":"denn","de":"Wir nehmen ein Taxi, ___ der Bus fährt nur einmal pro Stunde.","en":"We'll take a taxi, because the bus only runs once an hour."},{"ans":"weil","de":"Ich finde es nicht gut, nur ___ alle anderen es gut finden.","en":"I don't think it's good just because everyone else thinks it is."},{"ans":"obwohl","de":"Er geht zur Arbeit, ___ er Fieber hat.","en":"He goes to work although he has a fever."},{"ans":"obwohl","de":"Sie hat die Prüfung bestanden, ___ sie kaum gelernt hat.","en":"She passed the exam although she hardly studied."},{"ans":"deshalb","de":"Er hat Fieber, ___ geht er heute nicht zur Arbeit.","en":"He has a fever, so he isn't going to work today."}]},
 {"id":"ordentlich-ordinaer","lv":"C1","words":[{"w":"ordentlich","en":"tidy, neat, decent"},{"w":"ordinär","en":"vulgar, crude (usually NOT: ordinary)"}],"tip":"ordentlich = tidy, neat, decent; ordinär = vulgar, crude (false friend of \"ordinary\" – English \"ordinary\" is gewöhnlich).","items":[{"ans":"ordentlich","de":"Seine Wohnung ist immer sehr ___: Alles hat seinen Platz.","en":"His flat is always very tidy: everything has its place."},{"ans":"ordinär","de":"Sein Humor ist mir zu ___; solche Witze mag ich nicht.","en":"His humour is too vulgar for me; I don't like jokes like that."},{"ans":"ordentlich","de":"Mein Zimmer ist nicht sehr ___, aber ich finde alles sofort.","en":"My room isn't very tidy, but I find everything straight away."},{"ans":"ordinär","de":"Sie fand seine Ausdrucksweise ___ und verließ den Raum.","en":"She found his way of speaking vulgar and left the room."}]},
 {"id":"gift-geschenk-gabe","lv":"B1","words":[{"w":"Gift","en":"poison (NOT: gift)"},{"w":"Geschenk","en":"present, gift"},{"w":"Gabe","en":"talent, gift; offering"}],"tip":"English \"gift\" = Geschenk (present) or Gabe (talent). German Gift is poison!","items":[{"ans":"Gift","de":"Die Pilze enthalten ein tödliches ___.","en":"The mushrooms contain a deadly poison."},{"ans":"Gift","de":"Die Schlange spritzte ihrem Opfer ihr ___ ein.","en":"The snake injected its poison into its victim."},{"ans":"Geschenk","de":"Zum Geburtstag habe ich ein tolles ___ bekommen.","en":"I got a great present for my birthday."},{"ans":"Gabe","de":"Sie hat die ___, Menschen mit ihren Geschichten zu fesseln.","en":"She has the gift of captivating people with her stories."}]},
 {"id":"erlaubnis-erlebnis-ergebnis-erfahrung","lv":"B1","words":[{"w":"Erlaubnis","en":"permission"},{"w":"Erlebnis","en":"experience, event (that you lived through)"},{"w":"Ergebnis","en":"result"},{"w":"Erfahrung","en":"experience (accumulated)"}],"tip":"Erlaubnis = permission; Erlebnis = a single memorable event; Erfahrung = experience you learn from (also accumulated: Berufserfahrung); Ergebnis = result.","items":[{"ans":"Erlaubnis","de":"Ohne die ___ seiner Eltern darf er nicht mitfahren.","en":"He is not allowed to come along without his parents' permission."},{"ans":"Erlaubnis","de":"Für das Foto brauchst du die ___ des Besitzers.","en":"For the photo you need the owner's permission."},{"ans":"Erlebnis","de":"Gestern hatte ich im Supermarkt ein komisches ___ mit einer Kassiererin.","en":"Yesterday I had a funny experience with a cashier in the supermarket."},{"ans":"Erlebnis","de":"Der Freizeitpark verspricht ein ___ für die ganze Familie.","en":"The theme park promises an experience for the whole family."},{"ans":"Ergebnis","de":"Das ___ der Prüfung bekommst du per Post.","en":"You will get the result of the exam by post."},{"ans":"Ergebnis","de":"Nach langer Diskussion kamen sie zu einem ___.","en":"After a long discussion they came to a conclusion."},{"ans":"Erfahrung","de":"Für diese Stelle brauchen Sie mindestens zwei Jahre ___.","en":"For this position you need at least two years of experience."},{"ans":"Erfahrung","de":"Das war eine wichtige ___ für mich, daraus habe ich viel gelernt.","en":"That was an important experience for me; I learned a lot from it."}]},
 {"id":"chef-koch","lv":"B1","words":[{"w":"Chef","en":"boss, head (NOT: chef)"},{"w":"Koch","en":"cook, chef"}],"tip":"English \"chef\" = Koch. German Chef = boss, manager.","items":[{"ans":"Chef","de":"Mein ___ hat mir gestern eine Gehaltserhöhung angeboten.","en":"My boss offered me a pay rise yesterday."},{"ans":"Chef","de":"Unser ___ entscheidet, wer befördert wird.","en":"Our boss decides who gets promoted."},{"ans":"Koch","de":"Mein Bruder ist von Beruf ___ und arbeitet in einem Sternerestaurant.","en":"My brother is a cook by profession and works in a Michelin-starred restaurant."},{"ans":"Koch","de":"Mein Bruder möchte ___ werden, weil er so gern kocht.","en":"My brother wants to become a cook because he likes cooking so much."}]},
 {"id":"gymnasium-turnhalle-fitnessstudio","lv":"B1","words":[{"w":"Gymnasium","en":"secondary school leading to Abitur (NOT: gym)"},{"w":"Turnhalle","en":"school gym, sports hall"},{"w":"Fitnessstudio","en":"fitness centre (gym)"}],"tip":"English \"gym\" is never Gymnasium: Gymnasium = academic secondary school; Turnhalle = hall for school sports; Fitnessstudio = private gym.","items":[{"ans":"Gymnasium","de":"Nach der Grundschule wechselt sie aufs ___, weil sie Abitur machen will.","en":"After primary school she is moving to a Gymnasium because she wants to take her Abitur."},{"ans":"Turnhalle","de":"Bei Regen findet der Sportunterricht in der ___ statt.","en":"When it rains, PE takes place in the gym."},{"ans":"Turnhalle","de":"Die Kinder spielen nach der Schule oft Basketball in der ___.","en":"After school the children often play basketball in the sports hall."},{"ans":"Fitnessstudio","de":"Ich habe einen Vertrag im ___ und trainiere dreimal pro Woche.","en":"I have a contract at the gym and work out three times a week."}]},
 {"id":"sympathisch-nett","lv":"B1","words":[{"w":"sympathisch","en":"likeable (NOT: sympathetic)"},{"w":"nett","en":"nice, kind"}],"tip":"sympathisch = I like this person (mir sympathisch); nett = kind/pleasant behaviour (nett zu jdm.); English \"sympathetic\" = mitfühlend or verständnisvoll, not sympathisch.","items":[{"ans":"sympathisch","de":"Dein neuer Nachbar ist mir sehr ___.","en":"I like your new neighbour very much."},{"ans":"sympathisch","de":"Der neue Kollege war mir sofort ___.","en":"I took to the new colleague straight away."},{"ans":"nett","de":"Sei bitte ___ zu der neuen Kollegin und zeig ihr die Kaffeeküche.","en":"Please be nice to the new colleague and show her the coffee kitchen."},{"ans":"nett","de":"Der Verkäufer war sehr ___ zu mir und hat mir alles erklärt.","en":"The shop assistant was very nice to me and explained everything."}]},
 {"id":"eventuell-schliesslich-endlich","lv":"B2","words":[{"w":"eventuell","en":"possibly, perhaps (NOT: eventually)"},{"w":"schließlich","en":"after all; finally, eventually"},{"w":"endlich","en":"finally, at last"}],"tip":"English \"eventually\" ≠ eventuell! eventuell = possibly/maybe; schließlich = after all/in the end; endlich = at last (with relief or impatience).","items":[{"ans":"eventuell","de":"Ich komme morgen ___ etwas später, aber ich weiß es noch nicht.","en":"I may come a little later tomorrow, but I don't know yet."},{"ans":"eventuell","de":"Ruf mich morgen ___ noch einmal an, falls es Probleme gibt.","en":"Maybe call me again tomorrow in case there are problems."},{"ans":"schließlich","de":"Sei nicht so streng mit ihm, er ist ___ auch nur ein Mensch.","en":"Don't be so strict with him; he is only human, after all."},{"ans":"schließlich","de":"Du kannst ihm nicht böse sein, er ist ___ dein Bruder.","en":"You can't be angry with him; he is your brother, after all."},{"ans":"endlich","de":"Wann hört der Lärm ___ auf? Es geht schon seit Stunden so!","en":"When will the noise finally stop? It has been going on for hours!"},{"ans":"endlich","de":"Da bist du ja ___! Wir warten schon seit einer Stunde auf dich.","en":"There you are at last! We've been waiting for you for an hour."}]},
 {"id":"million-milliarde-billion","lv":"B1","words":[{"w":"Million","en":"million (10^6)"},{"w":"Milliarde","en":"billion (10^9)"},{"w":"Billion","en":"trillion (10^12)"}],"tip":"German Milliarde = English billion (10^9); German Billion = English trillion (10^12).","items":[{"ans":"Million","de":"Eine ___ hat sechs Nullen.","en":"A million has six zeros."},{"ans":"Milliarde","de":"Eine ___ ist tausend Millionen.","en":"A billion is a thousand million."},{"ans":"Billion","de":"Eine ___ ist eine Million Millionen.","en":"A trillion is a million million."}]},
 {"id":"bad-schlecht-boese","lv":"A2","words":[{"w":"Bad","en":"bath; bathroom"},{"w":"schlecht","en":"bad (poor quality), unwell"},{"w":"böse","en":"evil; angry"}],"tip":"English \"bad\" = schlecht (quality) or böse (evil/angry). German Bad is a bath/bathroom.","items":[{"ans":"Bad","de":"Ich gehe kurz ins ___, um mir die Hände zu waschen.","en":"I'm just going to the bathroom to wash my hands."},{"ans":"schlecht","de":"Das Essen in der Kantine war heute ___, ich habe die Hälfte stehen lassen.","en":"The food in the canteen was bad today; I left half of it."},{"ans":"schlecht","de":"Mir ist ___, ich glaube, ich habe zu viel gegessen.","en":"I feel sick; I think I've eaten too much."},{"ans":"böse","de":"Es tut mir leid, bitte sei mir nicht mehr ___.","en":"I'm sorry, please don't be angry with me any more."},{"ans":"böse","de":"Meine Mutter wird ___, wenn ich zu spät nach Hause komme.","en":"My mother gets angry if I come home late."}]},
 {"id":"handy-handlich-geschickt","lv":"B1","words":[{"w":"Handy","en":"mobile phone (NOT: handy)"},{"w":"handlich","en":"handy, easy to handle (compact)"},{"w":"geschickt","en":"handy, skilful"}],"tip":"\"Handy\" is a pseudo-anglicism = mobile phone. English \"handy\" = handlich (compact/convenient) or geschickt (skilful with hands).","items":[{"ans":"Handy","de":"Mein ___ hat im Keller keinen Empfang.","en":"My mobile has no reception in the basement."},{"ans":"Handy","de":"Ich habe mein ___ zu Hause vergessen.","en":"I forgot my mobile phone at home."},{"ans":"handlich","de":"Dieser Koffer ist klein und ___ und passt unter jeden Sitz.","en":"This suitcase is small and handy and fits under any seat."},{"ans":"geschickt","de":"Er ist sehr ___ mit den Händen und repariert alles selbst.","en":"He is very handy and repairs everything himself."}]},
 {"id":"wo-wohin-woher","lv":"A2","words":[{"w":"wo","en":"where (position)"},{"w":"wohin","en":"where to (direction)"},{"w":"woher","en":"where from (origin)"}],"tip":"wo = location (no movement); wohin = movement towards; woher = origin.","items":[{"ans":"wo","de":"Sie fragte mich, ___ ich wohne.","en":"She asked me where I live."},{"ans":"wo","de":"Weißt du, ___ mein Schlüssel liegt?","en":"Do you know where my key is?"},{"ans":"wohin","de":"Sie fragte mich, ___ die Reise im Sommer geht.","en":"She asked me where the trip is headed this summer."},{"ans":"woher","de":"Sie fragte mich, ___ ich ursprünglich komme.","en":"She asked me where I originally come from."},{"ans":"woher","de":"Mich interessiert, ___ der Brief kommt, er hat keinen Absender.","en":"I'm interested in where the letter comes from; it has no sender."}]},
 {"id":"hin-her","lv":"B2","words":[{"w":"hin","en":"there (away from the speaker)"},{"w":"her","en":"here (towards the speaker)"}],"tip":"hin = away from where the speaker is; her = towards the speaker. wohin / woher, hinfahren / herkommen.","items":[{"ans":"hin","de":"Wo willst du denn ___?","en":"Where are you heading, then?"},{"ans":"hin","de":"Das Café kenne ich nicht. Wie komme ich denn ___?","en":"I don't know that café. How do I get there, then?"},{"ans":"her","de":"Wo kommst du eigentlich ___? Dein Akzent klingt so interessant.","en":"Where do you actually come from? Your accent sounds so interesting."},{"ans":"her","de":"Komm bitte ___, ich zeige dir etwas!","en":"Please come here, I'll show you something!"}]},
 {"id":"dass-ob","lv":"B1","words":[{"w":"dass","en":"that (conjunction)"},{"w":"ob","en":"whether, if (indirect yes/no question)"}],"tip":"dass introduces a statement (\"I know that ...\"); ob introduces an indirect yes/no question (\"I ask whether ...\").","items":[{"ans":"dass","de":"Es ist schön, ___ du heute Abend da bist.","en":"It's nice that you are here tonight."},{"ans":"dass","de":"Ich bin sicher, ___ er morgen kommt.","en":"I'm sure that he's coming tomorrow."},{"ans":"ob","de":"Ich möchte wissen, ___ er morgen kommt oder nicht.","en":"I'd like to know whether he is coming tomorrow or not."},{"ans":"ob","de":"Ich weiß nicht, ___ ich dir glauben soll oder nicht.","en":"I don't know whether I should believe you or not."}]},
 {"id":"seit-vor-fuer-ab","lv":"B1","words":[{"w":"seit","en":"since, for (up to now)"},{"w":"vor","en":"ago"},{"w":"für","en":"for (planned duration)"},{"w":"ab","en":"from (a point in time onwards)"}],"tip":"seit = since/for (still continuing); vor = ago (finished event); für = planned duration; ab = starting from.","items":[{"ans":"seit","de":"Ich wohne ___ drei Jahren in Wien.","en":"I've been living in Vienna for three years."},{"ans":"vor","de":"Wir sind ___ drei Jahren nach Wien gezogen.","en":"We moved to Vienna three years ago."},{"ans":"für","de":"Nächsten Monat fahren wir ___ zwei Wochen nach Spanien.","en":"Next month we are going to Spain for two weeks."},{"ans":"ab","de":"Das Geschäft ist noch zu, aber ___ dem 1. Mai ist es wieder geöffnet.","en":"The shop is still closed, but it will be open again from 1 May."}]},
 {"id":"lassen-verlassen-hinterlassen-ueberlassen","lv":"B2","words":[{"w":"lassen","en":"to leave (be), to let"},{"w":"verlassen","en":"to leave (a place/person)"},{"w":"hinterlassen","en":"to leave behind (traces, message)"},{"w":"überlassen","en":"to leave to, to hand over"}],"tip":"lassen = let/leave something as it is; verlassen = depart from; hinterlassen = leave behind; überlassen = leave it to someone else.","items":[{"ans":"lassen","de":"Wir sollten das Kind nicht allein zu Hause ___.","en":"We shouldn't leave the child alone at home."},{"ans":"verlassen","de":"Wegen des Kriegs musste die Familie ihr Heimatland ___.","en":"Because of the war the family had to leave their homeland."},{"ans":"hinterlassen","de":"Der Dieb hat am Tatort keine Spuren ___.","en":"The thief left no traces at the scene of the crime."},{"ans":"überlassen","de":"Ob du mitkommst oder nicht, das bleibt dir ___.","en":"Whether you come along or not is up to you."}]},
 {"id":"kennenlernen-treffen-begegnen","lv":"B2","words":[{"w":"kennenlernen","en":"to get to know, to meet for the first time"},{"w":"treffen","en":"to meet (arranged or by chance), to hit"},{"w":"begegnen","en":"to encounter (+ Dat.)"}],"tip":"kennenlernen = first meeting / getting to know; treffen = meet someone (arranged, or also by chance: zufällig treffen) – takes Akk.; begegnen = come across by chance – takes Dat.","items":[{"ans":"kennenlernen","de":"Ich möchte dich besser ___.","en":"I would like to get to know you better."},{"ans":"treffen","de":"Wir wollen uns wie jede Woche morgen um acht vor dem Kino ___.","en":"We want to meet in front of the cinema at eight tomorrow, as we do every week."},{"ans":"begegnen","de":"Im Wald kann man manchmal einem Fuchs ___.","en":"In the forest you can sometimes come across a fox."}]},
 {"id":"zeit-mal-uhr-stunde","lv":"A2","words":[{"w":"Zeit","en":"time (as a concept)"},{"w":"Mal","en":"time (occasion)"},{"w":"Uhr","en":"clock, watch; o'clock"},{"w":"Stunde","en":"hour; lesson"}],"tip":"English \"time\" has many German words: Zeit = time in general; Mal = occasion (\"zum ersten Mal\"); Uhr = clock time; Stunde = 60 minutes/lesson.","items":[{"ans":"Zeit","de":"Es ist höchste ___, dass wir losfahren.","en":"It's high time we set off."},{"ans":"Mal","de":"Das war das erste ___, dass ich Sushi gegessen habe.","en":"That was the first time I had eaten sushi."},{"ans":"Uhr","de":"Wie viel ___ ist es jetzt?","en":"What time is it now?"},{"ans":"Uhr","de":"Meine ___ geht fünf Minuten nach.","en":"My watch is five minutes slow."},{"ans":"Stunde","de":"Wir warten schon seit einer geschlagenen ___ auf den Bus.","en":"We have been waiting for the bus for a full hour."},{"ans":"Stunde","de":"Eine ___ hat sechzig Minuten.","en":"An hour has sixty minutes."}]},
 {"id":"schueler-student-azubi","lv":"A2","words":[{"w":"Schüler","en":"pupil (at school)"},{"w":"Student","en":"university student"},{"w":"Azubi","en":"apprentice (trainee)"}],"tip":"English \"student\" is split: Schüler = at school; Student = at university; Azubi (Auszubildender) = apprentice.","items":[{"ans":"Schüler","de":"Mein Sohn ist noch ___ und geht in die neunte Klasse.","en":"My son is still at school and is in ninth grade."},{"ans":"Student","de":"Er ist ___ an der Universität Köln und studiert Physik.","en":"He is a student at the University of Cologne and studies physics."},{"ans":"Azubi","de":"Sie macht eine Lehre als Bäckerin und ist jetzt ___ im zweiten Lehrjahr.","en":"She is training as a baker and is now an apprentice in her second year."}]},
 {"id":"beruf-arbeit-stelle-job","lv":"A2","words":[{"w":"Beruf","en":"profession, occupation"},{"w":"Arbeit","en":"work; workplace"},{"w":"Stelle","en":"position, vacancy"},{"w":"Job","en":"job (informal, often temporary)"}],"tip":"Beruf = what you are by profession; Arbeit = work/the workplace; Stelle = a position at a company; Job = casual/temporary job.","items":[{"ans":"Beruf","de":"Was sind Sie von ___?","en":"What do you do for a living?"},{"ans":"Arbeit","de":"Ich gehe jetzt zur ___ und komme erst abends zurück.","en":"I'm going to work now and won't be back until the evening."},{"ans":"Stelle","de":"Er hat sich auf die ausgeschriebene ___ in Hamburg beworben.","en":"He applied for the advertised position in Hamburg."},{"ans":"Job","de":"Für den Sommer suche ich einen ___ als Kellner.","en":"For the summer I'm looking for a job as a waiter."}]},
 {"id":"termin-verabredung-reservierung","lv":"B1","words":[{"w":"Termin","en":"appointment (official), deadline"},{"w":"Verabredung","en":"date, arrangement to meet"},{"w":"Reservierung","en":"reservation, booking"}],"tip":"Termin = appointment with doctor/office/boss; Verabredung = private arrangement with friends; Reservierung = booked table/room/seat.","items":[{"ans":"Termin","de":"Ich habe morgen um zehn einen ___ beim Zahnarzt.","en":"I have an appointment at the dentist's tomorrow at ten."},{"ans":"Termin","de":"Ein ___ mit dem Chef ist schwer zu bekommen.","en":"An appointment with the boss is hard to get."},{"ans":"Verabredung","de":"Die beiden hatten gestern ihre erste ___ und sind ins Kino gegangen.","en":"The two of them had their first date yesterday and went to the cinema."},{"ans":"Reservierung","de":"Ich möchte für Samstagabend eine ___ für vier Personen machen.","en":"I'd like to make a reservation for four people for Saturday evening."}]},
 {"id":"urlaub-ferien-feiertag-freizeit","lv":"A2","words":[{"w":"Urlaub","en":"holiday from work, leave"},{"w":"Ferien","en":"school/university holidays (plural)"},{"w":"Feiertag","en":"public holiday"},{"w":"Freizeit","en":"free time, leisure"}],"tip":"Urlaub = time off work; Ferien (plural) = school holidays; Feiertag = public holiday (one day); Freizeit = spare time.","items":[{"ans":"Urlaub","de":"Meine Firma gibt mir im Jahr dreißig Tage bezahlten ___.","en":"My company gives me thirty days of paid leave per year."},{"ans":"Ferien","de":"Die Schule ist geschlossen, weil gerade ___ sind.","en":"The school is closed because it's the school holidays."},{"ans":"Feiertag","de":"Der Tag der Deutschen Einheit ist ein gesetzlicher ___.","en":"German Unity Day is a public holiday."},{"ans":"Freizeit","de":"In meiner ___ spiele ich gern Gitarre.","en":"In my free time I like to play the guitar."}]},
 {"id":"umziehen-ausziehen-einziehen","lv":"B1","words":[{"w":"umziehen","en":"to move house; to change clothes"},{"w":"ausziehen","en":"to move out; to take off clothes"},{"w":"einziehen","en":"to move in"}],"tip":"umziehen = move to another home; ausziehen = move out (or undress); einziehen = move into a new home.","items":[{"ans":"umziehen","de":"Wir müssen wegen der Arbeit von München nach Hamburg ___.","en":"We have to move from Munich to Hamburg because of work."},{"ans":"ausziehen","de":"Mit achtzehn wollte sie unbedingt von zu Hause ___.","en":"At eighteen she absolutely wanted to move out of her parents' home."},{"ans":"ausziehen","de":"Im Haus muss man die Schuhe ___.","en":"In the house you have to take off your shoes."},{"ans":"einziehen","de":"Meine Tochter will nächsten Monat bei ihrem Freund ___, weil sie zusammenwohnen möchten.","en":"My daughter wants to move in with her boyfriend next month because they want to live together."}]},
 {"id":"fragen-bitten-verlangen","lv":"B1","words":[{"w":"fragen","en":"to ask (a question)"},{"w":"bitten","en":"to ask (for), to request"},{"w":"verlangen","en":"to demand; to charge"}],"tip":"fragen = ask a question; bitten (um) = ask for something / request that someone does something; verlangen = demand, charge.","items":[{"ans":"fragen","de":"Ich muss noch jemanden nach dem Weg ___.","en":"I still have to ask someone for directions."},{"ans":"fragen","de":"Wenn du etwas nicht verstehst, kannst du mich jederzeit alles ___.","en":"If you don't understand something, you can ask me anything at any time."},{"ans":"bitten","de":"Darf ich Sie ___, das Fenster zu schließen?","en":"May I ask you to close the window?"},{"ans":"verlangen","de":"Die Firma kann dafür bis zu fünfzig Euro ___.","en":"The company can charge up to fifty euros for it."}]},
 {"id":"antworten-beantworten","lv":"B1","words":[{"w":"antworten","en":"to answer, to reply (+ Dat., auf)"},{"w":"beantworten","en":"to answer (+ Akk.)"}],"tip":"antworten takes a person (Dat.) or auf + Akk.; beantworten takes the thing answered directly: eine Frage beantworten.","items":[{"ans":"antworten","de":"Er hat versprochen, auf meine E-Mail bald zu ___.","en":"He promised to reply to my email soon."},{"ans":"antworten","de":"Er hat versprochen, dir bald zu ___.","en":"He promised to answer you soon."},{"ans":"beantworten","de":"Kannst du bitte meine Frage ___?","en":"Can you please answer my question?"},{"ans":"beantworten","de":"Der Minister musste viele kritische Fragen ___.","en":"The minister had to answer many critical questions."}]},
 {"id":"gefallen-moegen","lv":"A2","words":[{"w":"gefallen","en":"to please, to be liked (+ Dat.)"},{"w":"mögen","en":"to like (+ Akk.)"}],"tip":"gefallen: the thing is the subject, the person is dative (\"Der Film gefällt mir\"); mögen: the person is the subject (\"Ich mag den Film\").","items":[{"ans":"gefallen","de":"Ich glaube, dieser Film wird dir ___.","en":"I think you will like this film."},{"ans":"gefallen","de":"Das neue Kleid wird deiner Schwester bestimmt ___.","en":"Your sister will certainly like the new dress."},{"ans":"mögen","de":"Ich kann seinen Bruder einfach nicht ___.","en":"I just don't like his brother."},{"ans":"mögen","de":"Er hat nie gelernt, Fisch zu ___.","en":"He never learned to like fish."}]},
 {"id":"heissen-nennen-rufen-anrufen","lv":"B1","words":[{"w":"heißen","en":"to be called"},{"w":"nennen","en":"to name, to call (something/someone X)"},{"w":"rufen","en":"to call out, to shout"},{"w":"anrufen","en":"to phone, to call"}],"tip":"heißen = be called (no object); nennen = give a name (+ Akk.); rufen = call out loudly; anrufen = telephone someone.","items":[{"ans":"heißen","de":"Wie soll das Baby denn ___? Wir haben noch keinen Namen.","en":"So what is the baby going to be called? We still don't have a name."},{"ans":"nennen","de":"Wir möchten unsere Tochter nach ihrer Urgroßmutter ___.","en":"We would like to name our daughter after her great-grandmother."},{"ans":"rufen","de":"Wenn du Hilfe brauchst, musst du laut um Hilfe ___.","en":"If you need help, you have to call out loudly for help."},{"ans":"anrufen","de":"Ich muss meine Oma heute Abend noch ___, um ihr zu gratulieren.","en":"I still have to phone my grandma this evening to congratulate her."}]},
 {"id":"wohnen-leben","lv":"A2","words":[{"w":"wohnen","en":"to live (at a place), to reside"},{"w":"leben","en":"to live (be alive; lead a life)"}],"tip":"wohnen = have your home (or a temporary room: im Hotel wohnen) at a place; leben = be alive / lead a life. For a town or country both work: \"Ich wohne/lebe in Berlin\".","items":[{"ans":"wohnen","de":"Bei unserem Besuch in Berlin wollen wir drei Nächte in einem Hotel am Bahnhof ___.","en":"During our visit to Berlin we want to stay three nights in a hotel near the station."},{"ans":"leben","de":"Ohne Wasser kann kein Mensch lange ___.","en":"No human can live long without water."},{"ans":"leben","de":"Wir wollen ein langes und glückliches Leben ___.","en":"We want to lead a long and happy life."}]},
 {"id":"denken-glauben-meinen-finden","lv":"B1","words":[{"w":"denken","en":"to think (about/of)"},{"w":"glauben","en":"to believe; to think"},{"w":"meinen","en":"to mean; to think (opinion)"},{"w":"finden","en":"to find; to think (opinion about)"}],"tip":"denken (an) = think of; glauben = believe; meinen = mean/have the opinion; finden = judge: \"Wie findest du …?\" = what do you think of …?","items":[{"ans":"denken","de":"Ich muss oft an meine Familie ___ und vermisse sie sehr.","en":"I often find myself thinking of my family and miss them a lot."},{"ans":"glauben","de":"Das werde ich dir nie ___!","en":"I'll never believe you about that!"},{"ans":"meinen","de":"Sei ihm nicht böse, er wollte es doch nur gut ___.","en":"Don't be angry with him, he only meant well."},{"ans":"finden","de":"Wie kann man so einen Film nur gut ___?","en":"How can anyone possibly like a film like that?"}]},
 {"id":"nachdem-bevor-bis-seitdem","lv":"B1","words":[{"w":"nachdem","en":"after (conjunction)"},{"w":"bevor","en":"before (conjunction)"},{"w":"bis","en":"until"},{"w":"seitdem","en":"since (then)"}],"tip":"nachdem = after (usually Perfekt/Plusquamperfekt); bevor = before; bis = until (the moment when); seitdem = since (a point up to now).","items":[{"ans":"nachdem","de":"Ich konnte erst einschlafen, ___ ich lange gelesen hatte.","en":"I could only fall asleep after I had read for a long time."},{"ans":"bevor","de":"Ich muss noch duschen, ___ wir losfahren.","en":"I still have to shower before we set off."},{"ans":"bis","de":"Ich warte hier so lange, ___ du zurückkommst.","en":"I'll wait here until you come back."},{"ans":"seitdem","de":"Ich bin viel fitter, ___ ich regelmäßig Sport mache.","en":"I've been much fitter since I started exercising regularly."}]},
 {"id":"sehr-viel-zu","lv":"A2","words":[{"w":"sehr","en":"very (+ adjective/verb)"},{"w":"viel","en":"much, a lot; far (+ comparative)"},{"w":"zu","en":"too (much)"}],"tip":"sehr + adjective or verbs of feeling (sich sehr freuen); viel + noun, comparative (\"viel besser\") or activity verbs (viel arbeiten); zu = too (more than allowed): \"zu schwer, um ... zu\".","items":[{"ans":"sehr","de":"Vielen Dank, wir haben uns über das Geschenk ___ gefreut.","en":"Thank you very much, we were very pleased with the present."},{"ans":"viel","de":"Heute ist es ___ kälter als gestern.","en":"Today it is much colder than yesterday."},{"ans":"viel","de":"Ich trinke jeden Tag ___ Wasser.","en":"I drink a lot of water every day."},{"ans":"zu","de":"Der Koffer ist ___ schwer, um ihn allein zu tragen.","en":"The suitcase is too heavy to carry alone."}]},
 {"id":"verdienen-gewinnen","lv":"B1","words":[{"w":"verdienen","en":"to earn; to deserve"},{"w":"gewinnen","en":"to win"}],"tip":"verdienen = earn money (or deserve); gewinnen = win a game or prize.","items":[{"ans":"verdienen","de":"Als Kellner kann man in München im Monat nicht viel ___.","en":"As a waiter you can't earn much a month in Munich."},{"ans":"verdienen","de":"Sie will später als Ärztin gut ___.","en":"She wants to earn well as a doctor later."},{"ans":"gewinnen","de":"Unsere Mannschaft hat gute Chancen, das Spiel zu ___.","en":"Our team has a good chance of winning the match."},{"ans":"gewinnen","de":"Er hofft, einmal im Lotto zu ___.","en":"He hopes to win the lottery some day."}]},
 {"id":"wetter-klima-temperatur","lv":"B1","words":[{"w":"Wetter","en":"weather"},{"w":"Klima","en":"climate"},{"w":"Temperatur","en":"temperature"}],"tip":"Wetter = day-to-day conditions; Klima = long-term average; Temperatur = degrees.","items":[{"ans":"Wetter","de":"Das ___ ist heute schön: Sonne und kein Wind.","en":"The weather is nice today: sun and no wind."},{"ans":"Klima","de":"Durch die Erderwärmung verändert sich das ___ der Erde langfristig.","en":"Global warming is changing the Earth's climate in the long term."},{"ans":"Temperatur","de":"Die ___ liegt heute bei zwanzig Grad.","en":"The temperature is twenty degrees today."}]},
 {"id":"als-wie-vergleich","lv":"A2","words":[{"w":"als","en":"than (comparative)"},{"w":"wie","en":"as, like (equality)"}],"tip":"Comparative: größer als. Equality: so groß wie. (Common error: \"größer wie\").","items":[{"ans":"als","de":"Mein Bruder ist größer ___ ich.","en":"My brother is taller than I am."},{"ans":"als","de":"Heute ist alles teurer ___ früher.","en":"Everything is more expensive today than it used to be."},{"ans":"wie","de":"Er ist so groß ___ ich.","en":"He is as tall as I am."},{"ans":"wie","de":"Sie singt so schön ___ eine Nachtigall.","en":"She sings as beautifully as a nightingale."}]},
 {"id":"reise-fahrt-ausflug-flug","lv":"A2","words":[{"w":"Reise","en":"journey, trip"},{"w":"Fahrt","en":"ride, drive, journey (by vehicle)"},{"w":"Ausflug","en":"excursion, day trip"},{"w":"Flug","en":"flight"}],"tip":"Reise = longer trip; Fahrt = the ride in a vehicle; Ausflug = short trip for fun; Flug = by plane.","items":[{"ans":"Reise","de":"Die dreiwöchige ___ durch Indien – mit Zug, Bus und Flugzeug – war das größte Abenteuer ihres Lebens.","en":"The three-week trip through India was the greatest adventure of her life."},{"ans":"Fahrt","de":"Die ___ mit dem Bus in die Innenstadt kostet zwei Euro.","en":"The bus ride into the city centre costs two euros."},{"ans":"Ausflug","de":"Am Sonntag machen wir einen ___ an den See.","en":"On Sunday we're going on an excursion to the lake."},{"ans":"Flug","de":"Der ___ nach Rom wurde wegen des Gewitters umgeleitet.","en":"The flight to Rome was diverted because of the thunderstorm."}]},
 {"id":"kenntnis-erkenntnis-wissen","lv":"C1","words":[{"w":"Kenntnis","en":"knowledge (of something), awareness"},{"w":"Erkenntnis","en":"insight, realisation"},{"w":"Wissen","en":"knowledge (body of knowledge)"}],"tip":"Kenntnis = awareness of a fact (zur Kenntnis nehmen); Erkenntnis = insight, realisation; Wissen (das) = knowledge in general.","items":[{"ans":"Kenntnis","de":"Bitte nehmen Sie diese Änderung zur ___.","en":"Please take note of this change."},{"ans":"Erkenntnis","de":"Plötzlich kam ihm die ___: Er hatte den falschen Weg genommen.","en":"Suddenly it dawned on him that he had taken the wrong way."},{"ans":"Wissen","de":"Das ___ der Menschheit wächst ständig.","en":"Humanity's knowledge is constantly growing."},{"ans":"Wissen","de":"Mein ___ über Geschichte ist leider sehr begrenzt.","en":"My knowledge of history is unfortunately very limited."}]},
 {"id":"kein-nicht-nichts","lv":"A2","words":[{"w":"kein","en":"no, not a (before nouns)"},{"w":"nicht","en":"not (verb, adjective, whole sentence)"},{"w":"nichts","en":"nothing"}],"tip":"kein negates nouns with ein/no article; nicht negates verbs, adjectives, adverbs; nichts = nothing.","items":[{"ans":"kein","de":"In diesem Dorf gibt es ___ Restaurant.","en":"There is no restaurant in this village."},{"ans":"kein","de":"Das ist ___ guter Plan.","en":"That is not a good plan."},{"ans":"nicht","de":"Ich möchte heute ___ ins Kino gehen.","en":"I don't want to go to the cinema today."},{"ans":"nicht","de":"Das Buch gehört mir ___.","en":"The book doesn't belong to me."},{"ans":"nichts","de":"Gibt es etwas Neues? – Nein, es gibt ___ Neues.","en":"Is there anything new? – No, there is nothing new."},{"ans":"nichts","de":"Ich habe ___ zu verbergen.","en":"I have nothing to hide."}]},
 {"id":"trotzdem-sonst-ausserdem","lv":"B1","words":[{"w":"trotzdem","en":"nevertheless, all the same"},{"w":"sonst","en":"otherwise"},{"w":"außerdem","en":"besides, moreover"}],"tip":"trotzdem = contrast (\"nevertheless\"); sonst = \"otherwise / else\"; außerdem = adds a further point.","items":[{"ans":"trotzdem","de":"Er war krank, aber er ist ___ zur Arbeit gegangen.","en":"He was ill, but he went to work all the same."},{"ans":"sonst","de":"Beeil dich, ___ verpassen wir den Zug!","en":"Hurry up, otherwise we'll miss the train!"},{"ans":"außerdem","de":"Das Hotel hat einen Pool und ___ eine Sauna.","en":"The hotel has a pool and also a sauna."}]},
 {"id":"lang-lange","lv":"A2","words":[{"w":"lang","en":"long (adjective)"},{"w":"lange","en":"for a long time (adverb)"}],"tip":"lang = adjective (an object/period is long); lange = adverb: for a long time (with a verb). In casual speech \"lang\" is also heard as an adverb (\"Wir haben lang gewartet\"), but the standard form is lange. After a time span, lang is standard: drei Jahre lang, den ganzen Tag lang.","items":[{"ans":"lang","de":"Der Film war sehr ___.","en":"The film was very long."},{"ans":"lang","de":"Das Kleid ist zu ___.","en":"The dress is too long."},{"ans":"lange","de":"Wir haben ___ auf dich gewartet.","en":"We waited for you for a long time."},{"ans":"lange","de":"Ich schlafe am Wochenende gern ___.","en":"At weekends I like to sleep in."}]},
 {"id":"gern-lieber-am-liebsten","lv":"A2","words":[{"w":"gern","en":"gladly, like to"},{"w":"lieber","en":"rather, prefer to"},{"w":"am liebsten","en":"most of all, best of all"}],"tip":"gern – lieber – am liebsten is the comparison of \"like\": I like tea, I prefer coffee, I like water best of all.","items":[{"ans":"gern","de":"Ich esse sehr ___ Schokolade.","en":"I like eating chocolate very much."},{"ans":"lieber","de":"Ich trinke ___ Kaffee als Tee.","en":"I prefer coffee to tea."},{"ans":"am liebsten","de":"Wasser trinke ich von allen Getränken ___.","en":"Of all drinks, I like water best."}]},
 {"id":"angeblich-vermutlich","lv":"B2","words":[{"w":"angeblich","en":"allegedly, supposedly"},{"w":"vermutlich","en":"presumably, probably"}],"tip":"angeblich = someone claims it (I doubt it); vermutlich = I assume it is likely.","items":[{"ans":"angeblich","de":"Er hat ___ im Lotto gewonnen, aber ich glaube ihm kein Wort.","en":"He supposedly won the lottery, but I don't believe a word he says."},{"ans":"vermutlich","de":"Der Schlüssel ist nicht hier, ich habe ihn ___ im Büro vergessen.","en":"The key isn't here; I've probably left it at the office."}]},
 {"id":"effektiv-effizient","lv":"C1","words":[{"w":"effektiv","en":"effective (reaches the intended result)"},{"w":"effizient","en":"efficient (reaches it with little effort, cost or waste)"}],"tip":"effektiv = does it work, is the goal reached? effizient = at what cost? (little time, money, energy). A measure can be effektiv without being effizient.","items":[{"ans":"effektiv","de":"Die Kampagne war sehr ___: Sie erreichte ihr Ziel, kostete aber das Dreifache des geplanten Budgets.","en":"The campaign was very effective: it reached its goal, but cost three times the planned budget."},{"ans":"effizient","de":"Das Verfahren ist zwar sehr ___, aber nicht effektiv: Es spart Zeit und Material, löst das Problem aber nicht.","en":"The method is very efficient, admittedly, but not effective: it saves time and material but does not solve the problem."}]},
 {"id":"illusion-allusion-illustration","lv":"C1","words":[{"w":"Illusion","en":"illusion, delusion, false hope"},{"w":"Allusion","en":"allusion, veiled reference (literary)"},{"w":"Illustration","en":"illustration (picture; also: clarifying example)"}],"tip":"Illusion = Täuschung, falsche Hoffnung. Allusion = Anspielung (bildungssprachlich). Illustration = Bebilderung, Abbildung, Veranschaulichung.","items":[{"ans":"Illusion","de":"Er gab sich keiner ___ hin: Die Firma stand kurz vor der Pleite.","en":"He had no illusions: the company was on the verge of bankruptcy."},{"ans":"Illusion","de":"Zu glauben, ein Jahr reiche für die Promotion, ist eine reine ___.","en":"Believing that one year is enough for a doctorate is a pure illusion."},{"ans":"Allusion","de":"Seine Bemerkung war eine versteckte ___, die nur Eingeweihte verstanden.","en":"His remark was a veiled allusion that only insiders understood."},{"ans":"Illustration","de":"Das Kinderbuch lebt von der liebevollen ___ durch eine bekannte Zeichnerin.","en":"The children's book owes much of its charm to the loving illustrations by a well-known artist."},{"ans":"Illustration","de":"Zur ___ nannte der Dozent ein anschauliches Beispiel aus dem Alltag.","en":"By way of illustration, the lecturer gave a vivid example from everyday life."}]},
 {"id":"intention-intensitaet-intervention","lv":"C1","words":[{"w":"Intention","en":"intention, aim"},{"w":"Intensität","en":"intensity"},{"w":"Intervention","en":"intervention"}],"tip":"Intention = Absicht, Ziel. Intensität = Stärke, Heftigkeit. Intervention = Eingreifen (militärisch, medizinisch, politisch).","items":[{"ans":"Intention","de":"Es war nie meine ___, dich zu verletzen.","en":"It was never my intention to hurt you."},{"ans":"Intention","de":"Er hatte die ___, ihr bei der Übersetzung zu helfen, doch dann kam etwas dazwischen.","en":"He intended to help her with the translation, but then something came up."},{"ans":"Intensität","de":"Mit zunehmender ___ des Regens stieg der Pegel des Flusses rasch an.","en":"As the rain grew more intense, the river level rose quickly."},{"ans":"Intensität","de":"Die ___ des Schmerzes nahm im Laufe der Nacht immer weiter zu.","en":"The intensity of the pain kept increasing during the night."},{"ans":"Intervention","de":"Die ___ der Nachbarstaaten mit eigenen Truppen verschärfte den Konflikt.","en":"The intervention of the neighbouring states with their own troops exacerbated the conflict."},{"ans":"Intervention","de":"Eine frühzeitige ___ der Ärzte rettete dem Patienten das Leben.","en":"An early intervention by the doctors saved the patient's life."}]},
 {"id":"autoritaer-autoritativ-autorisiert","lv":"C1","words":[{"w":"autoritär","en":"authoritarian, domineering"},{"w":"autoritativ","en":"authoritative, carrying recognised authority (formal)"},{"w":"autorisiert","en":"authorised, officially permitted"}],"tip":"autoritär = befiehlt, duldet keinen Widerspruch. autoritativ = maßgeblich, mit anerkannter Autorität (selten). autorisiert = offiziell ermächtigt.","items":[{"ans":"autoritär","de":"Der Vater erzog seine Kinder streng und ___; Widerspruch duldete er nicht.","en":"The father raised his children strictly and in an authoritarian manner; he did not tolerate contradiction."},{"ans":"autoritär","de":"Er führt die Abteilung ___, ohne je die Meinung der Mitarbeiter zu hören.","en":"He runs the department in an authoritarian way, never listening to his staff's opinion."},{"ans":"autoritativ","de":"Der Kommentar gilt unter Juristen als ___: Die Gerichte folgen meist seiner Auslegung.","en":"Among lawyers the commentary is regarded as authoritative: the courts mostly follow its interpretation."},{"ans":"autorisiert","de":"Nur wer vom Hersteller ___ ist, darf das Gerät reparieren.","en":"Only those authorised by the manufacturer may repair the device."}]},
 {"id":"ethisch-ethnisch-aesthetisch","lv":"C1","words":[{"w":"ethisch","en":"ethical"},{"w":"ethnisch","en":"ethnic"},{"w":"ästhetisch","en":"aesthetic"}],"tip":"ethisch = die Ethik betreffend (richtig/falsch). ethnisch = zu einem Volk/einer Volksgruppe gehörend. ästhetisch = das Schöne/den Geschmack betreffend.","items":[{"ans":"ethisch","de":"Die Kommission prüft, ob die Genforschung ___ vertretbar ist.","en":"The commission is examining whether genetic research is ethically justifiable."},{"ans":"ethisch","de":"Das Unternehmen handelte ___ einwandfrei und hielt sich an alle Regeln der Berufsethik.","en":"The company acted impeccably from an ethical point of view and followed all the rules of professional ethics."},{"ans":"ethnisch","de":"Die Stadt ist ___ gemischt: Hier leben Menschen aus vielen Völkern.","en":"The city is ethnically mixed: people from many different ethnic groups live here."},{"ans":"ethnisch","de":"Der Konflikt ist nicht religiös, sondern ___ motiviert: Zwei Volksgruppen kämpfen um dasselbe Land.","en":"The conflict is not religiously but ethnically motivated: two ethnic groups are fighting over the same land."},{"ans":"ästhetisch","de":"Das Haus ist funktional, wirkt aber ___ wenig ansprechend.","en":"The house is functional, but not very appealing aesthetically."}]},
 {"id":"human-humanitaer-humanistisch","lv":"C1","words":[{"w":"human","en":"humane, considerate"},{"w":"humanitär","en":"humanitarian (aiding people in need)"},{"w":"humanistisch","en":"humanist, classical-educational"}],"tip":"human = menschlich, rücksichtsvoll. humanitär = auf Hilfe für Menschen in Not gerichtet. humanistisch = den Humanismus (Bildungsideal, Antike) betreffend.","items":[{"ans":"human","de":"Die Tiere sollen möglichst ___ geschlachtet werden, ohne unnötiges Leiden.","en":"The animals are to be slaughtered as humanely as possible, without unnecessary suffering."},{"ans":"human","de":"Der Richter urteilte streng, aber ___.","en":"The judge ruled strictly, but humanely."},{"ans":"humanitär","de":"Die Organisation ist ___ tätig: Sie verteilt Nahrung und Medikamente in Krisengebieten.","en":"The organisation does humanitarian work: it distributes food and medicine in crisis areas."},{"ans":"humanistisch","de":"Das Gymnasium ist ___ ausgerichtet: Latein und Griechisch stehen im Mittelpunkt des Lehrplans.","en":"The grammar school has a humanistic orientation: Latin and Greek are at the centre of the curriculum."}]},
 {"id":"oekologisch-oekonomisch-oekumenisch","lv":"C1","words":[{"w":"ökologisch","en":"ecological"},{"w":"ökonomisch","en":"economic; economical"},{"w":"ökumenisch","en":"ecumenical (across Christian churches)"}],"tip":"ökologisch = Umwelt, Natur. ökonomisch = Wirtschaft, Kosten, sparsam. ökumenisch = die christlichen Kirchen verbindend.","items":[{"ans":"ökologisch","de":"Das Waschmittel baut sich im Wasser vollständig ab und gilt daher als ___ unbedenklich.","en":"The detergent breaks down completely in water and is therefore considered ecologically harmless."},{"ans":"ökonomisch","de":"Für das Unternehmen ist die Fusion ___ sinnvoll, weil sie erhebliche Kosten spart.","en":"For the company the merger makes economic sense because it saves considerable costs."},{"ans":"ökumenisch","de":"Der Gottesdienst war bewusst ___ angelegt: Pfarrer beider Konfessionen predigten gemeinsam.","en":"The service was deliberately designed to be ecumenical: ministers of both denominations preached together."}]},
 {"id":"verleiten-verleumden-verleugnen","lv":"C1","words":[{"w":"verleiten","en":"to lead astray, to tempt (into doing something)"},{"w":"verleumden","en":"to slander"},{"w":"verleugnen","en":"to deny, to disown"}],"tip":"verleiten (zu) = jemanden zu etwas Unüberlegtem bringen. verleumden = Lügen über jemanden verbreiten. verleugnen = etwas Wahres (Herkunft, Gefühle, Bekanntschaft) abstreiten.","items":[{"ans":"verleiten","de":"Niedrige Preise können Kunden dazu ___, mehr zu kaufen, als sie brauchen.","en":"Low prices can tempt customers into buying more than they need."},{"ans":"verleiten","de":"Die Aussicht auf schnelles Geld darf dich nicht zu unüberlegten Entscheidungen ___.","en":"The prospect of quick money must not lead you into rash decisions."},{"ans":"verleumden","de":"Er wollte seine Kollegin durch erfundene Gerüchte bei der Chefin ___.","en":"He wanted to slander his colleague to the boss with invented rumours."},{"ans":"verleumden","de":"Es ist strafbar, andere Menschen mit erfundenen Vorwürfen zu ___.","en":"It is a punishable offence to slander other people with invented accusations."},{"ans":"verleugnen","de":"Er konnte seine Herkunft nicht länger ___ und stand endlich zu seiner Familie.","en":"He could no longer deny his origins and finally stood by his family."},{"ans":"verleugnen","de":"Der Zeuge versuchte, seine frühere Mitgliedschaft in der Partei zu ___.","en":"The witness tried to deny his earlier membership in the party."}]},
 {"id":"verbreiten-verbreitern","lv":"C1","words":[{"w":"verbreiten","en":"to spread, to disseminate"},{"w":"verbreitern","en":"to widen (make physically broader)"}],"tip":"verbreiten = Nachrichten, Krankheiten, Gerüchte ausbreiten. verbreitern = etwas breiter machen (Straße, Tisch, Weg).","items":[{"ans":"verbreiten","de":"Bitte hilf mir, die Nachricht schnell im Netz zu ___.","en":"Please help me spread the news quickly online."},{"ans":"verbreiten","de":"Falschmeldungen können sich in sozialen Netzwerken rasant ___.","en":"False reports can spread rapidly on social networks."},{"ans":"verbreitern","de":"Wegen des starken Verkehrs will die Stadt die Straße auf vier Spuren ___.","en":"Because of the heavy traffic the city wants to widen the road to four lanes."},{"ans":"verbreitern","de":"Um mehr Platz zu schaffen, will der Schreiner den Tisch um zwanzig Zentimeter ___.","en":"To create more space the carpenter wants to widen the table by twenty centimetres."}]},
 {"id":"anfuehren-auffuehren-ausfuehren","lv":"C1","words":[{"w":"anführen","en":"to lead; to cite, to adduce"},{"w":"aufführen","en":"to perform (play, music); to list"},{"w":"ausführen","en":"to carry out; to run (program); to take out (dog)"}],"tip":"anführen = an der Spitze führen / (Argument, Zitat) nennen. aufführen = vor Publikum spielen. ausführen = einen Auftrag/Befehl/ein Programm umsetzen; auch: den Hund ausführen (= Gassi gehen).","items":[{"ans":"anführen","de":"Ein Trommler soll den Festzug an der Spitze ___.","en":"A drummer is to lead the parade at the front."},{"ans":"anführen","de":"Der erfahrene Kapitän soll die Mannschaft beim Einlaufen ins Stadion ___.","en":"The experienced captain is to lead the team as it enters the stadium."},{"ans":"aufführen","de":"Die Schulklasse will zum Jahresende ein selbst geschriebenes Theaterstück ___.","en":"The class wants to perform a play they wrote themselves at the end of the year."},{"ans":"aufführen","de":"Im Sommer will das Stadttheater Shakespeares „Hamlet“ unter freiem Himmel ___.","en":"In summer the city theatre wants to stage Shakespeare's \"Hamlet\" in the open air."},{"ans":"ausführen","de":"Der alte Computer kann das neue Programm nicht mehr ___.","en":"The old computer can no longer run the new program."},{"ans":"ausführen","de":"Abends muss ich noch den Hund ___.","en":"In the evening I still have to take the dog out."}]},
 {"id":"einhalten-anhalten-aufhalten","lv":"C1","words":[{"w":"einhalten","en":"to comply with, to keep (rule, deadline)"},{"w":"anhalten","en":"to stop; to last, to persist"},{"w":"aufhalten","en":"to hold up, to detain; (sich) to stay"}],"tip":"einhalten = Regeln, Fristen, Zusagen beachten. anhalten = stehen bleiben / andauern. aufhalten = verzögern, an der Weiterfahrt hindern; sich aufhalten = sich irgendwo befinden.","items":[{"ans":"einhalten","de":"Alle Mitarbeiter müssen die Sicherheitsvorschriften strikt ___.","en":"All employees must strictly comply with the safety regulations."},{"ans":"einhalten","de":"Wir konnten die vereinbarte Frist leider nicht ___.","en":"Unfortunately we could not keep the agreed deadline."},{"ans":"anhalten","de":"Der Fahrer musste scharf bremsen und den Wagen mitten auf der Kreuzung ___.","en":"The driver had to brake hard and stop the car in the middle of the junction."},{"ans":"anhalten","de":"Die Hitzewelle wird voraussichtlich noch eine Woche ___.","en":"The heatwave is expected to last another week."},{"ans":"aufhalten","de":"Entschuldigung, ich möchte Sie nicht länger ___.","en":"Sorry, I don't want to hold you up any longer."},{"ans":"aufhalten","de":"Nach Angaben der Polizei soll sich der Verdächtige noch in der Stadt ___.","en":"According to the police, the suspect is still said to be in the city."}]},
 {"id":"begreifen-ergreifen-greifen","lv":"C1","words":[{"w":"begreifen","en":"to grasp, to understand"},{"w":"ergreifen","en":"to seize; to take (measures); to move (emotionally)"},{"w":"greifen","en":"to grab, to reach; to take effect"}],"tip":"begreifen = verstehen. ergreifen = packen, fassen; Maßnahmen/die Initiative/einen Beruf ergreifen. greifen (nach) = die Hand ausstrecken; (Maßnahmen) greifen = wirken.","items":[{"ans":"begreifen","de":"Ich kann einfach nicht ___, warum er das getan hat.","en":"I simply cannot understand why he did that."},{"ans":"begreifen","de":"Die Tragweite der Entscheidung wollte sie zunächst gar nicht ___.","en":"At first she did not want to grasp the implications of the decision at all."},{"ans":"ergreifen","de":"Die Regierung muss endlich wirksame Maßnahmen gegen die Inflation ___.","en":"The government finally has to take effective measures against inflation."},{"ans":"ergreifen","de":"Nach dem Studium wollte er unbedingt einen künstlerischen Beruf ___.","en":"After university he absolutely wanted to take up an artistic profession."},{"ans":"greifen","de":"Das Kind streckte die Hand aus, um nach dem Spielzeug zu ___.","en":"The child stretched out its hand to reach for the toy."},{"ans":"greifen","de":"Die neuen Sicherheitsvorkehrungen scheinen langsam zu ___.","en":"The new security precautions seem to be slowly taking effect."}]},
 {"id":"ersetzen-erstatten-vertreten","lv":"C1","words":[{"w":"ersetzen","en":"to replace; to compensate for"},{"w":"erstatten","en":"to refund; to file (report), to give (account)"},{"w":"vertreten","en":"to represent; to stand in for; to advocate (view)"}],"tip":"ersetzen = an die Stelle von etwas treten. erstatten = zurückzahlen; feste Verbindungen: Anzeige/Bericht erstatten. vertreten = im Namen von jemandem handeln; eine Meinung vertreten.","items":[{"ans":"ersetzen","de":"Der Hausbesitzer will die alte Heizung im Sommer durch eine Wärmepumpe ___.","en":"The homeowner wants to replace the old heating system with a heat pump in summer."},{"ans":"ersetzen","de":"Kein Computer kann den persönlichen Kontakt zwischen Lehrer und Schüler ___.","en":"No computer can replace the personal contact between teacher and pupil."},{"ans":"erstatten","de":"Wer bei der Polizei Anzeige ___ möchte, muss seine Personalien angeben.","en":"Anyone who wants to file a report with the police must give their personal details."},{"ans":"erstatten","de":"Der Ausschuss muss dem Parlament bis Juni Bericht ___.","en":"The committee must report to parliament by June."},{"ans":"vertreten","de":"Sie wird ihre Meinung auch gegenüber dem Chef offen ___.","en":"She will openly stand by her opinion in front of the boss, too."}]},
 {"id":"glaubhaft-glaubwuerdig-glaeubig","lv":"C1","words":[{"w":"glaubhaft","en":"plausible, credible (a statement, a claim)"},{"w":"glaubwürdig","en":"trustworthy, credible (a person, a source)"},{"w":"gläubig","en":"religious, devout"}],"tip":"glaubhaft = so, dass man es glauben kann (Aussage; glaubhaft machen). glaubwürdig = verdient Vertrauen (Person, Quelle). gläubig = religiös.","items":[{"ans":"glaubhaft","de":"Der Antragsteller muss ___ machen, dass er die Frist unverschuldet versäumt hat.","en":"The applicant must substantiate that he missed the deadline through no fault of his own."},{"ans":"glaubhaft","de":"Sie konnte vor Gericht ___ machen, dass sie zur Tatzeit nicht in der Stadt war.","en":"In court she was able to make it credible that she was not in the city at the time of the crime."},{"ans":"glaubwürdig","de":"Das Institut gilt als besonders ___ und unabhängig.","en":"The institute is regarded as particularly trustworthy and independent."},{"ans":"gläubig","de":"Seine Eltern sind tief ___ und gehen jeden Sonntag in die Kirche.","en":"His parents are deeply religious and go to church every Sunday."}]},
 {"id":"angesehen-ansehnlich-sehenswert","lv":"C1","words":[{"w":"angesehen","en":"respected, esteemed"},{"w":"ansehnlich","en":"considerable; good-looking, presentable"},{"w":"sehenswert","en":"worth seeing"}],"tip":"angesehen = hat einen guten Ruf. ansehnlich = beträchtlich (Summe) oder hübsch anzusehen. sehenswert = lohnt einen Besuch.","items":[{"ans":"angesehen","de":"Der Anwalt ist in der ganzen Stadt hoch ___.","en":"The lawyer is highly respected throughout the city."},{"ans":"angesehen","de":"Als Wissenschaftlerin ist sie auch international hoch ___.","en":"As a scientist she is also highly regarded internationally."},{"ans":"ansehnlich","de":"Mit 40.000 Euro ist der Betrag ___ genug, um fast alle Kosten zu decken.","en":"At 40,000 euros the amount is substantial enough to cover almost all the costs."},{"ans":"sehenswert","de":"Die Prager Burg ist unbedingt ___: Planen Sie für den Besuch mindestens einen halben Tag ein.","en":"Prague Castle is a must-see: allow at least half a day for the visit."}]},
 {"id":"anspruch-ansprache-anrede","lv":"C1","words":[{"w":"Anspruch","en":"claim, entitlement; demand"},{"w":"Ansprache","en":"(short) speech, address"},{"w":"Anrede","en":"form of address; salutation"}],"tip":"Anspruch (auf) = Recht auf etwas; hohe Ansprüche = hohe Erwartungen. Ansprache = kurze Rede. Anrede = Form, mit der man jemanden anspricht (im Brief: „Sehr geehrte …“).","items":[{"ans":"Anspruch","de":"Jeder Arbeitnehmer hat ___ auf bezahlten Urlaub.","en":"Every employee is entitled to paid leave."},{"ans":"Anspruch","de":"Sie hat einen hohen ___ an die Qualität ihrer Arbeit.","en":"She has high standards for the quality of her work."},{"ans":"Ansprache","de":"Der Bürgermeister hielt zur Eröffnung eine kurze ___.","en":"The mayor gave a short address at the opening."},{"ans":"Anrede","de":"In einem formellen Brief steht oben die ___, zum Beispiel „Sehr geehrte Frau Müller“.","en":"In a formal letter the salutation goes at the top, for example \"Sehr geehrte Frau Müller\"."}]},
 {"id":"eindruck-ausdruck-abdruck","lv":"C1","words":[{"w":"Eindruck","en":"impression"},{"w":"Ausdruck","en":"expression; printout"},{"w":"Abdruck","en":"imprint, print; reprint (in a publication)"}],"tip":"Eindruck = was man von etwas gewinnt (einen Eindruck haben/hinterlassen). Ausdruck = Äußerung (Gesichtsausdruck, passender Ausdruck) oder Papierausdruck. Abdruck = Spur eines Gegenstands; Veröffentlichung im Druck.","items":[{"ans":"Eindruck","de":"Ich habe den ___, dass er uns etwas verheimlicht.","en":"I have the impression that he is hiding something from us."},{"ans":"Eindruck","de":"Der neue Kollege hat bei der Präsentation einen sehr guten ___ hinterlassen.","en":"The new colleague made a very good impression at the presentation."},{"ans":"Ausdruck","de":"Sein Gesicht nahm plötzlich einen besorgten ___ an.","en":"His face suddenly took on a worried expression."},{"ans":"Ausdruck","de":"Er sucht noch nach dem passenden ___ für seine Gefühle.","en":"He is still looking for the right expression for his feelings."},{"ans":"Abdruck","de":"Für die neue Krone nimmt die Zahnärztin zuerst einen ___ der Zähne.","en":"For the new crown the dentist first takes an impression of the teeth."},{"ans":"Abdruck","de":"Die Redaktion lehnte den ___ des Leserbriefs in der nächsten Ausgabe ab.","en":"The editors rejected the printing of the reader's letter in the next issue."}]},
 {"id":"konzept-konzession-konzentration","lv":"C1","words":[{"w":"Konzept","en":"concept, plan; draft"},{"w":"Konzession","en":"concession; licence"},{"w":"Konzentration","en":"concentration"}],"tip":"Konzept = Plan, Entwurf. Konzession = Zugeständnis oder behördliche Erlaubnis (Schankkonzession). Konzentration = Aufmerksamkeit; Anhäufung.","items":[{"ans":"Konzept","de":"Das ___ der neuen Schule setzt auf Projektarbeit statt Frontalunterricht.","en":"The new school's concept relies on project work instead of teacher-centred lessons."},{"ans":"Konzept","de":"Der Redner hatte kein schriftliches ___ und sprach völlig frei.","en":"The speaker had no written draft and spoke completely freely."},{"ans":"Konzession","de":"Die Gemeinde erteilte dem Wirt die ___ für den Ausschank.","en":"The municipality granted the innkeeper the licence to serve alcohol."},{"ans":"Konzession","de":"In den Verhandlungen war die Gewerkschaft zu keiner einzigen ___ bereit.","en":"In the negotiations the union was not prepared to make a single concession."},{"ans":"Konzentration","de":"Für die Prüfung brauchst du höchste ___.","en":"For the exam you need the highest concentration."},{"ans":"Konzentration","de":"Bei dem Lärm fällt mir die ___ schwer.","en":"With this noise I find it hard to concentrate."}]},
 {"id":"praemisse-praemie-premiere","lv":"C1","words":[{"w":"Prämisse","en":"premise, assumption"},{"w":"Prämie","en":"bonus; (insurance) premium"},{"w":"Premiere","en":"premiere, first night"}],"tip":"Prämisse = Annahme, von der eine Argumentation ausgeht. Prämie = Bonus, Belohnung; auch Versicherungsbeitrag. Premiere = Erstaufführung.","items":[{"ans":"Prämisse","de":"Der ganzen Argumentation liegt eine falsche ___ zugrunde.","en":"The whole argument is based on a false premise."},{"ans":"Prämisse","de":"Unter der ___, dass die Preise stabil bleiben, ist der Plan realistisch.","en":"On the assumption that prices remain stable, the plan is realistic."},{"ans":"Prämie","de":"Für das Rekordjahr zahlte die Firma allen Mitarbeitern eine ___.","en":"For the record year the company paid all employees a bonus."},{"ans":"Prämie","de":"Die Versicherung verlangt jedes Jahr eine höhere ___.","en":"The insurer demands a higher premium every year."},{"ans":"Premiere","de":"Die ___ des neuen Stücks war schon Wochen vorher ausverkauft.","en":"The premiere of the new play was sold out weeks in advance."},{"ans":"Premiere","de":"Zur festlichen ___ des Films kamen viele Gäste in Abendgarderobe.","en":"Many guests in evening dress came to the festive premiere of the film."}]},
 {"id":"konsens-dissens","lv":"C1","words":[{"w":"Konsens","en":"consensus, agreement"},{"w":"Dissens","en":"disagreement, dissent"}],"tip":"Konsens = Übereinstimmung der Meinungen. Dissens = Meinungsverschiedenheit, fehlende Einigkeit.","items":[{"ans":"Konsens","de":"Nach langer Debatte erzielten die Delegierten endlich einen ___.","en":"After a long debate the delegates finally reached a consensus."},{"ans":"Konsens","de":"In der Frage der Rentenreform herrscht inzwischen ein breiter ___: Alle Fraktionen stimmen dem Entwurf zu.","en":"On the question of pension reform there is now broad consensus: all parliamentary groups agree to the draft."},{"ans":"Dissens","de":"Über die Finanzierung besteht weiterhin ein tiefer ___: Die Koalitionspartner sind sich nicht einig.","en":"There is still a deep disagreement over financing: the coalition partners cannot agree."},{"ans":"Dissens","de":"Ein ___ in dieser Grundsatzfrage ist nicht auszuschließen, denn die Positionen liegen weit auseinander.","en":"A disagreement on this matter of principle cannot be ruled out, because the positions are far apart."}]},
 {"id":"affekt-effekt-defekt","lv":"C1","words":[{"w":"Affekt","en":"(strong) emotion, passion"},{"w":"Effekt","en":"effect"},{"w":"Defekt","en":"defect, fault"}],"tip":"Affekt = heftige Gefühlsregung (im Affekt handeln). Effekt = Wirkung, Ergebnis. Defekt = technischer oder körperlicher Schaden.","items":[{"ans":"Affekt","de":"Er hat die Tat im ___ begangen, ohne vorher darüber nachzudenken.","en":"He committed the act in the heat of the moment, without thinking about it beforehand."},{"ans":"Affekt","de":"Das Gericht berücksichtigte, dass die Tat im ___ geschehen war.","en":"The court took into account that the act had occurred in the heat of the moment."},{"ans":"Effekt","de":"Die Maßnahme hatte den gewünschten ___: Die Zahl der Unfälle sank deutlich.","en":"The measure had the desired effect: the number of accidents fell significantly."},{"ans":"Effekt","de":"Der Zaubertrick hat auf das Publikum einen verblüffenden ___.","en":"The magic trick has an astonishing effect on the audience."},{"ans":"Defekt","de":"Der Ausfall wird durch einen ___ am Motor verursacht, den die Werkstatt reparieren muss.","en":"The breakdown is caused by a fault in the engine, which the garage has to repair."},{"ans":"Defekt","de":"Ein ___ am Bremssystem zwingt den Hersteller, das Auto zurückzurufen.","en":"A defect in the braking system forces the manufacturer to recall the car."}]},
 {"id":"gedenken-ermahnen","lv":"C1","words":[{"w":"gedenken","en":"to commemorate (+ Gen.)"},{"w":"ermahnen","en":"to admonish, to urge"}],"tip":"gedenken + Genitiv = feierlich an Verstorbene/Ereignisse denken (der Opfer gedenken). ermahnen = jemanden zu richtigem Verhalten auffordern (jemanden zur Ruhe ermahnen).","items":[{"ans":"gedenken","de":"Am Jahrestag wollen die Bürger der Opfer des Krieges mit einer Schweigeminute ___.","en":"On the anniversary the citizens want to commemorate the victims of the war with a minute's silence."},{"ans":"gedenken","de":"Die Gemeinde will ihres verstorbenen Pfarrers mit einem Gottesdienst ___.","en":"The parish wants to commemorate its late pastor with a service."},{"ans":"ermahnen","de":"Die Lehrerin musste den Schüler mehrfach zur Ruhe ___.","en":"The teacher had to admonish the pupil several times to be quiet."},{"ans":"ermahnen","de":"Der Richter musste den Zeugen eindringlich ___, bei der Wahrheit zu bleiben.","en":"The judge had to urge the witness earnestly to stick to the truth."}]},
 {"id":"betreffen-betragen-betreiben-betreten","lv":"B2","words":[{"w":"betreffen","en":"to affect, to concern"},{"w":"betragen","en":"to amount to"},{"w":"betreiben","en":"to run, to operate; to pursue"},{"w":"betreten","en":"to enter, to step on"}],"tip":"betreffen = jemanden/etwas angehen. betragen = (Summe, Dauer) ergeben. betreiben = einen Betrieb führen, eine Anlage laufen lassen. betreten = den Fuß auf/in etwas setzen.","items":[{"ans":"betreffen","de":"Die neue Regelung wird vor allem Familien mit Kindern ___.","en":"The new regulation will mainly affect families with children."},{"ans":"betreffen","de":"Das Problem könnte uns alle ___.","en":"The problem could affect all of us."},{"ans":"betragen","de":"Die Kosten für den Umbau werden voraussichtlich rund 40.000 Euro ___.","en":"The cost of the conversion is expected to amount to around 40,000 euros."},{"ans":"betragen","de":"Die Wartezeit kann bis zu drei Monate ___.","en":"The waiting time can be up to three months."},{"ans":"betreiben","de":"Mit dem geerbten Geld möchte sie ein kleines Café ___.","en":"With the money she inherited she would like to run a small café."},{"ans":"betreiben","de":"Das Unternehmen will ein eigenes Kraftwerk ___.","en":"The company wants to operate its own power plant."},{"ans":"betreten","de":"Bitte ziehen Sie die Schuhe aus, bevor Sie die Wohnung ___.","en":"Please take off your shoes before you enter the flat."},{"ans":"betreten","de":"Der Rasen darf nicht ___ werden.","en":"The lawn must not be walked on."}]},
 {"id":"bewahren-bewaehren-bewaeltigen","lv":"C1","words":[{"w":"bewahren","en":"to keep, to preserve"},{"w":"bewähren","en":"to prove oneself, to prove its worth (sich bewähren)"},{"w":"bewältigen","en":"to cope with, to master"}],"tip":"bewahren = erhalten, schützen (Ruhe bewahren). sich bewähren = sich als tauglich erweisen. bewältigen = eine schwierige Aufgabe schaffen.","items":[{"ans":"bewahren","de":"Auch in schwierigen Situationen sollte man Ruhe ___.","en":"Even in difficult situations one should keep calm."},{"ans":"bewahren","de":"Das Museum hat die Aufgabe, wertvolle Handschriften für kommende Generationen zu ___.","en":"The museum's task is to preserve valuable manuscripts for future generations."},{"ans":"bewähren","de":"Das neue System muss sich erst im Alltag ___.","en":"The new system first has to prove itself in everyday use."},{"ans":"bewähren","de":"Als Berufsanfänger will er sich zuerst im Team ___.","en":"As a career starter he first wants to prove himself in the team."},{"ans":"bewältigen","de":"Die Aufgabe ist allein kaum zu ___.","en":"The task can hardly be managed alone."},{"ans":"bewältigen","de":"Die Stadt muss die Folgen des Hochwassers ___.","en":"The city has to cope with the consequences of the flood."}]},
 {"id":"ausweichen-ausweisen-ausweiten","lv":"C1","words":[{"w":"ausweichen","en":"to dodge, to evade (+ Dat.)"},{"w":"ausweisen","en":"to expel (from a country); (sich) to show ID"},{"w":"ausweiten","en":"to expand, to extend"}],"tip":"ausweichen + Dat. = aus dem Weg gehen. ausweisen = des Landes verweisen; sich ausweisen = die Identität nachweisen. ausweiten = größer/umfassender machen.","items":[{"ans":"ausweichen","de":"Der Radfahrer konnte dem plötzlich bremsenden Auto nicht mehr ___.","en":"The cyclist could no longer swerve around the suddenly braking car."},{"ans":"ausweichen","de":"Der Minister wollte der unbequemen Frage unbedingt ___.","en":"The minister was determined to dodge the awkward question."},{"ans":"ausweisen","de":"Am Eingang müssen sich alle Besucher mit einem Personalausweis ___.","en":"At the entrance all visitors have to identify themselves with an ID card."},{"ans":"ausweisen","de":"Die Behörde will den straffälligen Ausländer aus dem Land ___.","en":"The authority wants to expel the foreign offender from the country."},{"ans":"ausweiten","de":"Das Unternehmen will sein Angebot auf neue Märkte ___.","en":"The company wants to extend its offer to new markets."},{"ans":"ausweiten","de":"Die Polizei will die Suche auf die umliegenden Wälder ___.","en":"The police want to extend the search to the surrounding forests."}]},
 {"id":"anerkennen-erkennen-bekennen","lv":"C1","words":[{"w":"anerkennen","en":"to recognise officially; to acknowledge"},{"w":"erkennen","en":"to recognise (identify); to realise"},{"w":"bekennen","en":"to confess; (sich) to profess, to declare oneself"}],"tip":"anerkennen = als gültig/verdient annehmen. erkennen = wahrnehmen, identifizieren. bekennen (sich zu) = offen zu etwas stehen; sich schuldig bekennen.","items":[{"ans":"anerkennen","de":"Viele Länder wollen den neuen Staat vorerst nicht diplomatisch ___.","en":"Many countries do not want to recognise the new state diplomatically for the time being."},{"ans":"anerkennen","de":"Die Behörde will den ausländischen Abschluss nicht ___.","en":"The authority does not want to recognise the foreign degree."},{"ans":"erkennen","de":"Selbst im Dunkeln konnte sie ihn an der Stimme ___.","en":"Even in the dark she could recognise him by his voice."},{"ans":"erkennen","de":"Ohne Brille kann ich die Schrift auf dem Schild nicht ___.","en":"Without glasses I cannot make out the writing on the sign."},{"ans":"bekennen","de":"Der Abgeordnete wollte sich öffentlich zu seinem Fehler ___.","en":"The member of parliament wanted to publicly own up to his mistake."},{"ans":"bekennen","de":"Der Verein will sich ausdrücklich zu den Grundwerten der Verfassung ___.","en":"The association explicitly wants to declare its commitment to the basic values of the constitution."}]},
 {"id":"ueberhoeren-ueberholen-ueberbringen-ueberfuehren","lv":"C1","words":[{"w":"überhören","en":"to fail to hear; to ignore (what is said)"},{"w":"überholen","en":"to overtake"},{"w":"überbringen","en":"to deliver (message, greetings)"},{"w":"überführen","en":"to prove guilty; to transfer (body, vehicle)"}],"tip":"überhören = nicht hören (wollen). überholen = an etwas vorbeifahren. überbringen = eine Nachricht/Botschaft zustellen. überführen = (einen Täter) der Schuld überführen; (einen Toten, ein Fahrzeug) an einen anderen Ort bringen.","items":[{"ans":"überhören","de":"Das laute Piepen kann man doch nicht ___!","en":"You can't possibly fail to hear that loud beeping!"},{"ans":"überhören","de":"Bei dem Lärm kann man den Wecker leicht ___.","en":"With that noise one can easily fail to hear the alarm clock."},{"ans":"überholen","de":"Auf dieser kurvigen Landstraße darf man nicht ___.","en":"On this winding country road you must not overtake."},{"ans":"überholen","de":"Der Radfahrer wollte den Lastwagen vor der Ampel ___.","en":"The cyclist wanted to overtake the lorry before the traffic light."},{"ans":"überbringen","de":"Der Bote sollte dem König eine schlechte Nachricht ___.","en":"The messenger was to deliver bad news to the king."},{"ans":"überbringen","de":"Ich soll Ihnen die besten Wünsche des Chefs ___.","en":"I am to convey the boss's best wishes to you."},{"ans":"überführen","de":"Die Polizei konnte den Täter anhand der DNA-Spuren ___.","en":"The police were able to prove the offender's guilt on the basis of the DNA traces."},{"ans":"überführen","de":"Man will den Sarg am Montag in die Heimatstadt des Verstorbenen ___.","en":"They intend to transfer the coffin to the deceased's home town on Monday."}]},
 {"id":"verstossen-entsprechen-widersprechen","lv":"C1","words":[{"w":"verstoßen","en":"to violate (gegen + Akk.)"},{"w":"entsprechen","en":"to correspond to, to meet (+ Dat.)"},{"w":"widersprechen","en":"to contradict, to object (+ Dat.)"}],"tip":"verstoßen gegen + Akk. = ein Gesetz/eine Regel brechen. entsprechen + Dat. = mit etwas übereinstimmen, eine Anforderung erfüllen. widersprechen + Dat. = anderer Meinung sein; im Gegensatz stehen.","items":[{"ans":"verstoßen","de":"Die Werbung darf nicht gegen das Gesetz ___.","en":"The advertising must not violate the law."},{"ans":"verstoßen","de":"Mit dieser Klausel würde der Vertrag gegen die guten Sitten ___.","en":"With this clause the contract would offend against public morals."},{"ans":"entsprechen","de":"Das Produkt muss den europäischen Sicherheitsnormen ___, sonst darf es nicht verkauft werden.","en":"The product must meet the European safety standards, otherwise it may not be sold."},{"ans":"entsprechen","de":"Die Beschreibung im Katalog sollte der Wirklichkeit ___, sonst fühlen sich Kunden getäuscht.","en":"The description in the catalogue should correspond to reality, otherwise customers feel deceived."},{"ans":"widersprechen","de":"Als Kind wagte ich es nie, meinem Vater laut zu ___.","en":"As a child I never dared to contradict my father out loud."},{"ans":"widersprechen","de":"Die Opposition wird der Behauptung des Ministers energisch ___.","en":"The opposition will vigorously contradict the minister's claim."}]},
 {"id":"foerdern-fordern-auffordern","lv":"B2","words":[{"w":"fördern","en":"to promote, to support"},{"w":"fordern","en":"to demand"},{"w":"auffordern","en":"to ask, to call upon (zu)"}],"tip":"fördern = unterstützen, voranbringen. fordern = nachdrücklich verlangen. auffordern (zu) = jemanden bitten oder anweisen, etwas zu tun.","items":[{"ans":"fördern","de":"Die Stadt vergibt jedes Jahr Stipendien, um junge Künstler finanziell zu ___.","en":"Every year the city awards scholarships in order to support young artists financially."},{"ans":"fördern","de":"Regelmäßiges Lesen kann die Sprachentwicklung von Kindern ___.","en":"Regular reading can promote children's language development."},{"ans":"fordern","de":"Die Gewerkschaft wird von den Arbeitgebern eine Lohnerhöhung von fünf Prozent ___.","en":"The union will demand a pay rise of five percent from the employers."},{"ans":"fordern","de":"Die Bürger wollen vom Staat mehr Transparenz ___.","en":"The citizens want to demand more transparency from the state."},{"ans":"auffordern","de":"Die Polizei musste die Demonstranten mehrfach ___, die Straße zu räumen.","en":"The police had to call upon the demonstrators several times to clear the street."},{"ans":"auffordern","de":"Der Moderator wird die Gäste ___, ihre Fragen zu stellen.","en":"The host will invite the guests to ask their questions."}]},
 {"id":"ressource-resonanz-resignation","lv":"C1","words":[{"w":"Ressource","en":"resource"},{"w":"Resonanz","en":"response, echo, resonance"},{"w":"Resignation","en":"resignation (giving up in dejection)"}],"tip":"Ressource = Vorrat, Mittel (Wasser, Zeit, Geld). Resonanz = Echo, Reaktion der Öffentlichkeit. Resignation = niedergeschlagenes Aufgeben (nicht: Rücktritt = resignation from an office).","items":[{"ans":"Ressource","de":"Wasser ist in vielen Regionen eine knappe ___.","en":"In many regions water is a scarce resource."},{"ans":"Ressource","de":"Die wichtigste ___ eines Dienstleisters ist die Zeit seiner Mitarbeiter.","en":"A service provider's most important resource is its employees' time."},{"ans":"Resonanz","de":"Die Kampagne fand eine große ___ in den Medien: Alle großen Zeitungen berichteten darüber.","en":"The campaign met with a great response in the media: all the big newspapers reported on it."},{"ans":"Resonanz","de":"Der Aufruf der Gemeinde blieb ohne jede ___: Kein einziger Bürger meldete sich.","en":"The municipality's appeal remained without any response: not a single citizen came forward."},{"ans":"Resignation","de":"Nach dem zehnten Misserfolg verfiel er in ___.","en":"After the tenth failure he sank into resignation."}]},
 {"id":"kontext-kontrolle-kontakt","lv":"B2","words":[{"w":"Kontext","en":"context"},{"w":"Kontrolle","en":"check, inspection; control"},{"w":"Kontakt","en":"contact"}],"tip":"Kontext = sprachlicher/sachlicher Zusammenhang. Kontrolle = Überprüfung; Beherrschung (außer Kontrolle). Kontakt = Verbindung, Berührung.","items":[{"ans":"Kontext","de":"Ein Zitat darf man nicht aus dem ___ reißen.","en":"One must not take a quotation out of context."},{"ans":"Kontext","de":"Die Bedeutung des Wortes ergibt sich erst aus dem ___.","en":"The meaning of the word only emerges from the context."},{"ans":"Kontrolle","de":"Bei der ___ an der Grenze wurde sein Koffer durchsucht.","en":"During the check at the border his suitcase was searched."},{"ans":"Kontrolle","de":"Das Feuer geriet außer ___.","en":"The fire got out of control."},{"ans":"Kontakt","de":"Nach dem Umzug haben wir den ___ zu den alten Nachbarn verloren.","en":"After the move we lost contact with our old neighbours."},{"ans":"Kontakt","de":"Bitte nehmen Sie ___ mit uns auf, wenn Sie Fragen haben.","en":"Please get in touch with us if you have any questions."}]},
 {"id":"aspekt-respekt-prospekt","lv":"B2","words":[{"w":"Aspekt","en":"aspect"},{"w":"Respekt","en":"respect"},{"w":"Prospekt","en":"brochure, leaflet"}],"tip":"Aspekt = Gesichtspunkt. Respekt = Achtung vor jemandem. Prospekt = Werbeheft, Broschüre.","items":[{"ans":"Aspekt","de":"Der wirtschaftliche ___ ist nur einer von mehreren Punkten der Debatte.","en":"The economic aspect is only one of several points in the debate."},{"ans":"Aspekt","de":"Unter diesem ___ habe ich die Sache noch nie betrachtet.","en":"I have never looked at the matter from this angle."},{"ans":"Respekt","de":"Die Schüler zeigten dem Lehrer keinerlei ___.","en":"The pupils showed the teacher no respect whatsoever."},{"ans":"Respekt","de":"Sie genießt bei den Kollegen großen ___.","en":"She enjoys great respect among her colleagues."},{"ans":"Prospekt","de":"Im Reisebüro nahm ich einen ___ über Norwegen mit.","en":"At the travel agency I took a brochure about Norway."},{"ans":"Prospekt","de":"Der ___ des Hotels zeigt Bilder der Zimmer und des Pools.","en":"The hotel's brochure shows pictures of the rooms and the pool."}]},
 {"id":"spenden-spendieren-stiften","lv":"C1","words":[{"w":"spenden","en":"to donate; to give (blood, applause)"},{"w":"spendieren","en":"to treat someone to, to buy for someone"},{"w":"stiften","en":"to endow, to found; to cause (peace, discord)"}],"tip":"spenden = Geld/Blut/Beifall geben. spendieren = jemanden einladen, etwas auf eigene Kosten ausgeben (Runde, Essen). stiften = dauerhaft Mittel geben (Lehrstuhl, Preis) oder bewirken (Frieden, Unruhe).","items":[{"ans":"spenden","de":"Wer Blut ___ möchte, muss gesund und mindestens 18 Jahre alt sein.","en":"Anyone who wants to donate blood must be healthy and at least 18."},{"ans":"spenden","de":"Das Publikum wollte den Musikern lange Beifall ___.","en":"The audience wanted to applaud the musicians for a long time."},{"ans":"spendieren","de":"Nach der Prüfung wollte er sich zur Belohnung ein großes Eis ___.","en":"After the exam he wanted to treat himself to a big ice cream as a reward."},{"ans":"stiften","de":"Mit dem Gerücht wollte er nur Unfrieden ___.","en":"He only wanted to sow discord with that rumour."},{"ans":"stiften","de":"Die widersprüchlichen Meldungen könnten nur Verwirrung ___.","en":"The contradictory reports could only cause confusion."}]},
 {"id":"beantragen-beauftragen-beanstanden-beanspruchen","lv":"C1","words":[{"w":"beantragen","en":"to apply for, to file a request for"},{"w":"beauftragen","en":"to commission, to instruct"},{"w":"beanstanden","en":"to complain about, to object to"},{"w":"beanspruchen","en":"to claim; to take up (time, space)"}],"tip":"beantragen = schriftlich bei einer Stelle verlangen (Genehmigung, Scheidung). beauftragen = jemandem einen Auftrag geben. beanstanden = einen Mangel rügen. beanspruchen = als Recht fordern; Zeit/Platz brauchen.","items":[{"ans":"beantragen","de":"Für den Umbau muss die Eigentümerin zuerst eine Baugenehmigung ___.","en":"For the conversion the owner first has to apply for a building permit."},{"ans":"beantragen","de":"Er möchte beim Familiengericht die Scheidung ___.","en":"He wants to file for divorce at the family court."},{"ans":"beauftragen","de":"Die Stadt will ein Architekturbüro mit der Planung ___.","en":"The city wants to commission an architects' office with the planning."},{"ans":"beauftragen","de":"Ich werde einen Anwalt ___, die Sache zu klären.","en":"I will instruct a lawyer to settle the matter."},{"ans":"beanstanden","de":"Der Kunde wollte die Ware ___, weil sie beschädigt war.","en":"The customer wanted to complain about the goods because they were damaged."},{"ans":"beanstanden","de":"Die Prüfer hatten an der Arbeit nichts zu ___.","en":"The examiners had nothing to object to in the work."},{"ans":"beanspruchen","de":"Das Projekt wird viel Zeit ___.","en":"The project will take up a lot of time."},{"ans":"beanspruchen","de":"Als Erbe kann er einen Teil des Vermögens als sein gutes Recht ___.","en":"As an heir he can claim part of the estate as his rightful due."}]},
 {"id":"kompliment-kompromiss-kompensation","lv":"C1","words":[{"w":"Kompliment","en":"compliment"},{"w":"Kompromiss","en":"compromise"},{"w":"Kompensation","en":"compensation (making up for something)"}],"tip":"Kompliment = freundliches Lob. Kompromiss = Einigung durch gegenseitiges Nachgeben. Kompensation = Ausgleich für einen Nachteil.","items":[{"ans":"Kompliment","de":"Er machte ihr ein ___ für ihre Rede.","en":"He paid her a compliment on her speech."},{"ans":"Kompliment","de":"Für dein neues Kleid bekommst du ein ___ von mir.","en":"You get a compliment from me for your new dress."},{"ans":"Kompromiss","de":"Nach langen Verhandlungen schlossen beide Seiten einen ___.","en":"After long negotiations both sides reached a compromise."},{"ans":"Kompromiss","de":"Beide Parteien suchten nach einem ___, mit dem alle leben könnten.","en":"Both parties were looking for a compromise everyone could live with."},{"ans":"Kompensation","de":"Für die vielen Überstunden bekommt er eine zeitliche ___: zwei zusätzliche Urlaubstage.","en":"For the many overtime hours he gets compensation in time off: two extra days of holiday."},{"ans":"Kompensation","de":"Die Firma bot den betroffenen Kunden eine finanzielle ___ an.","en":"The company offered the affected customers financial compensation."}]},
 {"id":"statue-statur-status","lv":"C1","words":[{"w":"Statue","en":"statue"},{"w":"Statur","en":"build, physique, stature"},{"w":"Status","en":"status, standing"}],"tip":"Statue = Standbild. Statur = Körperbau (von kräftiger Statur). Status = rechtliche/gesellschaftliche Stellung.","items":[{"ans":"Statue","de":"Auf dem Marktplatz steht eine bronzene ___ des Stadtgründers.","en":"On the market square stands a bronze statue of the city's founder."},{"ans":"Statue","de":"Die ___ wurde im Krieg zerstört und später originalgetreu nachgebildet.","en":"The statue was destroyed in the war and later faithfully recreated."},{"ans":"Statur","de":"Er ist ein Mann von kräftiger ___.","en":"He is a man of sturdy build."},{"ans":"Statur","de":"Mit seiner imposanten ___ fiel er in jeder Menschenmenge auf.","en":"With his imposing build he stood out in any crowd."},{"ans":"Status","de":"Der rechtliche ___ der Flüchtlinge ist noch nicht geklärt.","en":"The legal status of the refugees has not yet been clarified."},{"ans":"Status","de":"Mit dem neuen Titel stieg auch ihr sozialer ___.","en":"With the new title her social standing rose too."}]},
 {"id":"mangels-anlaesslich-infolge-dank","lv":"C1","words":[{"w":"mangels","en":"for lack of (+ Gen.)"},{"w":"anlässlich","en":"on the occasion of (+ Gen.)"},{"w":"infolge","en":"as a result of (+ Gen.)"},{"w":"dank","en":"thanks to (+ Dat./Gen.)"}],"tip":"mangels = weil etwas fehlt. anlässlich = aus Anlass eines Ereignisses. infolge = als Folge (oft eines negativen Ereignisses). dank = dank jemandes Hilfe (positive Ursache).","items":[{"ans":"mangels","de":"Wir mussten ___ Alternativen das teure Hotel nehmen.","en":"For lack of alternatives we had to take the expensive hotel."},{"ans":"mangels","de":"Die Veranstaltung fiel ___ Interesses aus.","en":"The event was cancelled for lack of interest."},{"ans":"anlässlich","de":"Die Stadt lud ___ ihres 800-jährigen Bestehens zu einem großen Fest ein.","en":"On the occasion of its 800th anniversary the city invited people to a big festival."},{"ans":"anlässlich","de":"Der Bürgermeister überreichte der ältesten Einwohnerin ___ ihres 90. Geburtstags einen Blumenstrauß.","en":"On the occasion of her 90th birthday the mayor presented the oldest resident with a bouquet."},{"ans":"infolge","de":"Er starb ___ einer schweren Lungenentzündung.","en":"He died as a result of severe pneumonia."},{"ans":"infolge","de":"Der Pilot erlitt ___ der extremen Belastung einen Kreislaufkollaps.","en":"The pilot suffered a circulatory collapse as a result of the extreme strain."},{"ans":"dank","de":"Das Feuer konnte ___ dem Einsatz der Feuerwehr schnell gelöscht werden.","en":"The fire could be extinguished quickly thanks to the fire brigade's efforts."},{"ans":"dank","de":"Wir haben die Prüfung nur ___ dir bestanden.","en":"We only passed the exam thanks to you."}]},
 {"id":"geschaeftig-geschaeftlich","lv":"C1","words":[{"w":"geschäftig","en":"busy, bustling (eagerly active)"},{"w":"geschäftlich","en":"on business; commercial"}],"tip":"geschäftig = eifrig beschäftigt, hektisch tätig. geschäftlich = das Geschäft/den Beruf betreffend (Gegensatz: privat).","items":[{"ans":"geschäftig","de":"Die Köchin werkelte den ganzen Morgen ___ in der Küche.","en":"The cook bustled about busily in the kitchen all morning."},{"ans":"geschäftig","de":"Kurz vor der Eröffnung eilten die Kellner ___ zwischen den Tischen hin und her.","en":"Shortly before the opening the waiters rushed busily back and forth between the tables."},{"ans":"geschäftlich","de":"Mein Mann reist diese Woche ___ nach Hamburg.","en":"My husband is travelling to Hamburg on business this week."},{"ans":"geschäftlich","de":"Wir treffen uns heute nicht privat, sondern ___.","en":"Today we are meeting not privately but on business."}]},
 {"id":"gebraeuchlich-brauchbar","lv":"C1","words":[{"w":"gebräuchlich","en":"common, in common use"},{"w":"brauchbar","en":"usable, serviceable"}],"tip":"gebräuchlich = allgemein üblich (Wort, Maßeinheit, Methode). brauchbar = nützlich, verwendbar (Ergebnis, Idee, Gerät).","items":[{"ans":"gebräuchlich","de":"Dieses Wort ist im Süden allgemein ___, im Norden dagegen kaum bekannt.","en":"This word is in widespread use in the south, but hardly known in the north."},{"ans":"gebräuchlich","de":"Die Methode ist zwar allgemein ___, aber nicht brauchbar: Sie liefert regelmäßig falsche Ergebnisse.","en":"The method is widely used, admittedly, but not usable: it regularly gives wrong results."},{"ans":"brauchbar","de":"Das Ergebnis der Messung ist nicht ___: Das Gerät war falsch eingestellt.","en":"The result of the measurement is not usable: the device was set incorrectly."},{"ans":"brauchbar","de":"Seine Idee war gut, aber in dieser Form kaum ___.","en":"His idea was good, but hardly workable in this form."}]},
 {"id":"bescheinigen-beschwichtigen-beschoenigen-beschwoeren","lv":"C1","words":[{"w":"bescheinigen","en":"to certify, to confirm in writing"},{"w":"beschwichtigen","en":"to appease, to calm down"},{"w":"beschönigen","en":"to gloss over, to sugar-coat"},{"w":"beschwören","en":"to swear to; to implore"}],"tip":"bescheinigen = schriftlich bestätigen. beschwichtigen = einen Aufgebrachten beruhigen. beschönigen = einen schlechten Sachverhalt schöner darstellen. beschwören = eidlich bekräftigen / eindringlich bitten.","items":[{"ans":"bescheinigen","de":"Der Arzt soll mir die Arbeitsunfähigkeit schriftlich ___.","en":"The doctor is supposed to certify my incapacity for work in writing."},{"ans":"bescheinigen","de":"Die Schule muss dem Schüler den erfolgreichen Abschluss ___.","en":"The school must certify the pupil's successful completion."},{"ans":"beschwichtigen","de":"Der Sprecher bemühte sich, die erregten Gemüter mit freundlichen Worten und einem Zugeständnis zu ___.","en":"The spokesman tried to calm the agitated spirits with friendly words and a concession."},{"ans":"beschwichtigen","de":"Er sagte, es sei alles halb so schlimm, um die besorgten Eltern ein wenig zu ___.","en":"He said it was not half as bad as it looked, to put the worried parents' minds at ease a little."},{"ans":"beschönigen","de":"Der Minister versuchte, die schlechten Wirtschaftsdaten zu ___, doch die Zahlen sprachen für sich.","en":"The minister tried to gloss over the poor economic data, but the figures spoke for themselves."},{"ans":"beschönigen","de":"Der Bericht neigt dazu, die Verluste zu ___.","en":"The report tends to play down the losses."},{"ans":"beschwören","de":"Der Zeuge war bereit, seine Aussage unter Eid zu ___.","en":"The witness was prepared to swear to his statement under oath."},{"ans":"beschwören","de":"Ich kann hoch und heilig ___, dass ich die Tür abgeschlossen habe.","en":"I can swear that I locked the door."}]},
 {"id":"gewaehren-gewaehrleisten","lv":"C1","words":[{"w":"gewähren","en":"to grant"},{"w":"gewährleisten","en":"to guarantee, to ensure"}],"tip":"gewähren = jemandem etwas bewilligen (Kredit, Einsicht, Urlaub). gewährleisten = dafür sorgen, dass etwas sicher eintritt oder gilt; oft mit „dass“-Satz.","items":[{"ans":"gewähren","de":"Die Bank wollte dem Unternehmen keinen weiteren Kredit ___.","en":"The bank did not want to grant the company any further loan."},{"ans":"gewähren","de":"Der Händler war bereit, uns bei Barzahlung drei Prozent Rabatt zu ___.","en":"The dealer was willing to grant us a three percent discount for cash payment."},{"ans":"gewährleisten","de":"Eine lückenlose Kontrolle soll ___, dass keine fehlerhaften Teile ausgeliefert werden.","en":"A complete inspection is meant to ensure that no faulty parts are delivered."},{"ans":"gewährleisten","de":"Die Stadt muss ___, dass alle Kinder einen Kitaplatz bekommen.","en":"The city must guarantee that all children get a daycare place."}]},
 {"id":"zeitig-zeitweise-zeitgemaess-zeitlich","lv":"C1","words":[{"w":"zeitig","en":"early, in good time"},{"w":"zeitweise","en":"at times, temporarily"},{"w":"zeitgemäß","en":"up to date, modern"},{"w":"zeitlich","en":"in terms of time, temporal"}],"tip":"zeitig = früh genug. zeitweise = ab und zu / für eine Weile. zeitgemäß = der heutigen Zeit entsprechend. zeitlich = die Zeit betreffend (zeitlich passt es nicht).","items":[{"ans":"zeitig","de":"Wir müssen morgen ___ aufstehen, denn der Zug fährt schon um fünf.","en":"We have to get up early tomorrow, because the train leaves at five."},{"ans":"zeitig","de":"Wer einen guten Platz haben möchte, sollte ___ da sein.","en":"Anyone who wants a good seat should be there in good time."},{"ans":"zeitweise","de":"Im Bergland kann es im Frühling ___ noch schneien.","en":"In the mountains it can still snow at times in spring."},{"ans":"zeitweise","de":"Das Kind hat ___ hohes Fieber, aber meist nur abends.","en":"The child has a high temperature at times, but mostly only in the evening."},{"ans":"zeitgemäß","de":"Die Methode ist nicht mehr ___; heute arbeiten wir digital.","en":"The method is no longer up to date; today we work digitally."},{"ans":"zeitgemäß","de":"Die Schule will ihren Unterricht endlich ___ gestalten: modern, digital, mit Tablets statt Kreidetafeln.","en":"The school finally wants to make its teaching up to date: modern, digital, with tablets instead of chalkboards."},{"ans":"zeitlich","de":"Die beiden Termine liegen ___ und räumlich weit auseinander.","en":"The two appointments are far apart both in time and in place."},{"ans":"zeitlich","de":"Das Projekt ist finanziell und ___ kaum zu stemmen.","en":"The project is hardly manageable financially and in terms of time."}]},
 {"id":"ausdruecklich-ausschliesslich-ausfuehrlich-ausgiebig","lv":"C1","words":[{"w":"ausdrücklich","en":"explicitly, expressly"},{"w":"ausschließlich","en":"exclusively, only"},{"w":"ausführlich","en":"in detail"},{"w":"ausgiebig","en":"extensively, at length (to the full)"}],"tip":"ausdrücklich = klar und deutlich gesagt. ausschließlich = nur, nichts anderes. ausführlich = mit vielen Einzelheiten. ausgiebig = reichlich, ohne Eile (ausgiebig frühstücken, ausschlafen).","items":[{"ans":"ausdrücklich","de":"Im Mietvertrag ist das Halten von Haustieren ___ verboten.","en":"In the tenancy agreement keeping pets is expressly forbidden."},{"ans":"ausdrücklich","de":"Mit einem einzigen Satz hat der Chef ___ klargemacht, dass niemand früher gehen darf.","en":"In a single sentence the boss made it explicitly clear that nobody may leave early."},{"ans":"ausschließlich","de":"Die Ursache liegt nicht ___ bei der Technik, sondern auch beim Personal.","en":"The cause lies not only with the technology but also with the staff."},{"ans":"ausschließlich","de":"Er ernährt sich nicht ___ von Fleisch, sondern isst auch viel Gemüse.","en":"He does not live exclusively on meat, but also eats a lot of vegetables."},{"ans":"ausführlich","de":"Der Bericht ist kurz, die Anlage dagegen sehr ___.","en":"The report is short, but the appendix is very detailed."},{"ans":"ausgiebig","de":"Nach der Wanderung haben wir lange und ___ gefrühstückt.","en":"After the hike we had a long, leisurely and hearty breakfast."},{"ans":"ausgiebig","de":"Am Wochenende schlafen wir gern lange und ___ aus.","en":"At the weekend we like to sleep in long and to our heart's content."},{"ans":"ausführlich","de":"Die Gebrauchsanweisung ist so ___, dass sie jeden einzelnen Handgriff erklärt.","en":"The instructions are so detailed that they explain every single step."}]},
 {"id":"stoeren-zerstoeren-verstoeren-betoeren","lv":"C1","words":[{"w":"stören","en":"to disturb, to bother"},{"w":"zerstören","en":"to destroy"},{"w":"verstören","en":"to unsettle, to disturb deeply"},{"w":"betören","en":"to bewitch, to captivate"}],"tip":"stören = unterbrechen, belästigen. zerstören = vernichten. verstören = seelisch erschüttern. betören = durch Reiz verzaubern (literarisch).","items":[{"ans":"stören","de":"Entschuldigung, ich wollte Sie bei der Arbeit nicht ___.","en":"Sorry, I didn't want to disturb you at work."},{"ans":"stören","de":"Der Lärm der Baustelle darf die Anwohner nachts nicht im Schlaf ___.","en":"The noise from the building site must not disturb the residents in their sleep at night."},{"ans":"zerstören","de":"Ein einziges Feuer kann ganze Wälder ___.","en":"A single fire can destroy entire forests."},{"ans":"zerstören","de":"Die Bomber wollten die Brücke ___.","en":"The bombers wanted to destroy the bridge."},{"ans":"verstören","de":"Die Bilder des Unglücks können kleine Kinder tief ___.","en":"The pictures of the accident can deeply unsettle small children."},{"ans":"betören","de":"Mit ihrem Charme wollte sie den reichen Geschäftsmann ___, um ihn für sich zu gewinnen.","en":"She wanted to captivate the rich businessman with her charm in order to win him over."},{"ans":"betören","de":"Der süße Duft des Flieders kann einen im Frühling geradezu ___ und verzaubern.","en":"In spring the sweet scent of lilac can positively bewitch and enchant you."}]},
 {"id":"vorwand-vorwurf-vorsatz-voraussetzung","lv":"C1","words":[{"w":"Vorwand","en":"pretext"},{"w":"Vorwurf","en":"reproach, accusation"},{"w":"Vorsatz","en":"resolution; intent"},{"w":"Voraussetzung","en":"prerequisite, condition"}],"tip":"Vorwand = vorgeschobener Grund. Vorwurf = Beschuldigung, Tadel. Vorsatz = fester Entschluss; juristisch: Absicht. Voraussetzung = Bedingung, die erfüllt sein muss.","items":[{"ans":"Vorwand","de":"Unter dem ___ einer Erkrankung blieb er der Sitzung fern.","en":"Under the pretext of an illness he stayed away from the meeting."},{"ans":"Vorwand","de":"Sie suchte nur einen ___, um früher gehen zu können.","en":"She was only looking for a pretext to be able to leave early."},{"ans":"Vorwurf","de":"Erst nach langen Ermittlungen erhob die Staatsanwaltschaft den ___ der Untreue.","en":"Only after lengthy investigations did the public prosecutor's office raise the accusation of breach of trust."},{"ans":"Vorwurf","de":"Ich mache dir deshalb keinen ___.","en":"I don't reproach you for that."},{"ans":"Vorsatz","de":"Mein guter ___ für das neue Jahr ist, mehr Sport zu treiben.","en":"My good resolution for the new year is to do more sport."},{"ans":"Vorsatz","de":"Die Tat geschah mit ___, nicht aus Versehen.","en":"The act was committed with intent, not by mistake."},{"ans":"Voraussetzung","de":"Eine abgeschlossene Ausbildung ist die wichtigste ___ für diese Stelle.","en":"A completed apprenticeship is the most important prerequisite for this job."},{"ans":"Voraussetzung","de":"Gute Sprachkenntnisse sind keine ___, aber ein Vorteil.","en":"Good language skills are not a requirement, but an advantage."}]},
 {"id":"anlass-anliegen-anlage-anlauf","lv":"C1","words":[{"w":"Anlass","en":"occasion, reason"},{"w":"Anliegen","en":"request, concern"},{"w":"Anlage","en":"facility, plant; enclosure; investment"},{"w":"Anlauf","en":"run-up; attempt"}],"tip":"Anlass = Grund, Gelegenheit. Anliegen = Bitte oder persönliches Herzensthema. Anlage = Einrichtung/Werk; Anhang einer Mail; Geldanlage. Anlauf = Anlaufstrecke; Versuch (beim zweiten Anlauf).","items":[{"ans":"Anlass","de":"Es besteht kein ___ zur Sorge.","en":"There is no reason for concern."},{"ans":"Anlass","de":"Das Treffen fand aus traurigem ___ statt: Der Gründer des Vereins war gestorben.","en":"The meeting took place on a sad occasion: the founder of the club had died."},{"ans":"Anliegen","de":"Ich habe ein ___ an Sie: Könnten Sie mir bitte helfen?","en":"I have a request to make of you: could you please help me?"},{"ans":"Anliegen","de":"Der Schutz der Wälder ist ihr persönliches ___.","en":"Protecting the forests is her personal concern."},{"ans":"Anlage","de":"Den unterschriebenen Vertrag finden Sie in der ___ zu dieser E-Mail.","en":"You will find the signed contract in the attachment to this e-mail."},{"ans":"Anlage","de":"Die neue ___ zur Abwasserreinigung geht im Herbst in Betrieb.","en":"The new sewage treatment plant goes into operation in autumn."},{"ans":"Anlauf","de":"Der Springer nahm einen langen ___ und sprang über die Latte.","en":"The jumper took a long run-up and cleared the bar."},{"ans":"Anlauf","de":"Nach mehreren gescheiterten Versuchen nahm er einen neuen ___.","en":"After several failed attempts he made a fresh attempt."}]},
 {"id":"absicht-aussicht-ansicht-einsicht","lv":"B2","words":[{"w":"Absicht","en":"intention"},{"w":"Aussicht","en":"view; prospect"},{"w":"Ansicht","en":"opinion; view (of something)"},{"w":"Einsicht","en":"insight; realisation; access (to files)"}],"tip":"Absicht = Plan, Vorsatz. Aussicht = Blick in die Ferne; Chance (Aussicht auf Erfolg). Ansicht = Meinung. Einsicht = Erkenntnis, Verständnis (Einsicht zeigen).","items":[{"ans":"Absicht","de":"Das war keine ___, ich habe dich wirklich nicht gesehen.","en":"That wasn't on purpose, I really didn't see you."},{"ans":"Absicht","de":"Es ist meine feste ___, nächstes Jahr in eine größere Wohnung umzuziehen.","en":"It is my firm intention to move to a bigger flat next year."},{"ans":"Aussicht","de":"Vom Turm hat man eine herrliche ___ auf die ganze Stadt.","en":"From the tower you have a wonderful view of the whole city."},{"ans":"Aussicht","de":"Es besteht keine ___ auf Erfolg.","en":"There is no prospect of success."},{"ans":"Ansicht","de":"Ich bin der ___, dass der Plan zu riskant ist.","en":"I am of the opinion that the plan is too risky."},{"ans":"Einsicht","de":"Der Anwalt beantragte beim Gericht ___ in die Akten.","en":"The lawyer applied to the court for access to the files."},{"ans":"Einsicht","de":"Er zeigte weder Reue noch ___ und wiederholte denselben Fehler.","en":"He showed neither remorse nor insight and repeated the same mistake."}]},
 {"id":"verstaendnis-verstaendigung-verstand","lv":"C1","words":[{"w":"Verständnis","en":"understanding, sympathy"},{"w":"Verständigung","en":"communication; agreement"},{"w":"Verstand","en":"mind, reason, intellect"}],"tip":"Verständnis = Einfühlung, Nachsicht (Verständnis haben für). Verständigung = Kommunikation oder Einigung. Verstand = Denkvermögen.","items":[{"ans":"Verständnis","de":"Haben Sie bitte ___ dafür, dass wir die Reise absagen müssen.","en":"Please understand that we have to cancel the trip."},{"ans":"Verständnis","de":"Für sein Verhalten habe ich kein ___.","en":"I have no sympathy for his behaviour."},{"ans":"Verständigung","de":"Die ___ zwischen den Delegationen war wegen der Sprachbarriere schwierig.","en":"Communication between the delegations was difficult because of the language barrier."},{"ans":"Verständigung","de":"Nach langen Gesprächen kam es endlich zu einer ___ über das weitere Vorgehen.","en":"After long talks an agreement on how to proceed was finally reached."},{"ans":"Verstand","de":"Hast du denn völlig den ___ verloren?","en":"Have you completely lost your mind?"},{"ans":"Verstand","de":"Hättest du deinen ___ benutzt, hättest du das Risiko erkannt.","en":"If you had used your brain, you would have recognised the risk."}]},
 {"id":"gleichgewicht-gleichgueltigkeit-gleichberechtigung","lv":"C1","words":[{"w":"Gleichgewicht","en":"balance, equilibrium"},{"w":"Gleichgültigkeit","en":"indifference"},{"w":"Gleichberechtigung","en":"equal rights, equality before the law"}],"tip":"Gleichgewicht = Balance. Gleichgültigkeit = Desinteresse (jemandem ist etwas gleichgültig). Gleichberechtigung = gleiche Rechte für alle (Männer und Frauen).","items":[{"ans":"Gleichgewicht","de":"Auf dem Schwebebalken verlor die Turnerin das ___ und fiel.","en":"On the beam the gymnast lost her balance and fell."},{"ans":"Gleichgewicht","de":"Im Ökosystem herrscht ein empfindliches ___.","en":"A delicate balance prevails in the ecosystem."},{"ans":"Gleichgültigkeit","de":"Seine ___ gegenüber dem Leid der anderen machte sie wütend.","en":"His indifference to the suffering of others made her angry."},{"ans":"Gleichgültigkeit","de":"Mit eisiger ___ reagierte er auf die Bitte um Hilfe.","en":"He reacted to the plea for help with icy indifference."},{"ans":"Gleichberechtigung","de":"Der Verein setzt sich für die rechtliche ___ von Frauen und Männern ein.","en":"The association campaigns for legal equality between women and men."},{"ans":"Gleichberechtigung","de":"Die ___ der Geschlechter ist im Grundgesetz verankert.","en":"Equal rights for the sexes are enshrined in the Basic Law."}]},
 {"id":"zusammenhang-zusammenhalt-zusammenstoss-zusammenkunft","lv":"C1","words":[{"w":"Zusammenhang","en":"connection, context"},{"w":"Zusammenhalt","en":"cohesion, solidarity"},{"w":"Zusammenstoß","en":"collision; clash"},{"w":"Zusammenkunft","en":"meeting, gathering (formal)"}],"tip":"Zusammenhang = logische Verbindung (im Zusammenhang mit). Zusammenhalt = Gruppenzusammengehörigkeit. Zusammenstoß = Kollision, Streit. Zusammenkunft = förmliches Treffen.","items":[{"ans":"Zusammenhang","de":"Im ___ mit dem Unfall wurden mehrere Zeugen befragt.","en":"In connection with the accident several witnesses were questioned."},{"ans":"Zusammenhang","de":"Ich sehe keinen ___ zwischen den beiden Ereignissen.","en":"I see no connection between the two events."},{"ans":"Zusammenhalt","de":"In der Krise zeigte sich der ___ der Dorfgemeinschaft.","en":"In the crisis the cohesion of the village community became apparent."},{"ans":"Zusammenhalt","de":"Gemeinsame Rituale stärken den ___ in einer Gruppe.","en":"Shared rituals strengthen the cohesion within a group."},{"ans":"Zusammenstoß","de":"Bei dem ___ an der Kreuzung wurden zwei Personen verletzt.","en":"Two people were injured in the collision at the crossroads."},{"ans":"Zusammenstoß","de":"Ein ___ zwischen den beiden Radfahrern ließ sich nicht mehr vermeiden.","en":"A collision between the two cyclists could no longer be avoided."},{"ans":"Zusammenkunft","de":"Die jährliche ___ der Vereinsmitglieder findet im Mai statt.","en":"The annual gathering of the club members takes place in May."}]},
 {"id":"vorbehalt-vorlage-vorgabe-vorbild","lv":"C1","words":[{"w":"Vorbehalt","en":"reservation, proviso"},{"w":"Vorlage","en":"template; model; submission"},{"w":"Vorgabe","en":"guideline, requirement"},{"w":"Vorbild","en":"role model; example"}],"tip":"Vorbehalt = Einschränkung (unter dem Vorbehalt, dass …). Vorlage = Muster zum Abschreiben/Nachbilden. Vorgabe = von außen gesetzte Richtlinie. Vorbild = Person oder Beispiel zum Nacheifern.","items":[{"ans":"Vorbehalt","de":"Er stimmte dem Vertrag nur unter dem ___ zu, dass die Preise stabil bleiben.","en":"He agreed to the contract only on the proviso that prices remain stable."},{"ans":"Vorbehalt","de":"Gegen den Plan habe ich einen grundsätzlichen ___.","en":"I have a fundamental reservation about the plan."},{"ans":"Vorlage","de":"Für den Lebenslauf kann man eine ___ herunterladen und einfach die eigenen Daten eintragen.","en":"You can download a template for the CV and simply fill in your own details."},{"ans":"Vorlage","de":"Der Maler malte das Porträt nach einer ___ ab: einem alten Foto der Familie.","en":"The painter copied the portrait from a model: an old photograph of the family."},{"ans":"Vorgabe","de":"Die Firma muss die ___ der Aufsichtsbehörde zum Datenschutz einhalten.","en":"The company has to comply with the supervisory authority's requirement on data protection."},{"ans":"Vorgabe","de":"Die zeitliche ___ des Auftraggebers war sehr eng.","en":"The client's time requirement was very tight."},{"ans":"Vorbild","de":"Für viele junge Sportler ist sie ein großes ___.","en":"For many young athletes she is a great role model."},{"ans":"Vorbild","de":"Nach dem ___ seines Vaters wurde auch er Arzt.","en":"Following his father's example, he too became a doctor."}]},
 {"id":"verfolgen-verfuegen-verfuehren","lv":"C1","words":[{"w":"verfolgen","en":"to pursue, to follow; to persecute"},{"w":"verfügen","en":"to have at one's disposal (über + Akk.); to order"},{"w":"verführen","en":"to seduce, to tempt"}],"tip":"verfolgen = hinterherlaufen, ein Ziel anstreben. verfügen (über) = besitzen, zur Verfügung haben. verführen = zu etwas Reizvollem, oft Unvernünftigem bringen.","items":[{"ans":"verfolgen","de":"Wir müssen unser Ziel konsequent ___.","en":"We must pursue our goal consistently."},{"ans":"verfolgen","de":"Die Hunde sollen die Spur des Wildes ___.","en":"The dogs are to follow the trail of the game."},{"ans":"verfügen","de":"Nur wenige Haushalte können über ein so hohes Einkommen ___.","en":"Only few households have such a high income at their disposal."},{"ans":"verfügen","de":"Das Gebäude soll über einen eigenen Aufzug ___.","en":"The building is to have its own lift."},{"ans":"verführen","de":"Die Werbung soll die Kunden zum Kauf ___.","en":"The advertising is meant to tempt customers to buy."},{"ans":"verführen","de":"Der Duft frischer Waffeln kann einen leicht zum Naschen ___.","en":"The smell of fresh waffles can easily tempt you to nibble."}]},
 {"id":"enthalten-enthuellen-entziehen","lv":"C1","words":[{"w":"enthalten","en":"to contain; (sich) to abstain"},{"w":"enthüllen","en":"to unveil; to reveal"},{"w":"entziehen","en":"to withdraw, to deprive of; (sich) to evade"}],"tip":"enthalten = als Bestandteil haben; sich enthalten = nicht mitstimmen. enthüllen = Verhülltes zeigen, Geheimnisse aufdecken. entziehen = wegnehmen; sich entziehen = ausweichen.","items":[{"ans":"enthalten","de":"Die Wandfarbe darf keine giftigen Stoffe ___.","en":"The wall paint must not contain any toxic substances."},{"ans":"enthalten","de":"Zur Überraschung aller wollte sich die Abgeordnete bei der Abstimmung der Stimme ___.","en":"To everyone's surprise the member of parliament wanted to abstain from voting."},{"ans":"enthüllen","de":"Der Künstler will das Denkmal am Montag feierlich ___.","en":"The artist wants to unveil the monument ceremonially on Monday."},{"ans":"enthüllen","de":"Die Zeitung will einen Skandal ___.","en":"The newspaper wants to expose a scandal."},{"ans":"entziehen","de":"Das Gericht kann ihm das Sorgerecht ___.","en":"The court can deprive him of custody."},{"ans":"entziehen","de":"Er versuchte, sich der Verhaftung durch die Flucht zu ___.","en":"He tried to evade arrest by fleeing."}]},
 {"id":"bemerkbar-bemerkenswert-bemerken","lv":"B2","words":[{"w":"bemerkbar","en":"noticeable"},{"w":"bemerkenswert","en":"remarkable, noteworthy"},{"w":"bemerken","en":"to notice; to remark"}],"tip":"bemerkbar = so, dass man es wahrnimmt (sich bemerkbar machen). bemerkenswert = auffällig gut oder ungewöhnlich. bemerken = wahrnehmen, anmerken.","items":[{"ans":"bemerkbar","de":"Wenn du Hilfe brauchst, musst du dich laut ___ machen.","en":"If you need help, you have to make yourself noticed loudly."},{"ans":"bemerkbar","de":"Die Wirkung der Tabletten wird erst nach einigen Stunden ___.","en":"The effect of the tablets only becomes noticeable after a few hours."},{"ans":"bemerkenswert","de":"Das Ergebnis ist wirklich ___: Niemand hatte damit gerechnet.","en":"The result is really remarkable: nobody had expected it."},{"ans":"bemerkenswert","de":"Es ist höchst ___, wie schnell sie die Sprache gelernt hat.","en":"It is most remarkable how quickly she has learned the language."},{"ans":"bemerken","de":"Ich hoffe, er wird den Fehler nicht ___.","en":"I hope he won't notice the mistake."},{"ans":"bemerken","de":"Er verließ den Saal, ohne dass es jemand ___ konnte.","en":"He left the hall without anyone being able to notice it."}]},
 {"id":"vorbeugen-verbeugen-vorbeikommen","lv":"B2","words":[{"w":"vorbeugen","en":"to prevent (+ Dat.); to lean forward"},{"w":"verbeugen","en":"to bow (sich verbeugen)"},{"w":"vorbeikommen","en":"to drop by; to pass by"}],"tip":"vorbeugen + Dat. = einer Gefahr zuvorkommen. sich verbeugen = den Oberkörper zur Begrüßung neigen. vorbeikommen = kurz besuchen oder vorbeigehen.","items":[{"ans":"vorbeugen","de":"Regelmäßige Bewegung kann vielen Krankheiten ___.","en":"Regular exercise can prevent many illnesses."},{"ans":"vorbeugen","de":"Mit einer Impfung kann man der Grippe ___.","en":"With a vaccination you can guard against the flu."},{"ans":"verbeugen","de":"Die Sängerin stand auf, um sich für den Applaus des Publikums zu ___.","en":"The singer stood up to bow in response to the audience's applause."},{"ans":"verbeugen","de":"Am Ende der Vorstellung treten die Schauspieler an die Rampe, um sich zu ___ und den Beifall entgegenzunehmen.","en":"At the end of the performance the actors step up to the front of the stage to take a bow and receive the applause."},{"ans":"vorbeikommen","de":"Wenn du in der Gegend bist, kannst du gerne bei uns ___.","en":"If you are in the area, you are welcome to drop by."},{"ans":"vorbeikommen","de":"Kannst du morgen kurz ___ und mir den Schlüssel zurückbringen?","en":"Can you drop by briefly tomorrow and bring the key back to me?"}]},
 {"id":"kompetent-zustaendig","lv":"B2","words":[{"w":"kompetent","en":"competent, skilled"},{"w":"zuständig","en":"responsible, in charge, having jurisdiction"}],"tip":"kompetent = fachlich fähig (seltener, amtssprachlich auch: befugt). zuständig = offiziell verantwortlich (für + Akk.). Wer zuständig ist, muss nicht fachlich kompetent sein, und umgekehrt.","items":[{"ans":"kompetent","de":"Die neue Beraterin wirkt fachlich sehr ___ und beantwortet jede Frage souverän.","en":"The new consultant seems highly competent and answers every question confidently."},{"ans":"zuständig","de":"Frau Meier ist zwar für die Beschwerden ___, fachlich aber alles andere als kompetent.","en":"Ms Meier is responsible for complaints, admittedly, but professionally anything but competent."},{"ans":"kompetent","de":"In Steuerfragen ist unsere Beraterin außerordentlich ___.","en":"Our consultant is extremely competent in tax matters."}]},
 {"id":"sorgfaeltig-sorglos-besorgt","lv":"B2","words":[{"w":"sorgfältig","en":"careful, thorough"},{"w":"sorglos","en":"carefree; careless"},{"w":"besorgt","en":"worried, concerned"}],"tip":"sorgfältig = mit Genauigkeit. sorglos = ohne Sorgen oder ohne Vorsicht. besorgt = voller Sorge.","items":[{"ans":"sorgfältig","de":"Er räumte die Wohnung vor der Übergabe gründlich und ___ auf.","en":"He tidied up the flat thoroughly and carefully before handing it over."},{"ans":"sorgfältig","de":"Bitte lesen Sie den Vertrag ___ durch, bevor Sie unterschreiben.","en":"Please read the contract carefully before you sign."},{"ans":"sorglos","de":"Als Kinder haben wir ___ im Garten gespielt, ohne an morgen zu denken.","en":"As children we played carefree in the garden without thinking of tomorrow."},{"ans":"sorglos","de":"Seit dem Lottogewinn leben sie ___ und müssen nicht mehr aufs Geld achten.","en":"Since winning the lottery they live without a care and no longer have to watch their money."},{"ans":"besorgt","de":"Die Mutter ist ___, weil ihr Sohn noch nicht zu Hause ist.","en":"The mother is worried because her son is not home yet."},{"ans":"besorgt","de":"Der Arzt zog die Stirn kraus und wirkte sichtlich ___, als er die Werte sah.","en":"The doctor frowned and looked visibly concerned when he saw the results."}]},
 {"id":"verhaeltnis-verhalten-verhandlung","lv":"B2","words":[{"w":"Verhältnis","en":"relationship; ratio"},{"w":"Verhalten","en":"behaviour"},{"w":"Verhandlung","en":"negotiation; court hearing"}],"tip":"Verhältnis = Beziehung oder Zahlenverhältnis. Verhalten = wie sich jemand benimmt. Verhandlung = Gespräche zur Einigung; Gerichtstermin.","items":[{"ans":"Verhältnis","de":"Das ___ zwischen den beiden Nachbarn ist seit dem Streit angespannt.","en":"The relationship between the two neighbours has been tense since the quarrel."},{"ans":"Verhältnis","de":"Die Mischung aus Wasser und Sand hat ein ___ von eins zu drei.","en":"The mixture of water and sand has a ratio of one to three."},{"ans":"Verhalten","de":"Sein ___ im Unterricht ist vorbildlich: Er hört zu und meldet sich ordentlich.","en":"His behaviour in class is exemplary: he listens and raises his hand properly."},{"ans":"Verhandlung","de":"Die ___ mit der Gewerkschaft dauerte bis tief in die Nacht.","en":"The negotiation with the union lasted until late into the night."},{"ans":"Verhandlung","de":"Die ___ vor dem Landgericht beginnt am Montag um neun Uhr.","en":"The hearing before the regional court begins on Monday at nine o'clock."}]},
 {"id":"dienlich-dienstlich","lv":"C1","words":[{"w":"dienlich","en":"helpful, useful (+ Dat.)"},{"w":"dienstlich","en":"official, on duty"}],"tip":"dienlich = nützlich für eine Sache (einer Sache dienlich sein). dienstlich = den Dienst/Beruf betreffend (Gegensatz: privat).","items":[{"ans":"dienlich","de":"Alle Hinweise, auch scheinbar unwichtige, können der Aufklärung des Falls ___ sein.","en":"All clues, even seemingly unimportant ones, can help to solve the case."},{"ans":"dienlich","de":"Diese Informationen sind der Sache nicht ___.","en":"This information is of no use to the matter."},{"ans":"dienstlich","de":"Er ist diese Woche ___ unterwegs und besucht Kunden in Süddeutschland.","en":"He is travelling on official business this week, visiting customers in southern Germany."},{"ans":"dienstlich","de":"Das Auto darf nur ___ genutzt werden.","en":"The car may only be used for official purposes."}]},
 {"id":"indem-dadurch-sodass","lv":"B2","words":[{"w":"indem","en":"by (doing) ...; verb at the end"},{"w":"dadurch","en":"as a result (of that); adverb, normal main-clause word order"},{"w":"sodass","en":"so that, with the result that; verb at the end"}],"tip":"indem = the MEANS (by doing X); dadurch = adverb pointing back to the previous event; sodass = the RESULT of the main clause. Only indem and sodass send the verb to the end.","items":[{"ans":"indem","de":"Er überzeugte die Jury, ___ er völlig frei und ohne Notizen vortrug.","en":"He convinced the jury by presenting completely freely and without notes."},{"ans":"indem","de":"Man verbessert sein Deutsch, ___ man jeden Tag liest und spricht.","en":"You improve your German by reading and speaking every day."},{"ans":"dadurch","de":"Die Brücke wurde gesperrt, und ___ entstand ein kilometerlanger Stau.","en":"The bridge was closed, and as a result a miles-long traffic jam built up."},{"ans":"dadurch","de":"Es hat wochenlang kaum geregnet. Die Ernte ist ___ deutlich kleiner ausgefallen.","en":"It hardly rained for weeks. As a result, the harvest turned out much smaller."},{"ans":"sodass","de":"Der Zug hatte eine Stunde Verspätung, ___ wir den Anschluss verpassten.","en":"The train was an hour late, so that we missed our connection."},{"ans":"sodass","de":"Es schneite die ganze Nacht, ___ am Morgen alle Straßen unpassierbar waren.","en":"It snowed all night, so that by morning all the roads were impassable."}]},
 {"id":"denn-weil-naemlich","lv":"B2","words":[{"w":"denn","en":"for, because (then the verb is in 2nd position)"},{"w":"weil","en":"because (verb at the end)"},{"w":"nämlich","en":"you see, namely (inside the clause)"}],"tip":"denn + main clause (verb 2nd); weil + subordinate clause (verb last); causal nämlich ('you see') sits inside the clause, never at its start. (Spoken German often puts the verb 2nd after weil, but standard written German needs it at the end.)","items":[{"ans":"denn","de":"Ich nehme heute den Bus, ___ mein Auto ist in der Werkstatt.","en":"I'm taking the bus today because my car is in the garage."},{"ans":"denn","de":"Wir müssen uns beeilen, ___ der Film beginnt in zehn Minuten.","en":"We have to hurry, for the film starts in ten minutes."},{"ans":"weil","de":"Sie ist nicht gekommen, ___ sie plötzlich krank geworden ist.","en":"She didn't come because she suddenly fell ill."},{"ans":"weil","de":"Er hat die Prüfung bestanden, ___ er monatelang intensiv gelernt hatte.","en":"He passed the exam because he had studied hard for months."},{"ans":"nämlich","de":"Ich bleibe heute zu Hause; mein Auto ist ___ in der Werkstatt.","en":"I'm staying at home today; my car, you see, is in the garage."},{"ans":"nämlich","de":"Sie konnte nicht kommen. Sie hatte ___ eine Grippe.","en":"She couldn't come. She had the flu, you see."}]},
 {"id":"sowohl-weder-entweder-nicht-nur","lv":"B2","words":[{"w":"als","en":"sowohl ... als auch"},{"w":"noch","en":"weder ... noch"},{"w":"oder","en":"entweder ... oder"},{"w":"sondern","en":"nicht nur ... sondern auch"}],"tip":"Two-part connectors: sowohl ... ALS auch, weder ... NOCH, entweder ... ODER, nicht nur ... SONDERN auch. The first half of the pair tells you which word closes it.","items":[{"ans":"als","de":"Der Kurs ist sowohl für Anfänger ___ auch für Fortgeschrittene geeignet.","en":"The course is suitable for both beginners and advanced learners."},{"ans":"als","de":"Sie spricht sowohl Spanisch ___ auch Portugiesisch fließend.","en":"She speaks both Spanish and Portuguese fluently."},{"ans":"noch","de":"Er hat weder Zeit ___ Lust, uns zu helfen.","en":"He has neither the time nor the desire to help us."},{"ans":"noch","de":"Weder der Chef ___ seine Mitarbeiter wussten von dem Plan.","en":"Neither the boss nor his employees knew about the plan."},{"ans":"oder","de":"Wir fahren entweder am Samstag ___ am Sonntag ab.","en":"We are leaving either on Saturday or on Sunday."},{"ans":"oder","de":"Du kannst entweder jetzt mitkommen ___ später nachkommen.","en":"You can either come along now or follow later."},{"ans":"sondern","de":"Das Hotel ist nicht nur günstig, ___ auch sehr sauber.","en":"The hotel is not only cheap but also very clean."},{"ans":"sondern","de":"Nicht nur das Wetter war schlecht, ___ auch das Essen.","en":"Not only was the weather bad, but the food too."}]},
 {"id":"dessen-deren-denen","lv":"B2","words":[{"w":"dessen","en":"whose (masc./neuter singular)"},{"w":"deren","en":"whose (feminine singular and all plurals)"},{"w":"denen","en":"to/with whom (dative plural)"}],"tip":"Genitive relative pronoun: dessen (der/das) vs deren (die, plural). Dative plural: denen. The pronoun agrees with the noun it refers back to, not with the noun that follows.","items":[{"ans":"dessen","de":"Der Nachbar, ___ Hund jede Nacht bellt, hat sich bei uns entschuldigt.","en":"The neighbour whose dog barks every night has apologised to us."},{"ans":"dessen","de":"Das Kind, ___ Fahrrad gestohlen wurde, weinte auf dem Heimweg.","en":"The child whose bicycle was stolen cried on the way home."},{"ans":"deren","de":"Die Kollegin, ___ Auto vor dem Haus parkt, arbeitet im Marketing.","en":"The colleague whose car is parked in front of the house works in marketing."},{"ans":"deren","de":"Die Schüler, ___ Eltern nicht gekommen waren, durften früher gehen.","en":"The pupils whose parents hadn't come were allowed to leave early."},{"ans":"denen","de":"Die Freunde, ___ ich von meinem Umzug erzählt habe, wollen mir helfen.","en":"The friends I told about my move want to help me."},{"ans":"denen","de":"Das sind die Kolleginnen, mit ___ ich oft zu Mittag esse.","en":"Those are the colleagues I often have lunch with."}]},
 {"id":"das-was-wo-relativ","lv":"B2","words":[{"w":"das","en":"which, that (relative pronoun after a neuter noun)"},{"w":"was","en":"what, that (after alles, nichts, etwas ...)"},{"w":"wo","en":"where (relative adverb of place)"}],"tip":"Standard relative clause: das after a neuter noun (das Auto, das Problem); was after alles / nichts / etwas or when it refers to a whole preceding clause; wo after a place noun when you mean \"where\". (Colloquial \"das Auto, was ...\" or dialect \"das Auto, wo ...\" is not standard.)","items":[{"ans":"das","de":"Das Auto, ___ vor dem Haus steht, gehört meinem Bruder.","en":"The car that is parked in front of the house belongs to my brother."},{"ans":"das","de":"Ich lese gerade das Buch, ___ du mir empfohlen hast.","en":"I'm currently reading the book you recommended to me."},{"ans":"was","de":"Alles, ___ du brauchst, findest du in der Küche.","en":"Everything you need you'll find in the kitchen."},{"ans":"was","de":"Er hat die Prüfung bestanden, ___ uns alle sehr gefreut hat.","en":"He passed the exam, which pleased all of us very much."},{"ans":"wo","de":"Ich komme aus der Stadt, ___ meine Eltern geboren wurden.","en":"I come from the city where my parents were born."},{"ans":"wo","de":"Das ist das Dorf, ___ ich aufgewachsen bin.","en":"That is the village where I grew up."}]},
 {"id":"wurde-worden-geworden","lv":"B2","words":[{"w":"wurde","en":"became / was (Präteritum of werden)"},{"w":"worden","en":"been (Perfekt of the passive)"},{"w":"geworden","en":"become (Perfekt of werden as a full verb)"}],"tip":"werden has two participles: worden = passive auxiliary (gebaut worden); geworden = werden as a full verb (Lehrer geworden). wurde = Präteritum of both.","items":[{"ans":"wurde","de":"Das Rathaus ___ im 18. Jahrhundert erbaut.","en":"The town hall was built in the 18th century."},{"ans":"wurde","de":"Vor drei Jahren ___ die Straße komplett erneuert.","en":"Three years ago the road was completely renovated."},{"ans":"worden","de":"Das Gebäude ist erst vor Kurzem renoviert ___.","en":"The building has only recently been renovated."},{"ans":"worden","de":"Wir sind gestern vom Chef gelobt ___.","en":"We were praised by the boss yesterday."},{"ans":"geworden","de":"Aus dem kleinen Dorf ist inzwischen eine Stadt ___.","en":"The little village has meanwhile become a town."},{"ans":"geworden","de":"Meine Schwester ist Pilotin ___.","en":"My sister has become a pilot."}]},
 {"id":"haette-waere-wuerde","lv":"B2","words":[{"w":"hätte","en":"would have (Konjunktiv II of haben)"},{"w":"wäre","en":"would be / would have been (Konjunktiv II of sein)"},{"w":"würde","en":"would (+ infinitive)"}],"tip":"Konjunktiv II: hätte + Partizip II for haben-verbs; wäre + Partizip II for sein-verbs; würde + infinitive is the usual present/future form for most other verbs.","items":[{"ans":"hätte","de":"Wenn ich mehr Zeit gehabt ___, wäre ich mitgekommen.","en":"If I had had more time, I would have come along."},{"ans":"hätte","de":"An deiner Stelle ___ ich den Vertrag nicht unterschrieben.","en":"In your place I wouldn't have signed the contract."},{"ans":"wäre","de":"Wenn er früher losgefahren ___, wäre er pünktlich angekommen.","en":"If he had set off earlier, he would have arrived on time."},{"ans":"wäre","de":"Ich ___ gestern gestürzt, wenn mich der Mann nicht gehalten hätte.","en":"I would have fallen yesterday if the man hadn't held me."},{"ans":"würde","de":"Wenn es nicht so kalt wäre, ___ ich mit dem Fahrrad fahren.","en":"If it weren't so cold, I would ride my bike."},{"ans":"würde","de":"Ich ___ dir gern helfen, aber ich habe leider keine Zeit.","en":"I would gladly help you, but unfortunately I have no time."}]},
 {"id":"haengte-hing","lv":"B2","words":[{"w":"hängte","en":"hung (something) up (transitive, weak)"},{"w":"hing","en":"hung (intransitive, strong)"},{"w":"gehängt","en":"hung up (transitive)"},{"w":"gehangen","en":"hung (intransitive)"}],"tip":"hängen (weak, + Akk.) = to hang something up: hängte, gehängt. hängen (strong, no object) = to be hanging: hing, gehangen.","items":[{"ans":"hängte","de":"Sie ___ den nassen Mantel über den Stuhl.","en":"She hung the wet coat over the chair."},{"ans":"hängte","de":"Der Hausmeister ___ ein Schild an die Tür.","en":"The caretaker hung a sign on the door."},{"ans":"hing","de":"Der nasse Mantel ___ über der Stuhllehne und tropfte.","en":"The wet coat hung over the back of the chair and dripped."},{"ans":"gehängt","de":"Hast du das Bild schon an die Wand ___?","en":"Have you already hung the picture on the wall?"},{"ans":"gehängt","de":"Der Mantel wurde ordentlich an den Haken ___.","en":"The coat was neatly hung on the hook."},{"ans":"gehangen","de":"Das Bild hat jahrelang im Flur ___.","en":"The picture hung in the hallway for years."}]},
 {"id":"erschrak-erschreckte-erschrocken","lv":"B2","words":[{"w":"erschrak","en":"got a fright (intransitive, strong)"},{"w":"erschreckte","en":"frightened (someone) (transitive, weak)"},{"w":"erschrocken","en":"startled, frightened (participle of intransitive erschrecken)"}],"tip":"erschrecken (strong, no object) = to be startled: erschrak, ist erschrocken. erschrecken (weak, + Akk.) = to frighten someone: erschreckte, hat erschreckt.","items":[{"ans":"erschrak","de":"Ich ___ furchtbar, als plötzlich das Licht ausging.","en":"I got a terrible fright when the light suddenly went out."},{"ans":"erschrak","de":"Der Hund ___, als es plötzlich laut knallte, und rannte davon.","en":"The dog got a fright when there was suddenly a loud bang, and ran away."},{"ans":"erschreckte","de":"Der Knall ___ den Hund so sehr, dass er davonrannte.","en":"The bang frightened the dog so much that it ran away."},{"ans":"erschreckte","de":"Der plötzliche Anruf ___ mich mitten in der Nacht.","en":"The sudden call gave me a fright in the middle of the night."},{"ans":"erschrocken","de":"Wir sind alle ___, als wir die Nachricht hörten.","en":"We were all startled when we heard the news."},{"ans":"erschrocken","de":"Sie ist zutiefst ___, als sie die Spinne gesehen hat.","en":"She was badly frightened when she saw the spider."}]},
 {"id":"sinken-senken","lv":"B2","words":[{"w":"sank","en":"sank, fell (intransitive)"},{"w":"senkte","en":"lowered (transitive)"},{"w":"gesunken","en":"sunk, fallen (participle of sinken)"},{"w":"gesenkt","en":"lowered (participle of senken)"}],"tip":"sinken (strong, no object) = to go down: sank, ist gesunken. senken (weak, + Akk.) = to lower something: senkte, hat gesenkt.","items":[{"ans":"sank","de":"Die Temperatur ___ über Nacht auf minus zehn Grad.","en":"The temperature fell to minus ten degrees overnight."},{"ans":"sank","de":"Das Schiff ___ innerhalb weniger Minuten.","en":"The ship sank within a few minutes."},{"ans":"senkte","de":"Die Zentralbank ___ den Leitzins um ein halbes Prozent.","en":"The central bank lowered the key interest rate by half a percent."},{"ans":"senkte","de":"Er ___ den Kopf und schwieg.","en":"He lowered his head and said nothing."},{"ans":"gesunken","de":"Die Sonne ist längst hinter den Bergen ___, und es wird kalt.","en":"The sun has long since sunk behind the mountains, and it is getting cold."},{"ans":"gesenkt","de":"Der Staat hat die Steuern auf Lebensmittel ___.","en":"The state has lowered the taxes on food."}]},
 {"id":"fiel-faellte","lv":"B2","words":[{"w":"fiel","en":"fell (intransitive)"},{"w":"fällte","en":"felled, cut down (transitive)"},{"w":"gefallen","en":"fallen (participle of fallen)"},{"w":"gefällt","en":"felled (participle of fällen)"}],"tip":"fallen (strong, no object) = to fall: fiel, ist gefallen. fällen (weak, + Akk.) = to cut down: fällte, hat gefällt.","items":[{"ans":"fiel","de":"Der Baum ___ bei dem Sturm quer über die Straße.","en":"The tree fell across the road during the storm."},{"ans":"fällte","de":"Der Förster ___ die alte Eiche am Waldrand.","en":"The forester felled the old oak at the edge of the forest."},{"ans":"gefallen","de":"Das Glas ist vom Tisch ___ und zerbrochen.","en":"The glass fell off the table and broke."},{"ans":"gefällt","de":"Im Park wurden mehrere alte Bäume ___.","en":"Several old trees were cut down in the park."}]},
 {"id":"sprang-sprengte","lv":"B2","words":[{"w":"sprang","en":"jumped (intransitive)"},{"w":"sprengte","en":"blew up; sprinkled (transitive)"},{"w":"gesprungen","en":"jumped; cracked (participle of springen)"},{"w":"gesprengt","en":"blown up (participle of sprengen)"}],"tip":"springen (strong) = to jump: sprang, ist gesprungen. sprengen (weak, + Akk.) = to blow up / to sprinkle: sprengte, hat gesprengt.","items":[{"ans":"sprang","de":"Der Hund ___ mit einem Satz über den Zaun.","en":"The dog jumped over the fence in one bound."},{"ans":"sprang","de":"Das Kind ___ vom Beckenrand ins Wasser.","en":"The child jumped from the edge of the pool into the water."},{"ans":"sprengte","de":"Die Arbeiter ___ den alten Schornstein in die Luft.","en":"The workers blew up the old chimney."},{"ans":"sprengte","de":"Der Gärtner ___ am Abend den Rasen mit dem Schlauch.","en":"In the evening the gardener sprinkled the lawn with the hose."},{"ans":"gesprungen","de":"Das Glas ist beim Spülen ___.","en":"The glass cracked while being washed up."},{"ans":"gesprengt","de":"Die Brücke wurde im Krieg ___.","en":"The bridge was blown up during the war."}]},
 {"id":"schuf-schaffte","lv":"B2","words":[{"w":"schuf","en":"created (strong)"},{"w":"schaffte","en":"managed, got done (weak)"},{"w":"geschaffen","en":"created; made (for)"},{"w":"geschafft","en":"managed; exhausted"}],"tip":"schaffen (strong: schuf, geschaffen) = to create; schaffen (weak: schaffte, geschafft) = to manage, to cope (and geschafft = worn out).","items":[{"ans":"schuf","de":"Der Künstler ___ aus einem einzigen Marmorblock eine lebensgroße Figur.","en":"The artist created a life-size figure from a single block of marble."},{"ans":"schuf","de":"Der Architekt ___ in den zwanziger Jahren mehrere Wohnsiedlungen, die noch heute als Vorbild gelten.","en":"In the 1920s the architect created several housing estates that are still regarded as models today."},{"ans":"schaffte","de":"Sie ___ die Prüfung mit Bestnote.","en":"She passed the exam with top marks."},{"ans":"schaffte","de":"Ich ___ es nicht mehr rechtzeitig zum Bahnhof.","en":"I didn't make it to the station in time any more."},{"ans":"geschaffen","de":"Dieses Werk wurde für die Ewigkeit ___.","en":"This work was created for eternity."},{"ans":"geschafft","de":"Nach dem Marathon war ich völlig ___.","en":"After the marathon I was completely worn out."}]},
 {"id":"dringen-draengen","lv":"C1","words":[{"w":"drang","en":"penetrated, got through (intransitive)"},{"w":"drängte","en":"urged; pressed (transitive/intransitive)"},{"w":"gedrungen","en":"penetrated (participle of dringen)"},{"w":"gedrängt","en":"urged; pushed (participle of drängen)"}],"tip":"dringen (strong) = to penetrate, force one's way through: drang, ist gedrungen. drängen (weak) = to urge, to push: drängte, hat gedrängt.","items":[{"ans":"drang","de":"Das Licht ___ nur schwach durch die dichten Vorhänge.","en":"The light penetrated only faintly through the thick curtains."},{"ans":"drang","de":"Kein Laut ___ durch die dicken Mauern nach draußen.","en":"No sound penetrated through the thick walls to the outside."},{"ans":"drängte","de":"Die Chefin ___ ihn, den Bericht noch heute fertigzustellen.","en":"The boss urged him to finish the report today."},{"ans":"drängte","de":"Die Zeit ___, wir mussten uns beeilen.","en":"Time was pressing; we had to hurry."},{"ans":"gedrungen","de":"Die Nachricht ist bis nach Berlin ___.","en":"The news got through all the way to Berlin."},{"ans":"gedrängt","de":"Er hat sich durch die Menge nach vorn ___.","en":"He pushed his way forward through the crowd."}]},
 {"id":"ist-hat-perfekt","lv":"B2","words":[{"w":"ist","en":"has (Perfekt with sein) – no object, change of place/state"},{"w":"hat","en":"has (Perfekt with haben) – with an accusative object"}],"tip":"Same participle, different auxiliary: without an object (change of place) → ist gefahren; with an accusative object (transporting something) → hat jemanden/etwas gefahren.","items":[{"ans":"ist","de":"Mein Vater ___ letztes Jahr nach Spanien gefahren.","en":"My father drove to Spain last year."},{"ans":"ist","de":"Das Eis ___ in der Sonne schnell geschmolzen.","en":"The ice melted quickly in the sun."},{"ans":"hat","de":"Der Busfahrer ___ die Touristen sicher zum Hotel gefahren.","en":"The bus driver drove the tourists safely to the hotel."},{"ans":"hat","de":"Sie ___ ihren Sohn heute früh zur Schule gefahren.","en":"She drove her son to school this morning."}]},
 {"id":"stattdessen-anstelle","lv":"B2","words":[{"w":"stattdessen","en":"instead (adverb)"},{"w":"anstelle","en":"in place of (+ Gen.)"}],"tip":"stattdessen = adverb, stands alone (\"instead\", often at the start of the 2nd clause or inside it); anstelle + Genitiv = in place of a noun (anstelle des Chefs, anstelle eines Autos).","items":[{"ans":"stattdessen","de":"Ich habe keine Lust auf Kino. Lass uns ___ spazieren gehen.","en":"I don't feel like going to the cinema. Let's go for a walk instead."},{"ans":"stattdessen","de":"Er sollte arbeiten, ging aber ___ angeln.","en":"He was supposed to work but went fishing instead."},{"ans":"anstelle","de":"Die Stellvertreterin hielt ___ des erkrankten Chefs die Rede.","en":"The deputy gave the speech in place of the sick boss."},{"ans":"anstelle","de":"Wir haben ___ eines Autos ein Boot gekauft.","en":"We bought a boat in place of a car."}]},
 {"id":"beide-beiden-beides-beider","lv":"B2","words":[{"w":"beide","en":"both (nom./acc. plural, no article)"},{"w":"beiden","en":"both (after an article, or dative plural)"},{"w":"beides","en":"both (things, neuter singular)"},{"w":"beider","en":"of both (genitive plural, no article)"}],"tip":"beide = both people/things as plural subject or object; beiden = after die/den/meine etc. or in the dative plural; beides = both different things taken together (singular verb: Beides ist teuer); beider = genitive plural.","items":[{"ans":"beide","de":"Ich habe zwei Brüder, ___ wohnen in Hamburg.","en":"I have two brothers; both live in Hamburg."},{"ans":"beide","de":"Mir gefallen ___ Lösungen gleich gut.","en":"I like both solutions equally well."},{"ans":"beiden","de":"Mit den ___ Kindern fahren wir im Sommer ans Meer.","en":"We're going to the seaside with the two children in summer."},{"ans":"beiden","de":"Ich möchte meinen ___ Töchtern danken.","en":"I'd like to thank my two daughters."},{"ans":"beides","de":"Brauchst du noch Salz oder Pfeffer? – Nein danke, ___ steht schon auf dem Tisch.","en":"Do you still need salt or pepper? – No thanks, both are already on the table."},{"ans":"beides","de":"Fisch und Fleisch kaufe ich selten, denn ___ ist zurzeit sehr teuer.","en":"I rarely buy fish and meat, because both are very expensive at the moment."},{"ans":"beider","de":"Die Meinung ___ Parteien muss berücksichtigt werden.","en":"The opinion of both parties must be taken into account."},{"ans":"beider","de":"Das war der gemeinsame Wunsch ___ Familien.","en":"That was the shared wish of both families."}]},
 {"id":"gehoert-besitzt","lv":"B2","words":[{"w":"gehört","en":"belongs to (+ Dat.)"},{"w":"besitzt","en":"owns (+ Akk.)"}],"tip":"gehören = belongs to someone (owner in the DATIVE); besitzen = someone owns something (owner is the SUBJECT, thing in the accusative).","items":[{"ans":"gehört","de":"Das Grundstück ___ meinem Onkel.","en":"The plot of land belongs to my uncle."},{"ans":"gehört","de":"Wem ___ dieser Schirm hier?","en":"Whose is this umbrella here?"},{"ans":"besitzt","de":"Mein Onkel ___ ein großes Grundstück am See.","en":"My uncle owns a big plot of land by the lake."},{"ans":"besitzt","de":"Sie ___ mehrere Wohnungen in der Innenstadt.","en":"She owns several flats in the city centre."}]},
 {"id":"handelt-behandelt-verhandelt","lv":"B2","words":[{"w":"handelt","en":"deals with / it is about (handelt von; es handelt sich um)"},{"w":"behandelt","en":"treats; discusses (+ Akk.)"},{"w":"verhandelt","en":"negotiates (mit ... über)"}],"tip":"handeln von / sich handeln um = to be about; behandeln + Akk. = to treat (patient) or to cover a topic; verhandeln (mit jemandem über etwas) = to negotiate.","items":[{"ans":"handelt","de":"Der Film ___ von einer Freundschaft zwischen zwei Außenseitern.","en":"The film is about a friendship between two outsiders."},{"ans":"handelt","de":"Es ___ sich um ein Missverständnis.","en":"It is a misunderstanding."},{"ans":"behandelt","de":"Der Arzt ___ den Patienten seit Wochen mit einem neuen Medikament.","en":"The doctor has been treating the patient with a new drug for weeks."},{"ans":"behandelt","de":"Die Lehrerin ___ im Unterricht gerade das Thema Umweltschutz.","en":"The teacher is currently covering the topic of environmental protection in class."},{"ans":"verhandelt","de":"Die Gewerkschaft ___ derzeit mit dem Arbeitgeberverband über einen neuen Tarifvertrag.","en":"The union is currently negotiating a new collective agreement with the employers' association."}]},
 {"id":"heraus-hinaus-herein-hinein","lv":"B2","words":[{"w":"heraus","en":"out (towards the speaker, who is outside)"},{"w":"hinaus","en":"out (away from the speaker, who is inside)"},{"w":"herein","en":"in (towards the speaker, who is inside)"},{"w":"hinein","en":"in (away from the speaker, who is outside)"}],"tip":"her- = towards the speaker, hin- = away from the speaker. Imagine where YOU are standing: speaker inside, movement out → hinaus; speaker outside, movement out → heraus; speaker inside, movement in → herein; speaker outside, movement in → hinein. (Spoken German often shortens all four to raus / rein.)","items":[{"ans":"heraus","de":"Ich warte draußen im Garten und rufe den Kindern im Haus zu: Kommt bitte ___, es gibt Eis!","en":"I'm waiting outside in the garden and call to the children in the house: Please come out, there's ice cream!"},{"ans":"hinaus","de":"Die Lehrerin sagt im Klassenzimmer zu den Kindern: Geht jetzt bitte alle ___ auf den Hof.","en":"In the classroom the teacher tells the children: Please all go out into the yard now."},{"ans":"hinaus","de":"Der Chef sitzt in seinem Büro und sagt: Gehen Sie bitte kurz ___, ich möchte mit Frau Berger allein sprechen.","en":"The boss, sitting in his office, says: Please step out for a moment, I'd like to talk to Ms Berger alone."},{"ans":"herein","de":"Ich stehe im Flur und öffne die Tür. Draußen steht ein Gast. Ich sage: Kommen Sie bitte ___!","en":"I'm standing in the hall and open the door. A guest is standing outside. I say: Please come in!"},{"ans":"herein","de":"Ich sitze im Wohnzimmer, mein Freund klingelt draußen. Ich rufe: Komm ___, die Tür ist offen!","en":"I'm sitting in the living room, my friend rings the bell outside. I call: Come in, the door is open!"},{"ans":"hinein","de":"Ich warte vor dem Haus. Gehen Sie ruhig schon ___, ich komme gleich nach.","en":"I'm waiting in front of the house. Do go in, I'll follow in a moment."}]},
 {"id":"worte-woerter","lv":"B2","words":[{"w":"Worte","en":"words (connected speech, utterances)"},{"w":"Wörter","en":"words (single vocabulary items)"}],"tip":"Wörter = individual words you can count or look up (Wörterbuch); Worte = words as meaningful speech (aufmunternde Worte, mit anderen Worten).","items":[{"ans":"Wörter","de":"Im Wörterbuch stehen mehr als hunderttausend ___.","en":"The dictionary contains more than a hundred thousand words."},{"ans":"Wörter","de":"Das Wort „Haustür“ besteht aus zwei ___: Haus und Tür.","en":"The word 'Haustür' consists of two words: Haus and Tür."},{"ans":"Worte","de":"Der Redner fand bewegende ___ für die Trauernden.","en":"The speaker found moving words for the mourners."},{"ans":"Worte","de":"Am Grab sprach der Pfarrer tröstende ___.","en":"At the graveside the pastor spoke comforting words."}]},
 {"id":"draussen-aussen-ausserhalb-auswaerts","lv":"B2","words":[{"w":"draußen","en":"outside, outdoors (location)"},{"w":"außen","en":"on the outside (surface)"},{"w":"außerhalb","en":"outside of (+ Gen.)"},{"w":"auswärts","en":"away (from home), out"}],"tip":"draußen = out in the open, not indoors; außen = on the outer side of something (opposite: innen); außerhalb + Gen. = beyond the limits of; auswärts = away from home (eating out, away game).","items":[{"ans":"draußen","de":"Bei dem schönen Wetter essen wir lieber ___ auf dem Balkon als drinnen.","en":"In this lovely weather we prefer to eat outside on the balcony rather than indoors."},{"ans":"draußen","de":"Die Kinder spielen den ganzen Nachmittag ___ im Schnee.","en":"The children play outdoors in the snow all afternoon."},{"ans":"außen","de":"Das Brot ist ___ knusprig, aber innen weich.","en":"The bread is crispy on the outside but soft inside."},{"ans":"außen","de":"Der Schrank ist innen weiß und ___ schwarz lackiert.","en":"The cupboard is white inside and painted black on the outside."},{"ans":"außerhalb","de":"Das Hotel liegt ___ der Stadt, direkt am See.","en":"The hotel is outside the town, right by the lake."},{"ans":"außerhalb","de":"Das liegt leider ___ meiner Zuständigkeit.","en":"Unfortunately that is outside my area of responsibility."},{"ans":"auswärts","de":"Zu Hause ist unsere Mannschaft ungeschlagen, aber ___ hat sie noch keinen Punkt geholt.","en":"At home our team is unbeaten, but away from home it hasn't picked up a single point yet."}]},
 {"id":"als-ob-wie-vergleichssatz","lv":"B2","words":[{"w":"als","en":"as if (als + verb straight after it, or als ob ...)"},{"w":"ob","en":"(als) ob = as if (verb at the end)"},{"w":"wie","en":"like, as (+ noun)"}],"tip":"Unreal comparison: als + verb straight after it (als wüsste sie ...) OR als ob + verb at the end (the word ob completes it). Simple comparison with a noun: wie.","items":[{"ans":"als","de":"Sie tut so, ___ wüsste sie nichts davon.","en":"She acts as if she knew nothing about it."},{"ans":"als","de":"Es sieht aus, ___ ob es gleich regnen würde.","en":"It looks as if it were going to rain any moment."},{"ans":"ob","de":"Er tat so, als ___ er schliefe.","en":"He pretended to be asleep."},{"ans":"ob","de":"Sie sah mich an, als ___ sie mich nicht kennen würde.","en":"She looked at me as if she didn't know me."},{"ans":"wie","de":"Er sieht aus ___ sein Vater.","en":"He looks like his father."},{"ans":"wie","de":"Sie schläft ___ ein Murmeltier.","en":"She sleeps like a log."}]},
 {"id":"wird-ist-passiv","lv":"B2","words":[{"w":"wird","en":"is being (Vorgangspassiv – process)"},{"w":"ist","en":"is (Zustandspassiv – resulting state)"}],"tip":"wird + Partizip II = the action is happening (Vorgangspassiv); ist + Partizip II = the result already exists (Zustandspassiv).","items":[{"ans":"ist","de":"Der Tisch ___ längst gedeckt, wir können jetzt essen.","en":"The table has long been set, so we can eat now."},{"ans":"ist","de":"Der Brief ___ bereits unterschrieben, Sie müssen ihn nur noch abschicken.","en":"The letter is already signed, you only have to send it."},{"ans":"wird","de":"Der Tisch ___ gerade von den Kellnern gedeckt, bitte warten Sie noch einen Moment.","en":"The table is just being laid by the waiters, please wait a moment."},{"ans":"wird","de":"Das Gebäude ___ momentan von Handwerkern renoviert.","en":"The building is currently being renovated by tradespeople."}]},
 {"id":"miteinander-voneinander-aufeinander-fuereinander","lv":"B2","words":[{"w":"miteinander","en":"with each other"},{"w":"voneinander","en":"from/of each other"},{"w":"aufeinander","en":"on/for each other"},{"w":"füreinander","en":"for each other"}],"tip":"einander + preposition: the preposition is the one the verb or adjective needs (streiten MIT, entfernt VON, warten/achten AUF, da sein FÜR).","items":[{"ans":"miteinander","de":"Die Geschwister streiten ständig ___ um das Spielzeug.","en":"The siblings are constantly arguing with each other over the toy."},{"ans":"miteinander","de":"Wir telefonieren fast jeden Abend ___.","en":"We talk to each other on the phone almost every evening."},{"ans":"voneinander","de":"Die beiden Städte liegen weit ___ entfernt.","en":"The two cities are far away from each other."},{"ans":"voneinander","de":"Wir wohnen nur zwei Straßen ___ entfernt.","en":"We live only two streets away from each other."},{"ans":"aufeinander","de":"Die Bücher stapelten sich ___ bis zur Decke.","en":"The books were piled on top of each other up to the ceiling."},{"ans":"aufeinander","de":"Im Team muss man ___ achten.","en":"In a team you have to look out for each other."},{"ans":"füreinander","de":"Gute Freunde sind immer ___ da.","en":"Good friends are always there for each other."},{"ans":"füreinander","de":"Die Geschwister sorgen ___, wenn die Eltern arbeiten müssen.","en":"The siblings look after each other when their parents have to work."}]},
 {"id":"fruehestens-spaetestens-mindestens-hoechstens","lv":"B2","words":[{"w":"frühestens","en":"at the earliest"},{"w":"spätestens","en":"at the latest"},{"w":"mindestens","en":"at least"},{"w":"höchstens","en":"at most"}],"tip":"frühestens / spätestens fix a point in time (not before / not after); mindestens / höchstens fix an amount (not less / not more).","items":[{"ans":"frühestens","de":"Das Paket kommt ___ morgen an, vorher ist es unmöglich.","en":"The package will arrive tomorrow at the earliest; before that is impossible."},{"ans":"frühestens","de":"Das Haus ist ___ im Herbst bezugsfertig, wahrscheinlich aber erst im Winter.","en":"The house will be ready to move into in autumn at the earliest, but probably only in winter."},{"ans":"spätestens","de":"Du musst das Formular ___ bis Freitag abgeben, danach ist es zu spät.","en":"You have to hand in the form by Friday at the latest; after that it's too late."},{"ans":"spätestens","de":"Ich bin ___ um 18 Uhr zurück, später auf keinen Fall.","en":"I'll be back by 6 p.m. at the latest, definitely not later."},{"ans":"mindestens","de":"Der Kurs dauert ___ drei Stunden, wahrscheinlich sogar länger.","en":"The course lasts at least three hours, probably even longer."},{"ans":"mindestens","de":"Dafür braucht man ___ zwei Personen, eine allein schafft es nicht.","en":"You need at least two people for that; one alone can't manage."},{"ans":"höchstens","de":"Das Konzert dauert ___ eine Stunde, länger bestimmt nicht.","en":"The concert lasts an hour at most, certainly not longer."},{"ans":"höchstens","de":"Auf dem Parkplatz ist Platz für ___ zehn Autos, mehr passen nicht hinein.","en":"The car park has room for ten cars at most; no more will fit."}]},
 {"id":"indem-in-dem-seitdem-seit-dem","lv":"B2","words":[{"w":"indem","en":"by (doing) ... (conjunction)"},{"w":"in dem","en":"in which (preposition + relative pronoun)"},{"w":"seitdem","en":"since (conjunction/adverb)"},{"w":"seit dem","en":"since the (preposition + dative noun)"}],"tip":"One word = conjunction (indem, seitdem; seitdem is also an adverb); two words = preposition + dem: in dem (preposition + relative pronoun, \"in which\"), seit dem + noun (preposition + article). If a noun follows right after, it is two words.","items":[{"ans":"indem","de":"Er rettete die Katze, ___ er ohne zu zögern ins Wasser sprang.","en":"He saved the cat by jumping into the water without hesitating."},{"ans":"indem","de":"Er löste die Aufgabe, ___ er einfach eine andere Methode benutzte.","en":"He solved the task by simply using a different method."},{"ans":"in dem","de":"Das ist das Zimmer, ___ ich als Kind geschlafen habe.","en":"That is the room in which I slept as a child."},{"ans":"in dem","de":"Sie öffnete den Schrank, ___ ihre Kleider hingen.","en":"She opened the cupboard in which her clothes hung."},{"ans":"seitdem","de":"Wir sehen uns häufiger, ___ sie in meine Nähe gezogen ist.","en":"We see each other more often since she moved close to me."},{"ans":"seit dem","de":"Er geht ___ Unfall am Stock.","en":"He has walked with a stick since the accident."},{"ans":"seitdem","de":"Er raucht nicht mehr, ___ er Vater geworden ist.","en":"He hasn't smoked since he became a father."},{"ans":"seit dem","de":"Wir leben ___ Umzug viel ruhiger.","en":"We have lived much more quietly since the move."}]},
 {"id":"verschwendet-verschwunden","lv":"B2","words":[{"w":"verschwendet","en":"wasted (participle of verschwenden)"},{"w":"verschwunden","en":"disappeared (participle of verschwinden)"}],"tip":"verschwenden (+ Akk.) = to waste, hat verschwendet; verschwinden = to disappear, ist verschwunden.","items":[{"ans":"verschwendet","de":"Er hat sein ganzes Erbe in wenigen Jahren ___.","en":"He squandered his entire inheritance in a few years."},{"ans":"verschwendet","de":"Wir haben auf dieser Sitzung nur unsere Zeit ___.","en":"We have only wasted our time at this meeting."},{"ans":"verschwunden","de":"Mein Schlüssel ist plötzlich spurlos ___.","en":"My key has suddenly vanished without a trace."},{"ans":"verschwunden","de":"Der Mann ist seit Tagen ___, die Polizei sucht ihn.","en":"The man has been missing for days; the police are looking for him."}]},
 {"id":"enttaeuscht-enttaeuschend","lv":"B2","words":[{"w":"enttäuscht","en":"disappointed (person feeling it)"},{"w":"enttäuschend","en":"disappointing (what causes it)"}],"tip":"enttäuscht = the PERSON who feels let down; enttäuschend = the THING or event that causes it (a result, a match, an answer).","items":[{"ans":"enttäuscht","de":"Die Fans waren vom Ergebnis des Spiels tief ___.","en":"The fans were deeply disappointed by the result of the match."},{"ans":"enttäuscht","de":"Ich bin ziemlich ___, dass du nicht angerufen hast.","en":"I'm rather disappointed that you didn't call."},{"ans":"enttäuschend","de":"Das Spiel war für die Zuschauer ___, denn die Heimmannschaft verlor 0:4.","en":"The match was disappointing for the spectators, as the home team lost 4–0."},{"ans":"enttäuschend","de":"Das Ergebnis der Prüfung war ___; wir hatten uns viel mehr erhofft.","en":"The exam result was disappointing; we had hoped for much more."}]},
 {"id":"ueberzeugt-ueberzeugend","lv":"B2","words":[{"w":"überzeugt","en":"convinced (person)"},{"w":"überzeugend","en":"convincing (argument, performance)"}],"tip":"überzeugt = the PERSON who has been convinced (also: davon überzeugt sein, dass ...); überzeugend = the argument, alibi or performance that convinces.","items":[{"ans":"überzeugt","de":"Ich bin fest davon ___, dass wir das schaffen.","en":"I'm firmly convinced that we'll manage it."},{"ans":"überzeugt","de":"Die Richterin war vom Alibi des Angeklagten nicht ___.","en":"The judge was not convinced by the defendant's alibi."},{"ans":"überzeugend","de":"Sein Alibi klang wenig ___, deshalb glaubte ihm niemand.","en":"His alibi sounded unconvincing, so nobody believed him."},{"ans":"überzeugend","de":"Das Argument war kaum ___, also blieb die Chefin bei ihrer Meinung.","en":"The argument was hardly convincing, so the boss stuck to her opinion."}]},
 {"id":"ueberrascht-ueberraschend","lv":"B2","words":[{"w":"überrascht","en":"surprised (person)"},{"w":"überraschend","en":"surprising; unexpectedly"}],"tip":"überrascht = the PERSON who is surprised; überraschend = the THING that surprises, or as an adverb \"unexpectedly\" (überraschend schnell).","items":[{"ans":"überrascht","de":"Wir waren alle ___, als sie plötzlich in der Tür stand.","en":"We were all surprised when she suddenly stood in the doorway."},{"ans":"überrascht","de":"Er war angenehm ___ über das Geschenk.","en":"He was pleasantly surprised by the present."},{"ans":"überraschend","de":"Das Ergebnis der Wahl war ___; niemand hatte damit gerechnet.","en":"The election result was surprising; nobody had expected it."},{"ans":"überraschend","de":"Das Wetter ist am Nachmittag ___ schnell umgeschlagen.","en":"The weather changed surprisingly quickly in the afternoon."}]},
 {"id":"beeindruckt-beeindruckend","lv":"B2","words":[{"w":"beeindruckt","en":"impressed (person)"},{"w":"beeindruckend","en":"impressive"}],"tip":"beeindruckt = the PERSON who is impressed; beeindruckend = the THING (view, performance) that impresses.","items":[{"ans":"beeindruckt","de":"Wir waren von der Leistung des jungen Pianisten tief ___.","en":"We were deeply impressed by the young pianist's performance."},{"ans":"beeindruckt","de":"Die Zuschauer zeigten sich von der Vorführung sichtlich ___.","en":"The spectators were visibly impressed by the show."},{"ans":"beeindruckend","de":"Die Aussicht vom Gipfel war wirklich ___.","en":"The view from the summit was really impressive."},{"ans":"beeindruckend","de":"Seine Leistung bei der Weltmeisterschaft war geradezu ___.","en":"His performance at the world championship was downright impressive."}]},
 {"id":"aufgeregt-aufregend","lv":"B2","words":[{"w":"aufgeregt","en":"excited, nervous (person)"},{"w":"aufregend","en":"exciting (thing, event)"}],"tip":"aufgeregt = the PERSON who is excited or nervous; aufregend = the THING or event that is exciting.","items":[{"ans":"aufgeregt","de":"Vor der Prüfung war ich so ___, dass ich kaum schlafen konnte.","en":"Before the exam I was so nervous that I could hardly sleep."},{"ans":"aufgeregt","de":"Die Kinder waren am Heiligabend schon früh ganz ___.","en":"On Christmas Eve the children were already very excited early on."},{"ans":"aufregend","de":"Die Reise durch Südamerika war unglaublich ___.","en":"The journey through South America was incredibly exciting."},{"ans":"aufregend","de":"Der Film war nicht besonders ___, ich bin fast eingeschlafen.","en":"The film wasn't particularly exciting; I almost fell asleep."}]},
 {"id":"verwirrt-verwirrend","lv":"B2","words":[{"w":"verwirrt","en":"confused (person)"},{"w":"verwirrend","en":"confusing"}],"tip":"verwirrt = the PERSON who is confused; verwirrend = the THING (instructions, route network) that confuses.","items":[{"ans":"verwirrt","de":"Nach dem langen Flug war er völlig ___ und wusste nicht, wo er war.","en":"After the long flight he was completely confused and didn't know where he was."},{"ans":"verwirrt","de":"Die alte Frau war nach dem Sturz völlig ___ und wusste nicht mehr, wie sie hieß.","en":"After her fall the old woman was completely confused and no longer knew her name."},{"ans":"verwirrend","de":"Die Anleitung ist so ___, dass niemand das Gerät zusammenbauen kann.","en":"The instructions are so confusing that nobody can assemble the device."},{"ans":"verwirrend","de":"Das Streckennetz der U-Bahn ist für Touristen ziemlich ___.","en":"The underground network is rather confusing for tourists."}]},
 {"id":"fasziniert-faszinierend","lv":"B2","words":[{"w":"fasziniert","en":"fascinated (person)"},{"w":"faszinierend","en":"fascinating"}],"tip":"fasziniert = the PERSON who is fascinated; faszinierend = the THING or event that fascinates.","items":[{"ans":"fasziniert","de":"Die Kinder sahen ganz ___ den Delfinen beim Springen zu.","en":"The children watched the dolphins jump, completely fascinated."},{"ans":"fasziniert","de":"Ich war von der Architektur der Altstadt sofort ___.","en":"I was instantly fascinated by the architecture of the old town."},{"ans":"faszinierend","de":"Die Geschichte dieser Stadt ist wirklich ___.","en":"The history of this city is really fascinating."},{"ans":"faszinierend","de":"Es ist ___ zu sehen, wie schnell sich die Technik entwickelt.","en":"It is fascinating to see how quickly technology is developing."}]},
 {"id":"konjunktiv-i-sei-habe-werde","lv":"C1","words":[{"w":"sei","en":"(Konjunktiv I of sein)"},{"w":"habe","en":"(Konjunktiv I of haben)"},{"w":"werde","en":"(Konjunktiv I of werden: future / passive)"}],"tip":"Indirect speech with Konjunktiv I: sei + adjective / gewesen / Partizip (sein-verbs); habe + Partizip II (haben-verbs); werde + infinitive for the future.","items":[{"ans":"sei","de":"Der Zeuge erklärte, er ___ zur Tatzeit zu Hause gewesen.","en":"The witness stated that he had been at home at the time of the crime."},{"ans":"sei","de":"Die Ministerin betonte, die Lage ___ unter Kontrolle.","en":"The minister stressed that the situation was under control."},{"ans":"habe","de":"Sie sagte, sie ___ den Brief nie gelesen.","en":"She said she had never read the letter."},{"ans":"habe","de":"Er behauptete, er ___ das Auto nicht gestohlen.","en":"He claimed he had not stolen the car."},{"ans":"werde","de":"Der Vorstand kündigte an, er ___ das Werk im nächsten Jahr schließen.","en":"The board announced it would close the plant next year."},{"ans":"werde","de":"Die Sprecherin versicherte, man ___ die Vorwürfe gründlich prüfen.","en":"The spokeswoman assured that the allegations would be examined thoroughly."}]},
 {"id":"subjektive-modalverben-muss-kann-will","lv":"C1","words":[{"w":"muss","en":"must (certain conclusion)"},{"w":"kann","en":"may, could (possibility)"},{"w":"will","en":"claims to (own claim)"}],"tip":"Subjective modal verbs + infinitive: muss ... sein = I am sure; kann ... sein = it is possible; will ... sein / will ... gewesen sein = a person claims it of himself/herself (not used with things).","items":[{"ans":"muss","de":"Das ___ ein Irrtum gewesen sein – eine andere Erklärung gibt es nicht.","en":"That must have been a mistake – there is no other explanation."},{"ans":"muss","de":"Das Fenster war offen und die Tür aufgebrochen – hier ___ ganz sicher ein Einbruch stattgefunden haben.","en":"The window was open and the door forced – a burglary must definitely have taken place here."},{"ans":"kann","de":"Das Paket ___ schon angekommen sein, aber ich habe keine Ahnung.","en":"The parcel may already have arrived, but I have no idea."},{"ans":"kann","de":"Das ___ sein, aber ich glaube es nicht.","en":"That may be, but I don't believe it."},{"ans":"will","de":"Er ___ der beste Koch der Stadt sein, dabei bekommt er nicht einmal ein Spiegelei hin.","en":"He claims to be the best cook in town, yet he can't even fry an egg."},{"ans":"will","de":"Er ___ an dem Abend zu Hause gewesen sein, dabei weiß ich genau, dass er mit mir im Kino war.","en":"He claims to have been at home that evening, yet I know for a fact that he was at the cinema with me."}]},
 {"id":"entgegen-gemaess","lv":"C1","words":[{"w":"entgegen","en":"contrary to (+ Dat.)"},{"w":"gemäß","en":"in accordance with (+ Dat.)"}],"tip":"entgegen = against (expectations, advice, rules); gemäß = in line with (rules, plans). Both take the Dative and may stand before or after the noun (entgegen dem Rat / dem Rat entgegen).","items":[{"ans":"entgegen","de":"Die Außenseiterin gewann ___ allen Prognosen das Rennen, obwohl niemand mit ihr gerechnet hatte.","en":"Contrary to all forecasts the outsider won the race, although nobody had counted on her."},{"ans":"entgegen","de":"Er verließ ___ dem ausdrücklichen Rat seines Arztes viel zu früh das Krankenhaus.","en":"He left the hospital far too early against his doctor's express advice."},{"ans":"gemäß","de":"Die Firma entsorgte den Müll ordnungsgemäß und ___ den gesetzlichen Vorschriften.","en":"The company disposed of the waste properly and in accordance with the statutory regulations."},{"ans":"gemäß","de":"Das Gebäude wurde ___ den Plänen des Architekten fertiggestellt, ohne jede Abweichung.","en":"The building was completed in accordance with the architect's plans, without any deviation."}]},
 {"id":"angesichts-anlaesslich-mittels","lv":"C1","words":[{"w":"angesichts","en":"in view of (+ Gen.)"},{"w":"anlässlich","en":"on the occasion of (+ Gen.)"},{"w":"mittels","en":"by means of (+ Gen.)"}],"tip":"Formal genitive prepositions: angesichts = given a (serious) situation; anlässlich = on a festive/special occasion; mittels = with a tool or method.","items":[{"ans":"angesichts","de":"Er blieb ___ der Gefahr erstaunlich ruhig.","en":"He remained astonishingly calm in the face of the danger."},{"ans":"angesichts","de":"Wir sollten uns ___ dieser Zahlen keine Illusionen machen.","en":"We shouldn't have any illusions in view of these figures."},{"ans":"anlässlich","de":"Die Stadt lud ___ ihres 800-jährigen Bestehens zu einem großen Fest ein.","en":"On the occasion of its 800th anniversary the city invited people to a big celebration."},{"ans":"anlässlich","de":"Der Verein überreichte ihm ___ seines 60. Geburtstags eine Urkunde.","en":"On the occasion of his 60th birthday the club presented him with a certificate."},{"ans":"mittels","de":"Die Tür wurde ___ eines Dietrichs geöffnet.","en":"The door was opened by means of a lock pick."},{"ans":"mittels","de":"Das Wasser wird ___ einer Pumpe aus dem Keller befördert.","en":"The water is removed from the cellar by means of a pump."}]},
 {"id":"infolge-zwecks-zugunsten-zulasten","lv":"C1","words":[{"w":"infolge","en":"as a result of (+ Gen.)"},{"w":"zwecks","en":"for the purpose of (+ Gen.)"},{"w":"zugunsten","en":"in favour of (+ Gen.)"},{"w":"zulasten","en":"at the expense of (+ Gen.)"}],"tip":"infolge = cause; zwecks = purpose; zugunsten = benefit of someone; zulasten = burden/cost for someone. All formal, all + Genitiv (zulasten/zugunsten may also be written zu Lasten/zu Gunsten).","items":[{"ans":"infolge","de":"Die Straße ist ___ starker Regenfälle überflutet.","en":"The road is flooded as a result of heavy rainfall."},{"ans":"infolge","de":"Mehrere Flüge fielen ___ des Streiks aus.","en":"Several flights were cancelled as a result of the strike."},{"ans":"zwecks","de":"Die Polizei lud ihn ___ Klärung des Sachverhalts vor.","en":"The police summoned him for the purpose of clarifying the facts."},{"ans":"zwecks","de":"Das Gerät wurde ___ Reparatur an den Hersteller geschickt.","en":"The device was sent to the manufacturer for repair."},{"ans":"zugunsten","de":"Der Verein sammelt Spenden ___ krebskranker Kinder.","en":"The association is collecting donations for children with cancer."},{"ans":"zugunsten","de":"Er verzichtete ___ seines jüngeren Bruders auf das Erbe.","en":"He waived the inheritance in favour of his younger brother."},{"ans":"zulasten","de":"Die Sparmaßnahmen gehen ___ der Patienten, die nun länger warten müssen.","en":"The savings measures are at the expense of the patients, who now have to wait longer."},{"ans":"zulasten","de":"Der Gewinn wurde ___ der Umwelt gesteigert, die unter den Abgasen leidet.","en":"The profit was increased at the expense of the environment, which suffers from the exhaust fumes."}]},
 {"id":"derer-deren-dessen","lv":"C1","words":[{"w":"derer","en":"of those (genitive plural demonstrative)"},{"w":"deren","en":"whose (fem./plural relative)"},{"w":"dessen","en":"whose (masc./neuter relative)"}],"tip":"derer = genitive of \"die\" as a demonstrative, followed by a relative clause (Gedenken derer, die ...); deren/dessen = relative \"whose\", agreeing with the antecedent.","items":[{"ans":"derer","de":"Wir gedenken heute ___, die im Krieg ihr Leben verloren haben.","en":"Today we remember those who lost their lives in the war."},{"ans":"derer","de":"Die Zahl ___, die keine Arbeit finden, steigt seit Jahren.","en":"The number of those who cannot find work has been rising for years."},{"ans":"deren","de":"Die Autorin, ___ neuer Roman erschienen ist, liest morgen in Berlin.","en":"The author whose new novel has come out will give a reading in Berlin tomorrow."},{"ans":"deren","de":"Die Familien, ___ Häuser überflutet wurden, erhielten Soforthilfe.","en":"The families whose houses were flooded received emergency aid."},{"ans":"dessen","de":"Der Pianist, ___ Konzert wir gestern besucht haben, kommt aus Wien.","en":"The pianist whose concert we attended yesterday comes from Vienna."},{"ans":"dessen","de":"Das Unternehmen, ___ Gründer vor zehn Jahren starb, besteht noch immer.","en":"The company whose founder died ten years ago still exists."}]},
 {"id":"ertrank-ertraenkte","lv":"C1","words":[{"w":"ertrank","en":"drowned (intransitive)"},{"w":"ertränkte","en":"drowned (someone/something) (transitive)"},{"w":"ertrunken","en":"drowned (participle of ertrinken)"},{"w":"ertränkt","en":"drowned (participle of ertränken)"}],"tip":"ertrinken (strong, no object) = to drown: ertrank, ist ertrunken. ertränken (weak, + Akk.) = to drown someone/something: ertränkte, hat ertränkt.","items":[{"ans":"ertrank","de":"Der Junge ___ beim Baden im See.","en":"The boy drowned while swimming in the lake."},{"ans":"ertränkte","de":"Als der Mörder sein Opfer im Fluss ___, sah ihn niemand.","en":"When the murderer drowned his victim in the river, nobody saw him."},{"ans":"ertränkte","de":"Als seine Frau ihn verließ, ___ er seinen Kummer im Alkohol.","en":"When his wife left him, he drowned his sorrows in alcohol."},{"ans":"ertrunken","de":"Zwei Touristen sind letzten Sommer im Meer ___.","en":"Two tourists drowned in the sea last summer."},{"ans":"ertränkt","de":"Die jungen Katzen wurden im Sack ___.","en":"The kittens were drowned in a sack."}]},
 {"id":"erlosch-loeschte","lv":"C1","words":[{"w":"erlosch","en":"went out (intransitive)"},{"w":"löschte","en":"extinguished, deleted (transitive)"},{"w":"erloschen","en":"gone out (participle of erlöschen)"},{"w":"gelöscht","en":"extinguished, deleted (participle of löschen)"}],"tip":"erlöschen (strong, no object) = to go out: erlosch, ist erloschen. löschen (weak, + Akk.) = to put out, to delete: löschte, hat gelöscht.","items":[{"ans":"erlosch","de":"Das Feuer ___ langsam, als der Regen einsetzte.","en":"The fire slowly went out when the rain set in."},{"ans":"erlosch","de":"Plötzlich ___ das Licht im ganzen Saal.","en":"Suddenly the light went out in the whole hall."},{"ans":"löschte","de":"Die Feuerwehr ___ den Brand in der Lagerhalle innerhalb einer Stunde.","en":"The fire brigade put out the fire in the warehouse within an hour."},{"ans":"löschte","de":"Er ___ das Licht und ging schlafen.","en":"He switched off the light and went to sleep."},{"ans":"erloschen","de":"Ihre Begeisterung für das Projekt ist längst ___.","en":"Her enthusiasm for the project has long since died out."},{"ans":"gelöscht","de":"Die Datei wurde versehentlich ___.","en":"The file was deleted by mistake."}]},
 {"id":"versank-versenkte","lv":"C1","words":[{"w":"versank","en":"sank (intransitive)"},{"w":"versenkte","en":"sank, scuttled (transitive)"},{"w":"versunken","en":"sunk (participle of versinken)"},{"w":"versenkt","en":"sunk, set deep (participle of versenken)"}],"tip":"versinken (strong, no object) = to sink: versank, ist versunken. versenken (weak, + Akk.) = to sink something: versenkte, hat versenkt.","items":[{"ans":"versank","de":"Das Schiff ___ in wenigen Minuten im Meer.","en":"The ship sank in the sea within a few minutes."},{"ans":"versank","de":"Sie ___ tief in Gedanken und hörte nichts mehr.","en":"She sank deep into thought and no longer heard anything."},{"ans":"versenkte","de":"Als der Kapitän das feindliche Boot mit einem Torpedo ___, brach an Deck Jubel aus.","en":"When the captain sank the enemy boat with a torpedo, cheering broke out on deck."},{"ans":"versunken","de":"Die Stadt ist vor Jahrhunderten im Meer ___.","en":"The city sank into the sea centuries ago."},{"ans":"versenkt","de":"Die Pfosten wurden tief im Boden ___.","en":"The posts were sunk deep into the ground."}]},
 {"id":"derzeit-seinerzeit-kuenftig","lv":"C1","words":[{"w":"derzeit","en":"at present"},{"w":"seinerzeit","en":"at that time (in the past)"},{"w":"künftig","en":"in future"}],"tip":"derzeit = now (old-fashioned also \"back then\"; avoid that today); seinerzeit = back then (past tense); künftig = from now on, in the future.","items":[{"ans":"derzeit","de":"Das Hotel ist ___ leider komplett ausgebucht, vielleicht gibt es morgen Absagen.","en":"At present the hotel is unfortunately fully booked; maybe there will be cancellations tomorrow."},{"ans":"derzeit","de":"Die Preise für Rohöl sind ___ so niedrig wie seit Jahren nicht.","en":"Crude oil prices are currently lower than they have been for years."},{"ans":"seinerzeit","de":"Der Architekt war ___ der jüngste Professor an der Universität.","en":"At that time the architect was the youngest professor at the university."},{"ans":"seinerzeit","de":"Das hatte man ___ noch nicht für möglich gehalten.","en":"Nobody had thought that possible at the time."},{"ans":"künftig","de":"Wir werden unsere Rechnungen ___ nur noch digital verschicken.","en":"In future we will only send our invoices digitally."},{"ans":"künftig","de":"Ab nächstem Monat gilt: Bitte melden Sie sich ___ rechtzeitig an.","en":"From next month the rule is: in future, please register in good time."}]},
 {"id":"zumal-zwar-obwohl","lv":"C1","words":[{"w":"zumal","en":"especially as, all the more since"},{"w":"zwar","en":"admittedly (... aber)"},{"w":"obwohl","en":"although"}],"tip":"zumal gives an extra reason that SUPPORTS the statement; obwohl gives a reason that works AGAINST it; zwar announces a concession that is answered by aber.","items":[{"ans":"zumal","de":"Wir sollten den Termin verschieben, ___ der Chef ohnehin krank ist.","en":"We should postpone the appointment, especially as the boss is ill anyway."},{"ans":"zumal","de":"Das Angebot ist verlockend, ___ die Bezahlung deutlich besser wäre als jetzt.","en":"The offer is tempting, especially as the pay would be much better than now."},{"ans":"zwar","de":"Die Wohnung ist ___ klein, aber sehr gemütlich.","en":"The flat is small, admittedly, but very cosy."},{"ans":"zwar","de":"Ich habe ___ keine Zeit, aber ich helfe dir trotzdem.","en":"I have no time, admittedly, but I'll help you anyway."},{"ans":"obwohl","de":"Er ging zur Arbeit, ___ er hohes Fieber hatte.","en":"He went to work although he had a high fever."},{"ans":"obwohl","de":"Sie kaufte das Kleid, ___ es viel zu teuer war.","en":"She bought the dress although it was far too expensive."}]},
 {"id":"jeweils-jeweiligen","lv":"C1","words":[{"w":"jeweils","en":"each, in each case (adverb)"},{"w":"jeweiligen","en":"respective (adjective)"}],"tip":"jeweils = adverb (\"each time / apiece\"), no ending; jeweilig- = adjective before a noun (die jeweiligen Gäste) and needs an ending.","items":[{"ans":"jeweils","de":"Jeder Teilnehmer erhält ___ ein eigenes Heft und einen Stift.","en":"Each participant receives their own notebook and a pen."},{"ans":"jeweils","de":"Die beiden Mannschaften erzielten ___ drei Tore.","en":"The two teams scored three goals each."},{"ans":"jeweiligen","de":"In den einzelnen Bundesländern gelten die ___ Landesgesetze.","en":"In the individual federal states the respective state laws apply."},{"ans":"jeweiligen","de":"Die Gäste wurden von den ___ Gastgebern empfangen.","en":"The guests were received by their respective hosts."}]},
 {"id":"wog-wiegte","lv":"C1","words":[{"w":"wog","en":"weighed (strong)"},{"w":"wiegte","en":"rocked (weak)"},{"w":"gewogen","en":"weighed (participle of wiegen)"},{"w":"gewiegt","en":"rocked (participle of wiegen)"}],"tip":"wiegen (strong: wog, gewogen) = to weigh; wiegen (weak: wiegte, gewiegt) = to rock gently (a baby, one's head), also to chop finely (Petersilie wiegen).","items":[{"ans":"wog","de":"Der Koffer ___ fast zwanzig Kilo.","en":"The suitcase weighed almost twenty kilos."},{"ans":"wiegte","de":"Die Mutter ___ ihr Kind sanft in den Schlaf.","en":"The mother gently rocked her child to sleep."},{"ans":"gewogen","de":"Die Mitarbeiterin am Postschalter hat das Paket vor dem Versand noch einmal ___.","en":"The post office clerk weighed the parcel once more before it was sent."},{"ans":"gewiegt","de":"Sie hat das schreiende Baby lange in ihren Armen ___.","en":"She rocked the crying baby in her arms for a long time."}]},
 {"id":"derart-derartige","lv":"C1","words":[{"w":"derart","en":"so, to such a degree (adverb)"},{"w":"derartige","en":"such (adjective)"}],"tip":"derart = adverb before an adjective/verb (derart schwierig, dass ...), no ending; derartig- = adjective before a noun (derartige Probleme) and takes an ending.","items":[{"ans":"derart","de":"Die Lage war ___ unübersichtlich, dass selbst Experten ratlos waren.","en":"The situation was so confusing that even experts were at a loss."},{"ans":"derart","de":"Es hat noch nie ___ stark geschneit.","en":"It has never snowed so heavily."},{"ans":"derartige","de":"Wir hatten noch nie ___ Probleme mit der Software.","en":"We have never had such problems with the software."},{"ans":"derartige","de":"Ich möchte ___ Bemerkungen in Zukunft nicht mehr hören.","en":"I don't want to hear such remarks in future."}]},
 {"id":"erschoepft-erschoepfend","lv":"C1","words":[{"w":"erschöpft","en":"exhausted (person)"},{"w":"erschöpfend","en":"exhaustive, comprehensive"}],"tip":"erschöpft = worn out (person); erschöpfend = usually exhaustive, leaving nothing out (information, treatment of a topic); also 'exhausting' (eine erschöpfende Tour).","items":[{"ans":"erschöpft","de":"Nach dem Marathon waren alle Läufer völlig ___.","en":"After the marathon all the runners were completely exhausted."},{"ans":"erschöpft","de":"Die Pflegekräfte sind nach der Nachtschicht ziemlich ___.","en":"The nurses are rather exhausted after the night shift."},{"ans":"erschöpfend","de":"Die Antwort des Experten war ___, es blieb keine Frage offen.","en":"The expert's answer was exhaustive; no question was left open."},{"ans":"erschöpfend","de":"Das Thema wurde in der Studie ___ behandelt, nichts blieb offen.","en":"The topic was dealt with exhaustively in the study; nothing was left open."}]},
 {"id":"ueberwaeltigt-ueberwaeltigend","lv":"C1","words":[{"w":"überwältigt","en":"overwhelmed (person)"},{"w":"überwältigend","en":"overwhelming"}],"tip":"überwältigt = the PERSON who is overwhelmed; überwältigend = the THING (majority, success, hospitality) that overwhelms.","items":[{"ans":"überwältigt","de":"Sie war von der Gastfreundschaft der Menschen völlig ___.","en":"She was completely overwhelmed by the people's hospitality."},{"ans":"überwältigt","de":"Als er den Preis entgegennahm, war er so ___, dass er kein Wort herausbrachte.","en":"When he accepted the prize he was so overwhelmed that he couldn't say a word."},{"ans":"überwältigend","de":"Die Mehrheit für den Antrag war ___; fast alle stimmten zu.","en":"The majority for the motion was overwhelming; almost everyone voted in favour."},{"ans":"überwältigend","de":"Der Erfolg des Films war ___.","en":"The success of the film was overwhelming."}]},
 {"id":"gereizt-reizend","lv":"C1","words":[{"w":"gereizt","en":"irritable, on edge (person)"},{"w":"reizend","en":"charming, lovely"}],"tip":"gereizt = irritated, in a bad mood (person, voice); reizend = charming, delightful (child, idea, gesture).","items":[{"ans":"gereizt","de":"Er war nach der durchwachten Nacht sehr ___ und fuhr jeden an.","en":"After the sleepless night he was very irritable and snapped at everyone."},{"ans":"gereizt","de":"Ihre Stimme klang ___; man merkte, dass sie kurz vor einem Streit stand.","en":"Her voice sounded irritated; you could tell she was on the verge of a quarrel."},{"ans":"reizend","de":"Die Kleine ist wirklich ___; alle im Haus mögen sie.","en":"The little one is really charming; everybody in the house likes her."},{"ans":"reizend","de":"Es war wirklich ___ von dir, uns zum Essen einzuladen.","en":"It was really charming of you to invite us for dinner."}]},
 {"id":"beschaemt-beschaemend","lv":"C1","words":[{"w":"beschämt","en":"ashamed (person)"},{"w":"beschämend","en":"shameful, humiliating"}],"tip":"beschämt = the PERSON who feels ashamed; beschämend = the THING (behaviour, situation) that is shameful.","items":[{"ans":"beschämt","de":"Er senkte ___ den Blick, als ihm sein Fehler klar wurde.","en":"He lowered his eyes in shame when his mistake became clear to him."},{"ans":"beschämt","de":"Sie war über ihr Verhalten tief ___.","en":"She was deeply ashamed of her behaviour."},{"ans":"beschämend","de":"Das Verhalten der Politiker in dieser Frage ist wirklich ___.","en":"The politicians' behaviour on this issue is truly shameful."},{"ans":"beschämend","de":"Es ist ___, wie wenig Geld für Schulen ausgegeben wird.","en":"It is shameful how little money is spent on schools."}]},
 {"id":"ernuechtert-ernuechternd","lv":"C1","words":[{"w":"ernüchtert","en":"sobered, disillusioned (person)"},{"w":"ernüchternd","en":"sobering, disillusioning"}],"tip":"ernüchtert = the PERSON who has been sobered / disillusioned; ernüchternd = the THING (result, balance) that has this effect.","items":[{"ans":"ernüchtert","de":"Nach dem Gespräch verließ er das Büro ziemlich ___.","en":"After the conversation he left the office rather disillusioned."},{"ans":"ernüchtert","de":"Die Anleger sind nach den schlechten Zahlen ___.","en":"Investors are disillusioned after the bad figures."},{"ans":"ernüchternd","de":"Das Ergebnis der Untersuchung ist ___: Die Maßnahmen haben kaum etwas bewirkt.","en":"The result of the investigation is sobering: the measures achieved hardly anything."},{"ans":"ernüchternd","de":"Die Bilanz nach einem Jahr fällt ___ aus.","en":"The balance after one year is sobering."}]},
 {"id":"ermutigt-ermutigend","lv":"C1","words":[{"w":"ermutigt","en":"encouraged (person)"},{"w":"ermutigend","en":"encouraging"}],"tip":"ermutigt = the PERSON who has been encouraged; ermutigend = the THING (results, news) that encourages.","items":[{"ans":"ermutigt","de":"Durch das Lob der Lehrerin fühlte er sich sehr ___.","en":"The teacher's praise made him feel very encouraged."},{"ans":"ermutigt","de":"Von den ersten Erfolgen ___, wagte sie den nächsten Schritt.","en":"Encouraged by the first successes, she dared to take the next step."},{"ans":"ermutigend","de":"Die ersten Testergebnisse sind sehr ___.","en":"The first test results are very encouraging."},{"ans":"ermutigend","de":"Es ist ___ zu sehen, wie viele Menschen sich engagieren.","en":"It is encouraging to see how many people get involved."}]},
 {"id":"alarmiert-alarmierend","lv":"C1","words":[{"w":"alarmiert","en":"alarmed (person)"},{"w":"alarmierend","en":"alarming"}],"tip":"alarmiert = the PERSON who is alarmed; alarmierend = the THING (figures, development) that alarms; also an adverb: alarmierend hoch.","items":[{"ans":"alarmiert","de":"Die Nachbarn waren durch den Lärm ___ und riefen die Polizei.","en":"The neighbours were alarmed by the noise and called the police."},{"ans":"alarmiert","de":"Wir sind über die Entwicklung ernsthaft ___.","en":"We are seriously alarmed by the development."},{"ans":"alarmierend","de":"Die Zahlen sind ___ hoch.","en":"The figures are alarmingly high."},{"ans":"alarmierend","de":"Die Entwicklung ist ___, und niemand reagiert.","en":"The development is alarming, and nobody reacts."}]},
 {"id":"bedrueckt-bedrueckend","lv":"C1","words":[{"w":"bedrückt","en":"depressed, downcast (person)"},{"w":"bedrückend","en":"oppressive, depressing"}],"tip":"bedrückt = the PERSON who feels downcast; bedrückend = the THING (silence, sight) that depresses.","items":[{"ans":"bedrückt","de":"Er fühlt sich seit dem Streit sehr ___.","en":"He has felt very downcast since the quarrel."},{"ans":"bedrückt","de":"Die Kinder saßen ___ am Tisch, weil sie schlechte Noten bekommen hatten.","en":"The children sat at the table downcast because they had got bad marks."},{"ans":"bedrückend","de":"Die Stille im leeren Haus war ___.","en":"The silence in the empty house was oppressive."},{"ans":"bedrückend","de":"Es ist ___, die Menschen so leiden zu sehen.","en":"It is depressing to see people suffer like this."}]},
 {"id":"erschuettert-erschuetternd","lv":"C1","words":[{"w":"erschüttert","en":"shaken, deeply moved (person)"},{"w":"erschütternd","en":"shocking, harrowing"}],"tip":"erschüttert = the PERSON who is deeply shaken; erschütternd = the THING (pictures, news) that shakes you.","items":[{"ans":"erschüttert","de":"Die ganze Stadt war von dem Unglück tief ___.","en":"The whole town was deeply shaken by the disaster."},{"ans":"erschüttert","de":"Wir sind zutiefst ___ über die Nachricht vom Tod des Lehrers.","en":"We are deeply shaken by the news of the teacher's death."},{"ans":"erschütternd","de":"Die Bilder aus dem Katastrophengebiet sind ___.","en":"The pictures from the disaster area are harrowing."},{"ans":"erschütternd","de":"Es ist ___, wie schnell ein Leben zerstört werden kann.","en":"It is harrowing how quickly a life can be destroyed."}]},
 {"id":"verstoert-verstoerend","lv":"C1","words":[{"w":"verstört","en":"distraught, disturbed (person)"},{"w":"verstörend","en":"disturbing, unsettling"}],"tip":"verstört = the PERSON who is distraught; verstörend = the THING (scene, reaction) that disturbs.","items":[{"ans":"verstört","de":"Das Kind war nach dem Unfall völlig ___.","en":"The child was completely distraught after the accident."},{"ans":"verstört","de":"Er stand ganz ___ vor dem zerstörten Haus.","en":"He stood completely distraught in front of the destroyed house."},{"ans":"verstörend","de":"Manche Szenen in dem Film sind wirklich ___.","en":"Some scenes in the film are really disturbing."},{"ans":"verstörend","de":"Ich finde es ___, wie gleichgültig er darauf reagiert hat.","en":"I find it disturbing how indifferently he reacted to it."}]},
 {"id":"irritiert-irritierend","lv":"C1","words":[{"w":"irritiert","en":"irritated, puzzled (person)"},{"w":"irritierend","en":"irritating, puzzling"}],"tip":"irritiert = the PERSON who is puzzled or irritated; irritierend = the THING (noise, display) that irritates or puzzles.","items":[{"ans":"irritiert","de":"Sie schaute mich sichtlich ___ an, weil sie nicht verstand, was ich meinte.","en":"She looked at me visibly puzzled because she didn't understand what I meant."},{"ans":"irritiert","de":"Ich war von seiner plötzlichen Kälte ziemlich ___.","en":"I was rather taken aback by his sudden coldness."},{"ans":"irritierend","de":"Das ständige Piepen des Geräts ist ziemlich ___.","en":"The constant beeping of the device is rather irritating."},{"ans":"irritierend","de":"Es ist ___, dass die Anzeige jedes Mal etwas anderes zeigt.","en":"It is puzzling that the display shows something different every time."}]},
 {"id":"hose-hase","lv":"A2","words":[{"w":"Hose","en":"trousers, pants"},{"w":"Hase","en":"hare (also: the Easter bunny)"}],"tip":"Only one vowel differs: die Hose (o) = trousers, der Hase (a) = hare/rabbit.","items":[{"ans":"Hose","de":"Meine neue ___ ist leider zu lang.","en":"Unfortunately, my new trousers are too long."},{"ans":"Hose","de":"Im Winter trage ich lieber eine warme ___ als einen Rock.","en":"In winter I prefer to wear warm trousers rather than a skirt."},{"ans":"Hase","de":"Im Garten sitzt ein kleiner ___ und frisst Gras.","en":"A little hare is sitting in the garden eating grass."},{"ans":"Hase","de":"Zu Ostern versteckt der ___ bunte Eier.","en":"At Easter the bunny hides coloured eggs."}]},
 {"id":"wald-wand-wind","lv":"A2","words":[{"w":"Wald","en":"forest, woods"},{"w":"Wand","en":"wall (inside a room)"},{"w":"Wind","en":"wind"}],"tip":"Wald = forest (trees); Wand = wall of a room; Wind = moving air. Don't mix up -ald / -and / -ind.","items":[{"ans":"Wald","de":"Im Herbst wachsen im ___ viele Pilze.","en":"In autumn lots of mushrooms grow in the forest."},{"ans":"Wald","de":"Hinter dem Dorf beginnt ein großer ___ mit vielen Tannen.","en":"Behind the village a big forest with many fir trees begins."},{"ans":"Wand","de":"Das Bild hängt an der ___ über dem Sofa.","en":"The picture hangs on the wall above the sofa."},{"ans":"Wand","de":"Wir streichen die ___ im Wohnzimmer weiß.","en":"We are painting the living-room wall white."},{"ans":"Wind","de":"Heute weht ein starker ___ aus Westen.","en":"Today a strong wind is blowing from the west."},{"ans":"Wind","de":"Bei starkem ___ kann ich nicht gut Fahrrad fahren.","en":"I can't ride a bike well in strong wind."}]},
 {"id":"winter-wetter","lv":"A2","words":[{"w":"Winter","en":"winter"},{"w":"Wetter","en":"weather"}],"tip":"der Winter = the cold season; das Wetter = weather (rain, sun, wind). Different gender, too.","items":[{"ans":"Winter","de":"Im ___ liegt hier oft viel Schnee.","en":"In winter there is often a lot of snow here."},{"ans":"Winter","de":"Der ___ ist bei uns lang und sehr kalt.","en":"Winter is long and very cold where we live."},{"ans":"Wetter","de":"Wie wird das ___ morgen?","en":"What will the weather be like tomorrow?"},{"ans":"Wetter","de":"Wenn das ___ schön ist, machen wir ein Picknick.","en":"If the weather is nice, we'll have a picnic."}]},
 {"id":"nach-noch","lv":"A2","words":[{"w":"nach","en":"after; to (a city/country)"},{"w":"noch","en":"still; another, more"}],"tip":"nach = after / to (Fahrt nach Berlin); noch = still / yet / another (noch einen Kaffee).","items":[{"ans":"nach","de":"Wir gehen ___ dem Essen ein bisschen spazieren.","en":"After the meal we go for a little walk."},{"ans":"nach","de":"Fährt dieser Zug ___ München?","en":"Does this train go to Munich?"},{"ans":"noch","de":"Möchtest du ___ einen Kaffee?","en":"Would you like another coffee?"},{"ans":"noch","de":"Kannst du bitte ___ ein Stück Brot mitbringen?","en":"Could you please bring one more piece of bread?"}]},
 {"id":"als-also","lv":"A2","words":[{"w":"als","en":"than; as; when (past)"},{"w":"also","en":"so, therefore"}],"tip":"als = than / as / when (past); also = so, therefore. Don't add the extra -o to comparisons!","items":[{"ans":"als","de":"Mein Bruder ist älter ___ ich.","en":"My brother is older than me."},{"ans":"als","de":"Mein Vater hat ___ Kind in Hamburg gewohnt.","en":"My father lived in Hamburg as a child."},{"ans":"also","de":"Es regnet stark, ___ nehmen wir lieber ein Taxi.","en":"It's raining hard, so we'd rather take a taxi."},{"ans":"also","de":"Du hast keine Zeit, ___ gehen wir morgen.","en":"You have no time, so we'll go tomorrow."}]},
 {"id":"preis-reis","lv":"A2","words":[{"w":"Preis","en":"price; prize"},{"w":"Reis","en":"rice"}],"tip":"der Preis = price (or prize); der Reis = rice. Pr- vs R-.","items":[{"ans":"Preis","de":"Der ___ für das Zimmer ist sehr günstig.","en":"The price for the room is very reasonable."},{"ans":"Preis","de":"Wie hoch ist der ___ für ein Ticket nach Wien?","en":"How much is a ticket to Vienna?"},{"ans":"Reis","de":"Zum Mittagessen gibt es Hähnchen mit ___.","en":"For lunch there is chicken with rice."},{"ans":"Reis","de":"Möchtest du lieber Kartoffeln oder ___?","en":"Would you rather have potatoes or rice?"}]},
 {"id":"gras-glas","lv":"A2","words":[{"w":"Gras","en":"grass"},{"w":"Glas","en":"glass; drinking glass; jar"}],"tip":"das Gras = what grows on a meadow; das Glas = glass (material), a glass to drink from, or a jar. Gra- vs Gla-.","items":[{"ans":"Gras","de":"Die Kühe fressen frisches ___ auf der Wiese.","en":"The cows are eating fresh grass in the meadow."},{"ans":"Gras","de":"Im Sommer liegen wir gern im ___ am Fluss.","en":"In summer we like lying in the grass by the river."},{"ans":"Glas","de":"Bring mir bitte ein ___ Wasser.","en":"Please bring me a glass of water."},{"ans":"Glas","de":"Das Fenster ist aus ___ und nicht aus Plastik.","en":"The window is made of glass, not plastic."}]},
 {"id":"schuh-schule","lv":"A2","words":[{"w":"Schuh","en":"shoe (singular)"},{"w":"Schuhe","en":"shoes (plural)"},{"w":"Schule","en":"school"}],"tip":"Schuh/Schuhe = footwear (sg./pl.); Schule = school. Schuhe and Schule differ only in h vs l, and the h in Schuhe is silent: Schu-e vs Schu-le.","items":[{"ans":"Schuh","de":"Mein linker ___ ist nass geworden.","en":"My left shoe has got wet."},{"ans":"Schuhe","de":"Im Geschäft habe ich neue ___ gekauft.","en":"In the shop I bought new shoes."},{"ans":"Schuhe","de":"Zieh bitte die nassen ___ aus!","en":"Please take off your wet shoes!"},{"ans":"Schule","de":"Die Kinder gehen jeden Morgen zur ___.","en":"The children go to school every morning."},{"ans":"Schule","de":"Nach der ___ spielen wir Fußball.","en":"After school we play football."}]},
 {"id":"nehmen-nennen-kennen","lv":"A2","words":[{"w":"nehmen","en":"to take"},{"w":"nennen","en":"to name, to call"},{"w":"kennen","en":"to know (a person, place)"}],"tip":"nehmen = take; nennen = call/name; kennen = know someone/something. They look and sound alike, but the meanings are far apart.","items":[{"ans":"nehmen","de":"Weil das Auto kaputt ist, ___ wir am Wochenende den Zug.","en":"Because the car is broken, we are taking the train at the weekend."},{"ans":"nehmen","de":"Ihr könnt euch gern ein Stück Kuchen ___.","en":"You are welcome to take a piece of cake."},{"ans":"nennen","de":"Seine Freunde ___ ihn alle nur Ben.","en":"His friends all just call him Ben."},{"ans":"nennen","de":"Wie wollt ihr euer Baby ___: Anna oder Emma?","en":"What do you want to name your baby: Anna or Emma?"},{"ans":"kennen","de":"Wir ___ uns schon seit der Schule und sind beste Freunde.","en":"We have known each other since school and are best friends."},{"ans":"kennen","de":"Sie ___ die Stadt sehr gut, deshalb brauchen sie keinen Stadtplan.","en":"They know the city very well, so they don't need a map."}]},
 {"id":"tisch-fisch-frisch","lv":"A2","words":[{"w":"Tisch","en":"table"},{"w":"Fisch","en":"fish"},{"w":"frisch","en":"fresh"}],"tip":"der Tisch = table; der Fisch = fish; frisch = fresh. Only the first letters change.","items":[{"ans":"Tisch","de":"Der ___ in unserem Esszimmer ist aus Holz und hat vier Beine.","en":"The table in our dining room is made of wood and has four legs."},{"ans":"Tisch","de":"Wir sitzen alle zusammen am großen ___.","en":"We all sit together at the big table."},{"ans":"Fisch","de":"Heute gibt es gebratenen ___ mit Kartoffeln.","en":"Today there is fried fish with potatoes."},{"ans":"Fisch","de":"Der kleine ___ schwimmt im Aquarium hin und her.","en":"The little fish swims back and forth in the aquarium."},{"ans":"frisch","de":"Die Brötchen sind ganz ___, sie kommen gerade aus dem Ofen.","en":"The rolls are really fresh, they've just come out of the oven."},{"ans":"frisch","de":"Im Sommer esse ich gern ___ gepflückte Erdbeeren.","en":"In summer I like eating freshly picked strawberries."}]},
 {"id":"hand-hund-hunger","lv":"A2","words":[{"w":"Hand","en":"hand"},{"w":"Hund","en":"dog"},{"w":"Hunger","en":"hunger"}],"tip":"die Hand = hand; der Hund = dog; der Hunger = hunger (Ich habe Hunger).","items":[{"ans":"Hand","de":"Gib mir bitte deine ___, dann gehen wir über die Straße.","en":"Give me your hand, then we'll cross the street."},{"ans":"Hand","de":"Sie schrieb mit der linken ___.","en":"She wrote with her left hand."},{"ans":"Hund","de":"Der ___ bellt laut, wenn jemand klingelt.","en":"The dog barks loudly when someone rings the bell."},{"ans":"Hund","de":"Er hält den ___ an der Leine.","en":"He is holding the dog on the lead."},{"ans":"Hunger","de":"Ich habe großen ___, ich habe heute noch nichts gegessen.","en":"I'm very hungry, I haven't eaten anything today."},{"ans":"Hunger","de":"Nach dem Sport hatten wir alle richtigen ___.","en":"After sports we were all really hungry."}]},
 {"id":"dorf-durst","lv":"A2","words":[{"w":"Dorf","en":"village"},{"w":"Durst","en":"thirst"}],"tip":"das Dorf = village; der Durst = thirst (Ich habe Durst = I am thirsty). Do-rf vs Du-rst.","items":[{"ans":"Dorf","de":"Wir wohnen in einem kleinen ___ auf dem Land.","en":"We live in a small village in the country."},{"ans":"Dorf","de":"Im ___ kennt jeder jeden.","en":"In the village everybody knows everybody."},{"ans":"Durst","de":"Bei der Hitze bekomme ich schnell ___.","en":"In this heat I quickly get thirsty."},{"ans":"Durst","de":"Hast du ___? Ich habe Saft im Kühlschrank.","en":"Are you thirsty? I have juice in the fridge."}]},
 {"id":"sohn-sonne-sonntag","lv":"A2","words":[{"w":"Sohn","en":"son"},{"w":"Sonne","en":"sun"},{"w":"Sonntag","en":"Sunday"}],"tip":"der Sohn (long o) = son; die Sonne (short o) = sun; der Sonntag = Sunday (Sonne + Tag).","items":[{"ans":"Sohn","de":"Ihr ___ ist fünf Jahre alt und geht in den Kindergarten.","en":"Their son is five years old and goes to nursery school."},{"ans":"Sohn","de":"Mein ___ spielt gern mit seinen Freunden Fußball.","en":"My son likes playing football with his friends."},{"ans":"Sonne","de":"Heute scheint den ganzen Tag die ___.","en":"Today the sun shines all day."},{"ans":"Sonne","de":"Im Urlaub liege ich gern in der ___ am Strand.","en":"On holiday I like lying in the sun on the beach."},{"ans":"Sonntag","de":"Am ___ schlafen wir gern lange.","en":"On Sunday we like to sleep in."},{"ans":"Sonntag","de":"Die Geschäfte sind am ___ geschlossen.","en":"The shops are closed on Sunday."}]},
 {"id":"geld-gold","lv":"A2","words":[{"w":"Geld","en":"money"},{"w":"Gold","en":"gold"}],"tip":"das Geld = money; das Gold = gold. Only one letter differs (e vs o).","items":[{"ans":"Geld","de":"Auf meinem Konto ist leider kein ___ mehr.","en":"Unfortunately there is no money left in my account."},{"ans":"Geld","de":"Wie viel ___ brauchst du für den Urlaub?","en":"How much money do you need for the holiday?"},{"ans":"Gold","de":"Der Ring ist aus echtem ___, nicht aus Silber.","en":"The ring is made of real gold, not silver."},{"ans":"Gold","de":"Ihr Haar glänzt in der Sonne wie ___.","en":"Her hair shines in the sun like gold."}]},
 {"id":"kuchen-kochen-kueche","lv":"A2","words":[{"w":"Kuchen","en":"cake"},{"w":"kochen","en":"to cook"},{"w":"Küche","en":"kitchen"}],"tip":"der Kuchen = cake; kochen = to cook; die Küche = kitchen. Kuchen and kochen both start with k, but Kuchen is a noun.","items":[{"ans":"Kuchen","de":"Zum Geburtstag backt meine Oma einen ___.","en":"For my birthday my grandma bakes a cake."},{"ans":"Kuchen","de":"Möchtest du noch ein Stück ___ essen?","en":"Would you like to eat another piece of cake?"},{"ans":"kochen","de":"Am Wochenende möchten wir zusammen etwas Leckeres ___.","en":"At the weekend we'd like to cook something delicious together."},{"ans":"kochen","de":"Mein Mann hat Spaß daran, für uns alle zu ___.","en":"My husband enjoys cooking for all of us."},{"ans":"Küche","de":"Die ___ in unserer Wohnung ist sehr klein.","en":"The kitchen in our flat is very small."},{"ans":"Küche","de":"Wir essen meistens in der ___.","en":"We mostly eat in the kitchen."}]},
 {"id":"gehen-stehen-sehen","lv":"A2","words":[{"w":"gehen","en":"to go, to walk"},{"w":"stehen","en":"to stand"},{"w":"sehen","en":"to see"}],"tip":"gehen = go/walk; stehen = stand; sehen = see. Three very similar infinitives with different first letters.","items":[{"ans":"gehen","de":"Der Bahnhof ist nicht weit, wir können zu Fuß ___.","en":"The station isn't far; we can walk."},{"ans":"gehen","de":"Nach dem Essen wollen wir noch ein bisschen spazieren ___.","en":"After the meal we'd like to go for a little walk as well."},{"ans":"stehen","de":"Die Autos ___ seit zehn Minuten im Stau und kommen keinen Meter weiter.","en":"The cars have been standing in a traffic jam for ten minutes and are not moving an inch."},{"ans":"stehen","de":"Die Kinder ___ an der Haltestelle und warten auf den Bus.","en":"The children are standing at the bus stop waiting for the bus."},{"ans":"sehen","de":"Von hier aus können wir das Meer gut ___.","en":"From here we can see the sea well."},{"ans":"sehen","de":"Wir ___ uns morgen um acht vor dem Kino.","en":"We'll see each other tomorrow at eight in front of the cinema."}]},
 {"id":"dick-dich","lv":"A2","words":[{"w":"dick","en":"thick; fat"},{"w":"dich","en":"you (accusative)"}],"tip":"dick = thick/fat (adjective, ck); dich = you (accusative of du, ch). Same sound structure, different spelling and job.","items":[{"ans":"dick","de":"Das Buch ist sehr ___ und hat mehr als tausend Seiten.","en":"The book is very thick and has more than a thousand pages."},{"ans":"dick","de":"Mein Winterpullover ist schön ___ und warm.","en":"My winter sweater is nice and thick and warm."},{"ans":"dich","de":"Ich rufe ___ heute Abend an.","en":"I'll call you this evening."},{"ans":"dich","de":"Wir haben ___ gestern im Park gesehen.","en":"We saw you in the park yesterday."}]},
 {"id":"sagen-fragen","lv":"A2","words":[{"w":"sagen","en":"to say, to tell"},{"w":"fragen","en":"to ask"}],"tip":"sagen = say/tell (jemandem etwas sagen); fragen = ask (jemanden etwas fragen). With fragen the person is in the accusative: dich fragen.","items":[{"ans":"sagen","de":"Ich muss dir leider ___, dass ich morgen nicht kommen kann.","en":"Unfortunately I have to tell you that I can't come tomorrow."},{"ans":"sagen","de":"Er wollte mir nichts von der Party ___.","en":"He didn't want to tell me anything about the party."},{"ans":"fragen","de":"Darf ich dich etwas ___?","en":"May I ask you something?"},{"ans":"fragen","de":"Wenn du den Weg nicht kennst, musst du jemanden ___.","en":"If you don't know the way, you have to ask somebody."}]},
 {"id":"zaehlen-zahlen","lv":"A2","words":[{"w":"zählen","en":"to count"},{"w":"zahlen","en":"to pay"}],"tip":"zählen (with ä) = to count (eins, zwei, drei); zahlen (with a) = to pay. The spelling differs only by the umlaut dots, the meaning by a lot.","items":[{"ans":"zählen","de":"Das Kind kann schon von eins bis hundert ___.","en":"The child can already count from one to a hundred."},{"ans":"zählen","de":"Bitte ___ Sie, wie viele Gäste da sind, bevor wir bestellen.","en":"Please count how many guests are here before we order."},{"ans":"zahlen","de":"Hier kann man nur bar ___.","en":"Here you can only pay in cash."},{"ans":"zahlen","de":"Darf ich mit Karte ___?","en":"May I pay by card?"}]},
 {"id":"vorschlag-vorschrift-vorsicht","lv":"B1","words":[{"w":"Vorschlag","en":"suggestion, proposal"},{"w":"Vorschrift","en":"rule, regulation"},{"w":"Vorsicht","en":"caution, care"}],"tip":"Vorschlag = a suggestion you can accept or reject; Vorschrift = an official rule you must follow; Vorsicht = care/caution (Vorsicht! = watch out!).","items":[{"ans":"Vorschlag","de":"Hast du einen ___, wo wir heute Abend essen gehen könnten?","en":"Do you have a suggestion where we could go for dinner tonight?"},{"ans":"Vorschlag","de":"Das ist ein guter ___, den sollten wir im Team besprechen.","en":"That is a good proposal; we should discuss it in the team."},{"ans":"Vorschrift","de":"Wer gegen diese ___ verstößt, muss eine Strafe zahlen.","en":"Anyone who breaks this regulation has to pay a fine."},{"ans":"Vorschrift","de":"Laut der neuen ___ muss jeder Mitarbeiter hier einen Helm tragen.","en":"According to the new regulation, every employee here has to wear a helmet."},{"ans":"Vorsicht","de":"Bei Glatteis sollte man mit großer ___ fahren.","en":"In icy conditions you should drive with great care."},{"ans":"Vorsicht","de":"Auf dem nassen Boden ist ___ geboten, sonst rutscht man aus.","en":"Caution is called for on the wet floor, otherwise you'll slip."}]},
 {"id":"gewicht-gewitter-gewinn","lv":"B1","words":[{"w":"Gewicht","en":"weight"},{"w":"Gewitter","en":"thunderstorm"},{"w":"Gewinn","en":"profit; prize, winnings"}],"tip":"Gewicht = weight (kilos); Gewitter = thunderstorm (Blitz und Donner); Gewinn = profit or something you win.","items":[{"ans":"Gewicht","de":"Das ___ des Pakets beträgt fünf Kilo.","en":"The weight of the parcel is five kilos."},{"ans":"Gewicht","de":"Seit dem Urlaub achte ich mehr auf mein ___.","en":"Since my holiday I have been paying more attention to my weight."},{"ans":"Gewitter","de":"Am Nachmittag zieht ein schweres ___ auf, mit Blitz und Donner.","en":"In the afternoon a heavy thunderstorm is coming, with lightning and thunder."},{"ans":"Gewitter","de":"Bei einem ___ sollte man nicht unter einem Baum stehen.","en":"During a thunderstorm you shouldn't stand under a tree."},{"ans":"Gewinn","de":"Die Firma hat im letzten Jahr einen hohen ___ gemacht.","en":"The company made a high profit last year."},{"ans":"Gewinn","de":"Der ___ aus dem Verkauf wurde gespendet.","en":"The proceeds from the sale were donated."}]},
 {"id":"geburt-gebuehr-gebaeude","lv":"B1","words":[{"w":"Geburt","en":"birth"},{"w":"Gebühr","en":"fee, charge"},{"w":"Gebäude","en":"building"}],"tip":"Geburt = birth; Gebühr = official fee; Gebäude = building. All three start with Ge- and are feminine, feminine, neuter.","items":[{"ans":"Geburt","de":"Zur ___ ihres Sohnes bekam sie viele Blumen.","en":"She received lots of flowers for the birth of her son."},{"ans":"Geburt","de":"Nach der ___ wird das Baby kurz untersucht.","en":"After the birth the baby is briefly examined."},{"ans":"Gebühr","de":"Für den Reisepass muss man eine ___ bezahlen.","en":"You have to pay a fee for the passport."},{"ans":"Gebühr","de":"Die ___ für die Bibliothekskarte beträgt zehn Euro im Jahr.","en":"The fee for the library card is ten euros a year."},{"ans":"Gebäude","de":"Das ___ neben dem Bahnhof ist über hundert Jahre alt.","en":"The building next to the station is over a hundred years old."},{"ans":"Gebäude","de":"In diesem ___ befindet sich das Rathaus.","en":"The town hall is located in this building."}]},
 {"id":"leihen-lehnen-leiden-leiten","lv":"B1","words":[{"w":"leihen","en":"to lend; to borrow (sich leihen)"},{"w":"lehnen","en":"to lean"},{"w":"leiden","en":"to suffer"},{"w":"leiten","en":"to lead, to manage"}],"tip":"leihen = lend/borrow; lehnen = lean; leiden = suffer; leiten = lead/manage. leihen, leiden and leiten share the diphthong ei; lehnen has a long e (eh).","items":[{"ans":"leihen","de":"Kannst du mir bitte zehn Euro ___?","en":"Could you lend me ten euros, please?"},{"ans":"leihen","de":"Darf ich mir dein Fahrrad kurz ___?","en":"May I borrow your bike for a moment?"},{"ans":"lehnen","de":"Du darfst dich nicht an die frisch gestrichene Wand ___.","en":"You mustn't lean against the freshly painted wall."},{"ans":"lehnen","de":"Er wollte sich nur kurz an den Zaun ___.","en":"He only wanted to lean against the fence for a moment."},{"ans":"leiden","de":"Er scheint seit Jahren an starken Kopfschmerzen zu ___.","en":"He seems to have been suffering from severe headaches for years."},{"ans":"leiden","de":"Viele Menschen ___ im Frühling unter Allergien.","en":"Many people suffer from allergies in spring."},{"ans":"leiten","de":"Wer soll das neue Projekt ___?","en":"Who is going to lead the new project?"},{"ans":"leiten","de":"Frau Wagner wird ab Montag die Abteilung ___.","en":"From Monday, Ms Wagner will manage the department."}]},
 {"id":"erinnern-merken","lv":"B1","words":[{"w":"erinnern","en":"to remember (sich erinnern an); to remind (jdn. an etw. erinnern)"},{"w":"merken","en":"to remember, memorise (sich etwas merken); to notice"}],"tip":"sich erinnern an + Akk. = remember something from the past; jdn. an etw. erinnern = remind someone; sich (Dat.) etwas merken = memorise it for later. Mnemonic: sich erinnern looks back, sich etwas merken looks ahead.","items":[{"ans":"erinnern","de":"Kannst du dich noch an unseren ersten Urlaub ___?","en":"Can you still remember our first holiday?"},{"ans":"erinnern","de":"Ich kann mich leider nicht mehr an seinen Namen ___.","en":"Unfortunately I can't remember his name any more."},{"ans":"erinnern","de":"Kannst du mich morgen an den Termin ___?","en":"Can you remind me of the appointment tomorrow?"},{"ans":"merken","de":"Diese Telefonnummer kann ich mir einfach nicht ___.","en":"I just can't memorise this phone number."},{"ans":"merken","de":"Wie kann ich mir die vielen Vokabeln am besten ___?","en":"What is the best way for me to memorise all these vocabulary words?"}]},
 {"id":"anstatt-stattdessen","lv":"B1","words":[{"w":"anstatt","en":"instead of"},{"w":"stattdessen","en":"instead (adverb)"}],"tip":"anstatt (+ zu + Infinitiv / Genitiv) = instead of doing/having something; stattdessen = instead (stands alone as an adverb).","items":[{"ans":"anstatt","de":"Er sah den ganzen Tag fern, ___ zu lernen.","en":"He watched TV all day instead of studying."},{"ans":"anstatt","de":"Nimm doch ___ der Tasche lieber einen Rucksack mit!","en":"Take a rucksack with you instead of the bag!"},{"ans":"stattdessen","de":"Sie wollte eigentlich lernen, aber sie ging ___ ins Kino.","en":"She actually wanted to study, but she went to the cinema instead."},{"ans":"stattdessen","de":"Der Zug fällt aus, deshalb nehmen wir ___ den Bus.","en":"The train is cancelled, so we're taking the bus instead."}]},
 {"id":"wunsch-wunder-wunde","lv":"B1","words":[{"w":"Wunsch","en":"wish, request"},{"w":"Wunder","en":"miracle; wonder"},{"w":"Wunde","en":"wound"}],"tip":"Wunsch = a wish; Wunder = a miracle; Wunde = a wound. All three start with Wun-.","items":[{"ans":"Wunsch","de":"Mein größter ___ ist eine Reise nach Japan.","en":"My greatest wish is a trip to Japan."},{"ans":"Wunsch","de":"Haben Sie noch einen ___? Dann sagen Sie es mir bitte.","en":"Do you have any other request? If so, please tell me."},{"ans":"Wunder","de":"Es ist ein ___, dass bei dem Unfall niemand verletzt wurde.","en":"It is a miracle that no one was injured in the accident."},{"ans":"Wunder","de":"Das neue Medikament wirkt wie ein ___.","en":"The new medicine works like a miracle."},{"ans":"Wunde","de":"Die ___ am Knie muss sauber gehalten werden.","en":"The wound on the knee has to be kept clean."},{"ans":"Wunde","de":"Die Ärztin verband die tiefe ___ am Arm.","en":"The doctor bandaged the deep wound on the arm."}]},
 {"id":"vorteil-nachteil-vorurteil","lv":"B1","words":[{"w":"Vorteil","en":"advantage"},{"w":"Nachteil","en":"disadvantage"},{"w":"Vorurteil","en":"prejudice"}],"tip":"Vorteil = advantage; Nachteil = disadvantage (opposites); Vorurteil = prejudice (a judgement before you know the facts). Vorteil and Vorurteil are easy to mix up.","items":[{"ans":"Vorteil","de":"Der große ___ des neuen Handys ist die sehr gute Kamera.","en":"The great advantage of the new phone is its very good camera."},{"ans":"Vorteil","de":"Ein großer ___ des Fahrrads ist, dass man damit schnell durch die Stadt kommt.","en":"A big advantage of the bicycle is that you get through the city quickly."},{"ans":"Nachteil","de":"Der ___ des Autos ist der hohe Benzinverbrauch.","en":"The disadvantage of the car is its high fuel consumption."},{"ans":"Nachteil","de":"Ein ___ der Wohnung ist, dass sie so laut ist.","en":"One disadvantage of the flat is that it is so noisy."},{"ans":"Vorurteil","de":"Er hat ein ___ gegenüber Fremden, obwohl er sie gar nicht kennt.","en":"He is prejudiced against strangers even though he doesn't know them at all."},{"ans":"Vorurteil","de":"Es ist ein weit verbreitetes ___, dass alle Deutschen immer pünktlich sind.","en":"It is a widespread prejudice that all Germans are always punctual."}]},
 {"id":"zeugnis-zeuge-zeichen","lv":"B1","words":[{"w":"Zeugnis","en":"school report; certificate"},{"w":"Zeuge","en":"witness (male)"},{"w":"Zeichen","en":"sign, signal"}],"tip":"Zeugnis = school report/certificate; Zeuge = witness; Zeichen = sign/signal. Zeug- words are about testimony; Zeichen is about signs.","items":[{"ans":"Zeugnis","de":"Am Ende des Schuljahres bekommen alle Kinder ein ___ mit ihren Noten.","en":"At the end of the school year all the children get a report with their grades."},{"ans":"Zeugnis","de":"Auf meinem ___ stehen zum Glück nur gute Noten.","en":"Fortunately my report only shows good grades."},{"ans":"Zeuge","de":"Der einzige ___ des Unfalls war ein kleiner Junge.","en":"The only witness to the accident was a little boy."},{"ans":"Zeuge","de":"Der ___ hat vor Gericht erzählt, was er gesehen hat.","en":"The witness told the court what he had seen."},{"ans":"Zeichen","de":"Das rote Licht ist ein ___ zum Anhalten.","en":"The red light is a signal to stop."},{"ans":"Zeichen","de":"Die Lehrerin gab uns mit der Hand ein ___, dass wir leise sein sollten.","en":"The teacher signalled to us with her hand that we should be quiet."}]},
 {"id":"entscheiden-unterscheiden","lv":"B1","words":[{"w":"entscheiden","en":"to decide"},{"w":"unterscheiden","en":"to distinguish, to tell apart"}],"tip":"entscheiden = make a decision (sich entscheiden für); unterscheiden = see the difference (A von B unterscheiden).","items":[{"ans":"entscheiden","de":"Ich kann mich nicht ___, welches Kleid ich nehmen soll.","en":"I can't decide which dress to take."},{"ans":"entscheiden","de":"Du musst dich bis morgen ___, ob du mitkommst.","en":"You have to decide by tomorrow whether you're coming along."},{"ans":"unterscheiden","de":"Die Zwillinge kann man kaum voneinander ___.","en":"You can hardly tell the twins apart."},{"ans":"unterscheiden","de":"Kannst du Butter und Margarine am Geschmack ___?","en":"Can you tell butter and margarine apart by the taste?"}]},
 {"id":"leistung-leitung","lv":"B1","words":[{"w":"Leistung","en":"performance, achievement"},{"w":"Leitung","en":"management; line, pipe"}],"tip":"Leistung = performance (what you achieve); Leitung = leadership/management (and a telephone line or pipe). Only the s differs.","items":[{"ans":"Leistung","de":"Für seine hervorragende ___ im Test bekam er eine Eins.","en":"He got an A for his excellent performance in the test."},{"ans":"Leistung","de":"Seine Noten zeigen, dass sich seine ___ in Mathe deutlich verbessert hat.","en":"His grades show that his performance in maths has improved significantly."},{"ans":"Leitung","de":"Die ___ der Schule hat einen neuen Plan für die Pausen.","en":"The school management has a new plan for the breaks."},{"ans":"Leitung","de":"Seit Montag liegt die ___ des Projekts bei Frau Klein.","en":"Since Monday the leadership of the project has been with Ms Klein."}]},
 {"id":"verein-vertrag-verkehr","lv":"B1","words":[{"w":"Verein","en":"club, association"},{"w":"Vertrag","en":"contract"},{"w":"Verkehr","en":"traffic"}],"tip":"Verein = club; Vertrag = contract; Verkehr = traffic. All three begin with Ver- and have similar length.","items":[{"ans":"Verein","de":"Mein Bruder spielt in einem ___ Fußball.","en":"My brother plays football in a club."},{"ans":"Verein","de":"Ich bin seit zehn Jahren Mitglied im ___.","en":"I have been a member of the club for ten years."},{"ans":"Vertrag","de":"Bevor Sie den ___ unterschreiben, lesen Sie ihn bitte genau.","en":"Before you sign the contract, please read it carefully."},{"ans":"Vertrag","de":"Der ___ für die Wohnung läuft noch bis Dezember.","en":"The contract for the flat runs until December."},{"ans":"Verkehr","de":"Morgens ist der ___ in der Stadt besonders dicht.","en":"In the morning the traffic in the city is particularly heavy."},{"ans":"Verkehr","de":"Durch den starken ___ sind wir zu spät gekommen.","en":"Because of the heavy traffic we arrived late."}]},
 {"id":"uebrig-uebrigens","lv":"B1","words":[{"w":"übrig","en":"left over"},{"w":"übrigens","en":"by the way"}],"tip":"übrig = left over (Ist noch Brot übrig?); übrigens = by the way, introducing a side remark. With the ending -ens, übrigens works as a sentence adverb.","items":[{"ans":"übrig","de":"Ist von der Suppe noch etwas ___?","en":"Is there any soup left?"},{"ans":"übrig","de":"Nach dem Fest war kaum noch Kuchen ___.","en":"After the party there was hardly any cake left."},{"ans":"übrigens","de":"Wie geht es ___ deiner Schwester?","en":"By the way, how is your sister?"},{"ans":"übrigens","de":"Ich habe ___ gestern deinen Bruder in der Stadt gesehen.","en":"By the way, I saw your brother in town yesterday."}]}
];

window.TK_HOMONYMS = [
 {"id":"see","word":"See","lv":"A2","tip":"der See = lake (masculine); die See = the sea (feminine). 'An die See fahren' = go to the seaside.","meanings":[{"gloss":"lake","art":"der","pl":"Seen","ex":[{"de":"Im Sommer schwimmen wir fast jeden Tag im {{See}}.","en":"In summer we swim in the lake almost every day."},{"de":"Im Winter ist der {{See}} manchmal zugefroren.","en":"In winter the lake is sometimes frozen over."},{"de":"In Bayern haben wir drei {{Seen}} besucht.","en":"In Bavaria we visited three lakes."}]},{"gloss":"the sea, ocean (esp. North Sea / Baltic); sea conditions","art":"die","pl":"","note":"Usually singular only; in everyday use 'Seen' means lakes. Also: 'zur See fahren' (to be a sailor).","ex":[{"de":"Wir machen Urlaub an der {{See}}, nicht in den Bergen.","en":"We're vacationing at the seaside, not in the mountains."},{"de":"Bei stürmischer {{See}} blieben die Fähren im Hafen.","en":"With the sea so stormy, the ferries stayed in port."},{"de":"Mein Großvater ist früher zur {{See}} gefahren.","en":"My grandfather used to be a sailor."}]}]},
 {"id":"tor","word":"Tor","lv":"B2","tip":"das Tor = gate / goal; der Tor (weak noun) = fool, literary. Plural of the neuter: Tore; of the masculine: Toren.","meanings":[{"gloss":"gate, large door","art":"das","pl":"Tore","ex":[{"de":"Das {{Tor}} zum Garten wird abends abgeschlossen.","en":"The garden gate is locked in the evening."},{"de":"Bitte schließen Sie das {{Tor}}, wenn Sie gehen.","en":"Please close the gate when you leave."},{"de":"Die großen {{Tore}} der Fabrik werden um sechs Uhr geöffnet.","en":"The big gates of the factory are opened at six o'clock."}]},{"gloss":"goal (football etc.)","art":"das","pl":"Tore","ex":[{"de":"Unsere Mannschaft hat in der zweiten Halbzeit zwei {{Tore}} geschossen.","en":"Our team scored two goals in the second half."},{"de":"Der Stürmer schoss den Ball knapp am {{Tor}} vorbei.","en":"The striker shot the ball just wide of the goal."},{"de":"Kurz vor dem Abpfiff fiel noch das entscheidende {{Tor}}.","en":"Shortly before the final whistle the decisive goal was scored."}]},{"gloss":"fool (literary, dated)","art":"der","pl":"Toren","note":"Weak noun: den/dem/des Toren. Literary or dated.","ex":[{"de":"Nur ein {{Tor}} glaubt solchen Versprechungen.","en":"Only a fool believes such promises."},{"de":"Ich war ein {{Tor}}, ihm mein Geld anzuvertrauen.","en":"I was a fool to entrust my money to him."},{"de":"Die {{Toren}} halten sich oft für klüger als alle anderen.","en":"Fools often think they are smarter than everyone else."}]}]},
 {"id":"leiter","word":"Leiter","lv":"B1","tip":"der Leiter = person in charge (female: die Leiterin); die Leiter = ladder.","meanings":[{"gloss":"head, manager, person in charge","art":"der","pl":"Leiter","note":"Female form: die Leiterin.","ex":[{"de":"Der {{Leiter}} der Abteilung ist heute im Urlaub.","en":"The head of the department is on vacation today."},{"de":"Wir haben einen neuen {{Leiter}} für das Projekt gefunden.","en":"We have found a new leader for the project."},{"de":"Die {{Leiter}} der Schulen trafen sich zu einer Konferenz.","en":"The heads of the schools met for a conference."}]},{"gloss":"ladder","art":"die","pl":"Leitern","ex":[{"de":"Hol bitte die {{Leiter}} aus dem Keller.","en":"Please get the ladder from the basement."},{"de":"Er stieg auf die {{Leiter}} und wechselte die Glühbirne.","en":"He climbed the ladder and changed the light bulb."},{"de":"Im Schuppen hängen zwei lange {{Leitern}} an der Wand.","en":"Two long ladders hang on the wall in the shed."}]}]},
 {"id":"band","word":"Band","lv":"B1","tip":"der Band = book volume; das Band = ribbon, tape, belt; die Band = music group (pronounced like English 'band').","meanings":[{"gloss":"volume (of a book)","art":"der","pl":"Bände","ex":[{"de":"Das Lexikon besteht aus zwölf {{Bänden}}.","en":"The encyclopedia consists of twelve volumes."},{"de":"Den zweiten {{Band}} der Reihe habe ich schon gelesen.","en":"I have already read the second volume of the series."},{"de":"Im Regal stehen die {{Bände}} seiner gesammelten Werke.","en":"The volumes of his collected works are on the shelf."}]},{"gloss":"ribbon, tape, belt; ligament","art":"das","pl":"Bänder","note":"Also: das Fließband (assembly line), das Tonband (audio tape), das Kreuzband (cruciate ligament). Plural 'Bande' (literary) = bonds, ties.","ex":[{"de":"Sie band sich ein rotes {{Band}} ins Haar.","en":"She tied a red ribbon in her hair."},{"de":"Die Arbeiter stehen den ganzen Tag am {{Band}} und montieren Autoteile.","en":"The workers stand at the assembly line all day assembling car parts."},{"de":"Beim Skifahren hat sie sich zwei {{Bänder}} im Knie gerissen.","en":"While skiing she tore two ligaments in her knee."}]},{"gloss":"band (music group)","art":"die","pl":"Bands","ex":[{"de":"Die {{Band}} spielt heute Abend im Jugendzentrum.","en":"The band is playing at the youth centre tonight."},{"de":"Mein Bruder hat mit Freunden eine {{Band}} gegründet.","en":"My brother founded a band with friends."},{"de":"Beide {{Bands}} traten nacheinander auf der großen Bühne auf.","en":"Both bands performed one after the other on the big stage."}]}]},
 {"id":"kiefer","word":"Kiefer","lv":"B2","tip":"der Kiefer = jaw (body); die Kiefer = pine tree.","meanings":[{"gloss":"jaw","art":"der","pl":"Kiefer","ex":[{"de":"Nach dem Unfall war sein {{Kiefer}} gebrochen.","en":"After the accident his jaw was broken."},{"de":"Beim Kauen tut mir der {{Kiefer}} weh.","en":"My jaw hurts when I chew."},{"de":"Der Zahnarzt hat meinen {{Kiefer}} geröntgt.","en":"The dentist X-rayed my jaw."}]},{"gloss":"pine (tree)","art":"die","pl":"Kiefern","ex":[{"de":"Auf dem sandigen Boden wachsen vor allem {{Kiefern}}.","en":"Mostly pines grow on the sandy soil."},{"de":"Unter der alten {{Kiefer}} liegen viele Zapfen.","en":"Lots of cones lie under the old pine tree."},{"de":"Die {{Kiefer}} ist ein Nadelbaum und bleibt im Winter grün.","en":"The pine is a conifer and stays green in winter."}]}]},
 {"id":"steuer","word":"Steuer","lv":"B1","tip":"das Steuer = steering wheel (am Steuer sitzen); die Steuer = tax (usually plural: die Steuern).","meanings":[{"gloss":"steering wheel; helm","art":"das","pl":"Steuer","note":"Also figurative: 'das Steuer übernehmen' = take the lead.","ex":[{"de":"Er saß am {{Steuer}} und konnte kaum die Augen offen halten.","en":"He was at the wheel and could hardly keep his eyes open."},{"de":"Bitte übernimm das {{Steuer}}, ich bin müde.","en":"Please take the wheel, I'm tired."},{"de":"Sie hielt das {{Steuer}} mit beiden Händen fest.","en":"She held the steering wheel tightly with both hands."}]},{"gloss":"tax","art":"die","pl":"Steuern","ex":[{"de":"Die {{Steuern}} sind in diesem Jahr wieder gestiegen.","en":"Taxes have gone up again this year."},{"de":"Auf Zigaretten wird eine hohe {{Steuer}} erhoben.","en":"A high tax is levied on cigarettes."},{"de":"Wir müssen bis Ende Juli unsere {{Steuern}} bezahlen.","en":"We have to pay our taxes by the end of July."}]}]},
 {"id":"erbe","word":"Erbe","lv":"B2","tip":"der Erbe = heir (weak noun, die Erbin); das Erbe = inheritance, legacy.","meanings":[{"gloss":"heir","art":"der","pl":"Erben","note":"Weak noun: den/dem/des Erben. Female form: die Erbin.","ex":[{"de":"Der {{Erbe}} des Hofes ist der älteste Sohn.","en":"The heir to the farm is the eldest son."},{"de":"Sie hat ihren Neffen zum {{Erben}} eingesetzt.","en":"She named her nephew as her heir."},{"de":"Die {{Erben}} stritten sich um das Haus.","en":"The heirs quarrelled over the house."}]},{"gloss":"inheritance; legacy, heritage","art":"das","pl":"","note":"No common plural.","ex":[{"de":"Von seinem Großvater bekam er ein großes {{Erbe}}.","en":"He received a large inheritance from his grandfather."},{"de":"Das kulturelle {{Erbe}} der Stadt wird sorgfältig geschützt.","en":"The city's cultural heritage is carefully protected."},{"de":"Sie hat das {{Erbe}} ausgeschlagen, weil es mit Schulden belastet war.","en":"She renounced the inheritance because it was burdened with debts."}]}]},
 {"id":"gehalt","word":"Gehalt","lv":"B2","tip":"das Gehalt = salary (Pl. Gehälter); der Gehalt = content, proportion (Pl. Gehalte).","meanings":[{"gloss":"salary","art":"das","pl":"Gehälter","ex":[{"de":"Mein {{Gehalt}} wird immer am Monatsende überwiesen.","en":"My salary is always transferred at the end of the month."},{"de":"Die Angestellten verlangen höhere {{Gehälter}}.","en":"The employees demand higher salaries."},{"de":"Nach der Beförderung bekam sie ein besseres {{Gehalt}}.","en":"After her promotion she received a better salary."}],"note":"Austria also: der Gehalt (salary); standard is das Gehalt."},{"gloss":"content, proportion (of a substance); substance, depth","art":"der","pl":"Gehalte","ex":[{"de":"Der Wein hat einen hohen {{Gehalt}} an Zucker.","en":"The wine has a high sugar content."},{"de":"Die Untersuchung zeigte einen erhöhten {{Gehalt}} an Blei im Wasser.","en":"The test showed an increased lead content in the water."},{"de":"Dem Roman fehlt es an geistigem {{Gehalt}}.","en":"The novel lacks intellectual substance."}]}]},
 {"id":"verdienst","word":"Verdienst","lv":"C1","tip":"der Verdienst = earnings, income; das Verdienst = merit, credit. Plural of both: Verdienste.","meanings":[{"gloss":"earnings, income","art":"der","pl":"Verdienste","ex":[{"de":"Sein {{Verdienst}} reicht kaum für die Miete.","en":"His earnings barely cover the rent."},{"de":"Der monatliche {{Verdienst}} der Kellner hängt stark vom Trinkgeld ab.","en":"The waiters' monthly income depends heavily on tips."},{"de":"Bei dem geringen {{Verdienst}} kann sie sich keine eigene Wohnung leisten.","en":"With such low earnings she cannot afford her own flat."}]},{"gloss":"merit, credit, achievement","art":"das","pl":"Verdienste","ex":[{"de":"Es ist das {{Verdienst}} unseres Teams, dass das Projekt gelang.","en":"It is thanks to our team that the project succeeded."},{"de":"Er erhielt einen Orden für seine {{Verdienste}} um die Stadt.","en":"He received a medal for his services to the city."},{"de":"Das {{Verdienst}} gebührt allen Beteiligten, nicht nur dem Chef.","en":"The credit belongs to everyone involved, not just the boss."}]}]},
 {"id":"mast","word":"Mast","lv":"C1","tip":"der Mast = pole, mast; die Mast = fattening of livestock.","meanings":[{"gloss":"mast, pole","art":"der","pl":"Masten","ex":[{"de":"Der {{Mast}} des Segelschiffs brach im Sturm.","en":"The sailing ship's mast broke in the storm."},{"de":"Am höchsten {{Mast}} wehte die Flagge.","en":"The flag flew from the tallest mast."},{"de":"Die {{Masten}} der Hochspannungsleitung ragen über die Felder.","en":"The pylons of the high-voltage line tower over the fields."}]},{"gloss":"fattening (of livestock)","art":"die","pl":"","note":"Plural practically not used.","ex":[{"de":"Die Schweine werden nach der {{Mast}} geschlachtet.","en":"The pigs are slaughtered after fattening."},{"de":"Für die {{Mast}} der Gänse braucht man vor Weihnachten viel Futter.","en":"Fattening the geese takes a lot of feed before Christmas."},{"de":"Rinder in der {{Mast}} bekommen oft Kraftfutter.","en":"Cattle being fattened often get concentrated feed."}]}]},
 {"id":"flur","word":"Flur","lv":"B2","tip":"der Flur = hallway; die Flur = fields, farmland (elevated, 'Feld und Flur').","meanings":[{"gloss":"hallway, corridor","art":"der","pl":"Flure","ex":[{"de":"Bitte stell die Schuhe im {{Flur}} ab.","en":"Please leave your shoes in the hallway."},{"de":"Im {{Flur}} hängen viele Familienfotos.","en":"Lots of family photos hang in the hallway."},{"de":"Die Wohnung hat einen langen, dunklen {{Flur}}.","en":"The flat has a long, dark hallway."}]},{"gloss":"fields, farmland (elevated style)","art":"die","pl":"Fluren","note":"Mostly in the phrase 'Feld und Flur' or in poetic language.","ex":[{"de":"Wir wanderten den ganzen Tag durch Wald und {{Flur}}.","en":"We hiked through woods and fields all day."},{"de":"Der Frost hat die {{Fluren}} weiß gefärbt.","en":"The frost has turned the fields white."},{"de":"Im Frühling grünt die ganze {{Flur}}.","en":"In spring all the countryside turns green."}]}]},
 {"id":"pony","word":"Pony","lv":"B1","tip":"das Pony = small horse; der Pony = fringe, bangs (hairstyle). Plural of both: Ponys.","meanings":[{"gloss":"pony (small horse)","art":"das","pl":"Ponys","ex":[{"de":"Die Kinder reiten auf einem {{Pony}} über den Hof.","en":"The children ride a pony across the yard."},{"de":"Zum Geburtstag wünschte sie sich ein {{Pony}}.","en":"For her birthday she wished for a pony."},{"de":"Die kleinen {{Ponys}} grasen auf der Weide.","en":"The little ponies are grazing in the pasture."}]},{"gloss":"fringe, bangs","art":"der","pl":"Ponys","ex":[{"de":"Sie hat sich beim Friseur einen {{Pony}} schneiden lassen.","en":"She had bangs cut at the hairdresser's."},{"de":"Der {{Pony}} fällt ihr ständig in die Augen.","en":"Her fringe keeps falling into her eyes."},{"de":"Sie trägt den {{Pony}} jetzt etwas kürzer.","en":"She wears her fringe a bit shorter now."}]}]},
 {"id":"marsch","word":"Marsch","lv":"C1","tip":"der Marsch = march (walk, military, music); die Marsch = fertile coastal marshland.","meanings":[{"gloss":"march (on foot; music)","art":"der","pl":"Märsche","ex":[{"de":"Nach einem langen {{Marsch}} erreichten die Soldaten das Lager.","en":"After a long march the soldiers reached the camp."},{"de":"Die Kapelle spielte einen schneidigen {{Marsch}}.","en":"The band played a brisk march."},{"de":"Bei der Demonstration schlossen sich Tausende dem {{Marsch}} an.","en":"Thousands joined the march at the demonstration."}]},{"gloss":"marsh, fertile coastal lowland","art":"die","pl":"Marschen","ex":[{"de":"An der Nordseeküste liegt fruchtbare {{Marsch}}.","en":"Fertile marshland lies on the North Sea coast."},{"de":"In der {{Marsch}} weiden Schafe und Rinder.","en":"Sheep and cattle graze in the marshland."},{"de":"Die {{Marschen}} werden durch hohe Deiche geschützt.","en":"The marshlands are protected by high dikes."}]}]},
 {"id":"heide","word":"Heide","lv":"B2","tip":"der Heide = pagan, heathen (weak noun); die Heide = heath, moorland.","meanings":[{"gloss":"pagan, heathen","art":"der","pl":"Heiden","note":"Weak noun: den/dem/des Heiden. Female form: die Heidin.","ex":[{"de":"Die Missionare wollten die {{Heiden}} bekehren.","en":"The missionaries wanted to convert the heathens."},{"de":"Im Dorf galt er als {{Heide}}, weil er nie in die Kirche ging.","en":"In the village he was regarded as a heathen because he never went to church."},{"de":"Für die frühen Christen war jeder Nichtchrist ein {{Heide}}.","en":"For the early Christians every non-Christian was a pagan."}]},{"gloss":"heath, moorland","art":"die","pl":"Heiden","ex":[{"de":"Im Spätsommer blüht die {{Heide}} lila.","en":"In late summer the heath blooms purple."},{"de":"Wir wanderten stundenlang durch die {{Heide}}.","en":"We hiked for hours across the heath."},{"de":"Auf der {{Heide}} weiden im Sommer viele Schafe.","en":"In summer lots of sheep graze on the heath."}]}]},
 {"id":"bund","word":"Bund","lv":"B2","tip":"der Bund = alliance; waistband; the federal government. das Bund = bunch (Pl. Bunde, often unchanged after numbers).","meanings":[{"gloss":"alliance, union; the federal government","art":"der","pl":"Bünde","ex":[{"de":"Die beiden Staaten schlossen einen {{Bund}} gegen den gemeinsamen Gegner.","en":"The two states formed an alliance against the common enemy."},{"de":"Sie haben vor zehn Jahren den {{Bund}} fürs Leben geschlossen.","en":"They tied the knot ten years ago."},{"de":"Der {{Bund}} und die Länder streiten über die Finanzierung der Schulen.","en":"The federal government and the states are arguing about school funding."}]},{"gloss":"waistband","art":"der","pl":"Bünde","ex":[{"de":"Die Hose ist mir am {{Bund}} zu eng.","en":"The trousers are too tight at the waistband."},{"de":"Der elastische {{Bund}} des Rocks drückt nicht.","en":"The skirt's elastic waistband doesn't pinch."}]},{"gloss":"bunch (of vegetables, herbs, keys)","art":"das","pl":"Bunde","note":"After a number often unchanged: zwei Bund Radieschen.","ex":[{"de":"Kauf bitte ein {{Bund}} Petersilie.","en":"Please buy a bunch of parsley."},{"de":"Zwei {{Bund}} Radieschen kosten auf dem Markt einen Euro.","en":"Two bunches of radishes cost one euro at the market."},{"de":"Sie hielt ein {{Bund}} Karotten in der Hand.","en":"She was holding a bunch of carrots."}]}]},
 {"id":"hut","word":"Hut","lv":"B2","tip":"der Hut = hat; die Hut = care, protection (auf der Hut sein = be on one's guard).","meanings":[{"gloss":"hat","art":"der","pl":"Hüte","ex":[{"de":"Im Sommer trägt er einen {{Hut}} gegen die Sonne.","en":"In summer he wears a hat against the sun."},{"de":"Sie nahm den {{Hut}} ab und grüßte höflich.","en":"She took off her hat and greeted politely."},{"de":"Auf dem Flohmarkt gibt es viele alte {{Hüte}}.","en":"There are lots of old hats at the flea market."}]},{"gloss":"care, protection, guard","art":"die","pl":"","note":"Only in set phrases: auf der Hut sein, in guter Hut.","ex":[{"de":"Vor Taschendieben muss man in der Stadt auf der {{Hut}} sein.","en":"You have to be on your guard against pickpockets in the city."},{"de":"Die Kinder sind bei der Großmutter in guter {{Hut}}.","en":"The children are in good hands with their grandmother."}]}]},
 {"id":"weise","word":"Weise","lv":"B2","tip":"der Weise = wise man (declines like an adjective); die Weise = way, manner (auf diese Weise).","meanings":[{"gloss":"wise man, sage","art":"der","pl":"Weisen","note":"Declines like an adjective: der Weise, ein Weiser.","ex":[{"de":"Ein {{Weiser}} lächelte nur und schwieg.","en":"A wise man just smiled and kept silent."},{"de":"Die drei {{Weisen}} aus dem Morgenland brachten Geschenke.","en":"The three wise men from the East brought gifts."},{"de":"Der {{Weise}} gab dem jungen Mann einen guten Rat.","en":"The sage gave the young man good advice."}]},{"gloss":"way, manner","art":"die","pl":"Weisen","note":"Mostly in phrases: auf diese Weise, in gewisser Weise.","ex":[{"de":"Auf diese {{Weise}} sparst du viel Zeit.","en":"This way you save a lot of time."},{"de":"Er erklärte es auf einfache {{Weise}}.","en":"He explained it in a simple way."},{"de":"Man kann das Problem auf zwei verschiedene {{Weisen}} lösen.","en":"The problem can be solved in two different ways."}]}]},
 {"id":"mangel","word":"Mangel","lv":"C1","tip":"der Mangel = lack; defect (Pl. Mängel); die Mangel = laundry mangle (jemanden in die Mangel nehmen = give someone a grilling).","meanings":[{"gloss":"lack, shortage; defect, fault","art":"der","pl":"Mängel","note":"Plural Mängel mostly for 'defects'.","ex":[{"de":"In vielen Regionen herrscht ein {{Mangel}} an Ärzten.","en":"In many regions there is a shortage of doctors."},{"de":"Der Gutachter fand mehrere {{Mängel}} am Dach.","en":"The expert found several defects in the roof."},{"de":"Aus {{Mangel}} an Beweisen wurde er freigesprochen.","en":"He was acquitted for lack of evidence."}]},{"gloss":"mangle (laundry press)","art":"die","pl":"Mangeln","note":"Idiom: jemanden in die Mangel nehmen = to grill someone.","ex":[{"de":"Früher glättete man die Bettwäsche in der {{Mangel}}.","en":"In the past people pressed the bed linen in the mangle."},{"de":"Der Kommissar nahm den Zeugen hart in die {{Mangel}}.","en":"The inspector gave the witness a hard grilling."},{"de":"Im Keller steht noch eine alte {{Mangel}} meiner Großmutter.","en":"My grandmother's old mangle is still in the basement."}]}]},
 {"id":"kunde","word":"Kunde","lv":"C1","tip":"der Kunde = customer (weak noun); die Kunde = news, tidings (literary).","meanings":[{"gloss":"customer, client","art":"der","pl":"Kunden","note":"Weak noun: den/dem/des Kunden. Female form: die Kundin.","ex":[{"de":"Der {{Kunde}} beschwerte sich über die lange Wartezeit.","en":"The customer complained about the long wait."},{"de":"Wir haben im letzten Jahr viele neue {{Kunden}} gewonnen.","en":"We won many new customers last year."},{"de":"Die Verkäuferin fragte den {{Kunden}}, ob er Hilfe brauche.","en":"The saleswoman asked the customer whether he needed help."}]},{"gloss":"news, tidings (literary)","art":"die","pl":"","note":"Literary and dated; hardly any plural.","ex":[{"de":"Die {{Kunde}} vom Sieg verbreitete sich schnell im ganzen Land.","en":"The news of the victory spread quickly throughout the country."},{"de":"Der Bote brachte frohe {{Kunde}} aus der Hauptstadt.","en":"The messenger brought glad tidings from the capital."},{"de":"Die traurige {{Kunde}} erreichte uns erst spät am Abend.","en":"The sad news only reached us late in the evening."}]}]},
 {"id":"reis","word":"Reis","lv":"B2","tip":"der Reis = rice; das Reis = twig, sprig (rare, gardening/literary).","meanings":[{"gloss":"rice","art":"der","pl":"","note":"Plural only for varieties: Reissorten.","ex":[{"de":"Zum Fisch gibt es gekochten {{Reis}}.","en":"There is boiled rice with the fish."},{"de":"Ich esse lieber {{Reis}} als Kartoffeln.","en":"I prefer rice to potatoes."},{"de":"In Asien wird auf vielen Feldern {{Reis}} angebaut.","en":"Rice is grown in many fields in Asia."}]},{"gloss":"twig, sprig; scion (for grafting)","art":"das","pl":"Reiser","note":"Rare: gardening and literary language.","ex":[{"de":"Er brach ein dünnes {{Reis}} vom Strauch.","en":"He broke a thin twig off the bush."},{"de":"Gärtner pfropfen ein junges {{Reis}} auf einen alten Baum.","en":"Gardeners graft a young scion onto an old tree."},{"de":"Aus {{Reisern}} flocht sie einen kleinen Korb.","en":"She wove a small basket out of twigs."}]}]},
 {"id":"stift","word":"Stift","lv":"B2","tip":"der Stift = pen, pencil, crayon; das Stift = religious foundation (abbey, monastery or convent).","meanings":[{"gloss":"pen, pencil, crayon","art":"der","pl":"Stifte","ex":[{"de":"Hast du einen {{Stift}}, den ich mir leihen kann?","en":"Do you have a pen I can borrow?"},{"de":"Die Kinder malen mit bunten {{Stiften}}.","en":"The children are drawing with coloured pencils."},{"de":"Ich habe meinen {{Stift}} zu Hause vergessen.","en":"I forgot my pen at home."}]},{"gloss":"religious foundation (abbey, monastery or convent)","art":"das","pl":"Stifte","note":"Rare; mostly in names of abbeys and religious foundations, especially in Austria.","ex":[{"de":"Das {{Stift}} wurde im Mittelalter von Mönchen gegründet.","en":"The abbey was founded by monks in the Middle Ages."},{"de":"Die Bibliothek des {{Stifts}} besitzt wertvolle alte Handschriften.","en":"The abbey's library has valuable old manuscripts."},{"de":"Sie lebte als Stiftsdame in einem adligen {{Stift}}.","en":"She lived as a canoness in a noble convent."}]}]},
 {"id":"schild","word":"Schild","lv":"B1","tip":"der Schild = shield; das Schild = sign (Pl. Schilder). Tip: 'das Schild an der Tür' - neuter for signs.","meanings":[{"gloss":"shield","art":"der","pl":"Schilde","note":"Idiom: etwas im Schilde führen = be up to something.","ex":[{"de":"Der Ritter hob den {{Schild}} zum Schutz vor den Pfeilen.","en":"The knight raised his shield to protect himself from the arrows."},{"de":"Der Ritter trug einen {{Schild}}, auf dem ein goldener Löwe prangte.","en":"The knight carried a shield emblazoned with a golden lion."},{"de":"Die Soldaten trugen große {{Schilde}} aus Holz.","en":"The soldiers carried large wooden shields."}]},{"gloss":"sign, signboard, plate","art":"das","pl":"Schilder","ex":[{"de":"An der Tür hängt ein {{Schild}} mit der Aufschrift „Bitte leise“.","en":"A sign saying 'Please be quiet' hangs on the door."},{"de":"Achte auf die {{Schilder}} am Straßenrand.","en":"Pay attention to the signs at the side of the road."},{"de":"Das {{Schild}} an der Brücke warnt vor Glatteis.","en":"The sign on the bridge warns of black ice."}]}]},
 {"id":"tau","word":"Tau","lv":"B2","tip":"der Tau = dew (no plural); das Tau = thick rope (ship).","meanings":[{"gloss":"dew","art":"der","pl":"","note":"No plural.","ex":[{"de":"Am frühen Morgen glitzert der {{Tau}} auf den Wiesen.","en":"Early in the morning the dew glitters on the meadows."},{"de":"Die Spinnennetze waren voller {{Tau}}.","en":"The spiderwebs were full of dew."},{"de":"Der {{Tau}} hat meine Schuhe durchnässt.","en":"The dew soaked my shoes."}]},{"gloss":"rope, hawser","art":"das","pl":"Taue","note":"Thick rope, especially on ships.","ex":[{"de":"Die Matrosen zogen das {{Tau}} fest an.","en":"The sailors pulled the rope tight."},{"de":"Das Schiff wurde mit einem dicken {{Tau}} am Kai festgemacht.","en":"The ship was moored to the quay with a thick rope."},{"de":"Im Sportunterricht klettern die Kinder an {{Tauen}} bis zur Decke.","en":"In PE class the children climb ropes up to the ceiling."}]}]},
 {"id":"laster","word":"Laster","lv":"B2","tip":"der Laster = lorry, truck (colloquial for Lastwagen); das Laster = vice. Plural of both: Laster.","meanings":[{"gloss":"lorry, truck","art":"der","pl":"Laster","note":"Colloquial short form of 'der Lastwagen'.","ex":[{"de":"Ein {{Laster}} blockiert die ganze Straße.","en":"A lorry is blocking the whole street."},{"de":"Der {{Laster}} hat zwanzig Tonnen Kies geladen.","en":"The truck is carrying twenty tonnes of gravel."},{"de":"Auf der Autobahn überholten uns mehrere {{Laster}}.","en":"Several lorries overtook us on the motorway."}]},{"gloss":"vice, bad habit","art":"das","pl":"Laster","ex":[{"de":"Rauchen war sein einziges {{Laster}}.","en":"Smoking was his only vice."},{"de":"Spielsucht ist ein gefährliches {{Laster}}.","en":"Gambling addiction is a dangerous vice."},{"de":"Früher galt Faulheit als {{Laster}}, heute eher als Luxus.","en":"In the past laziness was considered a vice, today more of a luxury."}]}]},
 {"id":"ekel","word":"Ekel","lv":"C1","tip":"der Ekel = disgust; das Ekel = nasty person, creep (colloquial). 'ein Ekel' looks the same for both.","meanings":[{"gloss":"disgust, revulsion","art":"der","pl":"","note":"No plural.","ex":[{"de":"Beim Anblick des verdorbenen Essens empfand er {{Ekel}}.","en":"At the sight of the spoiled food he felt disgust."},{"de":"Sie verzog das Gesicht vor {{Ekel}}.","en":"She screwed up her face in disgust."},{"de":"Der {{Ekel}} vor Spinnen ist bei vielen Menschen groß.","en":"Many people have a strong revulsion towards spiders."}]},{"gloss":"nasty person, creep (colloquial)","art":"das","pl":"Ekel","note":"Colloquial, derogatory.","ex":[{"de":"Dein Chef ist wirklich ein {{Ekel}}, er brüllt ständig die Mitarbeiter an.","en":"Your boss is really a creep; he is constantly yelling at his staff."},{"de":"Er war ein richtiges {{Ekel}} zu allen Kollegen.","en":"He was really horrible to all his colleagues."},{"de":"Mein Nachbar ist ein {{Ekel}}, er grüßt nie und beschwert sich über alles.","en":"My neighbour is a creep; he never says hello and complains about everything."}]}]},
 {"id":"golf","word":"Golf","lv":"B1","tip":"der Golf = gulf (bay of the sea); das Golf = the sport golf (no plural).","meanings":[{"gloss":"gulf, large bay","art":"der","pl":"Golfe","ex":[{"de":"Der {{Golf}} ist eine weit ins Land reichende Meeresbucht.","en":"A gulf is a bay of the sea reaching far into the land."},{"de":"Mehrere Hafenstädte liegen am {{Golf}}.","en":"Several port towns lie on the gulf."},{"de":"Die Fähre überquert den {{Golf}} in zwei Stunden.","en":"The ferry crosses the gulf in two hours."}]},{"gloss":"golf (sport)","art":"das","pl":"","note":"The sport is usually used without an article: Golf spielen.","ex":[{"de":"Am Wochenende spielt mein Vater {{Golf}}.","en":"On weekends my father plays golf."},{"de":"{{Golf}} ist ein teurer Sport.","en":"Golf is an expensive sport."},{"de":"Auf dem Platz wird jeden Tag {{Golf}} gespielt.","en":"Golf is played on the course every day."}]}]},
 {"id":"wehr","word":"Wehr","lv":"C1","tip":"das Wehr = weir (dam in a river); die Wehr = defence (sich zur Wehr setzen = defend oneself).","meanings":[{"gloss":"weir","art":"das","pl":"Wehre","ex":[{"de":"Das Wasser stürzt über das {{Wehr}} in die Tiefe.","en":"The water plunges over the weir."},{"de":"Am {{Wehr}} wurde eine Fischtreppe gebaut, damit die Lachse flussaufwärts wandern können.","en":"A fish ladder was built at the weir so that the salmon can migrate upstream."},{"de":"Im Fluss wurden mehrere {{Wehre}} gebaut, um den Wasserstand zu regeln.","en":"Several weirs were built in the river to regulate the water level."}]},{"gloss":"defence, resistance","art":"die","pl":"","note":"Almost only in the phrase 'sich zur Wehr setzen'; also in compounds (Feuerwehr, Abwehr).","ex":[{"de":"Das Opfer konnte sich nicht zur {{Wehr}} setzen.","en":"The victim was unable to defend themselves."},{"de":"Die Bürger setzten sich gegen die Schließung des Werks zur {{Wehr}}.","en":"The citizens put up a fight against the closure of the plant."}]}]},
 {"id":"mark","word":"Mark","lv":"B2","tip":"die Mark = the former German currency (D-Mark); das Mark = (bone) marrow, pith.","meanings":[{"gloss":"mark (former German currency)","art":"die","pl":"Mark","note":"After numbers unchanged: zwei Mark.","ex":[{"de":"Bis 2002 bezahlte man in Deutschland mit der {{Mark}}.","en":"Until 2002 people in Germany paid with the mark."},{"de":"Ein Eis kostete damals eine {{Mark}}.","en":"An ice cream cost one mark back then."},{"de":"In der Tasche hatte ich nur ein paar {{Mark}}.","en":"I only had a few marks in my pocket."}]},{"gloss":"marrow, pith","art":"das","pl":"","note":"No plural.","ex":[{"de":"Die Suppe wird mit {{Mark}} aus Rinderknochen gekocht.","en":"The soup is cooked with marrow from beef bones."},{"de":"Der Lärm ging ihm durch {{Mark}} und Bein.","en":"The noise went right through him."},{"de":"Die Nachricht erschütterte ihn bis ins {{Mark}}.","en":"The news shook him to the core."}]}]},
 {"id":"kiwi","word":"Kiwi","lv":"B1","tip":"die Kiwi = the fruit; der Kiwi = the flightless bird. Plural of both: Kiwis.","meanings":[{"gloss":"kiwi (fruit)","art":"die","pl":"Kiwis","ex":[{"de":"Zum Frühstück esse ich eine {{Kiwi}} mit Joghurt.","en":"For breakfast I eat a kiwi with yoghurt."},{"de":"Die {{Kiwis}} auf dem Markt sind noch nicht reif.","en":"The kiwis at the market aren't ripe yet."},{"de":"Schäle die {{Kiwi}} und schneide sie in dünne Scheiben.","en":"Peel the kiwi and cut it into thin slices."}]},{"gloss":"kiwi (bird)","art":"der","pl":"Kiwis","ex":[{"de":"Der {{Kiwi}} ist ein flugunfähiger Vogel aus Neuseeland.","en":"The kiwi is a flightless bird from New Zealand."},{"de":"Im Zoo kann man einen {{Kiwi}} im Nachttierhaus beobachten.","en":"At the zoo you can watch a kiwi in the nocturnal house."},{"de":"Die {{Kiwis}} sind nachtaktiv und legen riesige Eier.","en":"Kiwis are nocturnal and lay huge eggs."}]}]},
 {"id":"gang","word":"Gang","lv":"B1","tip":"der Gang = corridor, gear, course of a meal (Pl. Gänge); die Gang = street gang (Pl. Gangs).","meanings":[{"gloss":"corridor, aisle","art":"der","pl":"Gänge","ex":[{"de":"Die Büros liegen alle an einem langen {{Gang}}.","en":"The offices are all along a long corridor."},{"de":"Bitte bleiben Sie nicht im {{Gang}} stehen.","en":"Please do not stand in the aisle."},{"de":"Im Flugzeug saß ich am {{Gang}}.","en":"On the plane I sat on the aisle."}]},{"gloss":"gear (of a vehicle)","art":"der","pl":"Gänge","ex":[{"de":"Schalte vor der Kurve in den zweiten {{Gang}} zurück.","en":"Shift down into second gear before the bend."},{"de":"Mein Fahrrad hat sieben {{Gänge}}.","en":"My bicycle has seven gears."}]},{"gloss":"course (of a meal)","art":"der","pl":"Gänge","ex":[{"de":"Als ersten {{Gang}} gab es eine Gemüsesuppe.","en":"The first course was a vegetable soup."},{"de":"Das Menü bestand aus fünf {{Gängen}}.","en":"The menu consisted of five courses."}]},{"gloss":"gang (street gang)","art":"die","pl":"Gangs","note":"Pronounced like English 'gang'.","ex":[{"de":"Die {{Gang}} kontrollierte das ganze Viertel.","en":"The gang controlled the whole neighbourhood."},{"de":"Als Jugendlicher geriet er in eine kriminelle {{Gang}}.","en":"As a teenager he got involved with a criminal gang."},{"de":"Die rivalisierenden {{Gangs}} bekämpften sich auf offener Straße.","en":"The rival gangs fought each other in the open street."}]}]},
 {"id":"rock","word":"Rock","lv":"A2","tip":"der Rock = skirt (Pl. Röcke); der Rock = rock music (no plural).","meanings":[{"gloss":"skirt","art":"der","pl":"Röcke","ex":[{"de":"Sie trägt zum Pullover einen kurzen {{Rock}}.","en":"She wears a short skirt with her sweater."},{"de":"Im Schrank hängen drei {{Röcke}}.","en":"Three skirts hang in the wardrobe."},{"de":"Der {{Rock}} ist mir zu eng geworden.","en":"The skirt has become too tight for me."}]},{"gloss":"rock (music)","art":"der","pl":"","note":"No plural.","ex":[{"de":"Mein Vater hört am liebsten {{Rock}} aus den Siebzigern.","en":"My father likes listening to rock from the seventies best."},{"de":"Auf dem Festival gibt es Pop, Jazz und {{Rock}}.","en":"At the festival there is pop, jazz and rock."},{"de":"Seine Band spielt harten {{Rock}} und ist ziemlich laut.","en":"His band plays hard rock and is quite loud."}]}]},
 {"id":"zoll","word":"Zoll","lv":"B1","tip":"der Zoll = customs (Pl. Zölle); der Zoll = inch (Pl. unchanged: zwei Zoll).","meanings":[{"gloss":"customs; customs duty","art":"der","pl":"Zölle","ex":[{"de":"Am {{Zoll}} mussten wir unsere Koffer öffnen.","en":"At customs we had to open our suitcases."},{"de":"Auf diese Waren muss man hohen {{Zoll}} zahlen.","en":"You have to pay high duty on these goods."},{"de":"Die Regierung erhöhte die {{Zölle}} auf Stahl.","en":"The government raised the duties on steel."}]},{"gloss":"inch","art":"der","pl":"Zoll","note":"After numbers: zwei Zoll, fünfzig Zoll.","ex":[{"de":"Mein Fernseher hat einen Bildschirm von fünfzig {{Zoll}}.","en":"My TV has a fifty-inch screen."},{"de":"Ein {{Zoll}} entspricht 2,54 Zentimetern.","en":"One inch equals 2.54 centimetres."},{"de":"Das Rohr hat einen Durchmesser von zwei {{Zoll}}.","en":"The pipe has a diameter of two inches."}]}]},
 {"id":"rat","word":"Rat","lv":"B2","tip":"der Rat = advice (Pl. Ratschläge); der Rat = council, board (Pl. Räte).","meanings":[{"gloss":"advice","art":"der","pl":"Ratschläge","note":"Plural supplied by a different word: Ratschläge (not 'Räte', which belongs to the council sense).","ex":[{"de":"Ich brauche deinen {{Rat}}, bevor ich mich entscheide.","en":"I need your advice before I decide."},{"de":"Er hat auf den {{Rat}} seines Arztes hin mit dem Rauchen aufgehört.","en":"On his doctor's advice he stopped smoking."},{"de":"Sie holte sich {{Rat}} bei ihrer Anwältin.","en":"She sought advice from her lawyer."}]},{"gloss":"council, board","art":"der","pl":"Räte","note":"Also the person: ein Rat (councillor), e.g. Stadtrat, Betriebsrat.","ex":[{"de":"Der {{Rat}} der Gemeinde beschloss den Bau einer neuen Schule.","en":"The municipal council decided to build a new school."},{"de":"Der {{Rat}} tagt jeden zweiten Dienstag im Rathaus.","en":"The council meets every second Tuesday in the town hall."},{"de":"In vielen Betrieben vertreten gewählte {{Räte}} die Beschäftigten.","en":"In many companies elected councils represent the employees."}]}]},
 {"id":"strauss","word":"Strauß","lv":"B1","tip":"der Strauß = bouquet (Pl. Sträuße); der Strauß = ostrich (Pl. Strauße).","meanings":[{"gloss":"bouquet, bunch of flowers","art":"der","pl":"Sträuße","ex":[{"de":"Er brachte ihr einen {{Strauß}} roter Rosen mit.","en":"He brought her a bouquet of red roses."},{"de":"Auf dem Tisch stehen zwei {{Sträuße}} mit Tulpen.","en":"Two bouquets of tulips stand on the table."},{"de":"Sie band einen bunten {{Strauß}} aus Feldblumen.","en":"She tied a colourful bunch of wildflowers."}]},{"gloss":"ostrich","art":"der","pl":"Strauße","ex":[{"de":"Der {{Strauß}} ist der größte Vogel der Welt.","en":"The ostrich is the largest bird in the world."},{"de":"Im Zoo rannten zwei {{Strauße}} durch das Gehege.","en":"At the zoo two ostriches ran across the enclosure."},{"de":"Ein {{Strauß}} kann nicht fliegen, aber sehr schnell laufen.","en":"An ostrich cannot fly but can run very fast."}]}]},
 {"id":"verband","word":"Verband","lv":"B2","tip":"der Verband = bandage; also association, federation. Plural of both: Verbände.","meanings":[{"gloss":"bandage, dressing","art":"der","pl":"Verbände","ex":[{"de":"Die Ärztin legte mir einen {{Verband}} am Knöchel an.","en":"The doctor put a bandage on my ankle."},{"de":"Der {{Verband}} muss täglich gewechselt werden.","en":"The dressing must be changed daily."},{"de":"Die Krankenschwester wickelte einen frischen {{Verband}} um die Hand.","en":"The nurse wrapped a fresh bandage round the hand."}]},{"gloss":"association, federation","art":"der","pl":"Verbände","ex":[{"de":"Der {{Verband}} der Arbeitgeber fordert niedrigere Steuern.","en":"The employers' federation demands lower taxes."},{"de":"Sie arbeitet für einen {{Verband}} der Landwirte.","en":"She works for an association of farmers."},{"de":"Die {{Verbände}} protestierten gegen das neue Gesetz.","en":"The associations protested against the new law."}]}]},
 {"id":"hahn","word":"Hahn","lv":"B1","tip":"der Hahn = rooster; also tap, faucet. Plural of both: Hähne.","meanings":[{"gloss":"rooster, cock","art":"der","pl":"Hähne","ex":[{"de":"Der {{Hahn}} kräht jeden Morgen um fünf Uhr.","en":"The rooster crows every morning at five."},{"de":"Auf dem Bauernhof leben Hühner und ein stolzer {{Hahn}}.","en":"Chickens and a proud rooster live on the farm."},{"de":"Die beiden {{Hähne}} streiten sich im Hof.","en":"The two roosters are fighting in the yard."}]},{"gloss":"tap, faucet, valve","art":"der","pl":"Hähne","ex":[{"de":"Dreh bitte den {{Hahn}} zu, das Wasser läuft noch.","en":"Please turn off the tap, the water is still running."},{"de":"Der {{Hahn}} in der Küche tropft schon seit Tagen.","en":"The tap in the kitchen has been dripping for days."},{"de":"Im Bad gibt es zwei {{Hähne}}, einen für warmes und einen für kaltes Wasser.","en":"In the bathroom there are two taps, one for hot and one for cold water."}]}]},
 {"id":"moment","word":"Moment","lv":"C1","tip":"der Moment = moment; das Moment = factor, element (physics: torque).","meanings":[{"gloss":"moment","art":"der","pl":"Momente","ex":[{"de":"Einen {{Moment}}, ich bin gleich bei Ihnen.","en":"One moment, I'll be right with you."},{"de":"Im letzten {{Moment}} erreichte er den Zug noch.","en":"He caught the train at the last moment."},{"de":"Im Urlaub gab es viele wunderschöne {{Momente}}.","en":"On vacation there were many wonderful moments."}]},{"gloss":"factor, element, aspect","art":"das","pl":"Momente","note":"Formal; also physics: das Moment = torque (Drehmoment).","ex":[{"de":"Ein wichtiges {{Moment}} bei der Entscheidung war der Preis.","en":"An important factor in the decision was the price."},{"de":"Das Urteil berücksichtigt auch alle entlastenden {{Momente}}.","en":"The verdict also takes into account all factors in the defendant's favour."},{"de":"In seiner Rede steckt ein politisches {{Moment}}.","en":"There is a political element in his speech."}]}]},
 {"id":"acht","word":"Acht","lv":"B2","tip":"die Acht = the number eight (Pl. Achten); die Acht = attention, care (Acht geben, außer Acht lassen).","meanings":[{"gloss":"the number eight; (bus/tram) line 8","art":"die","pl":"Achten","ex":[{"de":"Sie kritzelte lauter {{Achten}} auf den Zettel.","en":"She doodled lots of eights on the piece of paper."},{"de":"Der Eiskunstläufer zeichnete eine perfekte {{Acht}} aufs Eis.","en":"The figure skater drew a perfect figure of eight on the ice."},{"de":"Nehmen Sie die {{Acht}}, sie fährt direkt zum Bahnhof.","en":"Take the number 8, it goes straight to the station."}]},{"gloss":"attention, care, heed","art":"die","pl":"","note":"Only in set phrases: Acht geben, sich in Acht nehmen, außer Acht lassen.","ex":[{"de":"Gib {{Acht}} auf deine kleine Schwester!","en":"Look after your little sister!"},{"de":"Er ließ die Warnung einfach außer {{Acht}}.","en":"He simply ignored the warning."},{"de":"Nimm dich vor dem Hund in {{Acht}}!","en":"Beware of the dog!"}]}]},
 {"id":"otter","word":"Otter","lv":"C1","tip":"der Otter = the semi-aquatic mammal (Fischotter); die Otter = venomous snake, adder (Kreuzotter).","meanings":[{"gloss":"otter","art":"der","pl":"Otter","ex":[{"de":"Der {{Otter}} schwimmt geschickt im Fluss und fängt Fische.","en":"The otter swims skilfully in the river and catches fish."},{"de":"Am Ufer haben wir einen {{Otter}} gesehen.","en":"We saw an otter on the bank."},{"de":"In den Flüssen leben wieder mehr {{Otter}}.","en":"More otters are living in the rivers again."}]},{"gloss":"adder, viper","art":"die","pl":"Ottern","ex":[{"de":"Eine {{Otter}} hat den Hund ins Bein gebissen, deshalb musste er zum Tierarzt.","en":"An adder bit the dog's leg and it had to go to the vet."},{"de":"Vorsicht, in dieser Gegend gibt es giftige {{Ottern}}.","en":"Be careful, there are venomous adders in this area."},{"de":"Die {{Otter}} lag regungslos im Gras und sonnte sich.","en":"The adder lay motionless in the grass, sunning itself."}]}]},
 {"id":"mutter","word":"Mutter","lv":"A2","tip":"die Mutter = mother (Pl. Mütter); die Mutter = nut (for a bolt) (Pl. Muttern).","meanings":[{"gloss":"mother","art":"die","pl":"Mütter","ex":[{"de":"Meine {{Mutter}} arbeitet als Lehrerin.","en":"My mother works as a teacher."},{"de":"Die {{Mütter}} warten vor der Schule auf ihre Kinder.","en":"The mothers are waiting outside the school for their children."},{"de":"Er hat seiner {{Mutter}} Blumen geschenkt.","en":"He gave his mother flowers."}]},{"gloss":"nut (for a screw or bolt)","art":"die","pl":"Muttern","ex":[{"de":"Zieh die {{Mutter}} mit dem Schraubenschlüssel fest.","en":"Tighten the nut with the wrench."},{"de":"Die Schraube braucht eine passende {{Mutter}}.","en":"The screw needs a matching nut."},{"de":"Im Werkzeugkasten liegen Schrauben und {{Muttern}} in allen Größen.","en":"In the toolbox there are screws and nuts in all sizes."}]}]},
 {"id":"gefallen","word":"Gefallen","lv":"B2","tip":"der Gefallen = favour (einen Gefallen tun); das Gefallen = pleasure, liking (Gefallen finden an).","meanings":[{"gloss":"favour","art":"der","pl":"Gefallen","ex":[{"de":"Kannst du mir einen {{Gefallen}} tun und die Post holen?","en":"Could you do me a favour and pick up the mail?"},{"de":"Ich schulde dir noch einen {{Gefallen}}.","en":"I still owe you a favour."},{"de":"Sie haben uns schon viele {{Gefallen}} erwiesen.","en":"They have done us many favours already."}]},{"gloss":"pleasure, liking","art":"das","pl":"","note":"No plural. Phrases: Gefallen finden an + Dat., nach Gefallen.","ex":[{"de":"Er fand großes {{Gefallen}} an klassischer Musik.","en":"He took great pleasure in classical music."},{"de":"Sie können die Stücke ganz nach {{Gefallen}} auswählen.","en":"You can choose the pieces entirely as you please."},{"de":"Das Angebot fand bei allen Kollegen {{Gefallen}}.","en":"The offer met with approval among all the colleagues."}]}]},
 {"id":"bank","word":"Bank","lv":"A2","tip":"Same article, different plural: Bänke (benches) vs. Banken (banks).","meanings":[{"gloss":"bench","art":"die","pl":"Bänke","ex":[{"de":"Wir sitzen gern auf der {{Bank}} im Park.","en":"We like sitting on the bench in the park."},{"de":"Der Hund liegt unter der {{Bank}} und schläft.","en":"The dog is lying under the bench, sleeping."},{"de":"Im Park stehen viele {{Bänke}} zum Ausruhen.","en":"There are many benches in the park to rest on."}]},{"gloss":"bank (financial institution)","art":"die","pl":"Banken","ex":[{"de":"Ich muss noch zur {{Bank}}, um Geld abzuheben.","en":"I still have to go to the bank to withdraw money."},{"de":"Die {{Banken}} schließen heute schon um 16 Uhr.","en":"The banks close as early as 4 pm today."},{"de":"Meine {{Bank}} verlangt hohe Gebühren für das Konto.","en":"My bank charges high fees for the account."}]}]},
 {"id":"schloss","word":"Schloss","lv":"A2","tip":"Both meanings are das Schloss, plural Schlösser: a lock opens with a key, a castle has towers.","meanings":[{"gloss":"lock","art":"das","pl":"Schlösser","ex":[{"de":"Der Schlüssel passt nicht in das {{Schloss}}.","en":"The key doesn't fit into the lock."},{"de":"Wir müssen das {{Schloss}} an der Haustür austauschen lassen.","en":"We have to have the lock on the front door replaced."},{"de":"Die {{Schlösser}} an den alten Kellertüren klemmen und lassen sich kaum noch öffnen.","en":"The locks on the old cellar doors stick and can hardly be opened any more."}]},{"gloss":"castle, palace","art":"das","pl":"Schlösser","ex":[{"de":"Das {{Schloss}} liegt auf einem Hügel und ist für Besucher geöffnet.","en":"The castle stands on a hill and is open to visitors."},{"de":"Der König ließ sich ein prächtiges {{Schloss}} bauen.","en":"The king had a magnificent palace built for himself."},{"de":"An der Loire stehen viele berühmte {{Schlösser}}.","en":"Many famous castles stand on the Loire."}]}]},
 {"id":"birne","word":"Birne","lv":"A2","tip":"Birne = pear (fruit) and light bulb (it has the same shape).","meanings":[{"gloss":"pear","art":"die","pl":"Birnen","ex":[{"de":"Ich esse zum Frühstück eine saftige {{Birne}}.","en":"I eat a juicy pear for breakfast."},{"de":"Auf dem Baum hängen reife {{Birnen}}.","en":"Ripe pears are hanging on the tree."}]},{"gloss":"light bulb","art":"die","pl":"Birnen","ex":[{"de":"Die {{Birne}} im Flur ist durchgebrannt, deshalb ist es dunkel.","en":"The bulb in the hallway has blown, so it is dark."},{"de":"Hast du noch eine {{Birne}} für die Stehlampe?","en":"Do you have another bulb for the floor lamp?"},{"de":"Beim Wechseln der {{Birne}} sollte man das Licht ausschalten.","en":"When changing the bulb you should switch off the light."}]}]},
 {"id":"ball","word":"Ball","lv":"B1","tip":"Der Ball: round object (sport) vs. formal dance. Both plural Bälle; the context decides (mit dem Ball spielen vs. auf einen Ball gehen).","meanings":[{"gloss":"ball","art":"der","pl":"Bälle","ex":[{"de":"Die Kinder spielen mit einem {{Ball}} im Garten.","en":"The children are playing with a ball in the garden."},{"de":"Der Torwart hat den {{Ball}} sicher gehalten.","en":"The goalkeeper held the ball safely."},{"de":"Wirf mir bitte die {{Bälle}} zu!","en":"Please throw the balls to me!"}]},{"gloss":"ball, formal dance","art":"der","pl":"Bälle","ex":[{"de":"Auf dem {{Ball}} trugen alle Damen lange Kleider.","en":"At the ball all the ladies wore long dresses."},{"de":"Im Rathaus findet jedes Jahr ein festlicher {{Ball}} mit Walzermusik statt.","en":"Every year a festive ball with waltz music takes place in the town hall."},{"de":"Zu den großen {{Bällen}} in Wien kommen jedes Jahr Tausende Gäste.","en":"Thousands of guests come to the big balls in Vienna every year."}]}]},
 {"id":"absatz","word":"Absatz","lv":"B1","tip":"Absatz: heel of a shoe and paragraph of text (Absätze for both).","meanings":[{"gloss":"heel (of a shoe)","art":"der","pl":"Absätze","ex":[{"de":"Der {{Absatz}} meines linken Schuhs ist abgebrochen.","en":"The heel of my left shoe has broken off."},{"de":"Sie trägt gern Schuhe mit hohem {{Absatz}}.","en":"She likes wearing shoes with high heels."},{"de":"Der Schuster hat die {{Absätze}} meiner Stiefel erneuert.","en":"The cobbler has renewed the heels of my boots."}]},{"gloss":"paragraph","art":"der","pl":"Absätze","ex":[{"de":"Bitte lies den zweiten {{Absatz}} des Textes laut vor.","en":"Please read the second paragraph of the text aloud."},{"de":"Nach jedem {{Absatz}} soll eine Leerzeile stehen.","en":"There should be a blank line after every paragraph."},{"de":"Der Vertrag enthält mehrere Artikel mit jeweils drei {{Absätzen}}.","en":"The contract contains several articles with three paragraphs each."}]}]},
 {"id":"feder","word":"Feder","lv":"B1","tip":"Feder = feather (bird) and spring (metal, in a sofa or mattress). Plural Federn for both.","meanings":[{"gloss":"feather","art":"die","pl":"Federn","ex":[{"de":"Auf dem Boden liegt eine weiße {{Feder}}.","en":"There is a white feather lying on the floor."},{"de":"Das Kissen ist mit {{Federn}} gefüllt.","en":"The pillow is filled with feathers."}]},{"gloss":"spring (metal)","art":"die","pl":"Federn","ex":[{"de":"In der alten Matratze ist eine {{Feder}} gebrochen.","en":"A spring has broken in the old mattress."},{"de":"Die {{Federn}} im Sofa quietschen, wenn man sich setzt.","en":"The springs in the sofa squeak when you sit down."},{"de":"Der Uhrmacher hat die gebrochene {{Feder}} im Werk ersetzt.","en":"The watchmaker replaced the broken spring in the movement."}]}]},
 {"id":"schlange","word":"Schlange","lv":"B1","tip":"Schlange = snake and queue (a long line of people). Idiom: Schlange stehen = to queue.","meanings":[{"gloss":"snake","art":"die","pl":"Schlangen","ex":[{"de":"Im Terrarium lebt eine giftige {{Schlange}}.","en":"A poisonous snake lives in the terrarium."},{"de":"Vor {{Schlangen}} habe ich große Angst.","en":"I am very afraid of snakes."}]},{"gloss":"queue, line of people","art":"die","pl":"Schlangen","ex":[{"de":"An der Kasse stand eine lange {{Schlange}}.","en":"There was a long queue at the checkout."},{"de":"Wir mussten eine Stunde in der {{Schlange}} warten, bevor wir ins Museum durften.","en":"We had to wait in the queue for an hour before we were allowed into the museum."},{"de":"Vor dem Konzert bildeten sich vor allen Eingängen lange {{Schlangen}}.","en":"Before the concert, long queues formed at all the entrances."}]}]},
 {"id":"karte","word":"Karte","lv":"A2","tip":"Karte covers map, ticket and playing card. Plural Karten for all; the context decides.","meanings":[{"gloss":"map","art":"die","pl":"Karten","ex":[{"de":"Zeig mir auf der {{Karte}}, wo wir gerade sind.","en":"Show me on the map where we are right now."},{"de":"Ohne {{Karte}} finden wir den Wanderweg nicht.","en":"Without a map we won't find the hiking trail."}]},{"gloss":"ticket","art":"die","pl":"Karten","ex":[{"de":"Ich habe zwei {{Karten}} für das Konzert gekauft.","en":"I have bought two tickets for the concert."},{"de":"Die {{Karten}} für das Theater waren schnell ausverkauft.","en":"The tickets for the theatre sold out quickly."}]},{"gloss":"playing card","art":"die","pl":"Karten","ex":[{"de":"Beim Skat bekommt jeder Spieler zehn {{Karten}}.","en":"In Skat every player gets ten cards."},{"de":"Er legte die letzte {{Karte}} auf den Tisch und gewann das Spiel.","en":"He put the last card on the table and won the game."}]}]},
 {"id":"blatt","word":"Blatt","lv":"A2","tip":"Blatt = leaf (plant) and sheet of paper. Plural Blätter for both.","meanings":[{"gloss":"leaf","art":"das","pl":"Blätter","ex":[{"de":"Im Herbst fallen die {{Blätter}} von den Bäumen.","en":"In autumn the leaves fall from the trees."},{"de":"Vom Ahorn segelte ein rotes {{Blatt}} langsam zu Boden.","en":"A red leaf drifted slowly down to the ground from the maple."}]},{"gloss":"sheet of paper","art":"das","pl":"Blätter","ex":[{"de":"Gib mir bitte ein leeres {{Blatt}} Papier.","en":"Please give me a blank sheet of paper."},{"de":"Schreib deinen Namen oben auf das {{Blatt}}.","en":"Write your name at the top of the sheet."},{"de":"Die Lehrerin verteilte {{Blätter}} mit Übungsaufgaben.","en":"The teacher handed out sheets with practice exercises."}]}]},
 {"id":"pass","word":"Pass","lv":"B1","tip":"Der Pass, Pl. Pässe: mountain pass, passport, or a pass in ball sports.","meanings":[{"gloss":"mountain pass","art":"der","pl":"Pässe","ex":[{"de":"Im Winter ist der {{Pass}} wegen Schnee gesperrt.","en":"In winter the pass is closed because of snow."},{"de":"Wir fuhren über einen hohen {{Pass}} in den Alpen.","en":"We drove over a high pass in the Alps."}]},{"gloss":"passport","art":"der","pl":"Pässe","ex":[{"de":"Ich habe meinen {{Pass}} zu Hause vergessen.","en":"I have forgotten my passport at home."},{"de":"Beim Grenzübertritt müssen alle ihre {{Pässe}} vorzeigen.","en":"When crossing the border everybody has to show their passports."}]},{"gloss":"pass (in ball sports)","art":"der","pl":"Pässe","ex":[{"de":"Der Stürmer erhielt einen genauen {{Pass}} und schoss ein Tor.","en":"The striker received a precise pass and scored a goal."},{"de":"Nach einem langen {{Pass}} stand er allein vor dem Torwart.","en":"After a long pass he stood alone in front of the goalkeeper."}]}]},
 {"id":"fluegel","word":"Flügel","lv":"B1","tip":"Flügel (no change in the plural): wing of a bird or plane vs. grand piano.","meanings":[{"gloss":"wing","art":"der","pl":"Flügel","ex":[{"de":"Der Vogel breitete seine {{Flügel}} aus und flog davon.","en":"The bird spread its wings and flew away."},{"de":"Dem Schmetterling fehlt ein {{Flügel}}.","en":"The butterfly is missing a wing."}]},{"gloss":"grand piano","art":"der","pl":"Flügel","ex":[{"de":"Im Konzertsaal steht ein schwarzer {{Flügel}}.","en":"A black grand piano stands in the concert hall."},{"de":"Sie setzte sich an den {{Flügel}} und begann zu spielen.","en":"She sat down at the grand piano and began to play."},{"de":"Der Klavierstimmer hat den {{Flügel}} gestern gestimmt.","en":"The piano tuner tuned the grand piano yesterday."}]}]},
 {"id":"laeufer","word":"Läufer","lv":"B2","tip":"Läufer = runner (person), long narrow rug, and chess bishop. No change in the plural.","meanings":[{"gloss":"runner","art":"der","pl":"Läufer","ex":[{"de":"Der {{Läufer}} erreichte nach drei Stunden das Ziel.","en":"The runner reached the finish after three hours."},{"de":"Beim Marathon starteten über 2000 {{Läufer}}.","en":"Over 2,000 runners started in the marathon."}]},{"gloss":"runner rug (long narrow carpet)","art":"der","pl":"Läufer","ex":[{"de":"Im Flur liegt ein langer, roter {{Läufer}}.","en":"A long red runner lies in the hallway."},{"de":"Auf der Treppe haben wir einen {{Läufer}} befestigt.","en":"We have fixed a runner on the stairs."}]},{"gloss":"bishop (chess)","art":"der","pl":"Läufer","ex":[{"de":"Beim Schach darf der {{Läufer}} nur diagonal ziehen.","en":"In chess the bishop may only move diagonally."},{"de":"Mit dem {{Läufer}} habe ich ihre Dame geschlagen.","en":"I captured her queen with the bishop."}]}]},
 {"id":"schein","word":"Schein","lv":"B2","tip":"Der Schein: a banknote (Pl. Scheine) or a glow of light (plural rare).","meanings":[{"gloss":"banknote","art":"der","pl":"Scheine","ex":[{"de":"Können Sie mir diesen {{Schein}} in Münzen wechseln?","en":"Can you change this note into coins for me?"},{"de":"Ich habe nur große {{Scheine}} im Portemonnaie und keine Münzen.","en":"I only have large notes in my wallet and no coins."}]},{"gloss":"glow, shine (of light)","art":"der","pl":"","note":"Plural rare in this meaning.","ex":[{"de":"Im {{Schein}} der Kerze las sie noch ein Kapitel.","en":"By the glow of the candle she read another chapter."},{"de":"Der {{Schein}} der Straßenlaterne fiel ins Zimmer.","en":"The glow of the street lamp fell into the room."}]}]},
 {"id":"note","word":"Note","lv":"B1","tip":"Note: school grade or musical note. Plural Noten for both.","meanings":[{"gloss":"grade, mark (school)","art":"die","pl":"Noten","ex":[{"de":"Für den Aufsatz hat sie die {{Note}} 1 bekommen.","en":"She got a grade of 1 for the essay."},{"de":"Seine {{Noten}} sind im letzten Halbjahr deutlich besser geworden.","en":"His grades have improved a lot in the last half-year."}]},{"gloss":"musical note","art":"die","pl":"Noten","ex":[{"de":"Die Sängerin traf jede {{Note}} genau.","en":"The singer hit every note exactly."},{"de":"Eine ganze {{Note}} ist viermal so lang wie eine Viertelnote.","en":"A whole note is four times as long as a quarter note."}]}]},
 {"id":"zelle","word":"Zelle","lv":"B1","tip":"Zelle: prison cell vs. biological cell. Plural Zellen for both.","meanings":[{"gloss":"(prison) cell","art":"die","pl":"Zellen","ex":[{"de":"Der Gefangene verbringt die Nacht in einer engen {{Zelle}}.","en":"The prisoner spends the night in a cramped cell."},{"de":"Die {{Zellen}} im alten Gefängnis sind kaum drei Quadratmeter groß.","en":"The cells in the old prison are barely three square metres."}]},{"gloss":"(biological) cell","art":"die","pl":"Zellen","ex":[{"de":"Der menschliche Körper besteht aus Billionen von {{Zellen}}.","en":"The human body consists of trillions of cells."},{"de":"Tumoren entstehen, wenn sich eine {{Zelle}} unkontrolliert teilt.","en":"Tumours arise when a cell divides uncontrollably."}]}]},
 {"id":"decke","word":"Decke","lv":"A2","tip":"Decke = blanket (on the bed) and ceiling (of a room). Plural Decken.","meanings":[{"gloss":"blanket","art":"die","pl":"Decken","ex":[{"de":"Im Winter schlafe ich unter einer dicken {{Decke}}.","en":"In winter I sleep under a thick blanket."},{"de":"Bring bitte eine {{Decke}} für das Picknick mit.","en":"Please bring a blanket for the picnic."}]},{"gloss":"ceiling","art":"die","pl":"Decken","ex":[{"de":"An der {{Decke}} hängt eine alte Lampe.","en":"An old lamp hangs from the ceiling."},{"de":"Die {{Decke}} im Altbau ist über drei Meter hoch.","en":"The ceiling in the old building is over three metres high."},{"de":"Eine Spinne läuft an der {{Decke}} entlang.","en":"A spider is crawling along the ceiling."}]}]},
 {"id":"fliege","word":"Fliege","lv":"B1","tip":"Fliege = fly (insect) and bow tie.","meanings":[{"gloss":"fly (insect)","art":"die","pl":"Fliegen","ex":[{"de":"Eine {{Fliege}} summt um den Kuchen.","en":"A fly is buzzing around the cake."},{"de":"Im Sommer sind überall {{Fliegen}} in der Küche.","en":"In summer there are flies everywhere in the kitchen."}]},{"gloss":"bow tie","art":"die","pl":"Fliegen","ex":[{"de":"Zum Smoking trägt er eine schwarze {{Fliege}}.","en":"With the tuxedo he wears a black bow tie."},{"de":"Der Kellner trug statt einer Krawatte eine rote {{Fliege}}.","en":"Instead of a tie the waiter wore a red bow tie."}]}]},
 {"id":"mine","word":"Mine","lv":"B2","tip":"Mine: mining site, refill (pen, pencil lead) or explosive device. Plural Minen for all.","meanings":[{"gloss":"mine (mining)","art":"die","pl":"Minen","ex":[{"de":"In dieser {{Mine}} wurde früher Silber abgebaut.","en":"Silver used to be mined in this mine."},{"de":"Die {{Mine}} wurde 1990 stillgelegt.","en":"The mine was shut down in 1990."}]},{"gloss":"refill, lead (pen, pencil)","art":"die","pl":"Minen","ex":[{"de":"Mein Kugelschreiber braucht eine neue {{Mine}}.","en":"My ballpoint pen needs a new refill."},{"de":"Ich habe vergessen, {{Minen}} für den Druckbleistift zu kaufen.","en":"I forgot to buy leads for the mechanical pencil."}]},{"gloss":"(land) mine, explosive","art":"die","pl":"Minen","ex":[{"de":"Der Panzer fuhr auf eine {{Mine}}.","en":"The tank ran over a mine."},{"de":"Nach dem Krieg wurden viele {{Minen}} auf den Feldern geräumt.","en":"After the war, many mines were cleared from the fields."}]}]},
 {"id":"messe","word":"Messe","lv":"B1","tip":"Messe = church service (Catholic mass) vs. trade fair. Plural Messen for both.","meanings":[{"gloss":"mass (church service)","art":"die","pl":"Messen","ex":[{"de":"Am Sonntag gehen wir zur {{Messe}} in die Kirche.","en":"On Sunday we go to mass at church."},{"de":"Der Pfarrer feiert heute Abend die {{Messe}}.","en":"The priest is celebrating mass this evening."}]},{"gloss":"trade fair","art":"die","pl":"Messen","ex":[{"de":"Auf der {{Messe}} in Frankfurt stellen viele Firmen neue Produkte vor.","en":"At the trade fair in Frankfurt many companies present new products."},{"de":"Wir haben einen Stand auf der {{Messe}} gebucht.","en":"We have booked a stand at the trade fair."},{"de":"Die {{Messen}} in Leipzig ziehen jedes Jahr Tausende Besucher an.","en":"The trade fairs in Leipzig attract thousands of visitors every year."}]}]},
 {"id":"maus","word":"Maus","lv":"A2","tip":"Maus = mouse (animal) and computer mouse. Plural Mäuse for both.","meanings":[{"gloss":"mouse (animal)","art":"die","pl":"Mäuse","ex":[{"de":"Die Katze hat eine {{Maus}} gefangen.","en":"The cat has caught a mouse."},{"de":"Im Keller leben {{Mäuse}}, deshalb stellen wir Fallen auf.","en":"Mice live in the cellar, so we are setting traps."}]},{"gloss":"(computer) mouse","art":"die","pl":"Mäuse","ex":[{"de":"Die {{Maus}} funktioniert nicht, der Zeiger bewegt sich nicht.","en":"The mouse doesn't work, the pointer doesn't move."},{"de":"Ich arbeite lieber mit einer {{Maus}} als mit dem Touchpad.","en":"I prefer working with a mouse to using the touchpad."}]}]},
 {"id":"gericht","word":"Gericht","lv":"B1","tip":"Das Gericht, Pl. Gerichte: a dish of food or a court of law.","meanings":[{"gloss":"dish (food)","art":"das","pl":"Gerichte","ex":[{"de":"Das {{Gericht}} besteht aus Reis und frischem Gemüse.","en":"The dish consists of rice and fresh vegetables."},{"de":"Im Restaurant gibt es täglich drei verschiedene {{Gerichte}}.","en":"The restaurant offers three different dishes every day."}]},{"gloss":"court (of law)","art":"das","pl":"Gerichte","ex":[{"de":"Der Fall kommt nächste Woche vor {{Gericht}}.","en":"The case goes to court next week."},{"de":"Das {{Gericht}} hat den Angeklagten freigesprochen.","en":"The court acquitted the defendant."},{"de":"Die {{Gerichte}} sind wegen der Feiertage geschlossen.","en":"The courts are closed because of the holidays."}]}]},
 {"id":"tafel","word":"Tafel","lv":"B2","tip":"Tafel: blackboard, bar of chocolate, or (formal) a festive dinner table. Plural Tafeln.","meanings":[{"gloss":"blackboard","art":"die","pl":"Tafeln","ex":[{"de":"Der Lehrer schreibt das Datum an die {{Tafel}}.","en":"The teacher writes the date on the blackboard."},{"de":"Wisch bitte die {{Tafel}} sauber!","en":"Please wipe the board clean!"}]},{"gloss":"bar (of chocolate)","art":"die","pl":"Tafeln","note":"Used with Schokolade.","ex":[{"de":"Zum Nachtisch gab es eine {{Tafel}} Schokolade.","en":"For dessert there was a bar of chocolate."},{"de":"Im Supermarkt kostet eine {{Tafel}} Vollmilchschokolade nur 79 Cent.","en":"In the supermarket a bar of milk chocolate costs only 79 cents."}]},{"gloss":"festive dining table","art":"die","pl":"Tafeln","note":"Elevated style.","ex":[{"de":"Die Gäste nahmen an der festlich gedeckten {{Tafel}} Platz.","en":"The guests took their seats at the festively laid table."},{"de":"Der Gastgeber hob das Glas und bat die ganze {{Tafel}} um Ruhe.","en":"The host raised his glass and asked the whole table for silence."}]}]},
 {"id":"zug","word":"Zug","lv":"B2","tip":"Der Zug, Pl. Züge: train, draught of air (plural rare), move in a game, puff/gulp.","meanings":[{"gloss":"train","art":"der","pl":"Züge","ex":[{"de":"Der {{Zug}} nach München fährt von Gleis 5 ab.","en":"The train to Munich departs from platform 5."},{"de":"Wir haben den letzten {{Zug}} verpasst.","en":"We missed the last train."},{"de":"Die {{Züge}} haben heute wegen des Sturms Verspätung.","en":"The trains are delayed today because of the storm."}]},{"gloss":"draught (of air)","art":"der","pl":"","ex":[{"de":"Das Fenster ist undicht, deshalb spürt man im Zimmer immer einen kalten {{Zug}}.","en":"The window leaks, so you always feel a cold draught in the room."},{"de":"Wegen des {{Zuges}} im Büro trägt sie immer einen Schal.","en":"Because of the draught in the office she always wears a scarf."}],"note":"Plural rare in this meaning."},{"gloss":"move (in a game)","art":"der","pl":"Züge","ex":[{"de":"Mit einem klugen {{Zug}} gewann er die Schachpartie.","en":"He won the chess game with a clever move."},{"de":"Jetzt bist du am {{Zug}}, ich habe schon gespielt.","en":"Now it's your move, I have already played."}]},{"gloss":"puff, gulp","art":"der","pl":"Züge","ex":[{"de":"Der Raucher nahm noch einen {{Zug}}, dann drückte er die Zigarette aus.","en":"The smoker took one more puff, then stubbed out the cigarette."},{"de":"Er trank das Glas in einem {{Zug}} leer.","en":"He emptied the glass in one gulp."}]}]},
 {"id":"kamm","word":"Kamm","lv":"B2","tip":"Der Kamm, Pl. Kämme: hair comb vs. mountain ridge.","meanings":[{"gloss":"comb","art":"der","pl":"Kämme","ex":[{"de":"Ich habe meinen {{Kamm}} im Bad vergessen.","en":"I have left my comb in the bathroom."},{"de":"Mit einem feinen {{Kamm}} kann man Läuse aus den Haaren entfernen.","en":"With a fine comb you can remove lice from the hair."}]},{"gloss":"ridge (of mountains)","art":"der","pl":"Kämme","ex":[{"de":"Der Wanderweg führt über den {{Kamm}} des Gebirges.","en":"The hiking trail leads along the ridge of the mountain range."},{"de":"Auf dem {{Kamm}} bläst ein kalter Wind.","en":"A cold wind blows on the ridge."}]}]},
 {"id":"schale","word":"Schale","lv":"B1","tip":"Schale = peel/shell (outer cover) and bowl. Plural Schalen for both.","meanings":[{"gloss":"peel, shell","art":"die","pl":"Schalen","ex":[{"de":"Die {{Schale}} der Banane ist schon ganz braun.","en":"The banana peel is already completely brown."},{"de":"Die Kartoffeln koche ich mit der {{Schale}}.","en":"I cook the potatoes with their skins on."},{"de":"Die {{Schale}} der Nuss ist sehr hart.","en":"The shell of the nut is very hard."}]},{"gloss":"bowl","art":"die","pl":"Schalen","ex":[{"de":"Stell die {{Schale}} mit dem Obst auf den Tisch.","en":"Put the bowl of fruit on the table."},{"de":"Auf dem Tisch stehen zwei {{Schalen}} mit Nüssen.","en":"There are two bowls of nuts on the table."}]}]},
 {"id":"kapelle","word":"Kapelle","lv":"B2","tip":"Kapelle: small church (chapel) vs. a (brass) band. Plural Kapellen.","meanings":[{"gloss":"chapel","art":"die","pl":"Kapellen","ex":[{"de":"Die kleine {{Kapelle}} im Wald wurde im 17. Jahrhundert gebaut.","en":"The little chapel in the forest was built in the 17th century."},{"de":"In der {{Kapelle}} fand eine stille Trauerfeier statt.","en":"A quiet memorial service took place in the chapel."}]},{"gloss":"(brass) band","art":"die","pl":"Kapellen","ex":[{"de":"Die {{Kapelle}} spielte beim Dorffest bayerische Volksmusik.","en":"The band played Bavarian folk music at the village fair."},{"de":"Auf dem Marktplatz spielt eine {{Kapelle}} Blasmusik.","en":"A band is playing brass music on the market square."}]}]},
 {"id":"platte","word":"Platte","lv":"B2","tip":"Platte: vinyl record, cooker hob (Herdplatte) or a serving platter. Plural Platten.","meanings":[{"gloss":"(vinyl) record","art":"die","pl":"Platten","ex":[{"de":"Opa hat noch alte {{Platten}} und einen Plattenspieler.","en":"Grandpa still has old records and a record player."},{"de":"Auf dem Flohmarkt habe ich eine seltene {{Platte}} der Beatles gefunden.","en":"At the flea market I found a rare Beatles record."}]},{"gloss":"hotplate, hob","art":"die","pl":"Platten","ex":[{"de":"Auf dem Herd ist die hintere {{Platte}} noch heiß, pass auf!","en":"On the cooker the back hotplate is still hot, be careful!"},{"de":"Bei diesem Herd lässt sich jede {{Platte}} einzeln einstellen.","en":"With this cooker each hotplate can be set individually."}]},{"gloss":"platter","art":"die","pl":"Platten","ex":[{"de":"Zum Abendessen gab es eine kalte {{Platte}} mit Wurst, Käse und Brot.","en":"For dinner there was a cold platter with sausage, cheese and bread."},{"de":"Die Kellnerin trug eine große {{Platte}} mit gebratenem Fleisch an den Tisch.","en":"The waitress carried a large platter of roast meat to the table."}]}]},
 {"id":"schalter","word":"Schalter","lv":"B1","tip":"Schalter (no change in the plural): an electric switch or a service counter (post office, bank, station).","meanings":[{"gloss":"(light) switch","art":"der","pl":"Schalter","ex":[{"de":"Wo ist der {{Schalter}} für das Licht?","en":"Where is the switch for the light?"},{"de":"Drück den roten {{Schalter}}, dann geht die Maschine an.","en":"Press the red switch and the machine starts."}]},{"gloss":"counter (in a post office, bank, station)","art":"der","pl":"Schalter","ex":[{"de":"Briefmarken bekommen Sie am {{Schalter}} drei.","en":"You can get stamps at counter three."},{"de":"Der {{Schalter}} der Bank ist nur vormittags geöffnet.","en":"The counter at the bank is only open in the morning."}]}]},
 {"id":"ton","word":"Ton","lv":"B1","tip":"Der Ton: sound/tone (Pl. Töne) vs. clay (material, no common plural).","meanings":[{"gloss":"sound, tone","art":"der","pl":"Töne","ex":[{"de":"Das Handy gab einen hohen {{Ton}} von sich.","en":"The phone gave out a high tone."},{"de":"Der Film hat keinen {{Ton}}, ich höre nichts.","en":"The film has no sound, I can't hear anything."}]},{"gloss":"clay","art":"der","pl":"","note":"No common plural in this meaning.","ex":[{"de":"Aus {{Ton}} kann man Vasen und Schalen töpfern.","en":"You can make vases and bowls out of clay."},{"de":"Die Kinder formen im Kunstunterricht Tiere aus nassem {{Ton}}.","en":"In art class the children form animals out of wet clay."}]}]},
 {"id":"spitze","word":"Spitze","lv":"B2","tip":"Spitze = tip/point and lace (fabric). Plural Spitzen.","meanings":[{"gloss":"tip, point","art":"die","pl":"Spitzen","ex":[{"de":"Die {{Spitze}} des Bleistifts ist abgebrochen.","en":"The tip of the pencil has broken off."},{"de":"Vorsicht, die {{Spitze}} der Nadel ist sehr scharf!","en":"Careful, the point of the needle is very sharp!"}]},{"gloss":"lace (fabric)","art":"die","pl":"Spitzen","ex":[{"de":"Das Hochzeitskleid ist mit feiner {{Spitze}} besetzt.","en":"The wedding dress is trimmed with fine lace."},{"de":"Die Tischdecke besteht aus weißer {{Spitze}}.","en":"The tablecloth is made of white lace."}]}]},
 {"id":"mandel","word":"Mandel","lv":"B1","tip":"Mandel = almond (nut) and tonsil (in the throat). Plural Mandeln for both.","meanings":[{"gloss":"almond","art":"die","pl":"Mandeln","ex":[{"de":"Für den Kuchen brauchst du hundert Gramm gemahlene {{Mandeln}}.","en":"For the cake you need a hundred grams of ground almonds."},{"de":"Im Müsli sind Rosinen und gehackte {{Mandeln}}.","en":"The muesli contains raisins and chopped almonds."}]},{"gloss":"tonsil","art":"die","pl":"Mandeln","ex":[{"de":"Der Arzt sagte, dass seine {{Mandeln}} stark entzündet sind.","en":"The doctor said that his tonsils are badly inflamed."},{"de":"Ihr wurden mit fünf Jahren die {{Mandeln}} entfernt.","en":"Her tonsils were removed when she was five."}]}]},
 {"id":"bremse","word":"Bremse","lv":"B1","tip":"Bremse = brake and horsefly. Plural Bremsen.","meanings":[{"gloss":"brake","art":"die","pl":"Bremsen","ex":[{"de":"Die {{Bremse}} am Fahrrad quietscht laut.","en":"The brake on the bike squeaks loudly."},{"de":"Tritt rechtzeitig auf die {{Bremse}}!","en":"Step on the brake in time!"}]},{"gloss":"horsefly","art":"die","pl":"Bremsen","ex":[{"de":"Eine {{Bremse}} hat das Pferd gestochen.","en":"A horsefly has stung the horse."},{"de":"Auf der Koppel plagen im Sommer viele {{Bremsen}} die Pferde.","en":"In summer many horseflies pester the horses in the paddock."}]}]},
 {"id":"weide","word":"Weide","lv":"B2","tip":"Weide = willow (tree) and pasture (meadow for grazing). Plural Weiden.","meanings":[{"gloss":"willow","art":"die","pl":"Weiden","ex":[{"de":"Am Ufer des Flusses wachsen alte {{Weiden}}.","en":"Old willows grow on the bank of the river."},{"de":"Die {{Weide}} lässt ihre langen Zweige bis ins Wasser hängen.","en":"The willow lets its long branches hang down into the water."}]},{"gloss":"pasture","art":"die","pl":"Weiden","ex":[{"de":"Die Kühe stehen den ganzen Sommer auf der {{Weide}}.","en":"The cows stay on the pasture all summer."},{"de":"Der Bauer treibt die Schafe auf die {{Weide}}.","en":"The farmer drives the sheep onto the pasture."}]}]},
 {"id":"fassung","word":"Fassung","lv":"B2","tip":"Fassung: version, socket (for a bulb) and composure (die Fassung verlieren).","meanings":[{"gloss":"version","art":"die","pl":"Fassungen","ex":[{"de":"Den Film gibt es auch in einer ungekürzten {{Fassung}}.","en":"The film is also available in an uncut version."},{"de":"Die deutsche {{Fassung}} des Films kam erst ein Jahr später in die Kinos.","en":"The German version of the film only came out in cinemas a year later."}]},{"gloss":"socket (for a bulb)","art":"die","pl":"Fassungen","ex":[{"de":"Die {{Fassung}} der Lampe ist locker, die Birne wackelt.","en":"The socket of the lamp is loose, the bulb wobbles."},{"de":"Er schraubte die Glühbirne in die {{Fassung}}.","en":"He screwed the light bulb into the socket."}]},{"gloss":"composure","art":"die","pl":"","note":"No plural in this meaning.","ex":[{"de":"Trotz der schlechten Nachricht verlor er nicht die {{Fassung}}.","en":"Despite the bad news he did not lose his composure."},{"de":"Sie konnte nur mit Mühe die {{Fassung}} bewahren.","en":"She could only just keep her composure."}]}]},
 {"id":"dichtung","word":"Dichtung","lv":"C1","tip":"Dichtung = poetry/literary fiction and seal (gasket). Plural Dichtungen.","meanings":[{"gloss":"poetry, literary writing","art":"die","pl":"Dichtungen","ex":[{"de":"Die {{Dichtung}} der Romantik ist voller Sehnsucht nach der Natur.","en":"The poetry of Romanticism is full of longing for nature."},{"de":"Er hat sein Leben der {{Dichtung}} gewidmet.","en":"He devoted his life to poetry."}]},{"gloss":"seal, gasket","art":"die","pl":"Dichtungen","ex":[{"de":"Der Wasserhahn tropft, weil die {{Dichtung}} kaputt ist.","en":"The tap is dripping because the gasket is broken."},{"de":"Der Installateur hat die {{Dichtung}} am Rohr ersetzt.","en":"The plumber replaced the seal on the pipe."}]}]},
 {"id":"lehre","word":"Lehre","lv":"B2","tip":"Lehre: apprenticeship, doctrine/teaching, or a lesson learned (eine Lehre ziehen). Plural Lehren.","meanings":[{"gloss":"apprenticeship","art":"die","pl":"Lehren","ex":[{"de":"Nach der Schule machte er eine {{Lehre}} als Tischler.","en":"After school he did an apprenticeship as a carpenter."},{"de":"Während der {{Lehre}} verdient man nur wenig.","en":"During an apprenticeship you earn only little."}]},{"gloss":"doctrine, teaching","art":"die","pl":"Lehren","ex":[{"de":"Die christliche {{Lehre}} spielt für ihn eine große Rolle.","en":"Christian doctrine plays a big role for him."},{"de":"Die marxistische {{Lehre}} hat viele politische Bewegungen beeinflusst.","en":"Marxist doctrine has influenced many political movements."}]},{"gloss":"lesson (moral, from experience)","art":"die","pl":"Lehren","ex":[{"de":"Aus dem Fehler müssen wir eine {{Lehre}} ziehen.","en":"We have to learn a lesson from the mistake."},{"de":"Das soll dir eine {{Lehre}} sein!","en":"Let that be a lesson to you!"}]}]},
 {"id":"linse","word":"Linse","lv":"B2","tip":"Linse = lens (optics) and lentil (legume). Plural Linsen.","meanings":[{"gloss":"lens","art":"die","pl":"Linsen","ex":[{"de":"Die {{Linse}} meiner Kamera ist zerkratzt.","en":"The lens of my camera is scratched."},{"de":"Er trägt seit Jahren weiche {{Linsen}} statt einer Brille.","en":"For years he has been wearing soft contact lenses instead of glasses."}]},{"gloss":"lentil","art":"die","pl":"Linsen","ex":[{"de":"Zum Mittag gibt es Eintopf mit {{Linsen}}.","en":"For lunch there is stew with lentils."},{"de":"Die {{Linsen}} müssen etwa zwanzig Minuten kochen.","en":"The lentils have to cook for about twenty minutes."}]}]},
 {"id":"pflaster","word":"Pflaster","lv":"B2","tip":"Das Pflaster (no change in plural): sticking plaster or paved road surface.","meanings":[{"gloss":"sticking plaster, band-aid","art":"das","pl":"Pflaster","ex":[{"de":"Auf die kleine Wunde klebt man ein {{Pflaster}}.","en":"You put a plaster on the small wound."},{"de":"Hast du ein {{Pflaster}} für mich? Ich habe mich geschnitten.","en":"Do you have a plaster for me? I've cut myself."}]},{"gloss":"paving, cobblestones","art":"das","pl":"Pflaster","ex":[{"de":"Das {{Pflaster}} glänzte nass im Regen.","en":"The cobbles gleamed wet in the rain."},{"de":"Die Stadt lässt das {{Pflaster}} der Fußgängerzone erneuern.","en":"The city is having the paving of the pedestrian zone renewed."}]}]},
 {"id":"schimmel","word":"Schimmel","lv":"B2","tip":"Der Schimmel: mould (no plural) vs. white horse (Pl. Schimmel).","meanings":[{"gloss":"mould","art":"der","pl":"","note":"no plural in this meaning","ex":[{"de":"Im Badezimmer wächst {{Schimmel}} an der Wand.","en":"Mould is growing on the bathroom wall."},{"de":"Wegen des {{Schimmels}} in der Wohnung musste die Familie ausziehen.","en":"Because of the mould in the flat the family had to move out."}]},{"gloss":"white horse","art":"der","pl":"Schimmel","ex":[{"de":"Die Prinzessin ritt auf einem {{Schimmel}} durch den Wald.","en":"The princess rode through the forest on a white horse."},{"de":"Auf der Koppel stehen ein Rappe und zwei {{Schimmel}}.","en":"A black horse and two white horses are standing in the paddock."}]}]},
 {"id":"bock","word":"Bock","lv":"B2","tip":"Der Bock, Pl. Böcke: male goat, or a four-legged stand (trestle; the vaulting buck in gymnastics).","meanings":[{"gloss":"billy goat, buck","art":"der","pl":"Böcke","ex":[{"de":"Der {{Bock}} stieß mit seinen Hörnern gegen das Gatter.","en":"The billy goat butted the gate with his horns."},{"de":"Auf der Alm leben Ziegen und ein alter {{Bock}}.","en":"Goats and an old billy goat live on the alpine pasture."}]},{"gloss":"trestle, sawhorse; vaulting buck (gymnastics)","art":"der","pl":"Böcke","ex":[{"de":"Der Tischler legte das Brett auf zwei {{Böcke}}.","en":"The carpenter laid the board on two trestles."},{"de":"Im Sportunterricht springen wir über den {{Bock}}.","en":"In PE we jump over the vaulting buck."},{"de":"Sie sprang mit Anlauf über den {{Bock}} und landete sicher.","en":"She jumped over the buck after a run-up and landed safely."}]}]},
 {"id":"kater","word":"Kater","lv":"B2","tip":"Der Kater: tomcat (Pl. Kater) vs. hangover (no plural).","meanings":[{"gloss":"tomcat","art":"der","pl":"Kater","ex":[{"de":"Unser {{Kater}} schläft den ganzen Tag auf dem Sofa.","en":"Our tomcat sleeps on the sofa all day."},{"de":"Der {{Kater}} war die ganze Nacht draußen unterwegs.","en":"The tomcat was out and about all night."}]},{"gloss":"hangover","art":"der","pl":"","note":"no plural in this meaning","ex":[{"de":"Nach der Feier hatte er einen schrecklichen {{Kater}}.","en":"After the party he had a terrible hangover."},{"de":"Gegen den {{Kater}} helfen Wasser und ein kräftiges Frühstück.","en":"Water and a hearty breakfast help against a hangover."}]}]},
 {"id":"stollen","word":"Stollen","lv":"C1","tip":"Der Stollen (no change in plural): mine tunnel, German Christmas fruit loaf, or stud on a football boot.","meanings":[{"gloss":"tunnel (in a mine)","art":"der","pl":"Stollen","ex":[{"de":"Die Bergleute fuhren in den dunklen {{Stollen}} ein.","en":"The miners went down into the dark tunnel."},{"de":"Der {{Stollen}} wurde nach dem Unglück gesperrt.","en":"The tunnel was closed after the accident."}]},{"gloss":"Stollen (Christmas fruit loaf)","art":"der","pl":"Stollen","ex":[{"de":"Zu Weihnachten backt meine Oma einen {{Stollen}} mit Rosinen.","en":"At Christmas my grandma bakes a Stollen with raisins."},{"de":"In Dresden kann man auf dem Markt den berühmten {{Stollen}} kaufen.","en":"In Dresden you can buy the famous Stollen at the market."}]},{"gloss":"stud (on a football boot)","art":"der","pl":"Stollen","ex":[{"de":"Die {{Stollen}} an den Fußballschuhen waren völlig abgelaufen.","en":"The studs on the football boots were completely worn down."},{"de":"Bei nassem Rasen braucht man Schuhe mit langen {{Stollen}}.","en":"On wet grass you need boots with long studs."}]}]},
 {"id":"angel","word":"Angel","lv":"C1","tip":"Die Angel, Pl. Angeln: fishing rod or door hinge (aus den Angeln heben).","meanings":[{"gloss":"fishing rod","art":"die","pl":"Angeln","ex":[{"de":"Er sitzt am Fluss und hält die {{Angel}} ins Wasser.","en":"He is sitting by the river holding his fishing rod in the water."},{"de":"Zum Geburtstag wünscht er sich eine neue {{Angel}}.","en":"For his birthday he wants a new fishing rod."}]},{"gloss":"(door) hinge","art":"die","pl":"Angeln","ex":[{"de":"Die Tür quietscht, weil die {{Angel}} nicht geölt ist.","en":"The door squeaks because the hinge isn't oiled."},{"de":"Der Sturm hat das Tor aus den {{Angeln}} gehoben.","en":"The storm lifted the gate off its hinges."}]}]},
 {"id":"einstellen","word":"einstellen","lv":"B2","tip":"einstellen (separable: stellt ... ein) has three main unrelated uses: hire people, adjust a device, stop something. The object tells you which: Mitarbeiter / Heizung / Produktion.","meanings":[{"gloss":"to hire, employ","art":null,"pl":null,"note":"separable: ein|stellen","ex":[{"de":"Die Firma will im Herbst drei neue Mitarbeiter {{einstellen}}.","en":"The company wants to hire three new employees in autumn."},{"de":"Wir haben gestern eine Verkäuferin {{eingestellt}}.","en":"We hired a saleswoman yesterday."}]},{"gloss":"to adjust, set (a device)","art":null,"pl":null,"note":"separable: ein|stellen","ex":[{"de":"Kannst du die Heizung etwas wärmer {{einstellen}}?","en":"Can you set the heating a bit warmer?"},{"de":"Der Mechaniker hat die Bremsen neu {{eingestellt}}.","en":"The mechanic has readjusted the brakes."}]},{"gloss":"to stop, discontinue","art":null,"pl":null,"note":"separable: ein|stellen","ex":[{"de":"Die Fabrik musste die Produktion {{einstellen}}.","en":"The factory had to stop production."},{"de":"Die Staatsanwaltschaft hat das Verfahren {{eingestellt}}.","en":"The public prosecutor's office has discontinued the proceedings."}]}]},
 {"id":"absetzen","word":"absetzen","lv":"B2","tip":"absetzen (separable) = drop off / remove from office / deduct from tax. Passengers, a minister and costs make the meaning clear.","meanings":[{"gloss":"to drop off (a passenger)","art":null,"pl":null,"note":"separable: ab|setzen","ex":[{"de":"Kannst du mich bitte vor dem Bahnhof {{absetzen}}?","en":"Can you drop me off in front of the station, please?"},{"de":"Der Fahrer hat die Kinder direkt vor der Schule {{abgesetzt}}.","en":"The driver dropped the children off right in front of the school."}]},{"gloss":"to remove from office, depose","art":null,"pl":null,"note":"separable: ab|setzen","ex":[{"de":"Das Parlament konnte den Präsidenten nicht {{absetzen}}.","en":"Parliament was unable to remove the president from office."},{"de":"Nach dem Putsch wurde der Minister {{abgesetzt}}.","en":"After the coup the minister was deposed."}]},{"gloss":"to deduct (from tax)","art":null,"pl":null,"note":"separable: ab|setzen","ex":[{"de":"Die Kosten für das Arbeitszimmer kann man von der Steuer {{absetzen}}.","en":"The costs of the home office can be deducted from tax."},{"de":"Ich habe die Fahrtkosten in meiner Steuererklärung {{abgesetzt}}.","en":"I deducted the travel costs in my tax return."}]}]},
 {"id":"aufheben","word":"aufheben","lv":"B2","tip":"aufheben (separable) = pick up / keep / abolish. A coin on the floor is picked up, a receipt is kept, a law is abolished.","meanings":[{"gloss":"to pick up (from the floor)","art":null,"pl":null,"note":"separable: auf|heben","ex":[{"de":"Er bückte sich, um das Portemonnaie {{aufzuheben}}.","en":"He bent down to pick up the wallet."},{"de":"Das Kind hat die Münze vom Boden {{aufgehoben}}.","en":"The child picked the coin up from the floor."}]},{"gloss":"to keep, save (for later)","art":null,"pl":null,"note":"separable: auf|heben","ex":[{"de":"Den Kassenbon sollte man ein Jahr lang {{aufheben}}.","en":"You should keep the receipt for a year."},{"de":"Meine Oma hat alle Briefe von früher {{aufgehoben}}.","en":"My grandma has kept all the letters from the past."}]},{"gloss":"to abolish, lift, repeal","art":null,"pl":null,"note":"separable: auf|heben","ex":[{"de":"Das Parlament will das Gesetz wieder {{aufheben}}.","en":"Parliament wants to repeal the law again."},{"de":"Die Sperrung der Straße wurde gestern {{aufgehoben}}.","en":"The closure of the road was lifted yesterday."}]}]},
 {"id":"umfahren","word":"umfahren","lv":"B2","tip":"Same spelling, different stress and prefix type: UMfahren (separable, perfect umgefahren) = knock down; umFAHren (inseparable, perfect umfahren) = drive around.","meanings":[{"gloss":"to knock down, run over","art":null,"pl":null,"note":"stress on um-, separable: um|fahren (fährt ... um, umgefahren)","ex":[{"de":"Der Lkw hat beim Rangieren einen Pfosten {{umgefahren}}.","en":"The truck knocked over a post while manoeuvring."},{"de":"Der Zaun wurde von einem Auto {{umgefahren}}.","en":"The fence was knocked down by a car."}]},{"gloss":"to drive around, bypass","art":null,"pl":null,"note":"stress on -fahr-, inseparable: umfahren (umfährt, umfahren)","ex":[{"de":"Wir wollen die Baustelle auf der Autobahn großräumig {{umfahren}}.","en":"We want to take a wide detour around the roadworks on the motorway."},{"de":"Der Bus {{umfährt}} die Innenstadt auf einer Ringstraße.","en":"The bus goes around the city centre on a ring road."},{"de":"Die Fahrer haben den Stau über Landstraßen {{umfahren}}.","en":"The drivers bypassed the traffic jam via country roads."}]}]},
 {"id":"uebersetzen","word":"übersetzen","lv":"B2","tip":"übersetzen: inseparable (überSETzen, übersetzt) = translate; separable (ÜBERsetzen, übergesetzt) = ferry across. Fähre and Ufer point to the second meaning.","meanings":[{"gloss":"to translate","art":null,"pl":null,"note":"stress on -set-, inseparable: übersetzen (übersetzt)","ex":[{"de":"Kannst du mir diesen Brief ins Deutsche {{übersetzen}}?","en":"Can you translate this letter into German for me?"},{"de":"Sie hat den Roman aus dem Russischen {{übersetzt}}.","en":"She translated the novel from Russian."}]},{"gloss":"to ferry across (a river)","art":null,"pl":null,"note":"stress on über-, separable: über|setzen (übergesetzt)","ex":[{"de":"Der Fährmann musste die Touristen ans andere Ufer {{übersetzen}}.","en":"The ferryman had to take the tourists across to the other bank."},{"de":"Wir wurden mit einem kleinen Boot ans andere Ufer {{übergesetzt}}.","en":"We were ferried across to the other bank in a small boat."}]}]},
 {"id":"uebertreten","word":"übertreten","lv":"C1","tip":"übertreten: inseparable (übertritt, übertreten) = violate a law; separable (tritt ... über, übergetreten) = switch sides, convert.","meanings":[{"gloss":"to violate, break (a law)","art":null,"pl":null,"note":"inseparable: übertreten (übertritt, übertreten)","ex":[{"de":"Wer dieses Gesetz {{übertritt}}, muss mit einer Strafe rechnen.","en":"Anyone who breaks this law must expect a penalty."},{"de":"Der Spieler hat die Regeln mehrfach {{übertreten}}.","en":"The player has violated the rules several times."}]},{"gloss":"to switch sides, convert, join","art":null,"pl":null,"note":"separable: über|treten (übergetreten)","ex":[{"de":"Sie ist vor zehn Jahren zum katholischen Glauben {{übergetreten}}.","en":"Ten years ago she converted to Catholicism."},{"de":"Er ist letztes Jahr zu einer anderen Partei {{übergetreten}}.","en":"Last year he switched to another party."}]}]},
 {"id":"umgehen","word":"umgehen","lv":"B2","tip":"umgehen: inseparable (umGEHen) = bypass, circumvent; separable (UMgehen, mit ... umgehen) = deal with someone/something.","meanings":[{"gloss":"to bypass, circumvent","art":null,"pl":null,"note":"stress on -geh-, inseparable: umgehen (umgeht, umgangen)","ex":[{"de":"Das Verbot lässt sich leicht {{umgehen}}, wenn man eine Lücke im Gesetz kennt.","en":"The ban is easy to get around if you know a loophole in the law."},{"de":"Die neue Straße {{umgeht}} das Dorf und entlastet die Anwohner.","en":"The new road bypasses the village and relieves the residents."}]},{"gloss":"to deal with, handle (mit ... umgehen)","art":null,"pl":null,"note":"stress on um-, separable; in this meaning with mit: um|gehen (ist umgegangen)","ex":[{"de":"Sie kann sehr gut mit Kindern {{umgehen}}.","en":"She is very good with children."},{"de":"Man muss lernen, mit Kritik {{umzugehen}}.","en":"You have to learn to deal with criticism."}]}]},
 {"id":"unterstellen","word":"unterstellen","lv":"C1","tip":"unterstellen: inseparable (unterSTELLen) = insinuate, imply; separable (UNterstellen) = store somewhere / (sich) shelter.","meanings":[{"gloss":"to insinuate, imply (something negative)","art":null,"pl":null,"note":"inseparable: unterstellen (unterstellt)","ex":[{"de":"Du kannst mir nicht einfach böse Absichten {{unterstellen}}!","en":"You can't just insinuate that I have bad intentions!"},{"de":"Er {{unterstellte}} ihr, dass sie gelogen habe.","en":"He insinuated that she had lied."}]},{"gloss":"to store, put under cover; to shelter","art":null,"pl":null,"note":"separable: unter|stellen (untergestellt)","ex":[{"de":"Wir können dein Sofa vorübergehend bei uns im Keller {{unterstellen}}.","en":"We can store your sofa in our cellar for the time being."},{"de":"Während des Gewitters haben wir uns unter dem Vordach {{untergestellt}}.","en":"During the thunderstorm we took shelter under the canopy."}]}]},
 {"id":"ueberlegen","word":"überlegen","lv":"B2","tip":"überlegen: verb (inseparable) = to think over; adjective = superior. Verb: Ich überlege. Adjective with an ending: ein überlegenes Lächeln.","meanings":[{"gloss":"to think over, consider (verb)","art":null,"pl":null,"note":"verb, inseparable: überlegen (überlegt)","ex":[{"de":"Ich muss noch ein paar Tage {{überlegen}}, ob ich das Angebot annehme.","en":"I still have to think for a few days about whether I'll accept the offer."},{"de":"Hast du dir schon {{überlegt}}, was du ihm schenkst?","en":"Have you thought about what to give him?"}]},{"gloss":"superior (adjective)","art":null,"pl":null,"note":"adjective: überlegen, überlegene ...","ex":[{"de":"Das Team war dem Gegner klar {{überlegen}}.","en":"The team was clearly superior to its opponent."},{"de":"Mit einem {{überlegenen}} Lächeln ging er an uns vorbei.","en":"With a superior smile he walked past us."}]}]},
 {"id":"schaffen","word":"schaffen","lv":"B2","tip":"schaffen has two verbs: strong schaffen (schuf, hat geschaffen) = create; weak schaffen (schaffte, hat geschafft) = manage, achieve. The past forms differ.","meanings":[{"gloss":"to create","art":null,"pl":null,"note":"strong verb: schaffen, schuf, geschaffen","ex":[{"de":"Der Bildhauer {{schuf}} die Statue im Jahr 1912.","en":"The sculptor created the statue in 1912."},{"de":"Die Regierung hat neue Arbeitsplätze {{geschaffen}}.","en":"The government has created new jobs."}]},{"gloss":"to manage, succeed in","art":null,"pl":null,"note":"weak verb: schaffen, schaffte, geschafft","ex":[{"de":"Sie {{schaffte}} die Prüfung mit Bestnote.","en":"She passed the exam with top marks."},{"de":"Wir haben es {{geschafft}}: Wir sind rechtzeitig angekommen!","en":"We've made it: we arrived on time!"}]}]},
 {"id":"wiegen","word":"wiegen","lv":"B2","tip":"wiegen has two verbs: strong wiegen (wog, gewogen) = weigh; weak wiegen (wiegte, gewiegt) = rock gently.","meanings":[{"gloss":"to weigh (have a weight)","art":null,"pl":null,"note":"strong verb: wiegen, wog, gewogen","ex":[{"de":"Das Baby {{wog}} bei der Geburt drei Kilo.","en":"The baby weighed three kilos at birth."},{"de":"Wie viel {{wiegt}} dein Koffer?","en":"How much does your suitcase weigh?"}]},{"gloss":"to rock (gently)","art":null,"pl":null,"note":"weak verb: wiegen, wiegte, gewiegt","ex":[{"de":"Die Mutter {{wiegte}} das Kind sanft in den Schlaf.","en":"The mother rocked the child gently to sleep."},{"de":"Er hat das Baby im Arm lange {{gewiegt}}.","en":"He rocked the baby in his arms for a long time."}]}]},
 {"id":"bewegen","word":"bewegen","lv":"C1","tip":"bewegen has two verbs: weak bewegen (bewegte, bewegt) = move; strong bewegen (bewog, bewogen) = induce someone to do something (usually with dazu).","meanings":[{"gloss":"to move","art":null,"pl":null,"note":"weak verb: bewegen, bewegte, bewegt","ex":[{"de":"Der Wind {{bewegte}} die Äste leicht hin und her.","en":"The wind moved the branches gently back and forth."},{"de":"Der Patient kann seinen Arm kaum noch {{bewegen}}.","en":"The patient can hardly move his arm any more."}]},{"gloss":"to induce, prompt (someone to do something)","art":null,"pl":null,"note":"strong verb: bewegen, bewog, bewogen; usually with dazu","ex":[{"de":"Was hat dich nur dazu {{bewogen}}, den Job zu kündigen?","en":"What on earth prompted you to quit the job?"},{"de":"Ihr Vorschlag {{bewog}} ihn schließlich zum Einlenken.","en":"Her suggestion finally induced him to give in."}]}]},
 {"id":"schleifen","word":"schleifen","lv":"C1","tip":"schleifen has two verbs: strong schleifen (schliff, geschliffen) = sharpen, grind; weak schleifen (schleifte, geschleift) = drag along the ground.","meanings":[{"gloss":"to sharpen, grind, polish","art":null,"pl":null,"note":"strong verb: schleifen, schliff, geschliffen","ex":[{"de":"Der Koch {{schliff}} die Messer vor dem Fest.","en":"The cook sharpened the knives before the feast."},{"de":"Das Messer muss mal wieder {{geschliffen}} werden.","en":"The knife needs sharpening again."}]},{"gloss":"to drag (along the ground)","art":null,"pl":null,"note":"weak verb: schleifen, schleifte, geschleift","ex":[{"de":"Er {{schleifte}} den schweren Sack über den Hof.","en":"He dragged the heavy sack across the yard."},{"de":"Die Kinder haben den schweren Schlitten durch den Schnee {{geschleift}}.","en":"The children dragged the heavy sledge through the snow."}]}]},
 {"id":"treffen","word":"treffen","lv":"B1","tip":"treffen = to meet (people) or to hit (a target). Look at the subject and context: people meeting each other (im Café, am Bahnhof) = meet; a projectile or blow (Pfeil, Stein; am Kopf, in die Mitte) = hit.","meanings":[{"gloss":"to meet","art":null,"pl":null,"ex":[{"de":"Ich {{treffe}} morgen meine Freundin im Café.","en":"I'm meeting my girlfriend in the café tomorrow."},{"de":"Gestern haben wir uns zufällig am Bahnhof {{getroffen}}.","en":"Yesterday we met by chance at the station."}]},{"gloss":"to hit (a target)","art":null,"pl":null,"ex":[{"de":"Der Pfeil {{traf}} genau in die Mitte der Scheibe.","en":"The arrow hit the exact centre of the target."},{"de":"Der Stein hat ihn am Kopf {{getroffen}}.","en":"The stone hit him on the head."}]}]},
 {"id":"anlegen","word":"anlegen","lv":"B2","tip":"anlegen (separable: legt ... an) = invest money, dock (ship), lay out (garden, park). Geld, Kai and Park/Teich give the meaning away.","meanings":[{"gloss":"to invest (money)","art":null,"pl":null,"note":"separable: an|legen","ex":[{"de":"Sie will ihr Geld langfristig in Aktien {{anlegen}}.","en":"She wants to invest her money in shares for the long term."},{"de":"Ich habe meine Ersparnisse sicher {{angelegt}}.","en":"I have invested my savings safely."}]},{"gloss":"to dock, moor (a ship)","art":null,"pl":null,"note":"separable: an|legen","ex":[{"de":"Das Fährschiff hat pünktlich am Kai {{angelegt}}.","en":"The ferry docked at the quay on time."},{"de":"Hier dürfen nur kleine Boote {{anlegen}}.","en":"Only small boats may dock here."}]},{"gloss":"to lay out, create (a garden, park)","art":null,"pl":null,"note":"separable: an|legen","ex":[{"de":"Hinter dem Haus haben wir einen kleinen Teich {{angelegt}}.","en":"Behind the house we have put in a small pond."},{"de":"Die Stadt will neben dem Rathaus einen Park {{anlegen}}.","en":"The city wants to create a park next to the town hall."}]}]},
 {"id":"ausrichten","word":"ausrichten","lv":"B2","tip":"ausrichten (separable: richtet ... aus) = pass on a message / host an event / align.","meanings":[{"gloss":"to pass on (a message, greetings)","art":null,"pl":null,"note":"separable: aus|richten","ex":[{"de":"Soll ich Herrn Müller etwas {{ausrichten}}?","en":"Shall I pass anything on to Mr Müller?"},{"de":"Kannst du deiner Schwester schöne Grüße von mir {{ausrichten}}?","en":"Can you give your sister my best wishes?"}]},{"gloss":"to host, organise (an event)","art":null,"pl":null,"note":"separable: aus|richten","ex":[{"de":"Die Stadt wird im nächsten Jahr die Europameisterschaft {{ausrichten}}.","en":"Next year the city will host the European Championship."},{"de":"Wir haben die Hochzeit meiner Schwester {{ausgerichtet}}.","en":"We organised my sister's wedding."}]},{"gloss":"to align, orient","art":null,"pl":null,"note":"separable: aus|richten","ex":[{"de":"Die Regale müssen genau an der Wand {{ausgerichtet}} werden.","en":"The shelves have to be aligned exactly with the wall."},{"de":"Man sollte die Antenne nach Süden {{ausrichten}}.","en":"You should point the antenna towards the south."}]}]},
 {"id":"aufnehmen","word":"aufnehmen","lv":"B2","tip":"aufnehmen (separable: nimmt ... auf) = record / take in, admit / take up, begin.","meanings":[{"gloss":"to record (sound, video)","art":null,"pl":null,"note":"separable: auf|nehmen","ex":[{"de":"Die Band hat ihr neues Album in nur zwei Wochen {{aufgenommen}}.","en":"The band recorded their new album in only two weeks."},{"de":"Ich möchte meine Stimme {{aufnehmen}}, um sie später anzuhören.","en":"I'd like to record my voice to listen to it later."}]},{"gloss":"to take in, admit","art":null,"pl":null,"note":"separable: auf|nehmen","ex":[{"de":"Die Familie hat zwei Flüchtlinge bei sich {{aufgenommen}}.","en":"The family has taken in two refugees."},{"de":"Das Krankenhaus kann keine weiteren Patienten mehr {{aufnehmen}}.","en":"The hospital cannot admit any more patients."}]},{"gloss":"to take up, begin (work, contact)","art":null,"pl":null,"note":"separable: auf|nehmen","ex":[{"de":"Sie wird im Herbst ihre Arbeit in Berlin {{aufnehmen}}.","en":"She will take up her work in Berlin in autumn."},{"de":"Die beiden Länder haben diplomatische Beziehungen {{aufgenommen}}.","en":"The two countries have established diplomatic relations."}]}]},
 {"id":"vorstellen","word":"vorstellen","lv":"B1","tip":"vorstellen (separable) = introduce someone; sich (Dat.) etwas vorstellen = imagine. Reflexive with dative = imagine.","meanings":[{"gloss":"to introduce (a person)","art":null,"pl":null,"note":"separable: vor|stellen","ex":[{"de":"Darf ich dir meinen Bruder {{vorstellen}}?","en":"May I introduce my brother to you?"},{"de":"Sie hat mich ihren Eltern {{vorgestellt}}.","en":"She introduced me to her parents."}]},{"gloss":"to imagine (sich etwas vorstellen)","art":null,"pl":null,"note":"reflexive with dative: sich (Dat.) etwas vor|stellen","ex":[{"de":"Das kann ich mir kaum {{vorstellen}}.","en":"I can hardly imagine that."},{"de":"Hast du dir den Urlaub so {{vorgestellt}}?","en":"Is this how you imagined the holiday?"}]}]},
 {"id":"verbinden","word":"verbinden","lv":"B1","tip":"verbinden (inseparable in both meanings: verband, verbunden) = connect, link or bandage a wound. Wunde/Arm means bandage; Städte/Drucker means connect.","meanings":[{"gloss":"to connect, link","art":null,"pl":null,"note":"inseparable: verbinden (verbindet, verband, verbunden)","ex":[{"de":"Dieser Tunnel soll die beiden Städte {{verbinden}}.","en":"This tunnel is meant to connect the two cities."},{"de":"Ich habe den Drucker mit dem Laptop {{verbunden}}.","en":"I have connected the printer to the laptop."}]},{"gloss":"to bandage, dress (a wound)","art":null,"pl":null,"note":"inseparable: verbinden (verband, verbunden)","ex":[{"de":"Die Ärztin {{verband}} die Wunde sorgfältig.","en":"The doctor carefully dressed the wound."},{"de":"Der Sanitäter hat ihm den verletzten Arm {{verbunden}}.","en":"The paramedic bandaged his injured arm."}]}]},
 {"id":"bestehen","word":"bestehen","lv":"B2","tip":"bestehen: pass (an exam); bestehen aus = consist of; bestehen auf + Dat. = insist on. The preposition and the object decide.","meanings":[{"gloss":"to pass (an exam)","art":null,"pl":null,"note":"bestehen + Akk.","ex":[{"de":"Hast du die Führerscheinprüfung {{bestanden}}?","en":"Did you pass the driving test?"},{"de":"Nur wer den Test {{besteht}}, bekommt das Zertifikat.","en":"Only those who pass the test get the certificate."}]},{"gloss":"to consist of (bestehen aus)","art":null,"pl":null,"note":"bestehen aus + Dat.","ex":[{"de":"Das Team {{besteht}} aus zwölf Spielern.","en":"The team consists of twelve players."},{"de":"Wasser {{besteht}} aus Wasserstoff und Sauerstoff.","en":"Water consists of hydrogen and oxygen."}]},{"gloss":"to insist on (bestehen auf)","art":null,"pl":null,"note":"bestehen auf + Dat.","ex":[{"de":"Der Kunde {{besteht}} auf einer schriftlichen Bestätigung.","en":"The customer insists on a written confirmation."},{"de":"Sie {{bestand}} darauf, selbst zu zahlen.","en":"She insisted on paying herself."}]}]},
 {"id":"erfahren","word":"erfahren","lv":"B2","tip":"erfahren: verb (er erfährt, hat erfahren) = find out, learn; adjective (eine erfahrene Ärztin) = experienced.","meanings":[{"gloss":"to find out, learn (news)","art":null,"pl":null,"note":"verb: erfahren, erfährt, hat erfahren","ex":[{"de":"Wir haben es erst gestern von einem Kollegen {{erfahren}}.","en":"We only found out about it yesterday from a colleague."},{"de":"Wie hast du von der Absage {{erfahren}}?","en":"How did you find out about the cancellation?"}]},{"gloss":"experienced (adjective)","art":null,"pl":null,"note":"adjective: erfahren, erfahrene ...","ex":[{"de":"Sie ist eine sehr {{erfahrene}} Ärztin.","en":"She is a very experienced doctor."},{"de":"Für diese Aufgabe suchen wir einen {{erfahrenen}} Projektleiter.","en":"For this task we are looking for an experienced project manager."}]}]},
 {"id":"verlassen","word":"verlassen","lv":"B1","tip":"verlassen: transitive = leave (a place, a person); sich verlassen auf + Akk. = rely on.","meanings":[{"gloss":"to leave (a place)","art":null,"pl":null,"note":"transitive: verlassen (verlässt, hat verlassen)","ex":[{"de":"Er hat die Stadt vor zehn Jahren {{verlassen}}.","en":"He left the city ten years ago."},{"de":"Wir müssen das Gebäude sofort {{verlassen}}.","en":"We have to leave the building immediately."}]},{"gloss":"to rely on (sich verlassen auf)","art":null,"pl":null,"note":"reflexive: sich verlassen auf + Akk.","ex":[{"de":"Auf ihn kann man sich immer {{verlassen}}.","en":"You can always rely on him."},{"de":"Ich habe mich auf dich {{verlassen}}, und du hast mich enttäuscht.","en":"I relied on you, and you let me down."}]}]},
 {"id":"passen","word":"passen","lv":"B2","tip":"passen = to fit/suit, or to pass (in a card game, or when you cannot answer a question).","meanings":[{"gloss":"to fit, suit","art":null,"pl":null,"note":"passen + Dat.","ex":[{"de":"Die Hose {{passt}} mir leider nicht mehr.","en":"The trousers unfortunately no longer fit me."},{"de":"Der Termin am Montag {{passt}} mir gut.","en":"Monday's appointment suits me well."}]},{"gloss":"to pass (give up a turn or an answer)","art":null,"pl":null,"ex":[{"de":"Bei dieser Frage muss ich leider {{passen}}.","en":"I'm afraid I have to pass on this question."},{"de":"Wenn du kein gutes Blatt hast, darfst du {{passen}}.","en":"If you don't have a good hand, you may pass."}]}]},
 {"id":"aufgeben","word":"aufgeben","lv":"B1","tip":"aufgeben (separable) = give up / post, check in / assign. Hausaufgaben = assign, Paket or Koffer = post or check in.","meanings":[{"gloss":"to give up","art":null,"pl":null,"note":"separable: auf|geben","ex":[{"de":"Er will nicht {{aufgeben}}, auch wenn es schwer ist.","en":"He doesn't want to give up, even though it is hard."},{"de":"Nach dem Unfall musste sie ihren Beruf {{aufgeben}}.","en":"After the accident she had to give up her job."}]},{"gloss":"to post, check in (parcel, luggage, ad)","art":null,"pl":null,"note":"separable: auf|geben","ex":[{"de":"Ich muss noch ein Paket bei der Post {{aufgeben}}.","en":"I still have to send a parcel at the post office."},{"de":"Am Flughafen haben wir die Koffer {{aufgegeben}}.","en":"At the airport we checked in the suitcases."}]},{"gloss":"to assign (homework)","art":null,"pl":null,"note":"separable: auf|geben","ex":[{"de":"Der Lehrer hat uns viele Hausaufgaben {{aufgegeben}}.","en":"The teacher has assigned us a lot of homework."},{"de":"Was hat euch die Lehrerin heute als Hausaufgabe {{aufgegeben}}?","en":"What did the teacher give you for homework today?"}]}]},
 {"id":"anziehen","word":"anziehen","lv":"B2","tip":"anziehen (separable) = put on clothes / tighten / attract. Jacke = put on, Schrauben = tighten, Magnet or Besucher = attract.","meanings":[{"gloss":"to put on (clothes)","art":null,"pl":null,"note":"separable: an|ziehen","ex":[{"de":"Es ist kalt, du solltest eine Jacke {{anziehen}}.","en":"It's cold, you should put on a jacket."},{"de":"Ich habe die neuen Schuhe heute zum ersten Mal {{angezogen}}.","en":"I put on the new shoes for the first time today."}]},{"gloss":"to tighten","art":null,"pl":null,"note":"separable: an|ziehen","ex":[{"de":"Der Mechaniker muss die Schrauben noch fester {{anziehen}}.","en":"The mechanic still has to tighten the screws more firmly."},{"de":"Die Schrauben am Rad wurden nicht fest genug {{angezogen}}.","en":"The screws on the wheel were not tightened firmly enough."}]},{"gloss":"to attract","art":null,"pl":null,"note":"separable: an|ziehen","ex":[{"de":"Ein Magnet kann Eisen {{anziehen}}.","en":"A magnet can attract iron."},{"de":"Das Festival hat in diesem Jahr Tausende Besucher {{angezogen}}.","en":"The festival has attracted thousands of visitors this year."}]}]},
 {"id":"ausgehen","word":"ausgehen","lv":"B2","tip":"ausgehen (separable) = go out socially / run out / assume (davon ausgehen, dass ...). Ist ... ausgegangen with a supply = run out.","meanings":[{"gloss":"to go out (socially)","art":null,"pl":null,"note":"separable: aus|gehen","ex":[{"de":"Am Wochenende wollen wir abends mit Freunden {{ausgehen}}.","en":"At the weekend we want to go out with friends in the evening."},{"de":"Gestern sind wir zum Tanzen {{ausgegangen}}.","en":"Yesterday we went out dancing."}]},{"gloss":"to run out (supplies)","art":null,"pl":null,"note":"separable: aus|gehen; subject = the thing that runs out","ex":[{"de":"Uns ist der Zucker {{ausgegangen}}.","en":"We've run out of sugar."},{"de":"Wenn uns das Benzin {{ausgeht}}, müssen wir zu Fuß weiter.","en":"If we run out of petrol, we'll have to continue on foot."}]},{"gloss":"to assume (davon ausgehen)","art":null,"pl":null,"note":"separable: aus|gehen; with davon, dass ...","ex":[{"de":"Wir können davon {{ausgehen}}, dass er pünktlich kommt.","en":"We can assume that he'll arrive on time."},{"de":"Ich bin immer davon {{ausgegangen}}, dass ihr das wisst.","en":"I always assumed that you knew that."}]}]},
 {"id":"schwer","word":"schwer","lv":"B1","tip":"schwer = heavy, difficult, or serious/severe. Koffer = heavy; Prüfung = difficult; verletzt/Fehler = serious.","meanings":[{"gloss":"heavy","art":null,"pl":null,"ex":[{"de":"Der Koffer ist zu {{schwer}}, ich kann ihn nicht tragen.","en":"The suitcase is too heavy, I can't carry it."},{"de":"Sie trägt einen {{schweren}} Rucksack.","en":"She is carrying a heavy rucksack."}]},{"gloss":"difficult","art":null,"pl":null,"ex":[{"de":"Die Prüfung war {{schwer}}, nur wenige haben sie bestanden.","en":"The exam was difficult, only a few passed it."},{"de":"Die Aufgabe war so {{schwer}}, dass niemand sie lösen konnte.","en":"The task was so difficult that nobody could solve it."}]},{"gloss":"serious, severe","art":null,"pl":null,"ex":[{"de":"Bei dem Unfall wurde er {{schwer}} verletzt.","en":"He was seriously injured in the accident."},{"de":"Das war ein {{schwerer}} Fehler, der viel Geld gekostet hat.","en":"That was a serious mistake that cost a lot of money."}]}]},
 {"id":"leicht","word":"leicht","lv":"B1","tip":"leicht = light (weight), easy, or slight. Rucksack = light; Aufgabe = easy; Erkältung/verletzt = slight.","meanings":[{"gloss":"light (not heavy)","art":null,"pl":null,"ex":[{"de":"Der Rucksack ist ganz {{leicht}}, ich spüre ihn kaum.","en":"The rucksack is quite light, I hardly feel it."},{"de":"Für den Sommer kaufte sie eine {{leichte}} Jacke.","en":"For summer she bought a light jacket."}]},{"gloss":"easy","art":null,"pl":null,"ex":[{"de":"Die Aufgabe war ganz {{leicht}}, alle haben sie gelöst.","en":"The task was quite easy, everybody solved it."},{"de":"Das ist {{leichter}} gesagt als getan.","en":"That is easier said than done."}]},{"gloss":"slight, mild","art":null,"pl":null,"ex":[{"de":"Ich habe nur eine {{leichte}} Erkältung, morgen gehe ich wieder arbeiten.","en":"I only have a mild cold; I'll go back to work tomorrow."},{"de":"Der Patient wurde nur {{leicht}} verletzt.","en":"The patient was only slightly injured."}]}]},
 {"id":"scharf","word":"scharf","lv":"B1","tip":"scharf = sharp (blade), spicy hot (food), or in sharp focus (photo, picture).","meanings":[{"gloss":"sharp (blade)","art":null,"pl":null,"ex":[{"de":"Vorsicht, das Messer ist sehr {{scharf}}!","en":"Careful, the knife is very sharp!"},{"de":"Der Hund hat {{scharfe}} Zähne.","en":"The dog has sharp teeth."}]},{"gloss":"spicy, hot (food)","art":null,"pl":null,"ex":[{"de":"Die Suppe ist mir zu {{scharf}}.","en":"The soup is too spicy for me."},{"de":"Magst du {{scharfes}} Essen?","en":"Do you like spicy food?"}]},{"gloss":"sharp, in focus (image)","art":null,"pl":null,"ex":[{"de":"Das Foto ist leider nicht {{scharf}}.","en":"Unfortunately the photo isn't sharp."},{"de":"Der Fernseher zeigt ein sehr {{scharfes}} Bild.","en":"The television shows a very sharp picture."}]}]},
 {"id":"schlecht","word":"schlecht","lv":"A2","tip":"schlecht = bad, or (in Mir ist schlecht) sick/nauseous.","meanings":[{"gloss":"bad, poor","art":null,"pl":null,"ex":[{"de":"Das Wetter ist heute {{schlecht}}.","en":"The weather is bad today."},{"de":"Das ist ein {{schlechtes}} Zeichen.","en":"That is a bad sign."}]},{"gloss":"sick, nauseous (mir ist schlecht)","art":null,"pl":null,"note":"only with a dative person: Mir ist/wird schlecht","ex":[{"de":"Mir wird {{schlecht}}, wenn ich im Bus lese.","en":"I feel sick when I read on the bus."},{"de":"Nach dem Essen war ihm {{schlecht}}.","en":"After the meal he felt sick."}]}]},
 {"id":"weiss","word":"weiß","lv":"A2","tip":"weiß = white (adjective) and weiß (ich/er weiß) from wissen. Same spelling; a verb with a subject vs. a colour word.","meanings":[{"gloss":"(he/she/I) knows (from wissen)","art":null,"pl":null,"note":"verb: wissen, ich/er/sie weiß","ex":[{"de":"Ich {{weiß}} die Antwort leider nicht.","en":"Unfortunately I don't know the answer."},{"de":"Er {{weiß}} nicht, wo sein Schlüssel ist.","en":"He doesn't know where his key is."}]},{"gloss":"white","art":null,"pl":null,"note":"adjective","ex":[{"de":"Sie trägt ein {{weißes}} Kleid.","en":"She is wearing a white dress."},{"de":"Im Winter ist die Landschaft ganz {{weiß}}.","en":"In winter the landscape is completely white."}]}]},
 {"id":"laut","word":"laut","lv":"B1","tip":"laut = loud (adjective/adverb), but also a preposition meaning according to (+ Gen. or Dat.).","meanings":[{"gloss":"loud, noisy (adjective, adverb)","art":null,"pl":null,"ex":[{"de":"Die Musik ist viel zu {{laut}}.","en":"The music is far too loud."},{"de":"Sprich bitte nicht so {{laut}}, das Baby schläft.","en":"Please don't speak so loudly, the baby is sleeping."}]},{"gloss":"according to (preposition)","art":null,"pl":null,"note":"preposition + Gen./Dat.","ex":[{"de":"{{Laut}} Wetterbericht gibt es morgen Gewitter.","en":"According to the weather forecast there will be thunderstorms tomorrow."},{"de":"Der Zug kommt {{laut}} Fahrplan um zehn Uhr an.","en":"According to the timetable the train arrives at ten o'clock."}]}]},
 {"id":"sein","word":"sein","lv":"A2","tip":"sein = to be (verb) or his/its (possessive determiner). A noun after it (sein Fahrrad) means possessive; zu Hause sein means to be.","meanings":[{"gloss":"to be (verb)","art":null,"pl":null,"note":"infinitive of the verb sein","ex":[{"de":"Ich möchte heute Abend pünktlich zu Hause {{sein}}.","en":"I'd like to be home on time this evening."},{"de":"Es muss schön {{sein}}, am Meer zu wohnen.","en":"It must be nice to live by the sea."}]},{"gloss":"his, its (possessive)","art":null,"pl":null,"note":"possessive determiner: sein, seine, seinen ...","ex":[{"de":"Das ist {{sein}} Fahrrad.","en":"That is his bike."},{"de":"Er hat {{seinen}} Schlüssel verloren.","en":"He has lost his key."}]}]},
 {"id":"bogen","word":"Bogen","lv":"B2","tip":"der Bogen (pl. Bögen, also Bogen) = arch / curve; bow (arrow, violin); sheet of paper. The object around it decides: Brücke / Pfeil / Papier.","meanings":[{"gloss":"arch, curve, bend","art":"der","pl":"Bögen","ex":[{"de":"Die alte Brücke hat drei steinerne {{Bögen}}.","en":"The old bridge has three stone arches."},{"de":"Der Fluss macht hier einen weiten {{Bogen}} um die Stadt.","en":"The river makes a wide bend around the town."},{"de":"Das Auto fuhr in einem großen {{Bogen}} um das Hindernis.","en":"The car drove around the obstacle in a wide curve."}]},{"gloss":"bow (for arrows; for string instruments)","art":"der","pl":"Bögen","ex":[{"de":"Er spannte den {{Bogen}} und zielte auf die Scheibe.","en":"He drew the bow and aimed at the target."},{"de":"Die Geigerin strich mit dem {{Bogen}} sanft über die Saiten.","en":"The violinist drew the bow gently across the strings."}]},{"gloss":"sheet (of paper or stamps)","art":"der","pl":"Bögen","ex":[{"de":"Für die Zeichnung brauche ich einen großen {{Bogen}} Papier.","en":"For the drawing I need a large sheet of paper."},{"de":"Briefmarken werden in {{Bögen}} zu je zehn Stück gedruckt.","en":"Stamps are printed in sheets of ten."}]}]},
 {"id":"krone","word":"Krone","lv":"B2","tip":"die Krone (pl. Kronen) = crown of a monarch, but also: tooth crown, treetop, and the currency (Danish krone). Context: König / Zahnarzt / Baum / Preis.","meanings":[{"gloss":"crown (of a monarch)","art":"die","pl":"Kronen","ex":[{"de":"Die Königin trug bei der Krönung eine goldene {{Krone}}.","en":"The queen wore a golden crown at the coronation."},{"de":"Im Museum werden die {{Kronen}} früherer Könige ausgestellt.","en":"The crowns of former kings are on display in the museum."}]},{"gloss":"crown (of a tooth)","art":"die","pl":"Kronen","ex":[{"de":"Der Zahnarzt hat mir eine {{Krone}} auf den Backenzahn gesetzt.","en":"The dentist put a crown on my molar."},{"de":"Die {{Krone}} hat sich gelöst, ich muss morgen zum Zahnarzt.","en":"The crown has come loose; I have to see the dentist tomorrow."}]},{"gloss":"treetop, crown (of a tree)","art":"die","pl":"Kronen","ex":[{"de":"Im Sturm bogen sich die {{Kronen}} der alten Buchen.","en":"In the storm the crowns of the old beeches bent over."},{"de":"Hoch oben in der {{Krone}} der Eiche klopfte ein Specht.","en":"High up in the crown of the oak a woodpecker was tapping."}]},{"gloss":"krone (currency, e.g. Danish)","art":"die","pl":"Kronen","ex":[{"de":"In Dänemark bezahlt man mit der {{Krone}}.","en":"In Denmark you pay with the krone."},{"de":"Der Pullover kostet in Kopenhagen 400 {{Kronen}}.","en":"The sweater costs 400 kroner in Copenhagen."}]}]},
 {"id":"leitung","word":"Leitung","lv":"B2","tip":"die Leitung = management; pipe/cable; telephone line. Wasser/Strom → pipe or cable; Schule/Firma → management; 'in der Leitung bleiben' → phone.","meanings":[{"gloss":"management, leadership","art":"die","pl":"","note":"in this sense mostly singular","ex":[{"de":"Die {{Leitung}} der Schule liegt bei Frau Dr. Weber.","en":"Dr. Weber is in charge of the school."},{"de":"Unter der {{Leitung}} des neuen Chefs wurde die Firma erfolgreicher.","en":"Under the new boss's leadership the company became more successful."}]},{"gloss":"pipe, cable, supply line","art":"die","pl":"Leitungen","ex":[{"de":"Im Winter ist im Keller eine {{Leitung}} geplatzt.","en":"A pipe burst in the cellar in winter."},{"de":"Die {{Leitungen}} im alten Haus müssen erneuert werden.","en":"The pipes and wiring in the old house have to be replaced."}]},{"gloss":"(telephone) line","art":"die","pl":"Leitungen","ex":[{"de":"Bitte bleiben Sie in der {{Leitung}}, ich verbinde Sie sofort.","en":"Please hold the line, I'll put you through right away."},{"de":"Die {{Leitung}} ist leider besetzt.","en":"Unfortunately the line is engaged."}]}]},
 {"id":"rate","word":"Rate","lv":"B2","tip":"die Rate (pl. Raten) = instalment payment; rate (percentage, statistics). 'in Raten zahlen' = pay in instalments.","meanings":[{"gloss":"instalment","art":"die","pl":"Raten","ex":[{"de":"Das Auto bezahle ich in monatlichen {{Raten}}.","en":"I'm paying for the car in monthly instalments."},{"de":"Die letzte {{Rate}} ist im Mai fällig.","en":"The last instalment is due in May."}]},{"gloss":"rate (statistics), proportion","art":"die","pl":"Raten","ex":[{"de":"Die {{Rate}} der Neuinfektionen sinkt seit Wochen.","en":"The rate of new infections has been falling for weeks."},{"de":"Die {{Rate}} der Schulabbrecher liegt bei fünf Prozent.","en":"The dropout rate is five percent."}]}]},
 {"id":"titel","word":"Titel","lv":"B2","tip":"der Titel (pl. Titel) = title of a book/film/song; title of rank (Doktor, Gräfin); sports championship. Plural unchanged.","meanings":[{"gloss":"title (of a book, film, song)","art":"der","pl":"Titel","ex":[{"de":"Der {{Titel}} des Romans verrät nichts über die Handlung.","en":"The title of the novel reveals nothing about the plot."},{"de":"Wie lautet der {{Titel}} dieses Liedes?","en":"What is the title of this song?"}]},{"gloss":"title (academic or noble rank)","art":"der","pl":"Titel","ex":[{"de":"Er führt den {{Titel}} eines Doktors der Philosophie.","en":"He holds the title of Doctor of Philosophy."},{"de":"Sie trägt den {{Titel}} einer Gräfin, benutzt ihn aber selten.","en":"She holds the title of countess but rarely uses it."}]},{"gloss":"(championship) title","art":"der","pl":"Titel","ex":[{"de":"Die Mannschaft holte zum dritten Mal den {{Titel}}.","en":"The team won the title for the third time."},{"de":"Er verteidigte seinen {{Titel}} im Schwergewicht.","en":"He defended his heavyweight title."}]}]},
 {"id":"sicherung","word":"Sicherung","lv":"B2","tip":"die Sicherung (pl. Sicherungen) = electrical fuse; backup of data; securing/safeguarding (jobs, peace; mostly singular).","meanings":[{"gloss":"fuse (electrical)","art":"die","pl":"Sicherungen","ex":[{"de":"Die {{Sicherung}} ist durchgebrannt, deshalb ist der ganze Flur dunkel.","en":"The fuse has blown, so the whole hallway is dark."},{"de":"Im Keller hängt ein Kasten mit den {{Sicherungen}}.","en":"In the cellar there is a box with the fuses."}]},{"gloss":"backup (of data)","art":"die","pl":"Sicherungen","ex":[{"de":"Die tägliche {{Sicherung}} der Daten läuft nachts automatisch.","en":"The daily backup of the data runs automatically at night."},{"de":"Für die {{Sicherung}} der Fotos benutzt sie eine externe Festplatte.","en":"She uses an external hard drive to back up her photos."}]},{"gloss":"safeguarding, securing","art":"die","pl":"","ex":[{"de":"Die {{Sicherung}} der Arbeitsplätze hat für die Gewerkschaft Vorrang.","en":"Safeguarding jobs is the union's priority."},{"de":"Zur {{Sicherung}} des Friedens wurde ein Vertrag unterzeichnet.","en":"A treaty was signed to safeguard the peace."}],"note":"in this sense mostly singular"}]},
 {"id":"spur","word":"Spur","lv":"B2","tip":"die Spur (pl. Spuren) = track/trail/lead; lane (road); a tiny amount ('eine Spur Salz').","meanings":[{"gloss":"track, trail, lead","art":"die","pl":"Spuren","ex":[{"de":"Im Schnee waren frische {{Spuren}} eines Hirsches zu sehen.","en":"Fresh tracks of a deer could be seen in the snow."},{"de":"Die Polizei verfolgt eine heiße {{Spur}}.","en":"The police are following a hot lead."}]},{"gloss":"lane (of a road)","art":"die","pl":"Spuren","ex":[{"de":"Auf der Autobahn wird die rechte {{Spur}} gesperrt.","en":"The right lane of the motorway is being closed."},{"de":"Der Lkw fuhr die ganze Zeit auf der linken {{Spur}}.","en":"The lorry stayed in the left lane the whole time."}]},{"gloss":"a touch, a hint (tiny amount)","art":"die","pl":"Spuren","ex":[{"de":"Die Soße braucht noch eine {{Spur}} Zitronensaft.","en":"The sauce still needs a touch of lemon juice."},{"de":"Das Fleisch war eine {{Spur}} zu salzig.","en":"The meat was a touch too salty."}]}]},
 {"id":"takt","word":"Takt","lv":"B2","tip":"der Takt = bar, time/beat in music (pl. Takte); tact (no plural). 'im Takt' = in time; 'keinen Takt haben' = be tactless.","meanings":[{"gloss":"bar; time, beat (music)","art":"der","pl":"Takte","ex":[{"de":"Die ersten vier {{Takte}} spielt das Klavier allein.","en":"The piano plays the first four bars alone."},{"de":"Bitte klatscht im {{Takt}} der Musik mit!","en":"Please clap along in time with the music!"}]},{"gloss":"tact","art":"der","pl":"","note":"no plural in this sense","ex":[{"de":"Es fehlte ihm der nötige {{Takt}}, um das Thema anzusprechen.","en":"He lacked the necessary tact to bring up the subject."},{"de":"Mit viel {{Takt}} überbrachte sie die schlechte Nachricht.","en":"She delivered the bad news with great tact."}]}]},
 {"id":"wache","word":"Wache","lv":"B2","tip":"die Wache (pl. Wachen) = guard (person) and guard duty; also the station (Polizeiwache, Feuerwache): 'zur Wache gehen'.","meanings":[{"gloss":"guard, sentry; guard duty","art":"die","pl":"Wachen","ex":[{"de":"Die {{Wache}} vor dem Palast wird jede Stunde abgelöst.","en":"The guard in front of the palace is relieved every hour."},{"de":"Zwei {{Wachen}} standen am Tor des Gefängnisses.","en":"Two guards stood at the prison gate."},{"de":"Der Soldat musste die ganze Nacht {{Wache}} halten.","en":"The soldier had to stand guard all night."}]},{"gloss":"(police or fire) station","art":"die","pl":"Wachen","ex":[{"de":"Nach dem Einbruch ging sie zur {{Wache}} und erstattete Anzeige.","en":"After the burglary she went to the police station and filed a report."},{"de":"Der Betrunkene verbrachte die Nacht auf der {{Wache}}.","en":"The drunk man spent the night at the police station."}]}]},
 {"id":"stimme","word":"Stimme","lv":"B2","tip":"die Stimme (pl. Stimmen) = voice; vote (Stimmen abgeben, zählen); part in music (die zweite Stimme).","meanings":[{"gloss":"voice","art":"die","pl":"Stimmen","ex":[{"de":"Sie hat eine warme, tiefe {{Stimme}}.","en":"She has a warm, deep voice."},{"de":"Nach dem Konzert war seine {{Stimme}} heiser.","en":"After the concert his voice was hoarse."}]},{"gloss":"vote","art":"die","pl":"Stimmen","ex":[{"de":"Bei der Wahl erhielt die Partei 40 Prozent der {{Stimmen}}.","en":"In the election the party received 40 percent of the votes."},{"de":"Der Antrag scheiterte an einer einzigen {{Stimme}}.","en":"The motion failed by a single vote."}]},{"gloss":"(musical) part","art":"die","pl":"Stimmen","ex":[{"de":"Im Chor singe ich die zweite {{Stimme}}.","en":"In the choir I sing the second part."},{"de":"Die Noten für die {{Stimme}} der Oboe sind verloren gegangen.","en":"The sheet music for the oboe part has gone missing."}]}]},
 {"id":"zeichen","word":"Zeichen","lv":"B1","tip":"das Zeichen (pl. Zeichen) = signal/cue (ein Zeichen geben); written character (a text has 2000 Zeichen); sign/indication (ein gutes Zeichen).","meanings":[{"gloss":"signal, cue (to do something)","art":"das","pl":"Zeichen","ex":[{"de":"Der Lehrer gab uns ein {{Zeichen}}, leise zu sein.","en":"The teacher signalled to us to be quiet."},{"de":"Auf ein {{Zeichen}} des Dirigenten setzte das Orchester ein.","en":"At a sign from the conductor the orchestra came in."}]},{"gloss":"character (letter, digit, symbol)","art":"das","pl":"Zeichen","ex":[{"de":"Der Text darf höchstens 2000 {{Zeichen}} lang sein.","en":"The text may be at most 2,000 characters long."},{"de":"Dieses {{Zeichen}} gibt es auf meiner Tastatur nicht.","en":"My keyboard doesn't have this character."}]},{"gloss":"sign, indication (of something)","art":"das","pl":"Zeichen","ex":[{"de":"Dass er schweigt, ist ein schlechtes {{Zeichen}}.","en":"The fact that he is silent is a bad sign."},{"de":"Fieber ist oft ein {{Zeichen}} für eine Infektion.","en":"Fever is often a sign of an infection."}]}]},
 {"id":"zunge","word":"Zunge","lv":"B2","tip":"die Zunge (pl. Zungen) = tongue (in the mouth); tongue of a shoe.","meanings":[{"gloss":"tongue (organ)","art":"die","pl":"Zungen","ex":[{"de":"Ich habe mir beim Essen auf die {{Zunge}} gebissen.","en":"I bit my tongue while eating."},{"de":"Der Arzt bat mich, die {{Zunge}} herauszustrecken.","en":"The doctor asked me to stick out my tongue."}]},{"gloss":"tongue (of a shoe)","art":"die","pl":"Zungen","ex":[{"de":"Die {{Zunge}} des Schuhs ist zu hart und drückt auf den Fuß.","en":"The tongue of the shoe is too stiff and presses on my foot."},{"de":"Beim Schnüren der Stiefel rutschte ihm die {{Zunge}} zur Seite.","en":"While he was lacing his boots the tongue slipped to the side."}]}]},
 {"id":"zweig","word":"Zweig","lv":"B2","tip":"der Zweig (pl. Zweige) = twig, branch of a tree; also a branch of an industry, family or science (Wirtschaftszweig).","meanings":[{"gloss":"twig, small branch","art":"der","pl":"Zweige","ex":[{"de":"Der Vogel saß auf einem dünnen {{Zweig}}.","en":"The bird sat on a thin twig."},{"de":"Er brach einen {{Zweig}} vom Strauch ab.","en":"He broke a twig off the bush."}]},{"gloss":"branch (of an industry, family, science)","art":"der","pl":"Zweige","ex":[{"de":"Der Tourismus ist ein wichtiger {{Zweig}} der Wirtschaft.","en":"Tourism is an important branch of the economy."},{"de":"Dieser {{Zweig}} der Familie wanderte nach Amerika aus.","en":"This branch of the family emigrated to America."},{"de":"Die Chemie ist ein {{Zweig}} der Naturwissenschaften.","en":"Chemistry is a branch of the natural sciences."}]}]},
 {"id":"futter","word":"Futter","lv":"B2","tip":"das Futter = animal feed OR lining of a coat/jacket. Both neuter; the second one is the textile layer inside.","meanings":[{"gloss":"(animal) feed, fodder","art":"das","pl":"","note":"no common plural (Futtersorten = types of feed)","ex":[{"de":"Das {{Futter}} für die Pferde wird morgens geliefert.","en":"The feed for the horses is delivered in the morning."},{"de":"Unsere Katze frisst nur noch das teure {{Futter}}.","en":"Our cat only eats the expensive food now."}]},{"gloss":"lining (of a garment)","art":"das","pl":"","note":"plural very rare","ex":[{"de":"Der Mantel hat ein warmes {{Futter}} aus Wolle.","en":"The coat has a warm woollen lining."},{"de":"Das {{Futter}} meiner Jacke ist an der Tasche gerissen.","en":"The lining of my jacket has torn at the pocket."}]}]},
 {"id":"kegel","word":"Kegel","lv":"B2","tip":"der Kegel (pl. Kegel) = cone (shape, traffic cone); skittle / ninepin (Kegeln = ninepin bowling, skittles).","meanings":[{"gloss":"cone","art":"der","pl":"Kegel","ex":[{"de":"Ein {{Kegel}} hat eine runde Grundfläche und läuft oben spitz zu.","en":"A cone has a round base and tapers to a point."},{"de":"Der Verkehr wurde um orangefarbene {{Kegel}} herumgeleitet.","en":"Traffic was diverted around orange cones."}]},{"gloss":"skittle, ninepin","art":"der","pl":"Kegel","ex":[{"de":"Die Kugel rollte durch die Bahn und warf alle {{Kegel}} um.","en":"The ball rolled down the lane and knocked over all the skittles."},{"de":"Beim Kegeln hat er mit einer Kugel acht {{Kegel}} getroffen.","en":"While bowling he hit eight pins with one ball."}]}]},
 {"id":"kern","word":"Kern","lv":"B2","tip":"der Kern (pl. Kerne) = pit/seed (cherry, apple); nucleus (atom, cell); core/essence of a matter (mostly singular).","meanings":[{"gloss":"pit, seed (of fruit)","art":"der","pl":"Kerne","ex":[{"de":"Vorsicht, in den Kirschen sind noch die {{Kerne}}!","en":"Careful, the cherries still have their pits in!"},{"de":"Sie spuckte den {{Kern}} der Pflaume in die Hand.","en":"She spat the plum stone into her hand."}]},{"gloss":"nucleus","art":"der","pl":"Kerne","ex":[{"de":"Der {{Kern}} eines Atoms besteht aus Protonen und Neutronen.","en":"The nucleus of an atom consists of protons and neutrons."},{"de":"Die meisten Zellen enthalten einen {{Kern}}.","en":"Most cells contain a nucleus."}]},{"gloss":"core, essence","art":"der","pl":"","note":"mostly singular in this sense","ex":[{"de":"Das ist der {{Kern}} des Problems.","en":"That is the heart of the problem."},{"de":"Im {{Kern}} stimme ich Ihnen zu.","en":"Essentially, I agree with you."}]}]},
 {"id":"anlage","word":"Anlage","lv":"B2","tip":"die Anlage (pl. Anlagen) = facility/plant; investment (Geldanlage); enclosure to a letter/e-mail ('in der Anlage').","meanings":[{"gloss":"facility, plant, installation","art":"die","pl":"Anlagen","ex":[{"de":"Die neue {{Anlage}} reinigt das Abwasser der ganzen Stadt.","en":"The new plant treats the sewage of the whole town."},{"de":"Der Zutritt zur {{Anlage}} ist nur mit Ausweis erlaubt.","en":"Access to the facility is only allowed with ID."}]},{"gloss":"investment","art":"die","pl":"Anlagen","ex":[{"de":"Sie suchte eine sichere {{Anlage}} für ihr Erspartes.","en":"She was looking for a safe investment for her savings."},{"de":"Aktien sind eine riskante {{Anlage}}.","en":"Shares are a risky investment."}]},{"gloss":"enclosure, attachment","art":"die","pl":"Anlagen","ex":[{"de":"Den Vertrag finden Sie in der {{Anlage}}.","en":"Please find the contract attached."},{"de":"Wir senden Ihnen die Unterlagen als {{Anlage}}.","en":"We are sending you the documents as an enclosure."}]}]},
 {"id":"abschluss","word":"Abschluss","lv":"B2","tip":"der Abschluss (pl. Abschlüsse) = end/conclusion; final qualification (school, degree); taking out / closing a contract or insurance.","meanings":[{"gloss":"end, conclusion","art":"der","pl":"Abschlüsse","ex":[{"de":"Zum {{Abschluss}} des Abends sangen alle ein Lied.","en":"To close the evening, everybody sang a song."},{"de":"Die Bauarbeiten stehen kurz vor dem {{Abschluss}}.","en":"The construction work is close to completion."}]},{"gloss":"final qualification, degree, certificate","art":"der","pl":"Abschlüsse","ex":[{"de":"Mit einem guten {{Abschluss}} findet man leicht eine Stelle.","en":"With a good qualification it is easy to find a job."},{"de":"Ohne {{Abschluss}} hat er kaum Chancen auf eine Lehrstelle.","en":"Without a certificate he has hardly any chance of an apprenticeship."}]},{"gloss":"taking out, closing (a contract, insurance, deal)","art":"der","pl":"Abschlüsse","ex":[{"de":"Der {{Abschluss}} einer Rentenversicherung lohnt sich vor allem für junge Leute.","en":"Taking out a private pension plan pays off above all for young people."},{"de":"Beim {{Abschluss}} einer Versicherung sollte man das Kleingedruckte lesen.","en":"When taking out an insurance policy you should read the small print."}]}]},
 {"id":"bar","word":"Bar","lv":"B2","tip":"die Bar (pl. Bars) = bar (pub); bar (adjective, not inflected) = in cash ('bar bezahlen').","meanings":[{"gloss":"bar (for drinks)","art":"die","pl":"Bars","ex":[{"de":"Nach dem Kino gingen wir noch in eine {{Bar}}.","en":"After the cinema we went to a bar."},{"de":"Hinter der {{Bar}} mixt der Barkeeper Cocktails.","en":"Behind the bar the bartender is mixing cocktails."}]},{"gloss":"in cash","art":null,"pl":null,"note":"adjective / adverb; not inflected in 'bar bezahlen'","ex":[{"de":"In dem kleinen Laden kann man nur {{bar}} bezahlen.","en":"In the little shop you can only pay in cash."},{"de":"Das Honorar wurde ihm {{bar}} auf die Hand ausgezahlt.","en":"The fee was paid to him in cash."}]}]},
 {"id":"schiene","word":"Schiene","lv":"B2","tip":"die Schiene (pl. Schienen) = rail (track); splint (medical).","meanings":[{"gloss":"rail","art":"die","pl":"Schienen","ex":[{"de":"Der Zug entgleiste, weil sich eine {{Schiene}} verbogen hatte.","en":"The train derailed because a rail had buckled."},{"de":"Die Straßenbahn fährt auf {{Schienen}} quer durch die Stadt.","en":"The tram runs on rails right across the town."}]},{"gloss":"splint","art":"die","pl":"Schienen","ex":[{"de":"Der Arzt legte dem Jungen eine {{Schiene}} an den gebrochenen Finger.","en":"The doctor put a splint on the boy's broken finger."},{"de":"Das Bein steckte sechs Wochen lang in einer {{Schiene}}.","en":"The leg was in a splint for six weeks."}]}]},
 {"id":"schicht","word":"Schicht","lv":"B2","tip":"die Schicht (pl. Schichten) = layer; work shift; social class/stratum.","meanings":[{"gloss":"layer, coat","art":"die","pl":"Schichten","ex":[{"de":"Auf dem Gipfel lag eine dicke {{Schicht}} Neuschnee.","en":"A thick layer of fresh snow lay on the summit."},{"de":"Der Maler trug zwei {{Schichten}} Farbe auf.","en":"The painter applied two coats of paint."}]},{"gloss":"(work) shift","art":"die","pl":"Schichten","ex":[{"de":"Meine {{Schicht}} beginnt um sechs Uhr morgens.","en":"My shift starts at six in the morning."},{"de":"Die Pflegekräfte arbeiten in drei {{Schichten}}.","en":"The nursing staff work in three shifts."}]},{"gloss":"social class, stratum","art":"die","pl":"Schichten","ex":[{"de":"Die Reform entlastet vor allem die unteren {{Schichten}} der Bevölkerung.","en":"The reform relieves mainly the lower strata of the population."},{"de":"Menschen aus allen sozialen {{Schichten}} besuchen das Festival.","en":"People from all social classes visit the festival."}]}]},
 {"id":"stelle","word":"Stelle","lv":"B2","tip":"die Stelle (pl. Stellen) = spot/place; job (position); passage in a text; office/authority.","meanings":[{"gloss":"spot, place","art":"die","pl":"Stellen","ex":[{"de":"An dieser {{Stelle}} ist der Fluss besonders tief.","en":"At this spot the river is particularly deep."},{"de":"Das Wasser tropft an einer {{Stelle}} durch die Decke.","en":"Water is dripping through the ceiling in one place."}]},{"gloss":"job, position","art":"die","pl":"Stellen","ex":[{"de":"Die Firma hat zwei neue {{Stellen}} ausgeschrieben.","en":"The company has advertised two new positions."},{"de":"Sie sucht eine {{Stelle}} als Lehrerin.","en":"She is looking for a job as a teacher."}]},{"gloss":"passage (in a text)","art":"die","pl":"Stellen","ex":[{"de":"Diese {{Stelle}} im Roman hat mich besonders berührt.","en":"This passage in the novel touched me especially."},{"de":"Kannst du mir die {{Stelle}} im Text zeigen, die du meinst?","en":"Can you show me the passage in the text that you mean?"}]},{"gloss":"office, authority, agency","art":"die","pl":"Stellen","ex":[{"de":"Wenden Sie sich bitte an die zuständige {{Stelle}}.","en":"Please contact the responsible office."},{"de":"Die Beschwerde wurde an eine höhere {{Stelle}} weitergeleitet.","en":"The complaint was forwarded to a higher authority."}]}]},
 {"id":"ausfallen","word":"ausfallen","lv":"B2","tip":"ausfallen (ist ausgefallen) = be cancelled / fail, break down / fall out / turn out (gut, schlecht ausfallen). The subject decides: Unterricht, Strom, Haare, Ergebnis.","meanings":[{"gloss":"to be cancelled, not take place","art":null,"pl":null,"note":"separable: aus|fallen; ist ausgefallen","ex":[{"de":"Wegen des Streiks werden morgen viele Züge {{ausfallen}}.","en":"Because of the strike many trains will be cancelled tomorrow."},{"de":"Schade, dass das Konzert wegen des Regens {{ausfällt}}.","en":"A pity that the concert is cancelled because of the rain."}]},{"gloss":"to fail, stop working","art":null,"pl":null,"note":"separable: aus|fallen; ist ausgefallen","ex":[{"de":"Bei dem Gewitter ist der Strom {{ausgefallen}}.","en":"The power failed during the thunderstorm."},{"de":"Wenn die Heizung {{ausfällt}}, rufen Sie bitte den Hausmeister.","en":"If the heating fails, please call the caretaker."}]},{"gloss":"to fall out (hair, teeth)","art":null,"pl":null,"note":"separable: aus|fallen; ist ausgefallen","ex":[{"de":"Seit der Chemotherapie sind ihr die Haare {{ausgefallen}}.","en":"Her hair has fallen out since the chemotherapy."},{"de":"Dem Kind ist ein Milchzahn {{ausgefallen}}.","en":"The child has lost a milk tooth."}]},{"gloss":"to turn out (well, badly …)","art":null,"pl":null,"note":"needs an adverb: gut/schlecht/anders ausfallen","ex":[{"de":"Die Prüfung ist besser {{ausgefallen}}, als ich dachte.","en":"The exam turned out better than I thought."},{"de":"Das Ergebnis der Wahl ist anders {{ausgefallen}}, als die Umfragen vermuten ließen.","en":"The election result turned out differently from what the polls suggested."}]}]},
 {"id":"durchfallen","word":"durchfallen","lv":"B2","tip":"durchfallen (ist durchgefallen) = fail an exam / fall through something / flop with the audience.","meanings":[{"gloss":"to fail (an exam)","art":null,"pl":null,"note":"separable: durch|fallen; ist durchgefallen","ex":[{"de":"Er hat Angst, bei der Prüfung {{durchzufallen}}.","en":"He is afraid of failing the exam."},{"de":"Sie ist schon zweimal in der Fahrprüfung {{durchgefallen}}.","en":"She has already failed the driving test twice."}]},{"gloss":"to fall through","art":null,"pl":null,"note":"separable: durch|fallen; ist durchgefallen","ex":[{"de":"In der Tasche war ein Loch, und die Münze ist einfach {{durchgefallen}}.","en":"There was a hole in the pocket and the coin simply fell through."},{"de":"Die Erbsen sind {{durchgefallen}}, weil die Löcher im Sieb zu groß waren.","en":"The peas fell through because the holes in the sieve were too big."}]},{"gloss":"to flop (play, film)","art":null,"pl":null,"note":"separable: durch|fallen; ist durchgefallen","ex":[{"de":"Das Stück ist beim Publikum {{durchgefallen}}.","en":"The play was a flop with the audience."},{"de":"Der Film ist bei den Kritikern {{durchgefallen}}.","en":"The film was panned by the critics."}]}]},
 {"id":"erschrecken","word":"erschrecken","lv":"B2","tip":"Two verbs: strong, intransitive erschrecken (erschrickt, erschrak, ist erschrocken) = get a fright; weak, transitive erschrecken (erschreckt, hat erschreckt) = frighten someone.","meanings":[{"gloss":"to be startled, get a fright","art":null,"pl":null,"note":"strong, intransitive: erschrickt, erschrak, ist erschrocken","ex":[{"de":"Als der Hund bellte, {{erschrak}} das Kind.","en":"When the dog barked, the child got a fright."},{"de":"Ich bin furchtbar {{erschrocken}}, als das Telefon klingelte.","en":"I got a terrible fright when the phone rang."},{"de":"Sie {{erschrickt}} bei jedem lauten Geräusch.","en":"She is startled by every loud noise."}]},{"gloss":"to frighten (someone)","art":null,"pl":null,"note":"weak, transitive: erschreckt, erschreckte, hat erschreckt","ex":[{"de":"Du hast mich {{erschreckt}}!","en":"You frightened me!"},{"de":"Entschuldige, ich wollte dich nicht {{erschrecken}}.","en":"Sorry, I didn't mean to scare you."}]}]},
 {"id":"aufziehen","word":"aufziehen","lv":"B2","tip":"aufziehen = wind up (clock) / tease / raise (child, animal) / roll in (storm clouds).","meanings":[{"gloss":"to wind up (a clock, a toy)","art":null,"pl":null,"note":"separable: auf|ziehen","ex":[{"de":"Opa muss die alte Uhr jeden Abend {{aufziehen}}.","en":"Grandpa has to wind the old clock every evening."},{"de":"Wenn die Spieluhr stehen bleibt, muss man sie neu {{aufziehen}}.","en":"When the music box stops, you have to wind it up again."}]},{"gloss":"to tease (someone)","art":null,"pl":null,"note":"colloquial; separable: auf|ziehen","ex":[{"de":"Die Klassenkameraden haben ihn wegen seiner neuen Brille {{aufgezogen}}.","en":"His classmates teased him about his new glasses."},{"de":"Hör auf, mich {{aufzuziehen}}, das ist nicht lustig!","en":"Stop teasing me, it isn't funny!"}]},{"gloss":"to raise, bring up (a child, a young animal)","art":null,"pl":null,"note":"separable: auf|ziehen","ex":[{"de":"Sie hat ihre drei Kinder allein {{aufgezogen}}.","en":"She raised her three children alone."},{"de":"Das verwaiste Rehkitz wurde mit der Flasche {{aufgezogen}}.","en":"The orphaned fawn was raised on the bottle."}]},{"gloss":"to approach, roll in (storm, clouds)","art":null,"pl":null,"note":"separable: auf|ziehen; ist aufgezogen","ex":[{"de":"Am Nachmittag ist ein Unwetter {{aufgezogen}}.","en":"A storm rolled in during the afternoon."},{"de":"Im Westen sieht man ein Gewitter {{aufziehen}}.","en":"You can see a thunderstorm gathering in the west."}]}]},
 {"id":"beziehen","word":"beziehen","lv":"B2","tip":"beziehen = put a cover on (bed) / move into (flat) / receive regularly (salary, paper) / sich beziehen auf = refer to. Inseparable: bezieht, bezog, hat bezogen.","meanings":[{"gloss":"to put a cover on (bed linen, upholstery)","art":null,"pl":null,"note":"inseparable: bezieht, bezog, hat bezogen","ex":[{"de":"Ich muss noch das Bett {{beziehen}}, bevor die Gäste kommen.","en":"I still have to make up the bed before the guests arrive."},{"de":"Die Stühle wurden neu mit Leder {{bezogen}}.","en":"The chairs were re-covered with leather."}]},{"gloss":"to move into (a flat, a house)","art":null,"pl":null,"note":"inseparable","ex":[{"de":"Nach der Hochzeit wollen sie eine gemeinsame Wohnung {{beziehen}}.","en":"After the wedding they want to move into a flat together."},{"de":"Die Mieter haben das Haus im April {{bezogen}}.","en":"The tenants moved into the house in April."}]},{"gloss":"to receive regularly, to get (salary, newspaper, goods)","art":null,"pl":null,"note":"inseparable","ex":[{"de":"Er {{bezieht}} eine kleine Rente.","en":"He receives a small pension."},{"de":"Ich {{beziehe}} die Zeitung seit zwanzig Jahren.","en":"I have subscribed to the newspaper for twenty years."}]},{"gloss":"sich beziehen auf: to refer to","art":null,"pl":null,"note":"sich auf etw. beziehen","ex":[{"de":"Auf welchen Absatz {{bezieht}} sich deine Frage?","en":"Which paragraph does your question refer to?"},{"de":"Die Aussage {{bezieht}} sich auf die Zahlen des vergangenen Jahres.","en":"The statement refers to last year's figures."}]}]},
 {"id":"aufgehen","word":"aufgehen","lv":"B2","tip":"aufgehen (ist aufgegangen) = rise (sun, dough) / come open / work out, add up / be absorbed in (in etw. aufgehen).","meanings":[{"gloss":"to rise (sun, dough)","art":null,"pl":null,"note":"separable: auf|gehen","ex":[{"de":"Die Sonne war schon {{aufgegangen}}, als wir losfuhren.","en":"The sun had already risen when we set off."},{"de":"Der Hefeteig muss eine Stunde {{aufgehen}}.","en":"The yeast dough has to rise for an hour."}]},{"gloss":"to come open, come undone","art":null,"pl":null,"note":"separable: auf|gehen","ex":[{"de":"Plötzlich ist die Tür von selbst {{aufgegangen}}.","en":"Suddenly the door opened by itself."},{"de":"Der Knoten wollte einfach nicht {{aufgehen}}.","en":"The knot simply wouldn't come undone."}]},{"gloss":"to work out, add up","art":null,"pl":null,"note":"separable: auf|gehen","ex":[{"de":"Die Division ist ohne Rest {{aufgegangen}}.","en":"The division came out without a remainder."},{"de":"Der Plan der Regierung ist {{aufgegangen}}: Die Wirtschaft wächst wieder.","en":"The government's plan has worked: the economy is growing again."}]},{"gloss":"to be absorbed in (in etw. aufgehen)","art":null,"pl":null,"note":"always with in + Dat.","ex":[{"de":"Er ist ganz in seiner Rolle als Vater {{aufgegangen}}.","en":"He was completely absorbed in his role as a father."},{"de":"Manche Lehrer können in ihrem Beruf richtig {{aufgehen}}.","en":"Some teachers can really lose themselves in their job."}]}]},
 {"id":"bestellen","word":"bestellen","lv":"B2","tip":"bestellen = order / till (a field) / pass on (a message, greetings) / summon (to an appointment).","meanings":[{"gloss":"to order","art":null,"pl":null,"ex":[{"de":"Wir haben zwei Pizzen {{bestellt}}.","en":"We have ordered two pizzas."},{"de":"Kann ich bei Ihnen auch online {{bestellen}}?","en":"Can I also order from you online?"}]},{"gloss":"to till, cultivate (a field)","art":null,"pl":null,"ex":[{"de":"Die Bauern {{bestellen}} im Frühjahr ihre Felder.","en":"The farmers work their fields in spring."},{"de":"Der Acker wurde mit Mais {{bestellt}}.","en":"The field was planted with maize."}]},{"gloss":"to pass on (a message, greetings)","art":null,"pl":null,"ex":[{"de":"{{Bestell}} deiner Mutter schöne Grüße von mir!","en":"Give your mother my best wishes!"},{"de":"Kannst du ihm bitte {{bestellen}}, dass ich später komme?","en":"Can you please tell him that I'll be late?"}]},{"gloss":"to summon, ask to come (appointment)","art":null,"pl":null,"ex":[{"de":"Der Arzt hat mich für Dienstag in die Praxis {{bestellt}}.","en":"The doctor has asked me to come to the practice on Tuesday."},{"de":"Ich bin für Montag um zehn Uhr zum Gespräch {{bestellt}}.","en":"I've been asked to come for an interview on Monday at ten o'clock."}]}]},
 {"id":"ausgeben","word":"ausgeben","lv":"B2","tip":"ausgeben = spend (money) / hand out, issue / sich ausgeben als = pose as.","meanings":[{"gloss":"to spend (money)","art":null,"pl":null,"note":"separable: aus|geben","ex":[{"de":"Sie hat ihr ganzes Geld für Schuhe {{ausgegeben}}.","en":"She spent all her money on shoes."},{"de":"Im Urlaub wollen wir nicht zu viel {{ausgeben}}.","en":"On holiday we don't want to spend too much."}]},{"gloss":"to hand out, issue","art":null,"pl":null,"note":"separable: aus|geben","ex":[{"de":"Am Eingang werden Kopfhörer {{ausgegeben}}.","en":"Headphones are handed out at the entrance."},{"de":"Die Bank hat neue Aktien {{ausgegeben}}.","en":"The bank has issued new shares."}]},{"gloss":"sich ausgeben als: to pose as","art":null,"pl":null,"note":"reflexive, with als","ex":[{"de":"Der Betrüger hat sich als Polizist {{ausgegeben}}.","en":"The fraudster posed as a policeman."},{"de":"Er wollte sich als Arzt {{ausgeben}}, obwohl er nie studiert hatte.","en":"He wanted to pass himself off as a doctor although he had never studied."}]}]},
 {"id":"verlegen","word":"verlegen","lv":"B2","tip":"verlegen (verb) = misplace / move, postpone / lay (cables, tiles); verlegen (adjective, same spelling) = embarrassed, shy.","meanings":[{"gloss":"to misplace, mislay","art":null,"pl":null,"ex":[{"de":"Ich habe meine Brille {{verlegt}} und kann sie nicht finden.","en":"I've mislaid my glasses and can't find them."},{"de":"Wo habe ich nur den Schlüssel {{verlegt}}?","en":"Where on earth did I put the key?"}]},{"gloss":"to move, reschedule","art":null,"pl":null,"ex":[{"de":"Das Treffen wurde auf Donnerstag {{verlegt}}.","en":"The meeting was moved to Thursday."},{"de":"Die Firma will ihren Sitz nach Hamburg {{verlegen}}.","en":"The company wants to move its headquarters to Hamburg."}]},{"gloss":"to lay (cables, tiles, pipes)","art":null,"pl":null,"ex":[{"de":"Der Elektriker muss neue Kabel {{verlegen}}.","en":"The electrician has to lay new cables."},{"de":"Wir lassen im Bad neue Fliesen {{verlegen}}.","en":"We're having new tiles laid in the bathroom."}]},{"gloss":"embarrassed, shy (adjective)","art":null,"pl":null,"note":"adjective, not a verb form here","ex":[{"de":"Sie wurde ganz {{verlegen}}, als alle sie anstarrten.","en":"She became quite embarrassed when everyone stared at her."},{"de":"Mit einem {{verlegenen}} Lächeln nahm er das Lob entgegen.","en":"He accepted the praise with an embarrassed smile."}]}]},
 {"id":"aufstellen","word":"aufstellen","lv":"B2","tip":"aufstellen = set up, erect / nominate, field (a candidate or team) / draw up (list, plan) / set (a record).","meanings":[{"gloss":"to set up, put up (tree, sign)","art":null,"pl":null,"note":"separable: auf|stellen","ex":[{"de":"Die Stadt hat auf dem Marktplatz einen großen Weihnachtsbaum {{aufgestellt}}.","en":"The town has put up a big Christmas tree in the market square."},{"de":"Am Ortseingang wurde ein neues Schild {{aufgestellt}}.","en":"A new sign was put up at the entrance to the village."}]},{"gloss":"to nominate, field (candidate, team)","art":null,"pl":null,"note":"separable: auf|stellen","ex":[{"de":"Die Partei will einen neuen Kandidaten {{aufstellen}}.","en":"The party wants to nominate a new candidate."},{"de":"Der Trainer hat die Mannschaft heute anders {{aufgestellt}}.","en":"The coach has lined up the team differently today."}]},{"gloss":"to draw up (list, plan, budget)","art":null,"pl":null,"note":"separable: auf|stellen","ex":[{"de":"Wir müssen bis Freitag einen Zeitplan {{aufstellen}}.","en":"We have to draw up a schedule by Friday."},{"de":"Sie hat eine Liste aller Teilnehmer {{aufgestellt}}.","en":"She has compiled a list of all participants."}]},{"gloss":"to set (a record)","art":null,"pl":null,"note":"separable: auf|stellen","ex":[{"de":"Er hat einen neuen Weltrekord {{aufgestellt}}.","en":"He has set a new world record."},{"de":"Die Läuferin will in Berlin einen Rekord {{aufstellen}}.","en":"The runner wants to set a record in Berlin."}]}]},
 {"id":"abziehen","word":"abziehen","lv":"B2","tip":"abziehen = deduct / strip (bed linen) / withdraw (troops); intransitively also: drift away (smoke, smell).","meanings":[{"gloss":"to deduct, subtract","art":null,"pl":null,"note":"separable: ab|ziehen","ex":[{"de":"Von dem Preis wird noch der Rabatt {{abgezogen}}.","en":"The discount is still deducted from the price."},{"de":"Die Steuern sind vom Gehalt schon {{abgezogen}}.","en":"The taxes have already been deducted from the salary."}]},{"gloss":"to strip (a bed)","art":null,"pl":null,"note":"separable: ab|ziehen","ex":[{"de":"Am Montag muss ich alle Betten {{abziehen}}.","en":"On Monday I have to strip all the beds."},{"de":"Hast du die Betten schon {{abgezogen}}?","en":"Have you stripped the beds yet?"}]},{"gloss":"to withdraw (troops)","art":null,"pl":null,"note":"separable: ab|ziehen; transitive hat abgezogen, intransitive ist abgezogen","ex":[{"de":"Das Militär will seine Truppen aus dem Gebiet {{abziehen}}.","en":"The military wants to withdraw its troops from the area."},{"de":"Im Mai sind die letzten Soldaten aus dem Land {{abgezogen}}.","en":"In May the last soldiers withdrew from the country."}]},{"gloss":"to drift away, clear (smoke, smell)","art":null,"pl":null,"note":"separable: ab|ziehen; intransitive, ist abgezogen","ex":[{"de":"Der Rauch ist durch das offene Fenster {{abgezogen}}.","en":"The smoke drifted out through the open window."},{"de":"Lass das Fenster offen, damit der Geruch {{abziehen}} kann.","en":"Leave the window open so that the smell can clear."}]}]},
 {"id":"dicht","word":"dicht","lv":"B2","tip":"dicht = dense / watertight, airtight / close (to). dichter Nebel, dichtes Dach, dicht am Wasser.","meanings":[{"gloss":"dense, thick","art":null,"pl":null,"ex":[{"de":"Im {{dichten}} Nebel sieht man kaum fünf Meter weit.","en":"In the dense fog you can hardly see five metres."},{"de":"Der Wald ist hier sehr {{dicht}}.","en":"The forest is very dense here."}]},{"gloss":"watertight, airtight, sealed","art":null,"pl":null,"ex":[{"de":"Das Dach ist nicht mehr {{dicht}}, es regnet durch.","en":"The roof is no longer watertight; the rain comes through."},{"de":"Die Fenster sind schön {{dicht}}, es zieht nicht.","en":"The windows are nicely sealed; there is no draught."}]},{"gloss":"close, right next to","art":null,"pl":null,"ex":[{"de":"Er stand {{dicht}} hinter ihr.","en":"He stood right behind her."},{"de":"Das Haus liegt {{dicht}} am Wasser.","en":"The house is right by the water."}]}]},
 {"id":"trocken","word":"trocken","lv":"B2","tip":"trocken = dry (not wet) / dry (wine, not sweet) / dry, deadpan (humour) / dull, dry (text, lecture).","meanings":[{"gloss":"dry (not wet)","art":null,"pl":null,"ex":[{"de":"Die Wäsche wird an der Sonne schnell {{trocken}}.","en":"The washing dries quickly in the sun."},{"de":"Meine Haut ist im Winter oft sehr {{trocken}}.","en":"My skin is often very dry in winter."}]},{"gloss":"dry (wine, sparkling wine)","art":null,"pl":null,"ex":[{"de":"Ich nehme ein Glas {{trockenen}} Weißwein.","en":"I'll have a glass of dry white wine."},{"de":"Der Sekt ist mir zu süß, ich mag ihn lieber {{trocken}}.","en":"The sparkling wine is too sweet for me; I prefer it dry."}]},{"gloss":"dry, deadpan (humour, remark)","art":null,"pl":null,"note":"","ex":[{"de":"Er hat einen herrlich {{trockenen}} Humor.","en":"He has a wonderfully dry sense of humour."},{"de":"„Na toll“, bemerkte sie {{trocken}}, als es zu regnen begann.","en":"\"Oh great,\" she remarked drily when it started to rain."}]},{"gloss":"dull, dry (text, lecture)","art":null,"pl":null,"note":"","ex":[{"de":"Das Buch ist leider sehr {{trocken}} geschrieben.","en":"Unfortunately the book is written in a very dry style."},{"de":"Der Vortrag war so {{trocken}}, dass einige Zuhörer einschliefen.","en":"The lecture was so dull that some listeners fell asleep."}]}]},
 {"id":"zaeh","word":"zäh","lv":"B2","tip":"zäh = tough (meat) / tenacious (person, will) / sluggish (traffic, talks).","meanings":[{"gloss":"tough, chewy","art":null,"pl":null,"ex":[{"de":"Das Steak war so {{zäh}}, dass ich es kaum kauen konnte.","en":"The steak was so tough that I could hardly chew it."},{"de":"Das Gulasch ist noch zu {{zäh}}, es muss länger kochen.","en":"The goulash is still too tough; it needs to cook longer."}]},{"gloss":"tenacious, resilient","art":null,"pl":null,"ex":[{"de":"Die Bergbauern sind {{zähe}} Menschen, die nicht so schnell aufgeben.","en":"The mountain farmers are tenacious people who don't give up easily."},{"de":"Mit {{zähem}} Willen arbeitete sie sich nach oben.","en":"With tenacious determination she worked her way up."}]},{"gloss":"sluggish, slow-moving","art":null,"pl":null,"ex":[{"de":"Der Verkehr kam nur {{zäh}} voran.","en":"Traffic moved only sluggishly."},{"de":"Die Verhandlungen verliefen {{zäh}}.","en":"The negotiations dragged on."}]}]},
 {"id":"locker","word":"locker","lv":"B2","tip":"locker = loose / relaxed / (colloquial) easily, no problem.","meanings":[{"gloss":"loose","art":null,"pl":null,"ex":[{"de":"Die Schraube ist {{locker}}, sie muss nachgezogen werden.","en":"The screw is loose; it needs tightening."},{"de":"Ihm saß schon ein Zahn {{locker}}.","en":"One of his teeth was already loose."}]},{"gloss":"relaxed, easy-going","art":null,"pl":null,"ex":[{"de":"Der neue Chef ist ganz {{locker}} und lässt uns viel Freiheit.","en":"The new boss is very relaxed and gives us a lot of freedom."},{"de":"Bleib {{locker}}, es ist nur ein Test.","en":"Stay relaxed, it's only a test."}]},{"gloss":"easily, effortlessly (colloquial)","art":null,"pl":null,"note":"colloquial adverb use","ex":[{"de":"Das schaffst du {{locker}} in einer Stunde.","en":"You'll easily manage that in an hour."},{"de":"Er hat die Prüfung {{locker}} bestanden.","en":"He passed the exam with ease."}]}]},
 {"id":"grob","word":"grob","lv":"B2","tip":"grob = coarse / rude / rough, approximate (grobe Schätzung) / gross, serious (grobe Fahrlässigkeit).","meanings":[{"gloss":"coarse (grain, fabric)","art":null,"pl":null,"ex":[{"de":"Das Mehl ist noch zu {{grob}}, wir müssen es noch einmal mahlen.","en":"The flour is still too coarse; we have to grind it again."},{"de":"Aus {{grobem}} Leinen nähte man früher Säcke.","en":"Sacks used to be sewn from coarse linen."}]},{"gloss":"rude, rough (behaviour)","art":null,"pl":null,"ex":[{"de":"Sei nicht so {{grob}} zu deiner kleinen Schwester!","en":"Don't be so rude to your little sister!"},{"de":"Der Türsteher war sehr {{grob}} zu den Gästen.","en":"The bouncer was very rough with the guests."}]},{"gloss":"rough, approximate","art":null,"pl":null,"ex":[{"de":"Ich kann Ihnen nur eine {{grobe}} Schätzung geben.","en":"I can only give you a rough estimate."},{"de":"{{Grob}} gerechnet kostet das 500 Euro.","en":"Roughly calculated, that costs 500 euros."}]},{"gloss":"gross, serious (negligence, error)","art":null,"pl":null,"ex":[{"de":"Dem Fahrer wurde {{grobe}} Fahrlässigkeit vorgeworfen.","en":"The driver was accused of gross negligence."},{"de":"Das war ein {{grober}} Fehler, der die Firma viel Geld gekostet hat.","en":"That was a serious mistake that cost the company a lot of money."}]}]},
 {"id":"glatt","word":"glatt","lv":"B2","tip":"glatt = smooth / slippery / outright, flat out (glatte Lüge, glatt abgelehnt).","meanings":[{"gloss":"smooth","art":null,"pl":null,"ex":[{"de":"Die Haut des Babys ist ganz {{glatt}}.","en":"The baby's skin is perfectly smooth."},{"de":"Der See lag {{glatt}} wie ein Spiegel da.","en":"The lake lay as smooth as a mirror."}]},{"gloss":"slippery, icy","art":null,"pl":null,"ex":[{"de":"Vorsicht, die Straße ist {{glatt}}!","en":"Careful, the road is slippery!"},{"de":"Nach dem Frost waren die Stufen gefährlich {{glatt}}.","en":"After the frost the steps were dangerously slippery."}]},{"gloss":"outright, flat out, completely","art":null,"pl":null,"ex":[{"de":"Das war eine {{glatte}} Lüge.","en":"That was an outright lie."},{"de":"Sie hat den Vorschlag {{glatt}} abgelehnt.","en":"She flatly rejected the proposal."},{"de":"Ich habe den Termin {{glatt}} vergessen.","en":"I clean forgot the appointment."}]}]},
 {"id":"kalt","word":"kalt","lv":"B1","tip":"kalt = cold (temperature) / unfeeling, unmoved / (rent) excluding utilities: '700 Euro kalt'.","meanings":[{"gloss":"cold (temperature)","art":null,"pl":null,"ex":[{"de":"Im Januar ist es hier oft eisig {{kalt}}.","en":"In January it's often icy cold here."},{"de":"Das Wasser im See ist noch viel zu {{kalt}} zum Baden.","en":"The water in the lake is still far too cold for swimming."}]},{"gloss":"cold, unfeeling; unmoved","art":null,"pl":null,"ex":[{"de":"Er sah sie mit {{kaltem}} Blick an.","en":"He looked at her with a cold stare."},{"de":"Das Schicksal der Menschen lässt ihn {{kalt}}.","en":"The people's fate leaves him cold."}]},{"gloss":"excluding heating and utilities (rent)","art":null,"pl":null,"note":"Kaltmiete = base rent; the opposite is 'warm'","ex":[{"de":"Die Wohnung kostet 700 Euro {{kalt}}, mit Nebenkosten 900.","en":"The flat costs 700 euros excluding utilities, 900 including them."},{"de":"Die Miete beträgt 650 Euro {{kalt}}.","en":"The rent is 650 euros before utilities."}]}]},
 {"id":"hart","word":"hart","lv":"B1","tip":"hart = hard (not soft) / harsh, severe / strong (hard liquor, hard drugs).","meanings":[{"gloss":"hard (not soft)","art":null,"pl":null,"ex":[{"de":"Das Brot ist über Nacht ganz {{hart}} geworden.","en":"The bread has gone completely hard overnight."},{"de":"Der Boden war {{hart}} gefroren.","en":"The ground was frozen hard."}]},{"gloss":"harsh, severe","art":null,"pl":null,"ex":[{"de":"Der Richter verhängte eine {{harte}} Strafe.","en":"The judge imposed a harsh sentence."},{"de":"Es war ein {{harter}} Winter mit viel Schnee.","en":"It was a hard winter with a lot of snow."}]},{"gloss":"strong (spirits, drugs)","art":null,"pl":null,"ex":[{"de":"Er trinkt keinen {{harten}} Alkohol.","en":"He doesn't drink hard liquor."},{"de":"Die Polizei warnt vor {{harten}} Drogen.","en":"The police warn against hard drugs."}]}]},
 {"id":"akt","word":"Akt","lv":"C1","tip":"der Akt (pl. Akte) = act of a play; nude (art); formal act, deed. Don't confuse with die Akte (file) – though in Austria der Akt also means 'file'.","meanings":[{"gloss":"act (of a play or opera)","art":"der","pl":"Akte","ex":[{"de":"Im zweiten {{Akt}} stirbt die Heldin.","en":"In the second act the heroine dies."},{"de":"Die Oper hat drei {{Akte}} und dauert fast vier Stunden.","en":"The opera has three acts and lasts almost four hours."}]},{"gloss":"nude (in art)","art":"der","pl":"Akte","ex":[{"de":"Im Kunstkurs zeichnen wir heute einen {{Akt}}.","en":"In the art class today we are drawing a nude."},{"de":"Der Maler ist vor allem für seine {{Akte}} bekannt.","en":"The painter is known above all for his nudes."}]},{"gloss":"act, deed (formal or symbolic)","art":"der","pl":"Akte","ex":[{"de":"Die Zerstörung der Brücke war ein {{Akt}} der Verzweiflung.","en":"The destruction of the bridge was an act of desperation."},{"de":"Die Unterzeichnung war ein symbolischer {{Akt}} der Versöhnung.","en":"The signing was a symbolic act of reconciliation."}]}]},
 {"id":"sprung","word":"Sprung","lv":"C1","tip":"der Sprung (pl. Sprünge) = jump, leap; crack (in a cup, glass).","meanings":[{"gloss":"jump, leap","art":"der","pl":"Sprünge","ex":[{"de":"Mit einem {{Sprung}} setzte er über den Graben.","en":"With one leap he cleared the ditch."},{"de":"Die Turnerin zeigte einen perfekten {{Sprung}}.","en":"The gymnast performed a perfect jump."}]},{"gloss":"crack (in china, glass)","art":"der","pl":"Sprünge","ex":[{"de":"Die Tasse hat einen {{Sprung}}, die benutze ich nicht mehr.","en":"The cup has a crack; I don't use it any more."},{"de":"Im Glas war ein feiner {{Sprung}} zu sehen.","en":"A fine crack was visible in the glass."}]}]},
 {"id":"hang","word":"Hang","lv":"C1","tip":"der Hang = slope (pl. Hänge); inclination, tendency (Hang zu + Dat., no plural).","meanings":[{"gloss":"slope, hillside","art":"der","pl":"Hänge","ex":[{"de":"Der {{Hang}} hinter dem Haus ist so steil, dass man dort nicht mähen kann.","en":"The slope behind the house is so steep that you can't mow it."},{"de":"Die Reben wachsen an einem sonnigen {{Hang}}.","en":"The vines grow on a sunny hillside."}]},{"gloss":"inclination, tendency (zu + Dat.)","art":"der","pl":"","note":"usually singular; Hang zu + Dat.","ex":[{"de":"Er hat einen starken {{Hang}} zur Übertreibung.","en":"He has a strong tendency to exaggerate."},{"de":"Ihr {{Hang}} zum Perfektionismus macht sie unzufrieden.","en":"Her tendency towards perfectionism makes her dissatisfied."}]}]},
 {"id":"tenor","word":"Tenor","lv":"C1","tip":"der Tenor = tenor (voice, singer; pl. Tenöre; stress te-NOR); gist, general tone of a text or discussion (no plural; stress TE-nor).","meanings":[{"gloss":"tenor (singer or voice)","art":"der","pl":"Tenöre","ex":[{"de":"In der Oper sang ein junger {{Tenor}} die Hauptrolle.","en":"A young tenor sang the lead role in the opera."},{"de":"Die {{Tenöre}} des Chors hatten ihren Einsatz verpasst.","en":"The tenors of the choir had missed their entry."}]},{"gloss":"gist, general tone","art":"der","pl":"","note":"no plural in this sense","ex":[{"de":"Der {{Tenor}} der Kommentare war eindeutig: Die Reform geht zu weit.","en":"The gist of the commentaries was clear: the reform goes too far."},{"de":"Der {{Tenor}} seiner Rede war versöhnlich.","en":"The overall tone of his speech was conciliatory."}]}]},
 {"id":"mandat","word":"Mandat","lv":"C1","tip":"das Mandat (pl. Mandate) = seat in a parliament; mandate, authorisation (UN mandate, a lawyer's mandate).","meanings":[{"gloss":"seat in a parliament","art":"das","pl":"Mandate","ex":[{"de":"Die Partei gewann bei der Wahl drei zusätzliche {{Mandate}}.","en":"The party won three additional seats in the election."},{"de":"Er hat sein {{Mandat}} im Parlament niedergelegt.","en":"He has resigned his seat in parliament."}]},{"gloss":"mandate, authorisation (to act on someone's behalf)","art":"das","pl":"Mandate","ex":[{"de":"Die Mission hat ein {{Mandat}} der Vereinten Nationen.","en":"The mission has a mandate from the United Nations."},{"de":"Ohne ein klares {{Mandat}} darf das Militär nicht eingreifen.","en":"Without a clear mandate the military may not intervene."}]}]},
 {"id":"schlag","word":"Schlag","lv":"C1","tip":"der Schlag (pl. Schläge) = blow; electric shock ('einen Schlag bekommen'); sort, type (of person: 'von altem Schlag').","meanings":[{"gloss":"blow, hit","art":"der","pl":"Schläge","ex":[{"de":"Der Boxer landete einen harten {{Schlag}} am Kinn.","en":"The boxer landed a hard blow on the chin."},{"de":"Mit einem einzigen {{Schlag}} zertrümmerte er die Scheibe.","en":"With a single blow he smashed the pane."}]},{"gloss":"electric shock","art":"der","pl":"Schläge","ex":[{"de":"Wer den Draht berührt, bekommt einen {{Schlag}}.","en":"Anyone who touches the wire gets a shock."},{"de":"Ich habe beim Auswechseln der Lampe einen elektrischen {{Schlag}} bekommen.","en":"I got an electric shock when I was changing the bulb."}]},{"gloss":"sort, type (of person)","art":"der","pl":"","note":"mostly in phrases like 'von altem Schlag'","ex":[{"de":"Der Lehrer war ein Mann von altem {{Schlag}}.","en":"The teacher was a man of the old school."},{"de":"Mit Menschen dieses {{Schlages}} möchte ich nichts zu tun haben.","en":"I want nothing to do with people of that sort."}]}]},
 {"id":"ladung","word":"Ladung","lv":"C1","tip":"die Ladung (pl. Ladungen) = cargo; (electric) charge; court summons.","meanings":[{"gloss":"load, cargo","art":"die","pl":"Ladungen","ex":[{"de":"Der Lkw verlor unterwegs seine ganze {{Ladung}}.","en":"The lorry lost its entire load on the way."},{"de":"Das Schiff hatte eine {{Ladung}} Kohle an Bord.","en":"The ship had a cargo of coal on board."}]},{"gloss":"(electric) charge","art":"die","pl":"Ladungen","ex":[{"de":"Jedes Proton trägt eine positive elektrische {{Ladung}}.","en":"Every proton carries a positive electric charge."},{"de":"Die {{Ladung}} des Akkus reicht für zwei Tage.","en":"The charge of the battery lasts for two days."}]},{"gloss":"(court) summons","art":"die","pl":"Ladungen","ex":[{"de":"Wer der {{Ladung}} des Gerichts nicht Folge leistet, muss mit einer Geldstrafe rechnen.","en":"Anyone who ignores the court's summons must expect a fine."},{"de":"Die {{Ladung}} zum Gerichtstermin kam per Post.","en":"The summons to the hearing came by post."}]}]},
 {"id":"zuschlag","word":"Zuschlag","lv":"C1","tip":"der Zuschlag (pl. Zuschläge) = surcharge, supplement; award of a contract / knock-down at an auction ('den Zuschlag erhalten').","meanings":[{"gloss":"surcharge, supplement","art":"der","pl":"Zuschläge","ex":[{"de":"Für den Schnellzug muss man einen {{Zuschlag}} bezahlen.","en":"For the express train you have to pay a supplement."},{"de":"Nachtarbeit wird mit einem {{Zuschlag}} von 25 Prozent vergütet.","en":"Night work is paid with a 25 percent supplement."}]},{"gloss":"award (of a contract); knock-down (auction)","art":"der","pl":"Zuschläge","ex":[{"de":"Bei der Auktion erhielt ein Sammler aus Köln den {{Zuschlag}}.","en":"At the auction the lot was knocked down to a collector from Cologne."},{"de":"Den {{Zuschlag}} für den Bau erhielt eine österreichische Firma.","en":"The contract for the construction was awarded to an Austrian firm."}]}]},
 {"id":"auflage","word":"Auflage","lv":"C1","tip":"die Auflage (pl. Auflagen) = edition / print run, circulation; condition imposed by an authority or court.","meanings":[{"gloss":"edition; print run, circulation","art":"die","pl":"Auflagen","ex":[{"de":"Das Buch erscheint in einer überarbeiteten {{Auflage}}.","en":"The book is appearing in a revised edition."},{"de":"Die Zeitung hat eine tägliche {{Auflage}} von 200.000 Exemplaren.","en":"The newspaper has a daily circulation of 200,000 copies."}]},{"gloss":"condition, requirement (imposed)","art":"die","pl":"Auflagen","ex":[{"de":"Die Genehmigung ist an strenge {{Auflagen}} gebunden.","en":"The permit is tied to strict conditions."},{"de":"Das Gericht erteilte ihm die {{Auflage}}, jeden Monat bei der Polizei zu erscheinen.","en":"The court ordered him to report to the police every month."}]}]},
 {"id":"lauf","word":"Lauf","lv":"C1","tip":"der Lauf (pl. Läufe) = run, race; course (of time, events, a river; no plural); barrel of a gun.","meanings":[{"gloss":"run, race, heat","art":"der","pl":"Läufe","ex":[{"de":"Sie gewann den {{Lauf}} über 800 Meter.","en":"She won the 800-metre race."},{"de":"Im ersten {{Lauf}} wurde er Dritter.","en":"In the first heat he came third."}]},{"gloss":"course (of time, events, a river)","art":"der","pl":"","note":"mostly singular in this sense","ex":[{"de":"Im {{Lauf}} der Jahre hat sich die Stadt stark verändert.","en":"Over the years the town has changed a lot."},{"de":"Man kann den {{Lauf}} der Dinge nicht aufhalten.","en":"You can't stop the course of events."}]},{"gloss":"barrel (of a gun)","art":"der","pl":"Läufe","ex":[{"de":"Der {{Lauf}} des Gewehrs muss regelmäßig gereinigt werden.","en":"The barrel of the rifle has to be cleaned regularly."},{"de":"Der Jäger richtete den {{Lauf}} auf den Boden.","en":"The hunter pointed the barrel at the ground."}]}]},
 {"id":"fuge","word":"Fuge","lv":"C1","tip":"die Fuge (pl. Fugen) = joint, gap, seam ('aus den Fugen geraten'); fugue (music).","meanings":[{"gloss":"joint, gap, seam","art":"die","pl":"Fugen","ex":[{"de":"Die {{Fugen}} zwischen den Fliesen müssen neu verfugt werden.","en":"The joints between the tiles need regrouting."},{"de":"Das Wasser drang durch eine {{Fuge}} im Mauerwerk.","en":"Water came in through a gap in the masonry."},{"de":"Seit dem Unfall ist sein Leben aus den {{Fugen}} geraten.","en":"Since the accident his life has come apart at the seams."}]},{"gloss":"fugue (music)","art":"die","pl":"Fugen","ex":[{"de":"Die Organistin spielte eine vierstimmige {{Fuge}}.","en":"The organist played a four-part fugue."},{"de":"In einer {{Fuge}} setzen die Stimmen nacheinander mit demselben Thema ein.","en":"In a fugue the voices enter one after another with the same theme."}]}]},
 {"id":"muster","word":"Muster","lv":"C1","tip":"das Muster (pl. Muster) = pattern; sample (of goods); model, paragon ('ein Muster an Fleiß').","meanings":[{"gloss":"pattern","art":"das","pl":"Muster","ex":[{"de":"Das Kleid hat ein buntes {{Muster}} aus Blumen.","en":"The dress has a colourful floral pattern."},{"de":"Im Verhalten der Kunden erkennt man ein bestimmtes {{Muster}}.","en":"A certain pattern can be recognised in the customers' behaviour."}]},{"gloss":"sample (of goods)","art":"das","pl":"Muster","ex":[{"de":"Bitte schicken Sie uns ein {{Muster}} des Stoffes, damit wir die Qualität prüfen können.","en":"Please send us a sample of the fabric so that we can check the quality."},{"de":"Die Firma verteilt kostenlose {{Muster}} ihrer neuen Creme.","en":"The company hands out free samples of its new cream."}]},{"gloss":"model, paragon (ein Muster an …)","art":"das","pl":"Muster","ex":[{"de":"Sie ist ein {{Muster}} an Pünktlichkeit.","en":"She is a model of punctuality."},{"de":"Er galt als ein {{Muster}} an Fleiß und Disziplin.","en":"He was regarded as a paragon of diligence and discipline."}]}]},
 {"id":"wurf","word":"Wurf","lv":"C1","tip":"der Wurf (pl. Würfe) = throw; litter (of young animals).","meanings":[{"gloss":"throw","art":"der","pl":"Würfe","ex":[{"de":"Mit einem weiten {{Wurf}} erreichte sie das Ziel.","en":"With a long throw she reached the target."},{"de":"Der Speer landete nach einem {{Wurf}} von 80 Metern im Gras.","en":"The javelin landed in the grass after a throw of 80 metres."}]},{"gloss":"litter (of young animals)","art":"der","pl":"Würfe","ex":[{"de":"Die Hündin hat einen {{Wurf}} von sechs Welpen.","en":"The female dog has a litter of six puppies."},{"de":"Aus dem ersten {{Wurf}} bleiben zwei Kätzchen bei uns.","en":"Two kittens from the first litter are staying with us."}]}]},
 {"id":"lager","word":"Lager","lv":"C1","tip":"das Lager (pl. Lager) = camp (also political camp); warehouse, stock ('auf Lager'); bearing (technical).","meanings":[{"gloss":"camp (also a political camp)","art":"das","pl":"Lager","ex":[{"de":"Die Flüchtlinge lebten monatelang in einem {{Lager}}.","en":"The refugees lived in a camp for months."},{"de":"Beide politischen {{Lager}} lehnten den Vorschlag ab.","en":"Both political camps rejected the proposal."}]},{"gloss":"warehouse, storeroom; stock","art":"das","pl":"Lager (in commerce also: Läger)","ex":[{"de":"Die Ware liegt noch im {{Lager}}.","en":"The goods are still in the warehouse."},{"de":"Dieser Artikel ist leider nicht mehr auf {{Lager}}.","en":"Unfortunately this item is no longer in stock."}]},{"gloss":"bearing (technical)","art":"das","pl":"Lager","ex":[{"de":"Das Rad quietscht, weil das {{Lager}} trocken ist.","en":"The wheel squeaks because the bearing is dry."},{"de":"Das {{Lager}} der Welle muss ausgetauscht werden.","en":"The bearing of the shaft has to be replaced."}]}]},
 {"id":"verfallen","word":"verfallen","lv":"C1","tip":"verfallen (verfällt, verfiel, ist verfallen) = fall into decay / expire, lapse / become addicted to (+ Dat.).","meanings":[{"gloss":"to decay, fall into ruin","art":null,"pl":null,"note":"inseparable; ist verfallen","ex":[{"de":"Wegen fehlender Pflege ist das Kloster nach und nach {{verfallen}}.","en":"For lack of maintenance the monastery has gradually fallen into ruin."},{"de":"Das Schloss lässt man seit Jahren {{verfallen}}.","en":"The castle has been left to decay for years."}]},{"gloss":"to expire, lapse","art":null,"pl":null,"note":"inseparable; ist verfallen","ex":[{"de":"Der Gutschein ist leider schon vor drei Monaten {{verfallen}}.","en":"Unfortunately the voucher expired three months ago."},{"de":"Die Eintrittskarten {{verfallen}}, wenn man sie nicht bis Freitag abholt.","en":"The tickets lapse if you don't collect them by Friday."}]},{"gloss":"to become addicted to, fall under the spell of (+ Dat.)","art":null,"pl":null,"note":"verfallen + Dat.","ex":[{"de":"Er ist dem Glücksspiel völlig {{verfallen}}.","en":"He is completely addicted to gambling."},{"de":"Sie ist dem Charme des Südens {{verfallen}}.","en":"She has fallen under the spell of the South."}]}]},
 {"id":"ansetzen","word":"ansetzen","lv":"C1","tip":"ansetzen = schedule / begin, get ready to (zu etw. ansetzen) / develop, put on (Rost, Fett) / reckon, budget.","meanings":[{"gloss":"to schedule, set (a date)","art":null,"pl":null,"note":"separable: an|setzen","ex":[{"de":"Das Gericht hat die Verhandlung für den 12. März {{angesetzt}}.","en":"The court has scheduled the hearing for 12 March."},{"de":"Die Sitzung wurde kurzfristig für Montag {{angesetzt}}.","en":"The meeting was scheduled at short notice for Monday."}]},{"gloss":"to prepare to, set about (zu etw. ansetzen)","art":null,"pl":null,"note":"separable: an|setzen; usually with zu (zum Sprung ansetzen; ansetzen, etwas zu sagen)","ex":[{"de":"Der Radfahrer wollte gerade zum Überholen {{ansetzen}}.","en":"The cyclist was just about to overtake."},{"de":"Er holte tief Luft, um zu einer Antwort {{anzusetzen}}.","en":"He took a deep breath to begin an answer."}]},{"gloss":"to develop, put on (rust, fat)","art":null,"pl":null,"note":"separable: an|setzen","ex":[{"de":"Das alte Fahrrad hat im Keller Rost {{angesetzt}}.","en":"The old bicycle has gathered rust in the cellar."},{"de":"Er hat in den letzten Monaten ordentlich Speck {{angesetzt}}.","en":"He has put on quite a bit of weight in recent months."}]},{"gloss":"to allow, budget (a sum)","art":null,"pl":null,"note":"separable: an|setzen","ex":[{"de":"Für die Reparatur würde ich etwa 500 Euro {{ansetzen}}.","en":"For the repair I would reckon about 500 euros."},{"de":"Die Kosten wurden viel zu niedrig {{angesetzt}}.","en":"The costs were set far too low."}]}]},
 {"id":"entnehmen","word":"entnehmen","lv":"C1","tip":"entnehmen = take (out of: + Dat. or aus + Dat.) / gather, infer from (+ Dat.). Inseparable: entnimmt, entnahm, entnommen.","meanings":[{"gloss":"to take (out of)","art":null,"pl":null,"note":"inseparable: entnimmt, entnahm, entnommen","ex":[{"de":"Aus der Schublade {{entnahm}} er einen Umschlag.","en":"He took an envelope out of the drawer."},{"de":"Die Ärztin hat dem Patienten Blut {{entnommen}}.","en":"The doctor took blood from the patient."}]},{"gloss":"to gather, infer (from)","art":null,"pl":null,"note":"einer Sache (Dat.) etwas entnehmen, e.g. 'dem Brief entnehmen, dass …'; also aus + Dat.","ex":[{"de":"Ihrem Brief {{entnehme}} ich, dass Sie noch in Berlin sind.","en":"From your letter I gather that you are still in Berlin."},{"de":"Aus den Zahlen ist zu {{entnehmen}}, dass die Umsätze sinken.","en":"It can be seen from the figures that sales are falling."}]}]},
 {"id":"zusagen","word":"zusagen","lv":"C1","tip":"zusagen = promise, give a firm yes (also: accept an invitation) / appeal to, suit (+ Dat.).","meanings":[{"gloss":"to promise, commit to; (without object) to accept an invitation","art":null,"pl":null,"note":"separable: zu|sagen; jdm. etw. zusagen = to promise; without object = to accept (an invitation)","ex":[{"de":"Alle Gäste haben schon {{zugesagt}}.","en":"All the guests have already accepted."},{"de":"Der Chef hat uns seine Unterstützung {{zugesagt}}.","en":"The boss has promised us his support."}]},{"gloss":"to appeal to, suit (+ Dat.)","art":null,"pl":null,"note":"separable: zu|sagen; with Dat.","ex":[{"de":"Die Wohnung hat uns auf Anhieb {{zugesagt}}.","en":"The flat appealed to us straight away."},{"de":"Das Konzept scheint ihm nicht {{zuzusagen}}.","en":"The concept doesn't seem to appeal to him."}]}]},
 {"id":"zustellen","word":"zustellen","lv":"C1","tip":"zustellen (separable: stellt ... zu) = deliver (post, parcels) / block with furniture or things.","meanings":[{"gloss":"to deliver (mail, parcels, documents)","art":null,"pl":null,"note":"separable: zu|stellen","ex":[{"de":"Die Post wird täglich vor zehn Uhr {{zugestellt}}.","en":"The post is delivered every day before ten o'clock."},{"de":"Der Kurier konnte das Paket nicht {{zustellen}}, weil niemand zu Hause war.","en":"The courier could not deliver the parcel because nobody was home."}]},{"gloss":"to block, clutter (with furniture, things)","art":null,"pl":null,"note":"separable: zu|stellen","ex":[{"de":"Der Nachbar hat die Einfahrt mit Mülltonnen völlig {{zugestellt}}.","en":"The neighbour has completely blocked the driveway with bins."},{"de":"Wir haben den Flur mit Kartons {{zugestellt}}.","en":"We've cluttered the hallway with boxes."}]}]},
 {"id":"brechen","word":"brechen","lv":"C1","tip":"brechen = break (bone, branch, promise, record) / vomit (colloquial) / refract (light, physics).","meanings":[{"gloss":"to break (bone, branch, promise, record)","art":null,"pl":null,"note":"breaks something: hat gebrochen; breaks by itself: ist gebrochen","ex":[{"de":"Beim Skifahren hat er sich das Bein {{gebrochen}}.","en":"He broke his leg while skiing."},{"de":"Der Ast ist unter der Last des Schnees {{gebrochen}}.","en":"The branch broke under the weight of the snow."},{"de":"Sie hat ihr Versprechen {{gebrochen}}.","en":"She has broken her promise."}]},{"gloss":"to vomit","art":null,"pl":null,"note":"colloquial; formal: sich übergeben / sich erbrechen","ex":[{"de":"Dem Kind war so schlecht, dass es in der Nacht zweimal {{gebrochen}} hat.","en":"The child felt so sick that it vomited twice during the night."},{"de":"Er musste auf der Überfahrt ständig {{brechen}}.","en":"He had to be sick all the time during the crossing."}]},{"gloss":"to refract (light)","art":null,"pl":null,"note":"physics; also reflexive: das Licht bricht sich","ex":[{"de":"Im Wasser {{bricht}} sich das Licht, deshalb sieht der Stab geknickt aus.","en":"Light is refracted in water, which is why the stick looks bent."},{"de":"Beim Übergang von Luft in Glas wird das Licht {{gebrochen}}.","en":"Light is refracted when it passes from air into glass."}]}]},
 {"id":"scheren","word":"scheren","lv":"C1","tip":"Two verbs: strong scheren (schor, geschoren) = shear, clip; weak scheren (scherte, geschert) = concern, bother (Das schert mich nicht).","meanings":[{"gloss":"to shear, clip","art":null,"pl":null,"note":"strong: schor, hat geschoren","ex":[{"de":"Im Frühjahr werden die Schafe {{geschoren}}.","en":"In spring the sheep are shorn."},{"de":"Der Friseur {{schor}} dem Soldaten den Kopf.","en":"The barber shaved the soldier's head."}]},{"gloss":"to concern, bother","art":null,"pl":null,"note":"weak: schert, scherte, hat geschert; mostly negative","ex":[{"de":"Was andere denken, {{schert}} mich nicht.","en":"I don't care what others think."},{"de":"Er hat sich nie darum {{geschert}}, was die Nachbarn sagen.","en":"He has never cared what the neighbours say."}]}]},
 {"id":"erheben","word":"erheben","lv":"C1","tip":"erheben = raise (glass, hand) / levy (fees, taxes) / bring (charges, objections: Anklage erheben) / sich erheben = rise up, rebel.","meanings":[{"gloss":"to raise, lift","art":null,"pl":null,"note":"inseparable: erhebt, erhob, hat erhoben","ex":[{"de":"Er {{erhob}} sein Glas und trank auf das Brautpaar.","en":"He raised his glass and drank to the bride and groom."},{"de":"Die Zeugin {{erhob}} die Hand zum Schwur.","en":"The witness raised her hand to take the oath."}]},{"gloss":"to levy, charge (fees, taxes)","art":null,"pl":null,"ex":[{"de":"Die Gemeinde {{erhebt}} eine Gebühr für die Nutzung.","en":"The municipality levies a fee for the use."},{"de":"In vielen Städten wird eine Steuer auf Hunde {{erhoben}}.","en":"In many towns a tax is levied on dogs."}]},{"gloss":"to bring (charges, objections)","art":null,"pl":null,"ex":[{"de":"Die Staatsanwaltschaft hat Anklage {{erhoben}}.","en":"The public prosecutor's office has brought charges."},{"de":"Die Anwohner {{erhoben}} Einspruch gegen den Bau.","en":"The residents lodged an objection to the construction."}]},{"gloss":"sich erheben: to rise up, rebel","art":null,"pl":null,"note":"reflexive","ex":[{"de":"Die Bauern {{erhoben}} sich gegen ihre Grundherren.","en":"The peasants rose up against their landlords."},{"de":"Das Volk {{erhob}} sich gegen den Diktator.","en":"The people rose up against the dictator."}]}]},
 {"id":"ergeben","word":"ergeben","lv":"C1","tip":"ergeben = yield, result in (Zwei mal drei ergibt sechs) / sich ergeben: surrender / sich ergeben: arise, come about.","meanings":[{"gloss":"to surrender (sich ergeben)","art":null,"pl":null,"note":"reflexive: sich ergeben, ergab sich, hat sich ergeben","ex":[{"de":"Nach langem Kampf {{ergab}} sich die Festung.","en":"After a long struggle the fortress surrendered."},{"de":"Die Soldaten mussten sich dem Feind {{ergeben}}.","en":"The soldiers had to surrender to the enemy."}]},{"gloss":"to yield, amount to, show (results)","art":null,"pl":null,"ex":[{"de":"Zwei mal drei {{ergibt}} sechs.","en":"Two times three makes six."},{"de":"Die Untersuchung hat keinen Hinweis auf eine Straftat {{ergeben}}.","en":"The investigation yielded no indication of a crime."}]},{"gloss":"(sich) ergeben: to arise, come about","art":null,"pl":null,"note":"reflexive","ex":[{"de":"Es hat sich so {{ergeben}}, dass wir uns ein Jahr später wiedersahen.","en":"It so happened that we saw each other again a year later."},{"de":"Aus dem Zufall {{ergab}} sich eine Freundschaft.","en":"A friendship arose from the coincidence."}]}]},
 {"id":"einraeumen","word":"einräumen","lv":"C1","tip":"einräumen = put away (furniture, dishes) / concede, admit / grant (a right, time).","meanings":[{"gloss":"to put away, put in (shelf, cupboard, dishwasher)","art":null,"pl":null,"note":"separable: ein|räumen","ex":[{"de":"Sie hat die Bücher ins Regal {{eingeräumt}}.","en":"She put the books away on the shelf."},{"de":"Nach dem Einkauf muss ich noch die Spülmaschine {{einräumen}}.","en":"After shopping I still have to load the dishwasher."}]},{"gloss":"to concede, admit","art":null,"pl":null,"note":"separable: ein|räumen","ex":[{"de":"Der Zeuge musste {{einräumen}}, dass er sich geirrt hatte.","en":"The witness had to concede that he had been mistaken."},{"de":"Er hat seinen Irrtum offen {{eingeräumt}}.","en":"He openly admitted his mistake."}]},{"gloss":"to grant (a right, a deadline)","art":null,"pl":null,"note":"separable: ein|räumen","ex":[{"de":"Die Bank hat uns eine Frist von drei Monaten {{eingeräumt}}.","en":"The bank has granted us a deadline of three months."},{"de":"Dem Mieter wurde ein Vorkaufsrecht {{eingeräumt}}.","en":"The tenant was granted a right of first refusal."}]}]},
 {"id":"vorlegen","word":"vorlegen","lv":"C1","tip":"vorlegen = submit, present / advance (money) / set (a pace).","meanings":[{"gloss":"to submit, present (documents, a bill)","art":null,"pl":null,"note":"separable: vor|legen","ex":[{"de":"Sie müssen bei der Anmeldung Ihren Ausweis {{vorlegen}}.","en":"You must present your ID at registration."},{"de":"Die Ministerin hat dem Parlament einen Gesetzentwurf {{vorgelegt}}.","en":"The minister has submitted a bill to parliament."}]},{"gloss":"to advance (money)","art":null,"pl":null,"note":"separable: vor|legen; informal (= auslegen, vorstrecken)","ex":[{"de":"Ich kann die Reisekosten erst einmal {{vorlegen}}, du zahlst mir das Geld später zurück.","en":"I can advance the travel costs first; you pay me back later."},{"de":"Der Verein hat das Geld für die Busse {{vorgelegt}}.","en":"The club advanced the money for the buses."}]},{"gloss":"to set (a pace)","art":null,"pl":null,"note":"separable: vor|legen","ex":[{"de":"Gleich nach dem Start wollte der Favorit ein hohes Tempo {{vorlegen}}.","en":"Right after the start the favourite wanted to set a high pace."},{"de":"Die Gastgeber haben ein hohes Tempo {{vorgelegt}} und führten schon nach zehn Minuten.","en":"The hosts set a fast pace and were already leading after ten minutes."}]}]},
 {"id":"aufbringen","word":"aufbringen","lv":"C1","tip":"aufbringen = come up with (money, patience, courage) / infuriate (aufgebracht = furious) / apply (a layer, paint).","meanings":[{"gloss":"to come up with, raise (money); to summon up (patience, courage)","art":null,"pl":null,"note":"separable: auf|bringen","ex":[{"de":"Die Familie konnte die 5000 Euro nicht {{aufbringen}}.","en":"The family could not raise the 5,000 euros."},{"de":"Dafür muss man viel Geduld {{aufbringen}}.","en":"For that you have to summon up a lot of patience."}]},{"gloss":"to infuriate, anger","art":null,"pl":null,"note":"separable: auf|bringen; adjective: aufgebracht = furious","ex":[{"de":"Seine Bemerkung hat sie furchtbar {{aufgebracht}}.","en":"His remark made her furious."},{"de":"Die Entscheidung hat die Anwohner sehr {{aufgebracht}}.","en":"The decision has greatly angered the residents."}]},{"gloss":"to apply (a layer, paint)","art":null,"pl":null,"note":"separable: auf|bringen","ex":[{"de":"Der Maler hat zuerst die Grundierung {{aufgebracht}}.","en":"The painter first applied the primer."},{"de":"Die Folie muss gleichmäßig {{aufgebracht}} werden.","en":"The film has to be applied evenly."}]}]},
 {"id":"anschlagen","word":"anschlagen","lv":"C1","tip":"anschlagen (schlägt an, schlug an, angeschlagen) = post up (notice) / take effect (medicine) / chip (crockery) / bark (dog).","meanings":[{"gloss":"to post up (a notice)","art":null,"pl":null,"note":"separable: an|schlagen","ex":[{"de":"Die Termine wurden am Schwarzen Brett {{angeschlagen}}.","en":"The dates were posted on the notice board."},{"de":"Das Plakat wurde an allen Litfaßsäulen {{angeschlagen}}.","en":"The poster was put up on all advertising columns."}]},{"gloss":"to take effect, work (medicine, diet)","art":null,"pl":null,"note":"separable: an|schlagen","ex":[{"de":"Die Medikamente haben endlich {{angeschlagen}}.","en":"The medication has finally taken effect."},{"de":"Die Diät will bei ihm einfach nicht {{anschlagen}}.","en":"The diet just won't work for him."}]},{"gloss":"to chip (crockery)","art":null,"pl":null,"note":"separable: an|schlagen; mostly as participle: angeschlagen","ex":[{"de":"Der Teller ist am Rand leicht {{angeschlagen}}.","en":"The plate is slightly chipped at the rim."},{"de":"Beim Abspülen habe ich eine Tasse {{angeschlagen}}.","en":"I chipped a cup while washing up."}]},{"gloss":"to bark (dog)","art":null,"pl":null,"note":"separable: an|schlagen","ex":[{"de":"Der Wachhund hat laut {{angeschlagen}}, als jemand am Tor stand.","en":"The guard dog barked loudly when someone was at the gate."},{"de":"Nachts hörte man den Hund immer wieder {{anschlagen}}.","en":"At night you could hear the dog bark again and again."}]}]},
 {"id":"durchsetzen","word":"durchsetzen","lv":"C1","tip":"durchsetzen (separable, stress DURCH: setzt ... durch; durchgesetzt) = enforce, push through; durchsetzen (inseparable: durchsetzt) = to be riddled/infiltrated with.","meanings":[{"gloss":"to enforce, push through; sich durchsetzen = to prevail","art":null,"pl":null,"note":"separable: durch|setzen; Partizip durchgesetzt","ex":[{"de":"Er konnte seine Forderungen nicht {{durchsetzen}}.","en":"He could not push through his demands."},{"de":"Die Gewerkschaft hat höhere Löhne {{durchgesetzt}}.","en":"The union has pushed through higher wages."},{"de":"Wer sich nicht {{durchsetzen}} kann, hat es im Beruf schwer.","en":"Anyone who can't assert themselves has a hard time at work."}]},{"gloss":"to be interspersed, infiltrated (with)","art":null,"pl":null,"note":"inseparable: durchsetzen (stress on -SET-); Partizip durchsetzt; mostly as participle","ex":[{"de":"Die Organisation war mit Spitzeln {{durchsetzt}}.","en":"The organisation was riddled with informers."},{"de":"Der Text ist mit Fachbegriffen {{durchsetzt}}.","en":"The text is peppered with technical terms."}]}]},
 {"id":"umstellen","word":"umstellen","lv":"C1","tip":"umstellen: separable (UMstellen, stellt ... um) = rearrange, switch over; inseparable (umSTELLen, umstellt) = surround.","meanings":[{"gloss":"to rearrange; to switch over","art":null,"pl":null,"note":"separable: um|stellen; Partizip umgestellt","ex":[{"de":"Wir haben das Wohnzimmer {{umgestellt}}: Das Sofa steht jetzt am Fenster.","en":"We've rearranged the living room: the sofa is now by the window."},{"de":"Die Firma will auf Ökostrom {{umstellen}}.","en":"The company wants to switch to green electricity."}]},{"gloss":"to surround, encircle","art":null,"pl":null,"note":"inseparable: umstellen (stress on -STELL-); Partizip umstellt","ex":[{"de":"Die Polizei hat das Gebäude {{umstellt}}.","en":"The police have surrounded the building."},{"de":"Das Haus war von Journalisten {{umstellt}}.","en":"The house was surrounded by journalists."}]}]},
 {"id":"umschreiben","word":"umschreiben","lv":"C1","tip":"umschreiben: separable (UMschreiben, schreibt ... um) = rewrite; inseparable (umSCHREIben, umschreibt) = paraphrase.","meanings":[{"gloss":"to rewrite","art":null,"pl":null,"note":"separable: um|schreiben; Partizip umgeschrieben","ex":[{"de":"Der Autor musste das letzte Kapitel noch einmal {{umschreiben}}.","en":"The author had to rewrite the last chapter once more."},{"de":"Sie hat die Rede komplett {{umgeschrieben}}.","en":"She has completely rewritten the speech."}]},{"gloss":"to paraphrase, describe indirectly","art":null,"pl":null,"note":"inseparable: umschreiben (stress on -SCHREI-); Partizip umschrieben","ex":[{"de":"Er {{umschrieb}} das Problem vorsichtig, ohne es beim Namen zu nennen.","en":"He described the problem cautiously, without naming it."},{"de":"Wenn du das Wort nicht kennst, musst du es {{umschreiben}}.","en":"If you don't know the word, you have to paraphrase it."}]}]},
 {"id":"ausschlagen","word":"ausschlagen","lv":"C1","tip":"ausschlagen (schlägt aus, schlug aus, ausgeschlagen) = decline (offer, inheritance) / kick out (horse) / swing, deflect (needle) / sprout.","meanings":[{"gloss":"to decline, turn down","art":null,"pl":null,"note":"separable: aus|schlagen","ex":[{"de":"Er hat das Angebot der Firma {{ausgeschlagen}}.","en":"He turned down the firm's offer."},{"de":"Sie hat das Erbe {{ausgeschlagen}}, weil darauf Schulden lagen.","en":"She renounced the inheritance because it came with debts."}]},{"gloss":"to kick out (horse)","art":null,"pl":null,"note":"separable: aus|schlagen","ex":[{"de":"Das Pferd begann plötzlich nach hinten {{auszuschlagen}}.","en":"The horse suddenly began to kick out backwards."},{"de":"Der Esel hat mit den Hinterbeinen {{ausgeschlagen}}.","en":"The donkey kicked with its hind legs."}]},{"gloss":"to swing, deflect (needle, pendulum)","art":null,"pl":null,"note":"separable: aus|schlagen","ex":[{"de":"Die Nadel des Messgeräts hat plötzlich weit {{ausgeschlagen}}.","en":"The needle of the gauge suddenly swung far."},{"de":"Das Pendel hat nach links {{ausgeschlagen}}.","en":"The pendulum swung to the left."}]},{"gloss":"to sprout, bud","art":null,"pl":null,"note":"separable: aus|schlagen","ex":[{"de":"Im März haben die Weiden schon {{ausgeschlagen}}.","en":"In March the willows had already come into leaf."},{"de":"Der Stumpf hat im Frühling neu {{ausgeschlagen}}.","en":"The stump sprouted anew in spring."}]}]},
 {"id":"aussetzen","word":"aussetzen","lv":"C1","tip":"aussetzen = expose (to) / abandon (an animal) / cut out, stop (engine, heart) / etwas auszusetzen haben = find fault.","meanings":[{"gloss":"to expose (to sun, danger)","art":null,"pl":null,"note":"separable: aus|setzen; + Dat.","ex":[{"de":"Man sollte Babys nicht zu lange der Sonne {{aussetzen}}.","en":"You shouldn't expose babies to the sun for too long."},{"de":"Die Arbeiter sind giftigen Dämpfen {{ausgesetzt}}.","en":"The workers are exposed to toxic fumes."}]},{"gloss":"to abandon (an animal)","art":null,"pl":null,"note":"separable: aus|setzen","ex":[{"de":"Das Paar hat den Hund auf einer Landstraße {{ausgesetzt}}.","en":"The couple abandoned the dog on a country road."},{"de":"Es ist strafbar, Tiere {{auszusetzen}}.","en":"It is a punishable offence to abandon animals."}]},{"gloss":"to cut out, stop suddenly (engine, heart)","art":null,"pl":null,"note":"separable: aus|setzen","ex":[{"de":"Mitten in der Fahrt hat der Motor {{ausgesetzt}}.","en":"In the middle of the drive the engine cut out."},{"de":"Während der Operation hat sein Herz kurz {{ausgesetzt}}.","en":"During the operation his heart stopped briefly."}]},{"gloss":"to find fault (etwas auszusetzen haben)","art":null,"pl":null,"note":"only in 'etwas auszusetzen haben / gibt es nichts auszusetzen'","ex":[{"de":"An seiner Arbeit gibt es nichts {{auszusetzen}}.","en":"There is nothing to criticise about his work."},{"de":"Hast du etwas an meinem Vorschlag {{auszusetzen}}?","en":"Do you have any objection to my proposal?"}]}]},
 {"id":"ausmachen","word":"ausmachen","lv":"C1","tip":"ausmachen = switch off / arrange, agree / matter, mind / make up, constitute.","meanings":[{"gloss":"to switch off, put out","art":null,"pl":null,"note":"separable: aus|machen","ex":[{"de":"Kannst du bitte das Licht {{ausmachen}}, wenn du gehst?","en":"Can you please turn off the light when you leave?"},{"de":"Die Feuerwehr hat das Feuer schnell {{ausgemacht}}.","en":"The fire brigade put out the fire quickly."}]},{"gloss":"to arrange, agree on","art":null,"pl":null,"note":"separable: aus|machen","ex":[{"de":"Habt ihr schon einen Termin {{ausgemacht}}?","en":"Have you arranged a date yet?"},{"de":"Wir haben für Freitag einen Treffpunkt {{ausgemacht}}.","en":"We have agreed on a meeting point for Friday."}]},{"gloss":"to matter, mind","art":null,"pl":null,"note":"separable: aus|machen; usually with nichts/etwas","ex":[{"de":"Es würde mir nichts {{ausmachen}}, früher zu kommen.","en":"I wouldn't mind coming earlier."},{"de":"Das hat ihr überhaupt nichts {{ausgemacht}}.","en":"That didn't bother her at all."}]},{"gloss":"to make up, constitute","art":null,"pl":null,"note":"separable: aus|machen","ex":[{"de":"Frauen werden in diesem Beruf bald mehr als die Hälfte der Beschäftigten {{ausmachen}}.","en":"Women will soon make up more than half of the employees in this profession."},{"de":"Die Miete hat früher fast die Hälfte seines Einkommens {{ausgemacht}}.","en":"The rent used to make up almost half of his income."}]}]},
 {"id":"umsetzen","word":"umsetzen","lv":"C1","tip":"umsetzen = implement / move to another place (pupil, plant) / turn over (sales) / convert (energy).","meanings":[{"gloss":"to implement (a plan)","art":null,"pl":null,"note":"separable: um|setzen","ex":[{"de":"Die Stadt will das Konzept bis nächstes Jahr {{umsetzen}}.","en":"The city wants to implement the concept by next year."},{"de":"Die Reform wurde nur halbherzig {{umgesetzt}}.","en":"The reform was only half-heartedly implemented."}]},{"gloss":"to move (to another seat or place); to transplant","art":null,"pl":null,"note":"separable: um|setzen","ex":[{"de":"Der Lehrer hat den Schüler in die erste Reihe {{umgesetzt}}.","en":"The teacher has moved the pupil to the front row."},{"de":"Im Frühjahr kann man die Sträucher {{umsetzen}}.","en":"In spring you can transplant the shrubs."}]},{"gloss":"to turn over (sales)","art":null,"pl":null,"note":"separable: um|setzen","ex":[{"de":"Der Händler hat im letzten Jahr Waren im Wert von zwei Millionen Euro {{umgesetzt}}.","en":"Last year the dealer turned over goods worth two million euros."},{"de":"Mit diesem Produkt wurden bereits fünf Millionen Euro {{umgesetzt}}.","en":"Five million euros of turnover has already been generated with this product."}]},{"gloss":"to convert (energy)","art":null,"pl":null,"note":"separable: um|setzen","ex":[{"de":"Solarzellen können Licht direkt in Strom {{umsetzen}}.","en":"Solar cells can convert light directly into electricity."},{"de":"In der Turbine wird Wärme in Bewegung {{umgesetzt}}.","en":"In the turbine heat is converted into motion."}]}]},
 {"id":"ueberfuehren","word":"überführen","lv":"C1","tip":"überführen = prove guilty (jdn. einer Tat überführen; inseparable, stress -FÜH-) / transfer, transport (patient, coffin; usually inseparable).","meanings":[{"gloss":"to prove guilty, establish guilt (of a crime)","art":null,"pl":null,"note":"inseparable: überführt; jdn. einer Tat überführen","ex":[{"de":"Die Polizei konnte den Täter durch eine DNA-Spur {{überführen}}.","en":"Thanks to a DNA trace the police were able to prove the offender guilty."},{"de":"Er wurde des Betrugs {{überführt}}.","en":"He was proved guilty of fraud."}]},{"gloss":"to transfer, transport","art":null,"pl":null,"note":"usually inseparable: überführt; also separable: übergeführt","ex":[{"de":"Der Patient wurde in ein anderes Krankenhaus {{überführt}}.","en":"The patient was transferred to another hospital."},{"de":"Der Sarg wird morgen nach Italien {{überführt}}.","en":"The coffin will be transported to Italy tomorrow."}]}]},
 {"id":"abschlagen","word":"abschlagen","lv":"C1","tip":"abschlagen (schlägt ab, schlug ab, abgeschlagen) = refuse (a request) / knock or chop off.","meanings":[{"gloss":"to refuse, turn down (a request, wish)","art":null,"pl":null,"note":"separable: ab|schlagen; jdm. etwas abschlagen (Bitte, Wunsch)","ex":[{"de":"Ich konnte ihm die Bitte nicht {{abschlagen}}.","en":"I couldn't turn down his request."},{"de":"Diesen Wunsch konnte sie ihrer Tochter nicht {{abschlagen}}.","en":"She couldn't refuse her daughter this wish."}]},{"gloss":"to knock off, chop off","art":null,"pl":null,"note":"separable: ab|schlagen","ex":[{"de":"Er hat mit der Axt einen dicken Ast {{abgeschlagen}}.","en":"He chopped off a thick branch with the axe."},{"de":"Der Gärtner hat die dürren Zweige mit einem Stock {{abgeschlagen}}.","en":"The gardener knocked off the dry twigs with a stick."}]}]},
 {"id":"stumpf","word":"stumpf","lv":"C1","tip":"stumpf = blunt (knife) / dull, without shine (hair, paint) / obtuse (angle).","meanings":[{"gloss":"blunt","art":null,"pl":null,"ex":[{"de":"Das Messer ist so {{stumpf}}, dass man damit kein Brot schneiden kann.","en":"The knife is so blunt that you can't cut bread with it."},{"de":"Mit {{stumpfen}} Scheren schneidet man schlecht.","en":"You can't cut well with blunt scissors."}]},{"gloss":"dull, lacklustre (surface, hair)","art":null,"pl":null,"ex":[{"de":"Ihr Haar wirkte {{stumpf}} und glanzlos.","en":"Her hair looked dull and lifeless."},{"de":"Der Lack ist mit der Zeit {{stumpf}} geworden.","en":"The paintwork has become dull over time."}]},{"gloss":"obtuse (angle)","art":null,"pl":null,"ex":[{"de":"Ein {{stumpfer}} Winkel ist größer als 90 Grad.","en":"An obtuse angle is greater than 90 degrees."},{"de":"Das Dreieck hat einen {{stumpfen}} Winkel.","en":"The triangle has an obtuse angle."}]}]},
 {"id":"dumpf","word":"dumpf","lv":"C1","tip":"dumpf = muffled, dull (sound) / musty (air, smell) / dull, vague (feeling, pain).","meanings":[{"gloss":"muffled, dull (sound)","art":null,"pl":null,"ex":[{"de":"Man hörte einen {{dumpfen}} Knall aus dem Keller.","en":"A muffled bang could be heard from the cellar."},{"de":"Die Trommel gab einen {{dumpfen}} Ton von sich.","en":"The drum gave out a dull sound."}]},{"gloss":"musty, stuffy","art":null,"pl":null,"ex":[{"de":"Im Keller roch es {{dumpf}} nach Feuchtigkeit.","en":"In the cellar it smelled musty and damp."},{"de":"Die {{dumpfe}} Luft im Raum machte ihr Kopfschmerzen.","en":"The stuffy air in the room gave her a headache."}]},{"gloss":"dull, vague (feeling, pain)","art":null,"pl":null,"ex":[{"de":"Ich hatte ein {{dumpfes}} Gefühl, dass etwas nicht stimmte.","en":"I had a vague feeling that something was wrong."},{"de":"Er spürte einen {{dumpfen}} Schmerz im Rücken.","en":"He felt a dull pain in his back."}]}]},
 {"id":"derb","word":"derb","lv":"C1","tip":"derb = coarse, crude (jokes, language) / sturdy, tough (shoes, fabric).","meanings":[{"gloss":"coarse, crude","art":null,"pl":null,"ex":[{"de":"Seine {{derben}} Witze brachten die Gäste in Verlegenheit.","en":"His crude jokes embarrassed the guests."},{"de":"Sie ist für ihre {{derbe}} Ausdrucksweise bekannt.","en":"She is known for her coarse way of speaking."}]},{"gloss":"sturdy, tough (material)","art":null,"pl":null,"ex":[{"de":"Zum Wandern braucht man {{derbe}} Schuhe.","en":"For hiking you need sturdy shoes."},{"de":"Der Stoff ist {{derb}} und hält viel aus.","en":"The fabric is tough and can take a lot."}]}]},
 {"id":"herb","word":"herb","lv":"C1","tip":"herb = tart, dry (taste) / harsh, painful (loss, criticism) / austere (beauty, landscape).","meanings":[{"gloss":"tart, bitter-dry (taste)","art":null,"pl":null,"ex":[{"de":"Dunkle Schokolade schmeckt etwas {{herb}}.","en":"Dark chocolate tastes slightly bitter."},{"de":"Der Wein ist {{herb}}, aber nicht sauer.","en":"The wine is dry but not sour."}]},{"gloss":"harsh, painful","art":null,"pl":null,"ex":[{"de":"Die Niederlage war ein {{herber}} Rückschlag für das Team.","en":"The defeat was a bitter setback for the team."},{"de":"Sie musste {{herbe}} Kritik einstecken.","en":"She had to take harsh criticism."}]},{"gloss":"austere (beauty, landscape)","art":null,"pl":null,"ex":[{"de":"Die {{herbe}} Schönheit der Landschaft beeindruckte sie.","en":"The austere beauty of the landscape impressed her."},{"de":"Die Küste hat einen {{herben}} Reiz.","en":"The coast has a rugged charm."}]}]},
 {"id":"matt","word":"matt","lv":"C1","tip":"matt = weak, faint (person, voice) / matt, not shiny (surface) / checkmate (matt setzen).","meanings":[{"gloss":"weak, exhausted","art":null,"pl":null,"ex":[{"de":"Nach der langen Krankheit fühlte er sich noch {{matt}}.","en":"After the long illness he still felt weak."},{"de":"Sie antwortete mit {{matter}} Stimme.","en":"She answered in a faint voice."}]},{"gloss":"matt (not glossy)","art":null,"pl":null,"ex":[{"de":"Ich möchte die Fotos lieber {{matt}} als glänzend.","en":"I would like the photos matt rather than glossy."},{"de":"Die Wand wurde mit {{matter}} Farbe gestrichen.","en":"The wall was painted with matt paint."}]},{"gloss":"checkmate (chess)","art":null,"pl":null,"note":"schachmatt; 'matt setzen' = to checkmate","ex":[{"de":"Nach zwanzig Zügen war der schwarze König {{matt}}.","en":"After twenty moves the black king was checkmated."},{"de":"Er setzte seinen Gegner in drei Zügen {{matt}}.","en":"He checkmated his opponent in three moves."}]}]},
 {"id":"blank","word":"blank","lv":"C1","tip":"blank = shiny, polished / bare, uninsulated / sheer, utter (blanker Unsinn) / broke (colloquial).","meanings":[{"gloss":"shiny, polished","art":null,"pl":null,"ex":[{"de":"Die {{blanken}} Schuhe glänzten in der Sonne.","en":"The polished shoes shone in the sun."},{"de":"Er hat den Kessel {{blank}} geputzt.","en":"He scrubbed the kettle until it shone."}]},{"gloss":"bare, uninsulated","art":null,"pl":null,"ex":[{"de":"Das Kabel liegt an einer Stelle {{blank}}, das ist gefährlich.","en":"The cable is bare at one point; that is dangerous."},{"de":"Zum Löten muss der Draht an der Spitze {{blank}} sein.","en":"For soldering, the wire must be bare at the tip."}]},{"gloss":"sheer, utter","art":null,"pl":null,"ex":[{"de":"Das ist doch {{blanker}} Unsinn!","en":"That is utter nonsense!"},{"de":"In ihren Augen lag {{blanke}} Angst.","en":"Sheer fear was in her eyes."}]},{"gloss":"broke (colloquial)","art":null,"pl":null,"note":"colloquial","ex":[{"de":"Ich kann dir nichts leihen, ich bin völlig {{blank}}.","en":"I can't lend you anything, I'm completely broke."},{"de":"Nach dem Urlaub waren wir alle {{blank}}.","en":"After the holiday we were all broke."}]}]},
 {"id":"muerbe","word":"mürbe","lv":"C1","tip":"mürbe = crumbly, short (pastry), tender (meat) / brittle, rotten (rope, wood) / worn down (mürbe machen).","meanings":[{"gloss":"crumbly, tender","art":null,"pl":null,"ex":[{"de":"Die Plätzchen sind knusprig und {{mürbe}}.","en":"The biscuits are crisp and crumbly."},{"de":"Das Fleisch ist nach drei Stunden Schmoren {{mürbe}}.","en":"The meat is tender after three hours of braising."}]},{"gloss":"brittle, rotten","art":null,"pl":null,"ex":[{"de":"Das {{mürbe}} Seil riss beim ersten Zug.","en":"The rotten rope snapped at the first pull."},{"de":"Das Holz der alten Brücke ist {{mürbe}} geworden.","en":"The wood of the old bridge has become rotten."}]},{"gloss":"worn down, ground down","art":null,"pl":null,"note":"mürbe machen / mürbe werden","ex":[{"de":"Die ständigen Anrufe haben ihn {{mürbe}} gemacht.","en":"The constant calls have worn him down."},{"de":"Die Verhandlungen haben beide Seiten {{mürbe}} gemacht.","en":"The negotiations have worn both sides down."}]}]},
 {"id":"fix","word":"fix","lv":"C1","tip":"fix = quick, nimble (colloquial) / fixed, set (fixe Kosten).","meanings":[{"gloss":"quick, nimble (colloquial)","art":null,"pl":null,"note":"colloquial","ex":[{"de":"Sie ist sehr {{fix}} und hat die Aufgabe in fünf Minuten erledigt.","en":"She is very quick and finished the task in five minutes."},{"de":"Das geht ganz {{fix}}, ich bin gleich zurück.","en":"That will be quick; I'll be right back."}]},{"gloss":"fixed, set","art":null,"pl":null,"ex":[{"de":"Die {{fixen}} Kosten betragen im Monat 800 Euro.","en":"The fixed costs are 800 euros a month."},{"de":"Er bekommt ein {{fixes}} Gehalt plus Provision.","en":"He gets a fixed salary plus commission."}]}]},
 {"id":"gemein","word":"gemein","lv":"C1","tip":"gemein = mean, nasty / in common (etw. gemein haben).","meanings":[{"gloss":"mean, nasty","art":null,"pl":null,"ex":[{"de":"Es war {{gemein}} von dir, ihr das nicht zu sagen.","en":"It was mean of you not to tell her."},{"de":"Der {{gemeine}} Kerl hat mir die Reifen zerstochen.","en":"The nasty guy slashed my tyres."}]},{"gloss":"in common (etw. gemein haben)","art":null,"pl":null,"note":"mit jdm. etw. gemein haben","ex":[{"de":"Die beiden Brüder haben nichts {{gemein}}.","en":"The two brothers have nothing in common."},{"de":"Er hat mit seinem Vater nur den Namen {{gemein}}.","en":"He has only the name in common with his father."}]}]},
 {"id":"billig","word":"billig","lv":"B2","tip":"billig = cheap (low price) / cheap, shoddy, feeble (excuse, trick; pejorative).","meanings":[{"gloss":"cheap (low price)","art":null,"pl":null,"ex":[{"de":"Im Supermarkt ist das Gemüse heute besonders {{billig}}.","en":"At the supermarket the vegetables are especially cheap today."},{"de":"Sie hat das Fahrrad ganz {{billig}} gekauft.","en":"She bought the bicycle very cheaply."}]},{"gloss":"cheap, shoddy (pejorative)","art":null,"pl":null,"ex":[{"de":"Das war eine {{billige}} Ausrede.","en":"That was a cheap excuse."},{"de":"Der Film setzt auf {{billige}} Effekte.","en":"The film relies on cheap effects."}]}]},
 {"id":"stock","word":"Stock","lv":"A2","tip":"Same article (der Stock), but a stick is something you hold, a floor is where you live: im dritten Stock.","meanings":[{"gloss":"stick, cane","art":"der","pl":"Stöcke","ex":[{"de":"Der alte Mann geht mit einem {{Stock}} spazieren.","en":"The old man goes for a walk with a stick."},{"de":"Der Hund bringt den {{Stock}} zurück.","en":"The dog brings the stick back."},{"de":"Beim Wandern benutze ich zwei {{Stöcke}}.","en":"When hiking I use two poles."}]},{"gloss":"floor, storey","art":"der","pl":"","note":"No real plural in this sense: after numbers 'Stock' stays unchanged (ein Haus mit fünf Stock); otherwise people say 'Stockwerke'. Counting starts above the ground floor (Erdgeschoss).","ex":[{"de":"Wir wohnen im dritten {{Stock}}, leider ohne Aufzug.","en":"We live on the third floor, unfortunately without a lift."},{"de":"Das Büro ist im ersten {{Stock}}.","en":"The office is on the first floor."},{"de":"Der Aufzug fährt bis in den vierten {{Stock}}.","en":"The lift goes up to the fourth floor."}]}]},
 {"id":"paar","word":"Paar","lv":"A2","tip":"das Paar (capital P) = a couple or a pair of things; ein paar (small p) = a few. Compare: ein Paar Schuhe (one pair) vs. ein paar Schuhe (some shoes).","meanings":[{"gloss":"couple; pair","art":"das","pl":"Paare","ex":[{"de":"Meine Eltern sind seit dreißig Jahren ein glückliches {{Paar}}.","en":"My parents have been a happy couple for thirty years."},{"de":"Ich habe mir ein {{Paar}} Handschuhe gekauft.","en":"I bought myself a pair of gloves."},{"de":"Auf der Hochzeit tanzten viele {{Paare}}.","en":"Many couples were dancing at the wedding."}]},{"gloss":"a few, some (ein paar)","art":null,"pl":null,"note":"indefinite numeral, written with a small p: ein paar","ex":[{"de":"Ich brauche nur ein {{paar}} Minuten.","en":"I only need a few minutes."},{"de":"Wir haben ein {{paar}} Freunde zum Essen eingeladen.","en":"We have invited a few friends for dinner."},{"de":"Kannst du mir ein {{paar}} Euro leihen?","en":"Can you lend me a few euros?"}]}]},
 {"id":"land","word":"Land","lv":"A2","tip":"das Land = country or federal state (plural Länder); auf dem Land = in the countryside; an Land = onto the shore.","meanings":[{"gloss":"country; federal state","art":"das","pl":"Länder","ex":[{"de":"Deutschland ist ein {{Land}} in Europa.","en":"Germany is a country in Europe."},{"de":"Aus welchem {{Land}} kommst du?","en":"Which country do you come from?"},{"de":"Im Urlaub besuchen wir drei verschiedene {{Länder}}.","en":"On holiday we are visiting three different countries."}]},{"gloss":"countryside","art":"das","pl":"","note":"no plural; usually in the phrases auf dem Land / aufs Land","ex":[{"de":"Meine Großeltern leben auf dem {{Land}}.","en":"My grandparents live in the countryside."},{"de":"Am Wochenende fahren wir aufs {{Land}}.","en":"At the weekend we are going to the countryside."},{"de":"Das Leben auf dem {{Land}} ist ruhiger als in der Stadt.","en":"Life in the countryside is quieter than in the city."}]},{"gloss":"land, shore (as opposed to sea)","art":"das","pl":"","note":"no plural; used without article: an Land gehen, Land sehen","ex":[{"de":"Nach drei Stunden auf dem Schiff sahen wir endlich {{Land}}.","en":"After three hours on the ship we finally saw land."},{"de":"Die Passagiere gingen in Hamburg an {{Land}}.","en":"The passengers went ashore in Hamburg."}]}]},
 {"id":"sauer","word":"sauer","lv":"A2","tip":"sauer = sour (lemon, milk) or, colloquially, angry. Food or drink: sour; a person with 'auf + Akk.': angry.","meanings":[{"gloss":"sour","art":null,"pl":null,"ex":[{"de":"Die Zitrone ist sehr {{sauer}}.","en":"The lemon is very sour."},{"de":"Die Milch ist {{sauer}} geworden, wir müssen sie wegschütten.","en":"The milk has gone sour; we have to throw it away."},{"de":"Die Äpfel sind noch nicht reif, sie sind ganz {{sauer}}.","en":"The apples aren't ripe yet; they are really sour."}]},{"gloss":"angry, annoyed (colloquial)","art":null,"pl":null,"note":"colloquial; usually: sauer auf jemanden sein","ex":[{"de":"Meine Mutter ist {{sauer}}, weil ich nicht angerufen habe.","en":"My mother is angry because I didn't call."},{"de":"Bist du {{sauer}} auf mich?","en":"Are you angry with me?"}]}]},
 {"id":"fach","word":"Fach","lv":"A2","tip":"das Fach, plural Fächer, for both: a subject at school or a compartment/shelf in a cupboard.","meanings":[{"gloss":"(school) subject","art":"das","pl":"Fächer","ex":[{"de":"Welches {{Fach}} magst du am liebsten?","en":"Which subject do you like best?"},{"de":"Chemie ist ein schwieriges {{Fach}}.","en":"Chemistry is a difficult subject."},{"de":"An unserer Schule gibt es viele {{Fächer}}, zum Beispiel Kunst und Musik.","en":"At our school there are many subjects, for example art and music."}]},{"gloss":"compartment, shelf","art":"das","pl":"Fächer","ex":[{"de":"Im obersten {{Fach}} liegen die Handtücher.","en":"The towels are in the top compartment."},{"de":"Der Schrank hat vier {{Fächer}} für Bücher.","en":"The cupboard has four shelves for books."},{"de":"Leg die Schlüssel bitte ins {{Fach}} neben der Tür.","en":"Please put the keys in the compartment next to the door."}]}]},
 {"id":"rezept","word":"Rezept","lv":"A2","tip":"das Rezept, plural Rezepte: in the kitchen = recipe, at the doctor's = prescription.","meanings":[{"gloss":"recipe","art":"das","pl":"Rezepte","ex":[{"de":"Hast du ein gutes {{Rezept}} für Apfelkuchen?","en":"Do you have a good recipe for apple cake?"},{"de":"Ich koche nach dem {{Rezept}} meiner Oma.","en":"I cook according to my grandma's recipe."},{"de":"Die {{Rezepte}} in diesem Buch sind alle einfach.","en":"The recipes in this book are all easy."}]},{"gloss":"prescription","art":"das","pl":"Rezepte","ex":[{"de":"Der Arzt hat mir ein {{Rezept}} für die Tabletten gegeben.","en":"The doctor gave me a prescription for the tablets."},{"de":"In der Apotheke braucht man für dieses Medikament ein {{Rezept}}.","en":"At the pharmacy you need a prescription for this medicine."},{"de":"Die Ärztin schreibt mir ein neues {{Rezept}}.","en":"The doctor is writing me a new prescription."}]}]},
 {"id":"praxis","word":"Praxis","lv":"A2","tip":"die Praxis: a doctor's practice (plural Praxen) or practice as opposed to theory (in der Praxis).","meanings":[{"gloss":"doctor's office, surgery","art":"die","pl":"Praxen","ex":[{"de":"Die {{Praxis}} meiner Hausärztin ist montags geschlossen.","en":"My family doctor's surgery is closed on Mondays."},{"de":"Ich warte schon eine Stunde in der {{Praxis}}.","en":"I have been waiting in the surgery for an hour."},{"de":"In diesem Haus gibt es drei {{Praxen}}: Hausarzt, Zahnarzt und Augenarzt.","en":"In this building there are three practices: a GP, a dentist and an eye doctor."}]},{"gloss":"practice (as opposed to theory)","art":"die","pl":"","note":"no plural in this sense","ex":[{"de":"In der Theorie klingt das einfach, aber in der {{Praxis}} ist es schwierig.","en":"In theory it sounds easy, but in practice it is difficult."},{"de":"Das Studium verbindet Theorie und {{Praxis}}.","en":"The course combines theory and practice."},{"de":"In der {{Praxis}} funktioniert dieser Plan leider nicht.","en":"In practice this plan unfortunately doesn't work."}]}]},
 {"id":"geschichte","word":"Geschichte","lv":"A2","tip":"die Geschichte = a story you tell (plural Geschichten) or history as a subject (no plural).","meanings":[{"gloss":"story","art":"die","pl":"Geschichten","ex":[{"de":"Die Mutter erzählt dem Kind jeden Abend eine {{Geschichte}}.","en":"The mother tells the child a story every evening."},{"de":"Das ist eine spannende {{Geschichte}} über einen Detektiv.","en":"That is an exciting story about a detective."},{"de":"In diesem Buch stehen zehn kurze {{Geschichten}}.","en":"This book contains ten short stories."}]},{"gloss":"history","art":"die","pl":"","note":"no plural in this sense","ex":[{"de":"In der Schule lernen wir viel über die deutsche {{Geschichte}}.","en":"At school we learn a lot about German history."},{"de":"{{Geschichte}} ist in der Schule mein Lieblingsfach.","en":"History is my favourite subject at school."},{"de":"Mein Bruder studiert {{Geschichte}} an der Universität.","en":"My brother studies history at university."}]}]},
 {"id":"tasche","word":"Tasche","lv":"A2","tip":"die Tasche = bag (Handtasche, Reisetasche) and also pocket (Hosentasche, Jackentasche). Plural: Taschen for both.","meanings":[{"gloss":"bag","art":"die","pl":"Taschen","ex":[{"de":"Sie packt ihre Sachen in eine große {{Tasche}}.","en":"She packs her things into a big bag."},{"de":"Meine {{Tasche}} ist schwer, weil ich zwei Bücher dabeihabe.","en":"My bag is heavy because I have two books with me."},{"de":"An der Garderobe hängen viele {{Taschen}}.","en":"Many bags are hanging in the cloakroom."}]},{"gloss":"pocket","art":"die","pl":"Taschen","note":"usually with a word like Hose or Jacke: Hosentasche, Jackentasche","ex":[{"de":"Ich habe den Schlüssel in die {{Tasche}} meiner Jacke gesteckt.","en":"I put the key into my jacket pocket."},{"de":"Er steckt die Hände in die {{Taschen}}, weil ihm kalt ist.","en":"He puts his hands in his pockets because he is cold."},{"de":"Sie suchte in der {{Tasche}} ihrer Jacke nach dem Handy.","en":"She looked in her jacket pocket for her phone."}]}]},
 {"id":"blitz","word":"Blitz","lv":"A2","tip":"der Blitz, plural Blitze: lightning in a thunderstorm, or the flash of a camera.","meanings":[{"gloss":"lightning","art":"der","pl":"Blitze","ex":[{"de":"Der {{Blitz}} hat in einen Baum eingeschlagen.","en":"Lightning has struck a tree."},{"de":"Nach dem {{Blitz}} hörten wir den Donner.","en":"After the lightning we heard the thunder."},{"de":"Bei einem Gewitter sieht man oft mehrere {{Blitze}} am Himmel.","en":"During a thunderstorm you often see several flashes of lightning in the sky."}]},{"gloss":"(camera) flash","art":"der","pl":"Blitze","ex":[{"de":"Bei diesem Foto habe ich den {{Blitz}} ausgeschaltet.","en":"I turned the flash off for this photo."},{"de":"In dem dunklen Raum braucht die Kamera einen {{Blitz}}.","en":"In the dark room the camera needs a flash."},{"de":"Bei Fotos mit {{Blitz}} sind die Augen oft rot.","en":"In photos taken with flash the eyes are often red."}]}]},
 {"id":"station","word":"Station","lv":"B1","tip":"die Station, plural Stationen: a stop on a bus/train line, or a ward in a hospital.","meanings":[{"gloss":"stop, station (public transport)","art":"die","pl":"Stationen","ex":[{"de":"Ich steige an der nächsten {{Station}} aus.","en":"I'm getting off at the next stop."},{"de":"Wie viele {{Stationen}} sind es noch bis zum Hauptbahnhof?","en":"How many stops are there left to the main station?"},{"de":"An der {{Station}} wartet eine Gruppe Touristen.","en":"A group of tourists is waiting at the stop."}],"note":"Haltestelle is the usual word for bus/tram stops; Station is common for underground and suburban trains (U-Bahn-Station)."},{"gloss":"ward (in a hospital)","art":"die","pl":"Stationen","ex":[{"de":"Die Patientin liegt schon eine Woche auf der {{Station}}.","en":"The patient has been on the ward for a week now."},{"de":"Auf dieser {{Station}} arbeiten zwölf Pflegekräfte.","en":"Twelve nurses work on this ward."},{"de":"Die Besuchszeit auf der {{Station}} ist von 14 bis 18 Uhr.","en":"Visiting hours on the ward are from 2 to 6 p.m."}]}]},
 {"id":"satz","word":"Satz","lv":"B1","tip":"der Satz, plural Sätze: a sentence you write, a jump/leap, or a set in tennis (also a set of things: ein Satz Reifen).","meanings":[{"gloss":"sentence","art":"der","pl":"Sätze","ex":[{"de":"Bilde bitte einen {{Satz}} mit dem Wort „Urlaub“.","en":"Please make a sentence with the word 'Urlaub'."},{"de":"Dieser {{Satz}} ist grammatisch nicht richtig.","en":"This sentence is not grammatically correct."},{"de":"Der Lehrer schrieb drei {{Sätze}} an die Tafel.","en":"The teacher wrote three sentences on the board."}]},{"gloss":"jump, leap","art":"der","pl":"Sätze","ex":[{"de":"Die Katze machte einen {{Satz}} auf den Tisch.","en":"The cat leapt onto the table."},{"de":"Mit einem großen {{Satz}} sprang der Hund über den Zaun.","en":"With a big leap the dog jumped over the fence."}]},{"gloss":"set (tennis; a set of things)","art":"der","pl":"Sätze","ex":[{"de":"Sie hat den ersten {{Satz}} mit 6:3 gewonnen.","en":"She won the first set 6-3."},{"de":"Beim Tennis führte er nach zwei gewonnenen {{Sätzen}}.","en":"In the tennis match he was leading after winning two sets."},{"de":"Ich habe einen neuen {{Satz}} Winterreifen gekauft.","en":"I bought a new set of winter tyres."}]}]},
 {"id":"kurs","word":"Kurs","lv":"B1","tip":"der Kurs, plural Kurse: a course you attend, or a rate (exchange rate, share price).","meanings":[{"gloss":"course, class","art":"der","pl":"Kurse","ex":[{"de":"Ich besuche einen {{Kurs}} für Anfänger.","en":"I'm taking a beginners' course."},{"de":"Der {{Kurs}} beginnt nächste Woche und dauert zwei Monate.","en":"The course starts next week and lasts two months."},{"de":"Die Volkshochschule bietet viele {{Kurse}} an.","en":"The adult-education centre offers many courses."}]},{"gloss":"rate (exchange rate; share price)","art":"der","pl":"Kurse","ex":[{"de":"Wie hoch ist heute der {{Kurs}} des Euro gegenüber dem Dollar?","en":"What is the euro's rate against the dollar today?"},{"de":"Der {{Kurs}} der Aktie ist gestern stark gefallen.","en":"The share price fell sharply yesterday."},{"de":"Bei einem guten {{Kurs}} tausche ich mein Geld am Flughafen.","en":"If the rate is good, I'll exchange my money at the airport."}]}]},
 {"id":"rolle","word":"Rolle","lv":"B1","tip":"die Rolle, plural Rollen: a role (in a film, in life: eine Rolle spielen) or a roll/reel of paper, tape, film.","meanings":[{"gloss":"role, part","art":"die","pl":"Rollen","ex":[{"de":"Sie spielt im neuen Film die {{Rolle}} einer Ärztin.","en":"She plays the role of a doctor in the new film."},{"de":"In der Familie hat jeder seine eigene {{Rolle}}.","en":"In the family everybody has their own role."},{"de":"Das Geld spielt bei der Entscheidung keine {{Rolle}}.","en":"Money plays no role in the decision."}]},{"gloss":"roll, reel","art":"die","pl":"Rollen","ex":[{"de":"Wir haben keine {{Rolle}} Toilettenpapier mehr.","en":"We have no roll of toilet paper left."},{"de":"Bring bitte eine {{Rolle}} Klebeband mit.","en":"Please bring a roll of sticky tape."},{"de":"Die {{Rolle}} Folie ist fast leer.","en":"The roll of cling film is almost empty."}]}]},
 {"id":"ausdruck","word":"Ausdruck","lv":"B1","tip":"Two plurals, two meanings: Ausdrücke = expressions/phrases; Ausdrucke = printouts.","meanings":[{"gloss":"expression, phrase","art":"der","pl":"Ausdrücke","ex":[{"de":"Dieser {{Ausdruck}} ist sehr höflich.","en":"This expression is very polite."},{"de":"Manche {{Ausdrücke}} kann man nicht wörtlich übersetzen.","en":"Some expressions cannot be translated literally."},{"de":"Im Alltag benutzt man oft andere {{Ausdrücke}} als in der Schule.","en":"In everyday life people often use different expressions than at school."}]},{"gloss":"printout","art":"der","pl":"Ausdrucke","note":"plural without Umlaut: die Ausdrucke","ex":[{"de":"Bring bitte einen {{Ausdruck}} deiner Buchung zum Flughafen mit.","en":"Please bring a printout of your booking to the airport."},{"de":"Ich habe zwei {{Ausdrucke}} des Vertrags in der Mappe.","en":"I have two printouts of the contract in the folder."}]}]},
 {"id":"anzeige","word":"Anzeige","lv":"B1","tip":"die Anzeige, plural Anzeigen: an ad in a newspaper, a report to the police (Anzeige erstatten), or the display of a device.","meanings":[{"gloss":"advertisement, ad","art":"die","pl":"Anzeigen","ex":[{"de":"Ich habe die Wohnung durch eine {{Anzeige}} in der Zeitung gefunden.","en":"I found the flat through an ad in the newspaper."},{"de":"Die Firma schaltet eine {{Anzeige}} für neue Mitarbeiter.","en":"The company is placing an ad for new employees."},{"de":"In der Zeitung stehen viele {{Anzeigen}} für Gebrauchtwagen.","en":"The newspaper has many ads for used cars."}]},{"gloss":"report to the police","art":"die","pl":"Anzeigen","note":"fixed phrase: Anzeige erstatten","ex":[{"de":"Wegen des Lärms hat sie eine {{Anzeige}} gegen die Nachbarn erstattet.","en":"She filed a report against the neighbours because of the noise."},{"de":"Nach dem Diebstahl hat er bei der Polizei {{Anzeige}} erstattet.","en":"After the theft he reported it to the police."}]},{"gloss":"display (of a device)","art":"die","pl":"Anzeigen","ex":[{"de":"Auf der {{Anzeige}} des Backofens blinkt eine rote Zahl.","en":"A red number is flashing on the oven's display."},{"de":"Die {{Anzeige}} im Auto zeigt die Außentemperatur.","en":"The display in the car shows the outside temperature."}]}]},
 {"id":"krebs","word":"Krebs","lv":"B1","tip":"der Krebs: a crab/crayfish (plural Krebse) or the disease cancer (no plural).","meanings":[{"gloss":"crab, crayfish","art":"der","pl":"Krebse","ex":[{"de":"Der {{Krebs}} läuft seitwärts über den Sand.","en":"The crab scuttles sideways across the sand."},{"de":"Am Strand haben die Kinder einen kleinen {{Krebs}} gefunden.","en":"On the beach the children found a little crab."},{"de":"Im Restaurant gibt es heute frische {{Krebse}} mit Knoblauch.","en":"At the restaurant there are fresh crayfish with garlic today."}]},{"gloss":"cancer (disease)","art":"der","pl":"","note":"usually no plural in this sense (types: Krebsarten)","ex":[{"de":"Ihr Großvater ist an {{Krebs}} gestorben.","en":"Her grandfather died of cancer."},{"de":"Rauchen kann {{Krebs}} verursachen.","en":"Smoking can cause cancer."},{"de":"Der Arzt hat bei ihm {{Krebs}} festgestellt.","en":"The doctor diagnosed him with cancer."}]}]},
 {"id":"hoerer","word":"Hörer","lv":"B1","tip":"der Hörer (plural also Hörer): the receiver of a telephone, or someone who listens (radio listener).","meanings":[{"gloss":"receiver (of a telephone)","art":"der","pl":"Hörer","ex":[{"de":"Er nahm den {{Hörer}} ab und meldete sich.","en":"He picked up the receiver and answered."},{"de":"Bitte legen Sie den {{Hörer}} nicht auf, ich verbinde Sie gleich.","en":"Please don't hang up, I'll put you through in a moment."},{"de":"Sie hielt den {{Hörer}} fest ans Ohr.","en":"She held the receiver tight to her ear."}]},{"gloss":"listener (e.g. radio)","art":"der","pl":"Hörer","note":"female form: die Hörerin","ex":[{"de":"Die {{Hörer}} können während der Sendung live anrufen.","en":"Listeners can call in live during the programme."},{"de":"Viele {{Hörer}} mögen die Sendung am Morgen.","en":"Many listeners like the morning programme."}]}]},
 {"id":"tonne","word":"Tonne","lv":"B1","tip":"die Tonne, plural Tonnen: a big bin or barrel (Mülltonne) or the unit of weight, 1,000 kg.","meanings":[{"gloss":"bin, barrel","art":"die","pl":"Tonnen","ex":[{"de":"Die gelbe {{Tonne}} steht vor dem Haus.","en":"The yellow bin stands in front of the house."},{"de":"Die {{Tonne}} für den Biomüll wird am Montag geleert.","en":"The organic-waste bin is emptied on Monday."},{"de":"Auf dem Hof stehen vier große {{Tonnen}} mit Regenwasser.","en":"In the yard there are four big barrels of rainwater."}]},{"gloss":"tonne (1,000 kg)","art":"die","pl":"Tonnen","ex":[{"de":"Der Lastwagen wiegt über zwanzig {{Tonnen}}.","en":"The lorry weighs over twenty tonnes."},{"de":"Das Schiff transportiert tausend {{Tonnen}} Getreide.","en":"The ship transports a thousand tonnes of grain."},{"de":"Eine {{Tonne}} entspricht tausend Kilogramm.","en":"A tonne is equal to a thousand kilograms."}]}]},
 {"id":"zehe","word":"Zehe","lv":"B1","tip":"die Zehe, plural Zehen: a toe (also: der Zeh), or one clove of garlic (only: eine Zehe Knoblauch).","meanings":[{"gloss":"toe","art":"die","pl":"Zehen","ex":[{"de":"Ich habe mir an der Tür die große {{Zehe}} gestoßen.","en":"I banged my big toe on the door."},{"de":"Im Winter habe ich oft kalte {{Zehen}}.","en":"In winter I often have cold toes."},{"de":"Sie stellte sich auf die {{Zehen}}, um das Buch oben im Regal zu erreichen.","en":"She stood on tiptoe to reach the book at the top of the shelves."}]},{"gloss":"clove (of garlic)","art":"die","pl":"Zehen","ex":[{"de":"Für die Soße brauchst du zwei {{Zehen}} Knoblauch.","en":"For the sauce you need two cloves of garlic."},{"de":"Eine {{Zehe}} Knoblauch reicht für den Salat.","en":"One clove of garlic is enough for the salad."}]}]},
 {"id":"hof","word":"Hof","lv":"B1","tip":"der Hof, plural Höfe: a courtyard/yard, a farm, or a royal court.","meanings":[{"gloss":"courtyard, yard","art":"der","pl":"Höfe","ex":[{"de":"Die Kinder spielen im {{Hof}} Fußball.","en":"The children are playing football in the yard."},{"de":"Unser Haus hat einen kleinen {{Hof}} mit einem Baum.","en":"Our house has a small courtyard with a tree."},{"de":"Im Sommer sitzen viele Leute abends im {{Hof}}.","en":"In summer many people sit in the courtyard in the evening."}]},{"gloss":"farm","art":"der","pl":"Höfe","ex":[{"de":"Im Urlaub haben wir auf einem {{Hof}} gewohnt und die Kühe gefüttert.","en":"On holiday we stayed on a farm and fed the cows."},{"de":"Der Bauer verkauft Eier und Milch direkt auf seinem {{Hof}}.","en":"The farmer sells eggs and milk directly on his farm."}]},{"gloss":"(royal) court","art":"der","pl":"Höfe","ex":[{"de":"Der König lebte mit seinem ganzen {{Hof}} im Schloss.","en":"The king lived in the castle with his entire court."},{"de":"Am {{Hof}} des Kaisers gab es große Feste.","en":"At the emperor's court there were big celebrations."}]}]},
 {"id":"schlagen","word":"schlagen","lv":"B1","tip":"schlagen (du schlägst, schlug, hat geschlagen): hit; whip cream; beat an opponent; strike (clock). The object and context show the meaning.","meanings":[{"gloss":"to hit","art":null,"pl":null,"ex":[{"de":"Man darf Kinder nicht {{schlagen}}.","en":"You must not hit children."},{"de":"Wütend {{schlug}} er mit der Faust gegen die Wand.","en":"Angrily he hit the wall with his fist."},{"de":"Er hat mit der Faust auf den Tisch {{geschlagen}}.","en":"He banged his fist on the table."}]},{"gloss":"to whip (cream, egg whites)","art":null,"pl":null,"ex":[{"de":"Für die Torte muss ich noch Sahne {{schlagen}}.","en":"For the cake I still have to whip some cream."},{"de":"Die Eiweiße müssen steif {{geschlagen}} werden.","en":"The egg whites have to be whisked until stiff."}]},{"gloss":"to beat, defeat","art":null,"pl":null,"ex":[{"de":"Unsere Mannschaft hat den Meister mit 3:0 {{geschlagen}}.","en":"Our team beat the champions 3-0."},{"de":"Er {{schlug}} seinen Gegner im Schach.","en":"He beat his opponent at chess."},{"de":"Wer den Weltmeister {{schlagen}} will, muss hart trainieren.","en":"Anyone who wants to beat the world champion has to train hard."}]},{"gloss":"to strike (of a clock)","art":null,"pl":null,"ex":[{"de":"Die Kirchenuhr {{schlägt}} zwölf Mal.","en":"The church clock strikes twelve times."},{"de":"Es hat gerade drei Uhr {{geschlagen}}.","en":"It has just struck three."}]}]},
 {"id":"raten","word":"raten","lv":"B1","tip":"raten (du rätst, riet, hat geraten): to guess (Rate mal!) or to advise (jemandem raten, etwas zu tun).","meanings":[{"gloss":"to guess","art":null,"pl":null,"ex":[{"de":"{{Rate}} mal, wen ich gestern getroffen habe!","en":"Guess who I met yesterday!"},{"de":"Er hat die richtige Antwort nur {{geraten}}.","en":"He only guessed the right answer."},{"de":"Ich muss die Lösung leider {{raten}}, weil ich sie nicht kenne.","en":"Unfortunately I have to guess the solution because I don't know it."}]},{"gloss":"to advise","art":null,"pl":null,"note":"with dative: jemandem raten","ex":[{"de":"Ich {{rate}} dir, nachts nicht allein durch den Park zu gehen.","en":"I advise you not to walk through the park alone at night."},{"de":"Der Arzt hat mir {{geraten}}, mehr Sport zu treiben.","en":"The doctor advised me to do more sport."},{"de":"Was {{rätst}} du mir: Soll ich die Stelle annehmen?","en":"What do you advise me: should I accept the job?"}]}]},
 {"id":"stimmen","word":"stimmen","lv":"B1","tip":"stimmen: Das stimmt! = that is right; ein Instrument stimmen = tune it; für/gegen etwas stimmen = vote.","meanings":[{"gloss":"to be correct, to be right","art":null,"pl":null,"ex":[{"de":"Das {{stimmt}} nicht, ich war gestern gar nicht da.","en":"That's not true; I wasn't even there yesterday."},{"de":"Die Rechnung {{stimmt}} leider nicht.","en":"Unfortunately the bill is not correct."},{"de":"{{Stimmt}} es, dass du umziehst?","en":"Is it true that you are moving?"}]},{"gloss":"to tune (an instrument)","art":null,"pl":null,"ex":[{"de":"Der Gitarrist muss seine Gitarre noch {{stimmen}}.","en":"The guitarist still has to tune his guitar."},{"de":"Vor dem Konzert {{stimmt}} das Orchester die Instrumente.","en":"Before the concert the orchestra tunes the instruments."}]},{"gloss":"to vote","art":null,"pl":null,"ex":[{"de":"Die meisten Mitglieder haben für den Vorschlag {{gestimmt}}.","en":"Most members voted for the proposal."},{"de":"Fast alle haben gegen den Plan {{gestimmt}}, nur zwei waren dafür.","en":"Almost everyone voted against the plan; only two were in favour."}]}]},
 {"id":"gerade","word":"gerade","lv":"B1","tip":"gerade = straight (eine gerade Linie), just now (Ich habe gerade gegessen) or even (gerade Zahl, opposite: ungerade).","meanings":[{"gloss":"straight","art":null,"pl":null,"ex":[{"de":"Zeichne bitte eine {{gerade}} Linie mit dem Lineal.","en":"Please draw a straight line with the ruler."},{"de":"Halte den Rücken {{gerade}}!","en":"Keep your back straight!"},{"de":"Dieser Baum ist ganz {{gerade}} gewachsen.","en":"This tree has grown completely straight."}]},{"gloss":"just (now), at the moment","art":null,"pl":null,"ex":[{"de":"Ich habe {{gerade}} mit dem Chef telefoniert.","en":"I have just spoken to the boss on the phone."},{"de":"Sie kocht {{gerade}}, ruf später noch mal an.","en":"She is cooking right now; call again later."},{"de":"Er ist {{gerade}} erst angekommen.","en":"He has only just arrived."}]},{"gloss":"even (of numbers)","art":null,"pl":null,"note":"opposite: ungerade (odd)","ex":[{"de":"Zwei, vier und sechs sind {{gerade}} Zahlen.","en":"Two, four and six are even numbers."},{"de":"Ist die Zahl zwölf {{gerade}} oder ungerade?","en":"Is the number twelve even or odd?"}]}]},
 {"id":"klappen","word":"klappen","lv":"B1","tip":"klappen: Es klappt! = it works out (colloquial); den Deckel/Sitz klappen = flip or fold something over.","meanings":[{"gloss":"to work out, to succeed (colloquial)","art":null,"pl":null,"note":"impersonal: es klappt","ex":[{"de":"Hat es mit dem neuen Job {{geklappt}}?","en":"Did it work out with the new job?"},{"de":"Das hat gut {{geklappt}}, wir sind pünktlich angekommen.","en":"That worked well; we arrived on time."},{"de":"Die Reservierung hat leider nicht {{geklappt}}.","en":"Unfortunately the booking didn't work out."}]},{"gloss":"to fold, to flip (up/down)","art":null,"pl":null,"ex":[{"de":"Man kann die Rückbank im Auto nach vorn {{klappen}}.","en":"You can fold the back seat of the car forward."},{"de":"Sie {{klappte}} den Deckel der Dose nach oben.","en":"She flipped the lid of the tin upwards."}]}]}
];
